window.JPG=window.JPG||{};JPG.N1=[{"id":"g1_053","t":"～なり～なり","ko":"~든 ~든 (뭐든)","cat":"조사","conn":[{"w":"명사","f":"電話 + なり + メール + なり"},{"w":"동사 사전형","f":"聞く + なり + 調べる + なり"}],"rule":["1. 같은 종류의 선택지 둘을 고른다(電話, メール).","2. 각 선택지 뒤에 なり를 하나씩 붙인다(電話なりメールなり).","3. 뒤에 필요한 조사를 붙이고(で) 권유·의뢰 표현으로 맺는다(連絡してください)."],"why":"","nu":"예로 든 것 중 어느 것이든, 또는 그와 비슷한 다른 것이라도 좋으니 해 보라는 뜻이다. 뒤에는 주로 권유·의뢰·명령·의지 표현이 오고, 이미 일어난 과거 사실을 나열하는 데는 쓰지 않는다.","cmp":[{"g":"～とか～とか","d":"단순히 예를 나열하며 과거 사실에도 쓴다. なり～なり는 그중에서 골라 행동하라는 권유에 쓴다."}],"ex":[{"jp":"電話[でんわ]なりメールなりで連絡[れんらく]してください。","ko":"전화든 메일이든 편한 방법으로 연락해 주세요."},{"jp":"わからないなら、先生[せんせい]に聞[き]くなり辞書[じしょ]で調[しら]べるなりしなさい。","ko":"모르겠으면 선생님께 묻든 사전으로 찾든 하렴."},{"jp":"疲[つか]れたなら、お茶[ちゃ]なりコーヒーなり飲[の]んで休[やす]んだらどう？","ko":"피곤하면 차든 커피든 마시고 쉬는 게 어때?"}],"dr":[{"t":"make","q":"電話・メール → ～なり～なり","a":"電話なりメールなり","hint":"각 명사 뒤에 なり"},{"t":"make","q":"聞く・調べる → ～なり～なり","a":"聞くなり調べるなり","hint":"동사 사전형 + なり"},{"t":"fill","q":"週末[しゅうまつ]は映画[えいが]を見[み]る（　）、買[か]い物[もの]に行[い]くなりして、気分転換[きぶんてんかん]したらどう？","a":"なり","opts":["なり","ので","のに","けど"]}],"src":["https://www.mlcjapanese.co.jp/n1_04_23.html"],"vf":1,"u":1,"g":1,"gp":"gg_N1_00"},{"id":"g1_229","t":"～びる","ko":"~다워지다, ~티가 나다, ~한 모습이 되다","cat":"활용","conn":[{"w":"명사","f":"大人 + びる → 大人びる"},{"w":"い형용사 어간","f":"古い → 古びる"}],"rule":["1. 명사는 그대로 두고(大人), い형용사는 어미 い를 뗀다(古い → 古).","2. 접미사 びる를 붙여 2그룹 동사를 만든다: 大人びる, 古びる.","3. 상태를 말할 때는 る를 떼고 ている를 붙인다: 大人びている, 古びている."],"why":"","nu":"'~의 성질·모습을 띠게 되다'는 뜻으로 동사를 만드는 접미사이다. 실제로 쓰는 말은 大人びる, 古びる, ひなびる(시골스럽다) 등 몇 개로 굳어져 있어서 아무 명사에나 붙여 새로 만들지 않는다. 문장 끝에서는 주로 ている형(大人びている), 명사 앞에서는 た형(古びた家)으로 쓴다. 大人びる는 아이가 나이에 비해 어른스러워 보인다는 뜻이다.","cmp":[{"g":"～ぶる","d":"실제로는 아닌데 '~인 척하다'(大人ぶる: 어른인 척하다). びる는 실제로 그런 모습이 되었다는 뜻(大人びる: 어른스러워 보이다)."},{"g":"～めく","d":"'~다운 기미가 보이다'(春めく). 역시 붙는 말이 정해져 있다."}],"ex":[{"jp":"その子[こ]は年[とし]のわりに大人[おとな]びている。","ko":"그 아이는 나이에 비해 어른스럽다."},{"jp":"久[ひさ]しぶりに帰[かえ]ると、実家[じっか]はすっかり古[ふる]びていた。","ko":"오랜만에 돌아가 보니 본가는 완전히 낡아 있었다."},{"jp":"妹[いもうと]は高校生[こうこうせい]になって、急[きゅう]に大人[おとな]びてきた。","ko":"여동생은 고등학생이 되더니 갑자기 어른스러워졌다."}],"dr":[{"t":"make","q":"大人 → ～びている","a":"大人びている","hint":"명사 + びる, る를 떼고 ている"},{"t":"make","q":"古い → ～びた","a":"古びた","hint":"い를 떼고 びる, る를 떼고 た"},{"t":"fill","q":"このお寺[てら]はずいぶん古[ふる]（　）いる。","a":"びて","opts":["びて","ぶって","がって","そうで"]}],"src":[],"vf":0,"u":1,"g":1,"gp":"gg_N1_00"},{"id":"g1_231","t":"～ぶって","ko":"~인 척하며, ~인 체하고","cat":"활용","conn":[{"w":"명사","f":"先輩 + ぶって"},{"w":"い형용사 어간","f":"偉い → 偉ぶって"},{"w":"관용 표현","f":"もったいぶって (뜸을 들이며, 거드름 피우며)"}],"rule":["1. 명사는 그대로, い형용사는 어미 い를 뗀다: 先輩 / 偉い → 偉.","2. 접미사 ぶる(1그룹 동사)를 붙인다: 先輩ぶる.","3. ぶる의 る를 っ로 바꾸고(촉음편) て를 붙인다: 先輩ぶって. 뒤에 동작이 이어진다(先輩ぶって説教する)."],"why":"","nu":"ぶる의 て형으로, '~인 척하면서 ~하다'처럼 뒤의 동작을 꾸미거나 문장을 잇는다. 상대의 태도를 비난하는 말이다. もったいぶって(괜히 뜸 들이며)는 하나의 굳은 표현으로 자주 쓴다. '모르는 걸 아는 척'은 知ったかぶりをする라고 하며, 知ったかぶって는 구어적 변형이다.","cmp":[{"g":"～ふりをして","d":"보통형 + ふりをして로 사실과 다르게 꾸미는 일반 표현(知らないふりをして). ぶって는 명사·형용사 어간에 붙어 거드름을 나무라는 느낌."}],"ex":[{"jp":"彼[かれ]は一年[いちねん]早[はや]く入[はい]っただけなのに、先輩[せんぱい]ぶって説教[せっきょう]する。","ko":"그는 1년 먼저 들어왔을 뿐인데 선배인 척하며 설교한다."},{"jp":"もったいぶっていないで、早[はや]く教[おし]えてよ。","ko":"뜸 들이지 말고 빨리 알려 줘."},{"jp":"部長[ぶちょう]は偉[えら]ぶって部下[ぶか]に命令[めいれい]ばかりしている。","ko":"부장은 잘난 체하며 부하에게 명령만 하고 있다."}],"dr":[{"t":"make","q":"先生 → ～ぶって","a":"先生ぶって","hint":"명사 + ぶる, る를 っ로 바꾸고 て"},{"t":"make","q":"偉い → ～ぶって","a":"偉ぶって","hint":"い를 떼고 ぶる → ぶって"},{"t":"fill","q":"彼[かれ]は通[つう]（　）、料理[りょうり]の説明[せつめい]を始[はじ]めた。","a":"ぶって","opts":["ぶって","びて","ながら","ついでに"]}],"src":[],"vf":0,"u":1,"g":1,"gp":"gg_N1_00"},{"id":"g1_233","t":"～ぶる","ko":"~인 척하다, ~인 체하다, ~티를 내다","cat":"활용","conn":[{"w":"명사","f":"学者 + ぶる"},{"w":"な형용사 어간","f":"上品な → 上品ぶる"},{"w":"い형용사 어간","f":"偉い → 偉ぶる"}],"rule":["1. 명사는 그대로, な형용사는 な를 떼고 어간만(上品な → 上品), い형용사는 어미 い를 뗀다(偉い → 偉).","2. 접미사 ぶる를 붙여 1그룹 동사를 만든다: 上品ぶる.","3. 1그룹 동사로 활용한다: 上品ぶって(て형), 上品ぶった(た형), 上品ぶらない(ない형)."],"why":"","nu":"실제로는 그렇지 않은데 그런 것처럼 행동한다는 뜻으로, 거의 항상 비난이나 경멸의 느낌이 있다. 学者ぶる, 上品ぶる, 偉ぶる, いい子ぶる 등이 자주 쓰인다. 남의 행동을 평가하는 말이라 자기를 낮출 때는 거의 쓰지 않는다. 1그룹 동사이므로 ます형은 ぶります, て형은 ぶって가 된다.","cmp":[{"g":"～ふりをする","d":"사실과 다르게 꾸민다는 일반 표현(寝たふりをする). ぶる는 지위·품격 등을 과시하는 태도를 나무라는 뜻이 강하다."},{"g":"～びる","d":"실제로 그런 모습이 되다(大人びる). ぶる는 그런 척하다(大人ぶる)."}],"ex":[{"jp":"彼女[かのじょ]はいつも上品[じょうひん]ぶっているが、本当[ほんとう]はそうでもない。","ko":"그녀는 항상 고상한 척하지만 사실은 그렇지도 않다."},{"jp":"少[すこ]し本[ほん]を読[よ]んだだけで学者[がくしゃ]ぶるのはやめなさい。","ko":"책 좀 읽었다고 학자인 척하는 건 그만해라."},{"jp":"先生[せんせい]の前[まえ]でだけいい子[こ]ぶる生徒[せいと]がいる。","ko":"선생님 앞에서만 착한 아이인 척하는 학생이 있다."}],"dr":[{"t":"make","q":"上品な → ～ぶる","a":"上品ぶる","hint":"な를 떼고 어간 + ぶる"},{"t":"make","q":"偉い → ～ぶらない (부정)","a":"偉ぶらない","hint":"い를 떼고 ぶる, 1그룹이므로 る를 ら로 + ない"},{"t":"fill","q":"彼[かれ]は偉[えら]（　）ことなく、誰[だれ]にでも親切[しんせつ]だ。","a":"ぶる","opts":["ぶる","びる","らしい","っぽい"]}],"src":[],"vf":0,"u":1,"g":1,"gp":"gg_N1_00"},{"id":"g1_071","t":"～に限る","ko":"~가 최고다, ~하는 게 제일이다","cat":"문말표현","conn":[{"w":"명사","f":"冷たいビール + に限る"},{"w":"동사 사전형","f":"寝る + に限る"},{"w":"동사 ない형","f":"開けない + に限る"}],"rule":["1. 명사나 동사 사전형·ない형 뒤에 に限る를 붙인다(寝るに限る).","2. 동사는 형태를 바꾸지 않고 사전형 그대로 쓴다(寝る).","3. 문장 끝에 놓으며 과거형으로 바꾸지 않는다."],"why":"","nu":"'(이럴 때는) ~가 가장 좋다'는 말하는 사람의 주관적 판단을 나타낸다. 회화에서도 자주 쓴다. 앞에 '暑い日は', '疲れたときは'처럼 상황을 먼저 말하는 경우가 많다. 객관적인 사실의 1위를 말할 때는 쓰지 않는다. 비슷해 보이는 に限って(하필 그때만)와 뜻이 전혀 다르다.","cmp":[{"g":"～に限って","d":"急いでいる時に限ってバスが来ない처럼 '하필 ~때만'이라는 뜻. に限る는 '~가 최고다'."}],"ex":[{"jp":"暑[あつ]い日[ひ]は冷[つめ]たいビールに限[かぎ]る。","ko":"더운 날은 차가운 맥주가 최고다."},{"jp":"疲[つか]れたときは、早[はや]く寝[ね]るに限[かぎ]る。","ko":"피곤할 때는 일찍 자는 게 제일이다."},{"jp":"知[し]らない人[ひと]からのメールは開[ひら]かないに限[かぎ]る。","ko":"모르는 사람에게서 온 메일은 열지 않는 게 제일이다."}],"dr":[{"t":"make","q":"早く寝る → ～に限る","a":"早く寝るに限る","hint":"동사 사전형 + に限る"},{"t":"make","q":"開かない → ～に限る","a":"開かないに限る","hint":"ない형 그대로 + に限る"},{"t":"fill","q":"夏[なつ]は冷[つめ]たいビール（　）。","a":"に限る","opts":["に限る","に限って","に先駆けて","にひきかえ"]}],"src":["https://nihongokyoshi-net.com/?p=6124"],"vf":1,"u":1,"g":1,"gp":"gg_N1_00"},{"id":"g1_082","t":"～きらいがある","ko":"~하는 (좋지 않은) 경향이 있다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"遅れる + きらいがある"},{"w":"동사 ない형","f":"人の話を聞かない + きらいがある"},{"w":"명사","f":"誇張の + きらいがある"}],"rule":["1. 동사는 사전형이나 ない형 그대로 뒤에 きらいがある를 붙인다: 遅れるきらいがある.","2. 명사는 の를 넣어 붙인다: 誇張のきらいがある.","3. きらい는 보통 히라가나로 쓰며(한자로는 嫌い), '싫어함'이라는 뜻이 아니다."],"why":"","nu":"어떤 사람이나 사물이 바람직하지 않은 쪽으로 기우는 경향이 있다고 비판적으로 평가하는 문어적 표현이다. 좋은 경향에는 쓰지 않는다. 好き嫌い의 嫌い처럼 '~을 싫어한다'로 오해하기 쉬우니 주의한다(魚のきらいがある는 '생선을 싫어한다'가 아니다).","cmp":[{"g":"～がちだ","d":"동사 ます형·명사에 붙어 '자주 ~하게 된다'는 뜻으로 회화에서도 쓴다(遅れがちだ). きらいがある는 더 문어적이고 성격·성향에 대한 평가다."},{"g":"～傾向がある","d":"좋고 나쁨에 관계없이 중립적으로 경향을 말한다."}],"ex":[{"jp":"彼[かれ]は何[なん]でも一人[ひとり]で決[き]めてしまうきらいがある。","ko":"그는 무엇이든 혼자 정해 버리는 경향이 있다."},{"jp":"姉[あね]は物事[ものごと]を悪[わる]いほうに考[かんが]えすぎるきらいがある。","ko":"언니는 일을 나쁜 쪽으로 지나치게 생각하는 경향이 있다."},{"jp":"彼[かれ]の話[はなし]は、いつも少[すこ]し誇張[こちょう]のきらいがある。","ko":"그의 이야기는 늘 조금 과장하는 경향이 있다."}],"dr":[{"t":"make","q":"人の話を聞かない → ～きらいがある","a":"人の話を聞かないきらいがある","hint":"ない형 그대로 + きらいがある"},{"t":"make","q":"誇張 → ～きらいがある","a":"誇張のきらいがある","hint":"명사 + の + きらいがある"},{"t":"fill","q":"彼[かれ]は自分[じぶん]の意見[いけん]を人[ひと]に押[お]し付[つ]ける（　）がある。","a":"きらい","opts":["きらい","ため","ほど","ついで"]}],"src":["https://nihongokyoshi-net.com/2019/02/19/jlptn1-grammar-kiraigaaru/","https://bunpro.jp/ja/grammar_points/%E3%81%8D%E3%82%89%E3%81%84%E3%81%8C%E3%81%82%E3%82%8B"],"vf":1,"u":2,"g":1,"gp":"gg_N1_00"},{"id":"g1_107","t":"～を禁じ得ない","ko":"~을 금할 수 없다","cat":"문말표현","conn":[{"w":"감정 명사","f":"驚き + を禁じ得ない"}],"rule":["1. 2그룹 동사 禁じる의 어미 る를 떼어 ます형 어간 禁じ를 만든다.","2. 가능을 나타내는 得る(える)의 부정형 得ない를 붙인다: 禁じ得ない.","3. 감정을 나타내는 명사 + を 앞에 둔다: 驚きを禁じ得ない."],"why":"禁じる(금하다)의 ます형 어간에 '~할 수 있다'는 뜻의 得る의 부정 得ない가 붙어 '금할 수 없다'는 뜻이 된다.","nu":"매우 딱딱한 문어 표현이다. 어떤 사실을 보고 들은 화자에게 驚き・怒り・同情・涙・失望 같은 감정이 저절로 솟아나 억누를 수 없다는 뜻이다. 앞에는 감정을 나타내는 명사만 온다. 보통 화자 자신의 감정에 쓰며 일상 회화에서는 거의 쓰지 않는다.","cmp":[{"g":"～ずにはいられない","d":"동사 ない형에 붙어(笑わずにはいられない) 감정이나 행동을 참을 수 없다는 뜻으로, 회화에서도 쓴다. を禁じ得ない는 감정 명사에만 붙는 문어체다."}],"ex":[{"jp":"事故[じこ]の知[し]らせに、驚[おどろ]きを禁[きん]じ得[え]ない。","ko":"사고 소식에 놀라움을 금할 수 없다."},{"jp":"被害者[ひがいしゃ]の話[はなし]を聞[き]いて、同情[どうじょう]を禁[きん]じ得[え]なかった。","ko":"피해자의 이야기를 듣고 동정을 금할 수 없었다."},{"jp":"このような不正[ふせい]には、怒[いか]りを禁[きん]じ得[え]ない。","ko":"이런 부정에는 분노를 금할 수 없다."}],"dr":[{"t":"make","q":"驚き → ～を禁じ得ない","a":"驚きを禁じ得ない","hint":"감정 명사 + を + 禁じ得ない"},{"t":"make","q":"禁じる + 得る의 부정형","a":"禁じ得ない","hint":"る를 떼고(禁じ) + 得ない"},{"t":"fill","q":"彼[かれ]の無責任[むせきにん]な態度[たいど]には、怒[いか]り（　）。","a":"を禁じ得ない","opts":["を禁じ得ない","を余儀なくされる","をものともしない","を皮切りにする"]}],"src":["https://nihongokyoshi-net.com/2019/06/15/jlptn1-grammar-wokinjienai/"],"vf":1,"u":2,"g":1,"gp":"gg_N1_00"},{"id":"g1_118","t":"～ずじまい","ko":"(결국) ~하지 못하고 끝남","cat":"문말표현","conn":[{"w":"1그룹 동사 ない형","f":"会わ + ずじまい"},{"w":"2그룹 동사 ない형","f":"見 + ずじまい"},{"w":"불규칙 する","f":"する → せずじまい"},{"w":"불규칙 来る","f":"来る → 来(こ)ずじまい"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꿔 ない형을 만든다. う는 わ가 된다: 会う → 会わ.","2. ない 대신 옛 부정형 ず를 붙인다: 会わず.","3. じまい를 붙인다: 会わずじまい. 문장 끝에서는 だ・だった, 이어질 때는 で를 붙인다.","4. 2그룹은 る를 떼고 ずじまい, する는 せずじまい가 된다."],"why":"고전 부정 조동사 ず에 '끝, 마침'을 뜻하는 しまい(仕舞い)가 연탁하여 じまい가 된 형태다.","nu":"하려고 했거나 할 기회가 있었는데 결국 하지 못한 채 끝나 버렸다는 아쉬움을 나타낸다. 이미 끝난 일에 쓰므로 ずじまいだった, ずじまいで帰った처럼 과거 문맥이 많다. 행동할 수 있었던 의지 동사(会う, 見る, 言う, 行く)와 함께 쓴다. 회화와 문장 모두에 쓴다.","cmp":[{"g":"～ないまま","d":"~하지 않은 상태가 그대로 이어진다는 뜻으로, 결과가 끝났다는 의미나 아쉬움이 ずじまい보다 약하다."}],"ex":[{"jp":"旅行中[りょこうちゅう]ずっと雨[あめ]で、富士山[ふじさん]は見[み]ずじまいだった。","ko":"여행 내내 비가 와서 후지산은 결국 못 보고 말았다."},{"jp":"忙[いそが]しくて、友達[ともだち]に会[あ]わずじまいで帰国[きこく]した。","ko":"바빠서 친구를 끝내 못 만나고 귀국했다."},{"jp":"せっかく買[か]ったのに、一度[いちど]も使[つか]わずじまいの服[ふく]がある。","ko":"모처럼 샀는데 한 번도 못 입고 끝난 옷이 있다."}],"dr":[{"t":"make","q":"行く → ～ずじまい","a":"行かずじまい","hint":"く → か(ない형) + ずじまい"},{"t":"make","q":"言う → ～ずじまい","a":"言わずじまい","hint":"う → わ(ない형) + ずじまい"},{"t":"fill","q":"本[ほん]を借[か]りたが、忙[いそが]しくて結局[けっきょく]読[よ]ま（　）だった。","a":"ずじまい","opts":["ずじまい","ずにはおかない","ざるを得ない","ずとも"]}],"src":["https://bunpro.jp/grammar_points/889"],"vf":1,"u":2,"g":1,"gp":"gg_N1_00"},{"id":"g1_120","t":"～ずにはおかない","ko":"반드시 ~하게 만든다, 꼭 ~하고 말겠다","cat":"문말표현","conn":[{"w":"사역 동사(2그룹 활용)","f":"泣かせ + ずにはおかない"},{"w":"1그룹 동사 ない형","f":"動かさ + ずにはおかない"},{"w":"불규칙 する","f":"する → せずにはおかない"}],"rule":["1. 사역형 泣かせる는 2그룹처럼 활용하므로 어미 る를 뗀다: 泣かせる → 泣かせ.","2. 부정의 ず를 붙이고 이어서 には를 붙인다: 泣かせずには.","3. おかない를 붙인다: 泣かせずにはおかない.","4. 1그룹은 ない형(あ단)에 붙이고(動かす → 動かさずにはおかない), する는 せずにはおかない가 된다."],"why":"ず(부정)에 に・は가 붙고, 措く(おく, 그대로 두다·그만두다)의 부정 おかない가 이어진 형태다. '~하지 않은 채로 두지 않는다'에서 '반드시 ~하게 한다'는 뜻이 된다.","nu":"두 가지로 쓴다. ① 작품·사건·말 등이 주어가 되어 사람에게 어떤 감정이나 행동을 저절로 일으킨다(人を感動させずにはおかない). 이때 사역 동사와 자주 쓴다. ② 화자의 강한 결의: 반드시 ~하고 말겠다(犯人を捕まえずにはおかない). 딱딱한 문어체다. 자기 감정을 억누를 수 없다는 ずにはいられない와 혼동하기 쉽다.","cmp":[{"g":"～ずにはいられない","d":"주어(나)가 감정을 참지 못해 저절로 하게 된다(笑わずにはいられない). ずにはおかない는 대상이 사람에게 그런 결과를 일으키거나 화자가 반드시 하겠다는 뜻이다."},{"g":"～ずにはすまない","d":"상황·상식상 하지 않고는 해결되지 않는다는 의무를 나타낸다."}],"ex":[{"jp":"この映画[えいが]は、見[み]る人[ひと]を泣[な]かせずにはおかない。","ko":"이 영화는 보는 사람을 반드시 울리고 만다."},{"jp":"彼[かれ]の言葉[ことば]は、聞[き]く人[ひと]の心[こころ]を動[うご]かさずにはおかない。","ko":"그의 말은 듣는 사람의 마음을 움직이지 않고는 두지 않는다."},{"jp":"今度[こんど]こそ、犯人[はんにん]を捕[つか]まえずにはおかない。","ko":"이번에야말로 범인을 꼭 잡고 말겠다."}],"dr":[{"t":"make","q":"感動させる → ～ずにはおかない","a":"感動させずにはおかない","hint":"る를 떼고 + ずにはおかない"},{"t":"make","q":"動かす → ～ずにはおかない","a":"動かさずにはおかない","hint":"す → さ(ない형) + ずにはおかない"},{"t":"fill","q":"この小説[しょうせつ]は、読[よ]む人[ひと]を考[かんが]えさせ（　）。","a":"ずにはおかない","opts":["ずにはおかない","てばかりいる","たがる","ずじまいだ"]}],"src":["https://bunpro.jp/grammar_points/945"],"vf":1,"u":2,"g":1,"gp":"gg_N1_00"},{"id":"g1_126","t":"～たことにしてください","ko":"~한 것으로 해 주세요","cat":"문말표현","conn":[{"w":"동사 た형","f":"行った + ことにしてください"},{"w":"동사 なかった형","f":"見なかった + ことにしてください"}],"rule":["1. 2그룹 동사 見る는 어미 る를 떼고 과거 부정 なかった를 붙인다: 見る → 見なかった.","2. 긍정이면 た형을 쓴다(1그룹은 음편: 行く → 行った).","3. 그 뒤에 ことに를 붙인다: 見なかったことに.","4. する의 て형 して와 ください를 붙인다: 見なかったことにしてください."],"why":"~ことにする(~한 것으로 하다)의 て형 ことにして에 의뢰의 ください가 붙은 형태다.","nu":"실제와 다르더라도 그런 것으로 처리해 달라, 그런 셈 쳐 달라고 부탁하는 표현이다. 今の話は聞かなかったことにしてください(방금 이야기는 못 들은 걸로 해 주세요)처럼 なかった와 자주 쓴다. 친한 사이에는 ことにして라고 줄인다. 사전형 + ことにする는 '~하기로 정하다'라는 결정의 뜻이므로, た형 + ことにする(~한 것으로 치다)와 구별해야 한다.","cmp":[{"g":"～ことにする","d":"동사 사전형 + ことにする는 앞으로의 행동을 결정한다(毎日走ることにする). た형에 붙으면 사실과 관계없이 그런 것으로 간주한다는 뜻이 된다."},{"g":"～ふりをする","d":"주어 자신이 실제로 그런 척 행동한다(寝たふりをする). ことにする는 사실을 그렇게 취급하는 것이다."}],"ex":[{"jp":"今[いま]の話[はなし]は聞[き]かなかったことにしてください。","ko":"방금 이야기는 못 들은 걸로 해 주세요."},{"jp":"このお金[かね]は、私[わたし]が借[か]りたことにしてください。","ko":"이 돈은 제가 빌린 것으로 해 주세요."},{"jp":"昨日[きのう]の約束[やくそく]は、なかったことにしてください。","ko":"어제 약속은 없었던 걸로 해 주세요."}],"dr":[{"t":"make","q":"聞く → ～なかったことにしてください","a":"聞かなかったことにしてください","hint":"く → か(ない형) + なかった + ことにしてください"},{"t":"make","q":"会う → ～たことにしてください","a":"会ったことにしてください","hint":"う → った(촉음편) + ことにしてください"},{"t":"fill","q":"恥[は]ずかしいので、今[いま]のは見[み]なかった（　）。","a":"ことにしてください","opts":["ことにしてください","ばかりです","ところです","ものですか"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/たことにする-たことになる-ta-koto-ni-suru-ta-koto-ni-naru-meaning/"],"vf":1,"u":2,"g":1,"gp":"gg_N1_00"},{"id":"g1_136","t":"～てみせる","ko":"꼭 ~하고 말겠다 / ~해 보이다","cat":"문말표현","conn":[{"w":"동사 て형","f":"勝って + みせる"},{"w":"する동사","f":"合格して + みせる"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 つ동사는 어미 つ가 っ로 바뀌고(촉음편) て가 붙는다: 勝つ → 勝って.","2. て형 뒤에 みせる(보이다)를 붙인다: 勝ってみせる.","3. みせる는 2그룹 동사처럼 활용한다: 勝ってみせます, 勝ってみせた."],"why":"동사 て형 + 見せる(보여 주다)로, 행동을 남에게 보여 준다는 뜻에서 '해 보이다'와 '(보란 듯이) 해내고 말겠다'는 결의가 나온다.","nu":"두 가지 뜻이 있다. ① 남에게 직접 해서 보여 주다(先生がやってみせた). ② 1인칭 주어로 '꼭 해내겠다'는 강한 결의(必ず合格してみせる). 결의의 뜻은 말하는 사람 자신의 행동에만 쓴다. ～てみる(시험 삼아 해 보다)와 혼동하지 않도록 주의한다.","cmp":[{"g":"～てみる","d":"시험 삼아 해 보다. てみせる는 남에게 보여 주거나 해내겠다는 결의다."}],"ex":[{"jp":"次[つぎ]の試合[しあい]では必[かなら]ず勝[か]ってみせる。","ko":"다음 시합에서는 반드시 이기고 말겠다."},{"jp":"来年[らいねん]こそ試験[しけん]に合格[ごうかく]してみせます。","ko":"내년에야말로 시험에 꼭 합격하겠습니다."},{"jp":"先生[せんせい]はまず自分[じぶん]で泳[およ]いでみせた。","ko":"선생님은 먼저 직접 헤엄쳐 보였다."}],"dr":[{"t":"make","q":"やる → ～てみせる","a":"やってみせる","hint":"る → って(촉음편), + みせる"},{"t":"make","q":"泳ぐ → ～てみせた","a":"泳いでみせた","hint":"ぐ → いで(イ음편), + みせた"},{"t":"fill","q":"いつか絶対[ぜったい]に夢[ゆめ]をかなえて（　）。","a":"みせる","opts":["みせる","みる","おく","しまう"]}],"src":["https://bunpro.jp/es/grammar_points/verb-%E3%81%A6-%E3%81%BF%E3%81%9B%E3%82%8B"],"vf":1,"u":3,"g":1,"gp":"gg_N1_00"},{"id":"g1_141","t":"～ないものだろうか","ko":"어떻게 ~할 수 없을까","cat":"문말표현","conn":[{"w":"동사 가능형의 ない형","f":"取れない + ものだろうか"},{"w":"동사 ない형","f":"変わらない + ものだろうか"}],"rule":["1. 1그룹 동사는 어미 う단을 え단으로 바꾸고 る를 붙여 가능형을 만든다: 取る → 取れる.","2. 가능형의 る를 ない로 바꾼다: 取れる → 取れない.","3. ない형 뒤에 ものだろうか를 붙인다: 取れないものだろうか.","4. 2그룹 동사의 가능형은 られる: 食べる → 食べられないものだろうか."],"why":"","nu":"실현이 쉽지 않은 일을 어떻게든 이룰 방법이 없을까 하고 강하게 바라는 마음을 나타낸다. なんとか, どうにか와 함께 쓰는 경우가 많고, 주로 가능형의 부정에 붙는다. 혼잣말이나 글에서 많이 쓰며, 회화에서는 ～ないものか, ～ないかな도 쓴다. 단순한 의문문이 아니라 바람의 표현이다.","cmp":[{"g":"～ないものか","d":"같은 뜻으로, ものだろうか보다 조금 짧고 감정이 직접적이다."}],"ex":[{"jp":"なんとかもう少[すこ]し安[やす]く買[か]えないものだろうか。","ko":"어떻게 좀 더 싸게 살 수 없을까."},{"jp":"この渋滞[じゅうたい]、どうにかならないものだろうか。","ko":"이 교통 체증, 어떻게 안 될까."},{"jp":"もっと早[はや]く家[いえ]に帰[かえ]れないものだろうか。","ko":"좀 더 일찍 집에 돌아갈 수 없을까."}],"dr":[{"t":"make","q":"会う → (가능형) ～ないものだろうか","a":"会えないものだろうか","hint":"う → え + る(가능형), る → ない, + ものだろうか"},{"t":"make","q":"休む → (가능형) ～ないものだろうか","a":"休めないものだろうか","hint":"む → め + る(가능형), る → ない, + ものだろうか"},{"t":"fill","q":"なんとかこの問題[もんだい]を解決[かいけつ]できない（　）。","a":"ものだろうか","opts":["ものだろうか","ものだから","ものなら","ものの"]}],"src":["https://bunpro.jp/grammar_points/851"],"vf":1,"u":3,"g":1,"gp":"gg_N1_00"},{"id":"g1_148","t":"～ようか～まいか","ko":"~할까 말까","cat":"문말표현","conn":[{"w":"1그룹 동사","f":"話そう + か + 話す + まいか"},{"w":"2그룹 동사","f":"辞めよう + か + 辞めまい(辞めるまい) + か"},{"w":"する","f":"しよう + か + しまい(するまい) + か"}],"rule":["1. 1그룹 동사는 어미 う단을 お단으로 바꾸고 う를 붙여 의향형을 만든다: 話す → 話そう. 2그룹은 る를 빼고 よう: 辞める → 辞めよう.","2. 의향형 뒤에 か를 붙인다: 話そうか.","3. 같은 동사에 まい를 붙인다. 1그룹은 사전형 + まい(話すまい), 2그룹은 る를 뺀 형태나 사전형 + まい(辞めまい・辞めるまい)이다.","4. 다시 か를 붙인다: 話そうか話すまいか. 뒤에 迷う・悩む 같은 말이 온다."],"why":"의향형(~하자) + か와 부정 의지의 まい + か를 나란히 놓아 '할까, 하지 말까'를 나타낸다.","nu":"어떤 행동을 할지 말지 결정하지 못하고 망설이는 모습을 나타낸다. 문어적이고 딱딱한 표현으로, 뒤에는 迷う・悩む・考える・決められない 등이 온다. 회화에서는 ～ようかどうしようか, ～ようかやめようか가 더 자연스럽다.","cmp":[{"g":"～かどうか","d":"'~인지 아닌지'로 의지와 관계없이 일반 사실에도 쓴다. ようか～まいか는 말하는 사람의 의지적 망설임에 쓴다."},{"g":"～ようが～まいが","d":"'~하든 말든'으로 결과는 변하지 않는다는 뜻. ようか～まいか는 망설임이다."}],"ex":[{"jp":"彼女[かのじょ]に本当[ほんとう]のことを言[い]おうか言[い]うまいか、迷[まよ]っている。","ko":"그녀에게 사실을 말할까 말까 망설이고 있다."},{"jp":"留学[りゅうがく]しようかするまいか、一晩中[ひとばんじゅう]悩[なや]んだ。","ko":"유학을 갈까 말까 밤새 고민했다."},{"jp":"会社[かいしゃ]を辞[や]めようか辞[や]めまいか、まだ決[き]められない。","ko":"회사를 그만둘까 말까 아직 정하지 못했다."}],"dr":[{"t":"make","q":"行く → ～ようか～まいか","a":"行こうか行くまいか","hint":"의향형 行こう + か + 사전형 + まいか"},{"t":"make","q":"買う → ～ようか～まいか","a":"買おうか買うまいか","hint":"う → おう(의향형) + か + 買う + まいか"},{"t":"fill","q":"パーティーに行[い]こうか行[い]く（　）、まだ迷[まよ]っている。","a":"まいか","opts":["まいか","まいが","ばかりか","ことか"]}],"src":["https://www.gyanmirai.com/jlpt/jlpt-n2/grammar-study/youkamaika","https://bunpro.jp/grammar_points/343"],"vf":1,"u":3,"g":1,"gp":"gg_N1_01"},{"id":"g1_160","t":"～ときりがない","ko":"~하자면 끝이 없다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"気にする + ときりがない"},{"w":"동사 사전형","f":"言い出す + ときりがない"}],"rule":["1. 동사는 사전형을 그대로 쓴다: 気にする.","2. 사전형 뒤에 조건의 と를 붙인다: 気にすると.","3. 그 뒤에 きりがない를 붙인다: 気にするときりがない."],"why":"きり(切り, 끝·한도) + が + ない. '~하면 끝이 없다'라는 구성이다.","nu":"어떤 일을 시작하면 끝없이 이어지니 적당히 해야 한다는 느낌으로 쓴다. 欲しいもの, 心配, 文句, 細かいこと처럼 계속 늘어날 수 있는 일과 잘 어울린다. 회화에서 자주 쓰며 ～たらきりがない, ～ばきりがない도 같은 뜻이다.","cmp":[{"g":"～たら / ～ばきりがない","d":"조건 표현만 다르고 뜻은 같다(言い出したらきりがない)."},{"g":"～てしかたがない","d":"감정·감각이 참을 수 없을 정도라는 뜻. きりがない는 '끝이 없다'는 수량·연속을 말한다."}],"ex":[{"jp":"細[こま]かいことを気[き]にするときりがない。","ko":"사소한 것을 신경 쓰자면 끝이 없다."},{"jp":"欲[ほ]しいものを言[い]い出[だ]すときりがない。","ko":"갖고 싶은 것을 말하기 시작하면 끝이 없다."},{"jp":"心配[しんぱい]し始[はじ]めるときりがないから、もう寝[ね]よう。","ko":"걱정하기 시작하면 끝이 없으니까 이제 자자."}],"dr":[{"t":"make","q":"比べる → ～ときりがない","a":"比べるときりがない","hint":"사전형 + と + きりがない"},{"t":"make","q":"数えます → ～ときりがない","a":"数えるときりがない","hint":"ます형을 사전형으로(数え → 数える) + ときりがない"},{"t":"fill","q":"人[ひと]と比[くら]べると（　）。","a":"きりがない","opts":["きりがない","しかたがない","ほかない","にすぎない"]}],"src":["https://www.vnjpclub.com/en/n1-grammar/bakiriga-nai.html","https://aiueo.cc/pages_v2/en/grammar/web/621.php"],"vf":1,"u":3,"g":1,"gp":"gg_N1_01"},{"id":"g1_165","t":"～にはあたらない","ko":"~할 것까지는 없다, ~할 일은 아니다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"驚く + にはあたらない"},{"w":"명사(する동사)","f":"非難 + にはあたらない"}],"rule":["1. 동사는 사전형 그대로 둔다: 驚く.","2. 사전형 뒤에 にはあたらない를 붙인다: 驚くにはあたらない.","3. 명사로 쓸 때는 명사에 바로 붙인다: 非難にはあたらない."],"why":"동사 あたる(当たる, 해당하다)의 부정형 あたらない에 に + は가 붙은 형태로, '~에는 해당하지 않는다', 즉 그럴 만한 일이 아니라는 뜻이다.","nu":"상대나 세상이 보이는 반응(놀람, 비난, 칭찬, 걱정 등)이 그 정도까지 할 일은 아니라고 평가하는 딱딱한 표현이다. 驚く・心配する・悲観する・非難する・責める・感心する 등 감정·평가를 나타내는 동사와 주로 쓰인다. 일반적인 행동 동사(行く, 食べる 등)와는 잘 쓰지 않는다. 회화에서는 ~する必要はない, ~ことはない가 자연스럽다.","cmp":[{"g":"～ことはない","d":"'~할 필요 없다'는 일상 표현으로 어떤 동사에도 쓰며 상대에게 조언하는 느낌이다. にはあたらない는 감정·평가 동사에 한정되고 문어적이다."},{"g":"～までもない","d":"너무 당연하거나 사소해서 그 행동을 할 필요조차 없다는 뜻이다."}],"ex":[{"jp":"彼[かれ]が優勝[ゆうしょう]したのは、驚[おどろ]くにはあたらない。毎日[まいにち]練習[れんしゅう]していたのだから。","ko":"그가 우승한 것은 놀랄 일이 아니다. 매일 연습했으니까."},{"jp":"一度[いちど]の失敗[しっぱい]で悲観[ひかん]するにはあたらない。","ko":"한 번의 실패로 비관할 것까지는 없다."},{"jp":"子供[こども]のしたことだから、そこまで責[せ]めるにはあたらない。","ko":"아이가 한 일이니 그렇게까지 탓할 일은 아니다."}],"dr":[{"t":"make","q":"心配する → ～にはあたらない","a":"心配するにはあたらない","hint":"동사 사전형 + にはあたらない"},{"t":"make","q":"非難 → ～にはあたらない","a":"非難にはあたらない","hint":"명사 + にはあたらない"},{"t":"fill","q":"その程度[ていど]のミスなら、驚[おどろ]く（　）。","a":"にはあたらない","opts":["にはあたらない","に違いない","に越したことはない","わけにはいかない"]}],"src":["https://bunpro.jp/grammar_points/812"],"vf":1,"u":4,"g":1,"gp":"gg_N1_01"},{"id":"g1_172","t":"～までもない","ko":"~할 것까지도 없다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"言う + までもない"},{"w":"동사 사전형","f":"説明する + までもない"}],"rule":["1. 동사는 사전형 그대로 둔다: 言う.","2. 사전형 뒤에 までもない를 붙인다: 言うまでもない.","3. 부사처럼 쓸 때는 までもなく가 된다: 言うまでもなく."],"why":"조사 まで(~까지) + も + ない로, '그 행동까지 할 필요도 없다'는 뜻이 구성 그대로 드러난다.","nu":"너무 당연하거나 사소해서 일부러 그 행동을 할 필요가 없다는 뜻이다. 言うまでもない(말할 것도 없다), 言うまでもなく(말할 것도 없이)가 특히 자주 쓰인다. 뒤에 명사를 꾸밀 때는 までもないこと처럼 쓴다. 다소 딱딱하지만 회화에서도 쓴다.","cmp":[{"g":"～ことはない","d":"'~할 필요 없다'고 상대에게 조언·위로하는 느낌이다. までもない는 정도가 뻔해서 그럴 필요가 없다는 평가다."},{"g":"～にはあたらない","d":"놀람·비난 같은 반응이 그럴 만한 일이 아니라는 평가로, 감정·평가 동사에 한정된다."}],"ex":[{"jp":"健康[けんこう]が大切[たいせつ]なのは言[い]うまでもない。","ko":"건강이 중요하다는 것은 말할 것도 없다."},{"jp":"この程度[ていど]のけがなら、病院[びょういん]へ行[い]くまでもない。","ko":"이 정도 상처라면 병원에 갈 것까지도 없다."},{"jp":"わざわざ電話[でんわ]するまでもないことだから、メールで知[し]らせた。","ko":"일부러 전화할 것까지도 없는 일이라 메일로 알렸다."}],"dr":[{"t":"make","q":"調べる → ～までもない","a":"調べるまでもない","hint":"동사 사전형 + までもない"},{"t":"make","q":"言う → ～までもなく","a":"言うまでもなく","hint":"사전형 + までもなく(부사형)"},{"t":"fill","q":"簡単[かんたん]な問題[もんだい]だから、先生[せんせい]に聞[き]く（　）。","a":"までもない","opts":["までもない","ほかない","に違いない","ばかりだ"]}],"src":["https://bunpro.jp/grammar_points/までもない"],"vf":1,"u":4,"g":1,"gp":"gg_N1_01"},{"id":"g1_173","t":"～ものとする","ko":"~하는 것으로 한다, ~한 것으로 간주한다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"支払う + ものとする"},{"w":"동사 ない형","f":"認めない + ものとする"},{"w":"동사 た형","f":"欠席した + ものとする"}],"rule":["1. 동사는 사전형(또는 ない형)을 그대로 둔다: 支払う.","2. 그 뒤에 ものとする를 붙여 규정으로 만든다: 支払うものとする.","3. 동사 た형에 붙이면 '~한 것으로 간주한다'가 된다: 欠席したものとする."],"why":"","nu":"법률·계약서·규칙 등에서 의무나 약속 사항을 정해 둘 때 쓰는 매우 딱딱한 문어체다. 일상 대화에서는 쓰지 않는다. た형과 함께 쓰면 사실과 상관없이 그렇게 취급한다는 '간주'의 뜻이 된다. 명사에는 직접 붙지 않으며, 명사로 정할 때는 ~とする(有効とする)를 쓴다.","cmp":[{"g":"～こととする","d":"말하는 사람·조직이 결정했다는 뜻이 강하다. ものとする는 규정·조항의 내용으로 정해 둔다는 느낌이다."},{"g":"～べきだ","d":"당위를 말하는 일반 표현으로 규정문 형식이 아니다."}],"ex":[{"jp":"料金[りょうきん]は月末[げつまつ]までに支払[しはら]うものとする。","ko":"요금은 월말까지 지불하는 것으로 한다."},{"jp":"この契約[けいやく]は、毎年[まいとし]自動的[じどうてき]に更新[こうしん]されるものとする。","ko":"이 계약은 매년 자동으로 갱신되는 것으로 한다."},{"jp":"連絡[れんらく]なしに休[やす]んだ場合[ばあい]は、欠席[けっせき]したものとする。","ko":"연락 없이 쉰 경우에는 결석한 것으로 간주한다."}],"dr":[{"t":"make","q":"返す → ～ものとする","a":"返すものとする","hint":"동사 사전형 + ものとする"},{"t":"make","q":"辞退する(た형) → ～ものとする","a":"辞退したものとする","hint":"た형 + ものとする = 간주"},{"t":"fill","q":"会員[かいいん]は年[ねん]に一度[いちど]、会費[かいひ]を納[おさ]める（　）。","a":"ものとする","opts":["ものとする","ものか","ものの","ものだから"]}],"src":["https://bunpro.jp/grammar_points/987"],"vf":1,"u":4,"g":1,"gp":"gg_N1_01"},{"id":"g1_175","t":"～始末だ","ko":"(결국) ~하는 꼴이다, ~하는 지경이다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"泣き出す + 始末だ"},{"w":"동사 ない형","f":"連絡もしない + 始末だ"},{"w":"この / その","f":"この + 始末だ"}],"rule":["1. 동사는 사전형 그대로 둔다: 泣き出す.","2. 사전형 뒤에 始末だ를 붙인다: 泣き出す始末だ.","3. 과거 일을 말할 때는 だ를 だった로 바꾼다: 泣き出す始末だった."],"why":"","nu":"좋지 않은 일이 계속 이어진 끝에 결국 더 나쁜 결과가 되었다고 비판·한탄하는 표현이다. 앞에 경위(~て、~て)를 쓰고 마지막에 始末だ로 맺는 경우가 많으며, 말하는 사람의 못마땅한 감정이 담긴다. 좋은 결과에는 쓰지 않는다. この始末だ(이 꼴이다)처럼 단독으로도 쓴다.","cmp":[{"g":"～結果","d":"좋고 나쁨과 상관없이 결과를 중립적으로 말한다."},{"g":"～羽目になる","d":"원치 않는 곤란한 상황에 처하게 되었다는 뜻으로, 주로 자기 자신의 일에 쓴다. 始末だ는 남의 행동을 비판할 때 잘 쓴다."}],"ex":[{"jp":"弟[おとうと]は遊[あそ]んでばかりで、ついに学校[がっこう]をやめる始末[しまつ]だ。","ko":"남동생은 놀기만 하다가 결국 학교를 그만두는 꼴이 됐다."},{"jp":"彼[かれ]は何度[なんど]注意[ちゅうい]しても遅刻[ちこく]し、最近[さいきん]は連絡[れんらく]もしない始末[しまつ]だ。","ko":"그는 몇 번을 주의해도 지각하고, 요즘은 연락도 안 하는 지경이다."},{"jp":"娘[むすめ]はゲームを取[と]り上[あ]げられて、泣[な]き出[だ]す始末[しまつ]だった。","ko":"딸은 게임기를 빼앗기자 울음을 터뜨리는 지경이었다."}],"dr":[{"t":"make","q":"倒れる → ～始末だ","a":"倒れる始末だ","hint":"동사 사전형 + 始末だ"},{"t":"make","q":"謝らない → ～始末だ","a":"謝らない始末だ","hint":"ない형 + 始末だ"},{"t":"fill","q":"借金[しゃっきん]を重[かさ]ね、とうとう家[いえ]まで売[う]る（　）。","a":"始末だ","opts":["始末だ","おかげだ","次第だ","ところだ"]}],"src":["https://nihongokyoshi-net.com/2019/07/08/jlptn1-grammar-shimatsuda/","https://bunpro.jp/grammar_points/940"],"vf":1,"u":4,"g":1,"gp":"gg_N1_01"},{"id":"g1_177","t":"いつまで～のやら","ko":"언제까지 ~할는지 (모르겠다)","cat":"문말표현","conn":[{"w":"동사 보통형","f":"いつまで + 降る + のやら"},{"w":"い형용사","f":"いつまで + 寒い + のやら"},{"w":"な형용사 / 명사","f":"いつまで + 暇な + のやら"}],"rule":["1. 문장 앞에 いつまで를 둔다.","2. 동사는 보통형 그대로 쓴다: いつまで降る.","3. 끝에 のやら를 붙인다: いつまで降るのやら.","4. な형용사·명사는 だ를 な로 바꾸어 のやら를 붙인다: 暇なのやら."],"why":"","nu":"어떤 상태가 언제까지 계속될지 알 수 없다는 불안·짜증·한탄을 혼잣말처럼 나타낸다. のやら로 문장을 끝내도 되고, 뒤에 わからない 등을 이어도 된다. 주로 좋지 않은 상태의 지속에 쓰며, 다소 예스럽고 문어적인 느낌이 있다.","cmp":[{"g":"～のだろうか","d":"단순한 의문 '~일까'로, 감정적 한탄의 느낌은 약하다."},{"g":"AのやらBのやら","d":"A인지 B인지 알 수 없다는 뜻으로, 두 가지를 나열한다."}],"ex":[{"jp":"この雨[あめ]はいつまで降[ふ]るのやら。","ko":"이 비는 언제까지 내릴는지."},{"jp":"息子[むすこ]はいつまでゲームをしているのやら。","ko":"아들은 언제까지 게임을 하고 있을는지."},{"jp":"この暑[あつ]さはいつまで続[つづ]くのやら、見当[けんとう]もつかない。","ko":"이 더위가 언제까지 이어질지 짐작도 안 된다."}],"dr":[{"t":"make","q":"続く → いつまで～のやら","a":"いつまで続くのやら","hint":"いつまで + 보통형 + のやら"},{"t":"make","q":"寒い → いつまで～のやら","a":"いつまで寒いのやら","hint":"い형용사 보통형 + のやら"},{"t":"fill","q":"彼[かれ]の長[なが]い話[はなし]は、いつまで続[つづ]く（　）。","a":"のやら","opts":["のやら","ものか","ことだ","わけだ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/のやら-ものやら-ことやら-no-yara-mono-yara-koto-yara-meaning/"],"vf":1,"u":4,"g":1,"gp":"gg_N1_01"},{"id":"g1_187","t":"～つもりだ","ko":"~할 생각이다, ~할 작정이다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"留学する + つもりだ"},{"w":"동사 ない형","f":"行かない + つもりだ"},{"w":"명사","f":"冗談の + つもりだ (~한 셈, ~라고 생각함)"}],"rule":["1. 동사를 사전형(또는 ない형)으로 둔다: 留学する.","2. 그 뒤에 명사 つもり를 붙인다: 留学するつもり.","3. 끝에 だ(정중하게는 です)를 붙여 문장을 맺는다: 留学するつもりだ."],"why":"","nu":"말하는 사람이 미리 정해 둔 의도·계획을 나타낸다. 제3자의 의도는 彼は留学するつもりだと言っていた처럼 전해 들은 형태로 말하는 것이 자연스럽다. 윗사람에게 직접 ～つもりですか라고 묻는 것은 실례로 들릴 수 있다. '하지 않을 생각'은 行かないつもりだ가 기본이고, 行くつもりはない는 더 강한 부정이다. 과거형·ている + つもり는 '(실제와 달리) 자기는 ~했다고 생각한다'라는 뜻이 된다.","cmp":[{"g":"～(よ)うと思う","d":"그 자리에서 생각한 의지에도 쓴다. つもりだ는 이미 정해 둔 계획이라는 느낌이 강하다."},{"g":"～予定だ","d":"공식적으로 정해진 일정. 개인의 의도보다 객관적인 계획을 나타낸다."}],"ex":[{"jp":"来年[らいねん]、日本[にほん]に留学[りゅうがく]するつもりだ。","ko":"내년에 일본에 유학할 생각이다."},{"jp":"今日[きょう]はどこにも行[い]かないつもりです。","ko":"오늘은 아무 데도 안 갈 생각입니다."},{"jp":"冗談[じょうだん]のつもりだったが、彼[かれ]を怒[おこ]らせてしまった。","ko":"농담으로 한 말이었는데 그를 화나게 하고 말았다."}],"dr":[{"t":"make","q":"結婚する → ～つもりだ","a":"結婚するつもりだ","hint":"동사 사전형 + つもりだ"},{"t":"make","q":"タバコを吸う(부정) → ～つもりだ","a":"タバコを吸わないつもりだ","hint":"ない형 + つもりだ: う → わない"},{"t":"fill","q":"夏休[なつやす]みは北海道[ほっかいどう]へ行[い]く（　）です。","a":"つもり","opts":["つもり","ところ","わけ","はず"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201212.html","https://bunpro.jp/ja/grammar_points/%E3%81%A4%E3%82%82%E3%82%8A%E3%81%A0"],"vf":1,"u":5,"g":1,"gp":"gg_N1_01"},{"id":"g1_217","t":"～なくもない","ko":"~하지 않는 것도 아니다, ~할 수도 있다","cat":"문말표현","conn":[{"w":"동사 ない형","f":"食べない → 食べなくもない"},{"w":"1그룹 동사","f":"読まない → 読まなくもない"},{"w":"가능 동사","f":"考えられない → 考えられなくもない"},{"w":"불규칙 동사","f":"来ない → 来なくもない / しない → しなくもない"}],"rule":["1. 동사를 ない형으로 만든다(2그룹은 る를 떼고 ない, 1그룹은 어미 う단을 あ단으로 바꾸고 ない): 食べる → 食べない.","2. ない의 마지막 い를 く로 바꾼다: ない → なく.","3. 그 뒤에 もない를 붙인다: 食べなくもない."],"why":"부정형 なく + 조사 も + ない로 이루어진 이중 부정이다. '~하지 않는 것도 아니다'라는 뜻이 되어 소극적인 긍정을 나타낸다.","nu":"완전히 긍정하지 않고 '조건에 따라서는 ~할 수도 있다', '그렇게 느껴지지 않는 것도 아니다'처럼 망설이며 인정할 때 쓴다. 気がしなくもない, 考えられなくもない, わからなくもない 형태가 자주 쓰인다. 같은 뜻으로 ～ないでもない, ～ないこともない가 있다. 한국어 '~할 수도 있다'처럼 적극적인 가능을 말하는 표현이 아니므로, 분명히 할 수 있는 일에는 쓰지 않는다.","cmp":[{"g":"～ないこともない","d":"뜻은 거의 같고 회화에서 더 흔하다. なくもない는 조금 더 짧고 딱딱한 느낌이다."},{"g":"～ないでもない","d":"ない형 + でもない. 역시 소극적 긍정으로 뜻 차이는 거의 없다."}],"ex":[{"jp":"少[すこ]しだけなら、食[た]べなくもない。","ko":"조금만이라면 먹지 못할 것도 없다."},{"jp":"彼[かれ]の気持[きも]ちもわからなくもない。","ko":"그의 기분도 이해 못 하는 건 아니다."},{"jp":"言[い]われてみれば、そんな気[き]がしなくもない。","ko":"듣고 보니 그런 느낌이 들지 않는 것도 아니다."}],"dr":[{"t":"make","q":"読む → ～なくもない","a":"読まなくもない","hint":"1그룹: む를 ま로 바꿔 読まない, ない의 い를 く로 + もない"},{"t":"make","q":"来る → ～なくもない","a":"来なくもない","hint":"来る의 ない형은 来ない(こない), ない → なく + もない"},{"t":"fill","q":"時間[じかん]があれば、手伝[てつだ]わ（　）。","a":"なくもない","opts":["なくもない","ざるを得ない","ずにはいられない","てはならない"]}],"src":[],"vf":0,"u":5,"g":1,"gp":"gg_N1_01"},{"id":"g1_220","t":"～に堪えない","ko":"차마 ~할 수 없다 / ~을 금할 수 없다","cat":"문말표현","conn":[{"w":"동사 사전형(見る・聞く・読む 등)","f":"見る + に堪えない"},{"w":"감정 명사(感謝・遺憾・同情 등)","f":"感謝 + に堪えない"}],"rule":["1. 동사 사전형 또는 감정 명사에 조사 に를 붙인다: 見るに.","2. 2그룹 동사 堪える(たえる)의 어미 る를 떼고 ない를 붙인다: 堪える → 堪えない.","3. 합치면 見るに堪えない / 感謝に堪えない."],"why":"堪える(견디다, 감당하다)의 부정형이다. '보는 것을 감당할 수 없다', '감사하는 마음을 다 감당할 수 없다'에서 두 가지 뜻이 나온다.","nu":"뜻이 둘이다. ① 見る・聞く・読む + に堪えない: 내용이 너무 심하거나 수준이 낮아 차마 보거나 들을 수 없다(비난). ② 感謝・遺憾・同情・喜び 등 + に堪えない: 그 감정을 억누를 수 없을 만큼 강하게 느낀다. ②는 인사말·성명 같은 매우 격식 있는 문어체이다. ①에 쓰는 동사는 거의 정해져 있어서 아무 동사에나 붙이지 않는다.","cmp":[{"g":"～に堪える","d":"긍정형. 見るに堪える처럼 '~할 만한 가치가 있다'는 뜻이다."},{"g":"～てならない","d":"감정이 저절로 강하게 드는 것을 말하는 일반적 표현(心配でならない). に堪えない의 감정 용법은 훨씬 격식적이다."}],"ex":[{"jp":"あの番組[ばんぐみ]は内容[ないよう]がひどくて、見[み]るに堪[た]えない。","ko":"그 프로그램은 내용이 형편없어서 차마 볼 수가 없다."},{"jp":"人[ひと]の悪口[わるくち]ばかりで、聞[き]くに堪[た]えない話[はなし]だった。","ko":"남의 험담뿐이어서 차마 들을 수 없는 이야기였다."},{"jp":"皆様[みなさま]のご支援[しえん]には感謝[かんしゃ]に堪[た]えません。","ko":"여러분의 지원에 감사를 금할 수 없습니다."}],"dr":[{"t":"make","q":"聞く → ～に堪えない","a":"聞くに堪えない","hint":"사전형 + に + 堪える의 る를 떼고 ない"},{"t":"make","q":"遺憾 → ～に堪えない","a":"遺憾に堪えない","hint":"감정 명사 + に + 堪えない"},{"t":"fill","q":"事故[じこ]の現場[げんば]は見[み]る（　）ほどひどい状態[じょうたい]だった。","a":"に堪えない","opts":["に堪えない","に越したことはない","に限る","にほかならない"]}],"src":[],"vf":0,"u":5,"g":1,"gp":"gg_N1_01"},{"id":"g1_234","t":"～までだ","ko":"~할 뿐이다, ~하면 그만이다 / ~했을 뿐이다","cat":"문말표현","conn":[{"w":"동사 사전형","f":"歩く + までだ"},{"w":"동사 た형","f":"聞いた + までだ"}],"rule":["1. 동사 사전형 + までだ: 다른 방법이 없으면 그렇게 할 뿐이다. 사전형을 그대로 둔다: 歩く → 歩くまでだ.","2. 동사 た형 + までだ: 특별한 의도 없이 그냥 그렇게 했을 뿐이다. 1그룹 く는 いた로 바꾼다: 聞く → 聞いた → 聞いたまでだ.","3. 같은 뜻으로 までのことだ도 쓴다: 歩くまでのことだ."],"why":"","nu":"사전형 용법은 앞에 ～なら, ～ても 같은 조건이 오고 '그렇게 되면 ~하면 그만이다'라는 각오나 담담한 태도를 나타낸다(だめなら、またやり直すまでだ). た형 용법은 '단지 ~했을 뿐 깊은 뜻은 없다'고 변명하거나 겸손하게 말할 때 쓴다(思ったことを言ったまでだ). '~까지이다'라는 시간·범위의 まで + だ(会議は五時までだ)와는 다른 문법이므로 구별한다.","cmp":[{"g":"～しかない","d":"사전형 + しかない. '~할 수밖에 없다'는 어쩔 수 없음이 강하다. までだ는 '그러면 그만'이라는 담담한 각오가 들어간다."},{"g":"～だけだ","d":"た형 + だけだ도 '~했을 뿐'. たまでだ는 더 딱딱하고 변명하는 느낌이 있다."}],"ex":[{"jp":"バスがないなら、駅[えき]まで歩[ある]くまでだ。","ko":"버스가 없으면 역까지 걸어가면 그만이다."},{"jp":"今年[ことし]がだめなら、来年[らいねん]もう一度[いちど]受[う]けるまでだ。","ko":"올해가 안 되면 내년에 한 번 더 보면 그만이다."},{"jp":"怒[おこ]らないで。本当[ほんとう]のことを言[い]ったまでだよ。","ko":"화내지 마. 사실을 말했을 뿐이야."}],"dr":[{"t":"make","q":"自分でやる → ～までだ (각오)","a":"自分でやるまでだ","hint":"동사 사전형 + までだ"},{"t":"make","q":"聞く → ～までだ (그냥 했을 뿐)","a":"聞いたまでだ","hint":"く를 いた로 바꾼 た형 + までだ"},{"t":"fill","q":"誰[だれ]も手伝[てつだ]ってくれないなら、一人[ひとり]でやる（　）。","a":"までだ","opts":["までだ","ものを","に至った","ぶりだ"]}],"src":[],"vf":0,"u":5,"g":1,"gp":"gg_N1_01"},{"id":"g1_031","t":"～たる～","ko":"~인 (~의 지위에 있는)","cat":"명사화·수식","conn":[{"w":"명사 + 명사","f":"教師 + たる + 者"},{"w":"명사 + もの","f":"医者 + たる + もの"}],"rule":["1. 지위·자격을 나타내는 명사1을 둔다(教師).","2. 'である' 자리에 たる를 붙인다(教師である者 → 教師たる者).","3. 뒤에 명사2(者・もの・人 등)를 둔다. 문장 뒤쪽에는 보통 '~べきだ, ~なければならない'가 온다."],"why":"고전 단정 조동사 たり의 연체형이 たる다. 현대어의 '~である'에 해당한다.","nu":"딱딱한 문어체·연설체. '그런 지위에 있는 사람이라면 마땅히'라는 당위를 말할 때 쓴다. 教師・医者・親・リーダー 같은 사회적 역할을 나타내는 명사에 붙는다. 일상 회화에서는 거의 쓰지 않는다.","cmp":[{"g":"～として","d":"教師として働く처럼 자격·입장을 나타내는 일반 표현. たる는 '그 지위에 걸맞게 해야 한다'는 당위가 강하다."}],"ex":[{"jp":"教師[きょうし]たる者[もの]、生徒[せいと]の手本[てほん]にならなければならない。","ko":"교사인 자는 학생의 본보기가 되어야 한다."},{"jp":"医者[いしゃ]たる者[もの]は、患者[かんじゃ]の命[いのち]を第一[だいいち]に考[かんが]えるべきだ。","ko":"의사인 자는 환자의 생명을 가장 먼저 생각해야 한다."},{"jp":"一国[いっこく]のリーダーたる人[ひと]が、嘘[うそ]をついてはいけない。","ko":"한 나라의 지도자인 사람이 거짓말을 해서는 안 된다."}],"dr":[{"t":"make","q":"教師である者 → たる","a":"教師たる者","hint":"である 자리에 たる"},{"t":"make","q":"医者である者 → たる","a":"医者たる者","hint":"である 자리에 たる"},{"t":"fill","q":"社長[しゃちょう]（　）者[もの]、社員[しゃいん]の生活[せいかつ]を守[まも]るべきだ。","a":"たる","opts":["たる","にとって","について","によって"]}],"src":["https://nihongokyoshi-net.com/2019/06/18/jlptn1-grammar-tarumono/","https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%8B"],"vf":1,"u":6,"g":1,"gp":"gg_N1_01"},{"id":"g1_037","t":"～という～","ko":"~라는 (이름·내용을 밝히는) ~","cat":"명사화·수식","conn":[{"w":"명사 + 명사","f":"ポチ + という + 犬"},{"w":"보통형 문장 + 명사(내용)","f":"会社を辞める + という + 話"}],"rule":["1. 앞자리 명사(N1)에 이름이나 구체적인 내용을 넣는다(ポチ).","2. N1 뒤에 という를 그대로 붙인다. 형태 변화는 없다.","3. 뒤에 그 이름이 속하는 종류의 명사(N2)를 놓는다(ポチという犬)."],"why":"と(인용 조사) + いう(言う, 말하다)로 이루어져 'N1이라고 말하는 N2', 곧 'N1이라는 N2'가 된다.","nu":"듣는 사람이 잘 모를 수 있는 이름(사람·가게·지명)을 소개하거나, 話・うわさ・ニュース 같은 명사의 내용을 밝힐 때 쓴다. 회화에서는 って・っていう로 줄이는 일이 많다. 한국어 '~라는'처럼 쓰이지만 서로 잘 아는 대상에는 보통 붙이지 않는다.","cmp":[{"g":"～っていう","d":"という의 회화체 축약형으로 뜻은 같다. 격식 있는 글이나 자리에서는 という를 쓴다."}],"ex":[{"jp":"ポチという犬[いぬ]を飼[か]っています。","ko":"포치라는 개를 키우고 있습니다."},{"jp":"田中[たなか]さんという人[ひと]から電話[でんわ]がありました。","ko":"다나카 씨라는 사람에게서 전화가 왔었습니다."},{"jp":"彼[かれ]が会社[かいしゃ]を辞[や]めるという話[はなし]を聞[き]いた。","ko":"그가 회사를 그만둔다는 이야기를 들었다."}],"dr":[{"t":"make","q":"ポチ・犬 → ～という～","a":"ポチという犬","hint":"이름 + という + 종류 명사"},{"t":"make","q":"さくら・店 → ～という～","a":"さくらという店","hint":"이름 + という + 종류 명사"},{"t":"fill","q":"山田[やまだ]さん（　）人[ひと]から電話[でんわ]がありました。","a":"という","opts":["という","として","について","によって"]}],"src":["https://cotoacademy.com/jlpt-grammar-to-iu-in-japanese/"],"vf":1,"u":6,"g":1,"gp":"gg_N1_02"},{"id":"g1_039","t":"～というもの","ko":"~라는 것(은), ~란 (본질)","cat":"명사화·수식","conn":[{"w":"명사","f":"子供 + というもの(は)"}],"rule":["1. 성질을 말하고 싶은 명사를 놓고 조사 は를 붙인다(子供は).","2. 명사와 は 사이에 というもの를 끼워 넣는다(子供というものは).","3. 문장 끝은 흔히 ～ものだ로 맺어 일반적인 성질임을 나타낸다."],"why":"","nu":"개별 대상이 아니라 그 명사 전체가 일반적으로 지닌 성질·본질을 말할 때 쓴다. 감회나 교훈을 담은 말투가 되며 뒤에 ～ものだ가 자주 온다. 'この一年というもの'처럼 기간 명사에 붙어 '그 기간 내내'를 뜻하는 다른 용법도 있다.","cmp":[{"g":"～ということ","d":"ということ는 사실이나 내용을 명사화한다. というもの는 대상 자체의 본질·성질을 말한다."}],"ex":[{"jp":"子供[こども]というものは、よく遊[あそ]ぶものだ。","ko":"아이란 잘 노는 법이다."},{"jp":"時間[じかん]というものは、大切[たいせつ]に使[つか]わなければならない。","ko":"시간이라는 것은 소중히 써야 한다."},{"jp":"親[おや]というものは、いつも子供[こども]の心配[しんぱい]をしている。","ko":"부모란 늘 자식 걱정을 하고 있다."}],"dr":[{"t":"make","q":"子供 → ～というものは","a":"子供というものは","hint":"명사 + というもの + は"},{"t":"make","q":"人生 → ～というものは","a":"人生というものは","hint":"명사 + というもの + は"},{"t":"fill","q":"人間[にんげん]（　）は、一人[ひとり]では生[い]きられないものだ。","a":"というもの","opts":["というもの","ということ","というところ","というわけ"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/language/201906.html"],"vf":1,"u":6,"g":1,"gp":"gg_N1_02"},{"id":"g1_057","t":"～にあるまじき","ko":"~로서 있어서는 안 될, ~답지 못한","cat":"명사화·수식","conn":[{"w":"명사1(사람의 입장) + 명사2","f":"教師 + にあるまじき + 発言"}],"rule":["1. 직업·입장을 나타내는 명사1을 쓴다(教師).","2. 그 뒤에 にあるまじき를 붙인다(教師にあるまじき).","3. 마지막에 행동·말을 나타내는 명사2를 놓는다(教師にあるまじき発言)."],"why":"まじき는 고전 조동사 まじ의 연체형으로 '~해서는 안 될'이라는 뜻이며, ある에 붙어 あるまじき(있어서는 안 될)가 된다. 연체형이라 뒤에 반드시 명사가 온다.","nu":"문어적이고 강한 비난을 담은 표현이다. 명사1에는 教師・医者・政治家・社会人처럼 지켜야 할 기준이 있는 입장이 오고, 명사2에는 行為・発言・態度・振る舞い 같은 말이 온다. 'Nとしてあるまじき'라고도 한다. 문장 끝에서 단독으로 끝내지 않고 명사를 꾸미는 형태로 쓴다.","cmp":[{"g":"～らしくない","d":"회화체로 '~답지 않다'. にあるまじき는 문어적이며 '도저히 용납할 수 없다'는 강한 비난이 있다."}],"ex":[{"jp":"それは教師[きょうし]にあるまじき発言[はつげん]だ。","ko":"그것은 교사로서 있어서는 안 될 발언이다."},{"jp":"政治家[せいじか]にあるまじき行為[こうい]が問題[もんだい]になっている。","ko":"정치가로서 있어서는 안 될 행위가 문제가 되고 있다."},{"jp":"患者[かんじゃ]を無視[むし]するなんて、医者[いしゃ]にあるまじき態度[たいど]だ。","ko":"환자를 무시하다니 의사로서 있어서는 안 될 태도다."}],"dr":[{"t":"make","q":"警察官・行為 → ～にあるまじき～","a":"警察官にあるまじき行為","hint":"명사1 + にあるまじき + 명사2"},{"t":"make","q":"社会人・態度 → ～にあるまじき～","a":"社会人にあるまじき態度","hint":"입장 명사 + にあるまじき + 행동 명사"},{"t":"fill","q":"選手[せんしゅ]に（　）暴言[ぼうげん]が問題[もんだい]になった。","a":"あるまじき","opts":["あるまじき","あっては","即して","限って"]}],"src":["https://bunpro.jp/grammar_points/885"],"vf":1,"u":6,"g":1,"gp":"gg_N1_02"},{"id":"g1_066","t":"～に即した","ko":"~에 입각한, ~에 맞는","cat":"명사화·수식","conn":[{"w":"명사1 + 명사2","f":"現実 + に即した + 計画"}],"rule":["1. 即する(꼭 맞다, 따르다)의 어미 する를 した로 바꿔 た형 即した를 만든다.","2. 기준이 되는 명사1 뒤에 に + 即した를 붙인다(現実に即した).","3. 그 뒤에 꾸밈을 받는 명사2를 놓는다(現実に即した計画)."],"why":"即する(딱 맞다, 따르다)의 た형 即した가 뒤의 명사를 꾸미는 형태로 '~에 딱 맞춘'이라는 뜻이 된다.","nu":"문어적이며 보고서·논설·공문에서 쓴다. 명사1에는 現実・実態・事実・状況・実情처럼 '실제 모습'을 나타내는 말이 자주 온다. 뜬구름 잡는 계획이 아니라 실제 상황에 들어맞는다는 뉘앙스다. 동사를 꾸밀 때는 に即して를 쓴다.","cmp":[{"g":"～に即して","d":"같은 뜻으로 뒤에 동사가 온다(現実に即して考える). に即した는 뒤에 명사가 온다."}],"ex":[{"jp":"現実[げんじつ]に即[そく]した計画[けいかく]を立[た]てる必要[ひつよう]がある。","ko":"현실에 맞는 계획을 세울 필요가 있다."},{"jp":"地域[ちいき]の実情[じつじょう]に即[そく]した支援[しえん]が求[もと]められている。","ko":"지역의 실정에 맞는 지원이 요구되고 있다."},{"jp":"新聞[しんぶん]は事実[じじつ]に即[そく]した報道[ほうどう]をするべきだ。","ko":"신문은 사실에 입각한 보도를 해야 한다."}],"dr":[{"t":"make","q":"即する → た형","a":"即した","hint":"する를 した로 바꾼다"},{"t":"make","q":"現実・計画 → ～に即した～","a":"現実に即した計画","hint":"명사1 + に即した + 명사2"},{"t":"fill","q":"実態[じったい]（　）対策[たいさく]を考[かんが]えなければならない。","a":"に即した","opts":["に即した","にあるまじき","にひきかえ","にもまして"]}],"src":["https://bunpro.jp/grammar_points/882"],"vf":1,"u":6,"g":1,"gp":"gg_N1_02"},{"id":"g1_072","t":"～抜いた＋名詞","ko":"끝까지 ~해 낸 (명사)","cat":"명사화·수식","conn":[{"w":"1그룹 동사 ます형","f":"走る → 走り + 抜いた"},{"w":"2그룹 동사 ます형","f":"考える → 考え + 抜いた"}],"rule":["1. 동사를 ます형으로 만든다. 1그룹은 어미 う단을 い단으로(走る → 走り), 2그룹은 る를 뺀다(考える → 考え).","2. ます형 뒤에 抜く를 붙인다(走り抜く).","3. 抜く의 く를 い로 바꾸고 た를 붙여 た형 抜いた를 만든다(走り抜いた).","4. 그 뒤에 명사를 놓아 꾸민다(走り抜いた選手)."],"why":"","nu":"동사 ます형 + 抜く는 '힘든 일을 끝까지 철저히 해내다'라는 뜻이며, 그 た형 抜いた가 명사를 꾸민다. 考え抜いた末(に), 悩み抜いた結果처럼 末・結果와 자주 쓴다. 고생·노력을 견디고 끝까지 했다는 느낌이 강하다.","cmp":[{"g":"～切る","d":"食べ切る처럼 '전부, 완전히 ~하다'는 완료에 초점. 抜く는 어려움을 견디며 끝까지 해낸다는 끈기에 초점이 있다."}],"ex":[{"jp":"考[かんが]え抜[ぬ]いた末[すえ]に、会社[かいしゃ]を辞[や]めることにした。","ko":"끝까지 고민한 끝에 회사를 그만두기로 했다."},{"jp":"最後[さいご]まで走[はし]り抜[ぬ]いた選手[せんしゅ]に、大[おお]きな拍手[はくしゅ]が送[おく]られた。","ko":"마지막까지 달려낸 선수에게 큰 박수가 보내졌다."},{"jp":"彼女[かのじょ]は悩[なや]み抜[ぬ]いた結果[けっか]、留学[りゅうがく]を決[き]めた。","ko":"그녀는 고민에 고민을 거듭한 결과 유학을 결정했다."}],"dr":[{"t":"make","q":"考える → ～抜いた","a":"考え抜いた","hint":"2그룹은 る를 빼고 抜いた"},{"t":"make","q":"走る → ～抜いた","a":"走り抜いた","hint":"1그룹은 る를 り로 바꾸고 抜いた"},{"t":"fill","q":"悩[なや]み（　）末[すえ]に、留学[りゅうがく]を決[き]めた。","a":"抜いた","opts":["抜いた","始めた","かけた","出した"]}],"src":["https://bunpro.jp/grammar_points/抜く"],"vf":1,"u":7,"g":1,"gp":"gg_N1_02"},{"id":"g1_143","t":"～のない～","ko":"~이 없는 ~","cat":"명사화·수식","conn":[{"w":"명사 + のない + 명사","f":"雲 + のない + 空"},{"w":"동사 ます형에서 온 명사","f":"笑い + のない + 人生"}],"rule":["1. 문장 '명사 + が + ない'를 만든다: 雲がない.","2. 뒤에 꾸밀 명사를 붙여 명사 수식절로 만든다: 雲がない空.","3. 명사 수식절 안의 주어 표시 が는 の로 바꿀 수 있다: 雲がない空 → 雲のない空.","4. 동사는 ます형을 명사로 써서 넣는다: 笑う → 笑い → 笑いのない人生."],"why":"명사를 꾸미는 절 안에서는 주어를 나타내는 が를 の로 바꿀 수 있다는 일본어의 일반 규칙(が・の 교체)에 따른 형태다.","nu":"'~이 없는 (명사)'라는 뜻으로 회화와 글 모두에서 매우 자주 쓴다. ない 앞에는 명사가 와야 하며, 동사 사전형을 그대로 넣어 食べるのない처럼 쓰면 틀린다. 동사의 뜻을 넣고 싶으면 笑い, 迷い, 休み처럼 ます형에서 온 명사를 쓰거나, 休まない人처럼 동사 부정형으로 직접 꾸민다. が를 그대로 쓴 雲がない空도 틀리지 않다.","cmp":[{"g":"～がない～","d":"뜻은 같다. 명사 수식에서는 の가 더 자연스럽게 들리는 경우가 많다."},{"g":"～なしの～ / ～抜きの～","d":"명사 + なし는 '~ 없음'을 간결하게 나타낸다(砂糖なしのコーヒー)."}],"ex":[{"jp":"今日[きょう]は雲[くも]のない、きれいな青空[あおぞら]だ。","ko":"오늘은 구름 없는 맑고 푸른 하늘이다."},{"jp":"笑[わら]いのない毎日[まいにち]はつまらない。","ko":"웃음 없는 하루하루는 재미없다."},{"jp":"彼[かれ]は迷[まよ]いのない声[こえ]で答[こた]えた。","ko":"그는 망설임 없는 목소리로 대답했다."}],"dr":[{"t":"make","q":"欠点がない人 → ～のない～","a":"欠点のない人","hint":"명사 수식절 안의 が를 の로 바꾼다"},{"t":"make","q":"休む・日 → ～のない～","a":"休みのない日","hint":"休む를 ます형 명사 休み로 바꾸고 + のない + 日"},{"t":"fill","q":"水[みず]（　）ない場所[ばしょ]では、植物[しょくぶつ]は育[そだ]たない。","a":"の","opts":["の","を","に","で"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AE-subject"],"vf":1,"u":7,"g":1,"gp":"gg_N1_02"},{"id":"g1_212","t":"～と言わんばかりの + 명사","ko":"마치 ~라고 말하는 듯한 (명사)","cat":"명사화·수식","conn":[{"w":"동사 (보통형·명령형 등 인용)","f":"もう知らない + と言わんばかりの顔"},{"w":"い형용사","f":"つまらない + と言わんばかりの態度"},{"w":"な형용사","f":"当然だ + と言わんばかりの態度"},{"w":"명사","f":"邪魔だ + と言わんばかりの目"}],"rule":["1. 인용 내용 + と言わんばかり까지는 と言わんばかりに와 같다(言う → 言わ + ん).","2. 부사적으로 쓰는 に를 명사를 꾸미는 の로 바꾼다: と言わんばかりの.","3. 뒤에 顔・態度・目・笑顔 같은 명사를 붙인다: と言わんばかりの顔."],"why":"言う의 ない형 言わ에 문어 조동사 ん(현대어의 う・よう에 해당)이 붙은 言わん + ばかり에, 명사 수식의 の가 이어진 형태다.","nu":"말로 하지는 않지만 그런 메시지가 드러나는 표정·태도·눈빛 등을 묘사한다. 뒤에 오는 명사는 顔, 表情, 態度, 目, 口調, 笑顔처럼 겉으로 드러나는 모습이 대부분이다. 문장체·묘사문 표현이며 주로 남의 모습에 쓴다.","cmp":[{"g":"～と言わんばかりに","d":"같은 표현의 부사형으로, 뒤에 동사(にらむ, 見る 등)가 온다."},{"g":"～ような + 명사","d":"일반적인 비유 수식. と言わんばかりの는 상대가 무언으로 전하는 말이 내용이 된다."}],"ex":[{"jp":"彼[かれ]は「もう知[し]らない」と言[い]わんばかりの顔[かお]をした。","ko":"그는 '이제 몰라'라고 말하는 듯한 얼굴을 했다."},{"jp":"彼女[かのじょ]は当然[とうぜん]だと言[い]わんばかりの態度[たいど]だった。","ko":"그녀는 당연하다고 말하는 듯한 태도였다."},{"jp":"子[こ]どもは早[はや]く遊[あそ]びたいと言[い]わんばかりの目[め]でこちらを見[み]ていた。","ko":"아이는 빨리 놀고 싶다고 말하는 듯한 눈으로 이쪽을 보고 있었다."}],"dr":[{"t":"make","q":"つまらない → ～と言わんばかりの顔","a":"つまらないと言わんばかりの顔","hint":"인용 + と言わんばかり + の + 명사"},{"t":"make","q":"当然だ → ～と言わんばかりの態度","a":"当然だと言わんばかりの態度","hint":"인용 + と言わんばかり + の(に가 아님) + 명사"},{"t":"fill","q":"店員[てんいん]は早[はや]く帰[かえ]ってほしいと言[い]わんばかり（　）表情[ひょうじょう]をしていた。","a":"の","opts":["の","に","で","を"]}],"src":[],"vf":0,"u":7,"g":1,"gp":"gg_N1_02"},{"id":"g1_214","t":"～ながらの + 명사","ko":"~하면서 하는 (명사), 예로부터 그대로인 (명사)","cat":"명사화·수식","conn":[{"w":"동사 ます형","f":"歩く → 歩き + ながらの + スマホ"},{"w":"する동사","f":"散歩する → 散歩し + ながらの + 会話"},{"w":"명사 (한정된 말)","f":"昔 + ながらの + 町並み"}],"rule":["1. 동사를 ます형으로 바꾼다: 1그룹은 어미 う단을 い단으로(歩く → 歩き), 2그룹은 る를 뗀다(見る → 見).","2. 뒤에 ながら를 붙인다: 歩きながら.","3. 명사를 꾸미기 위해 の를 넣고 명사를 붙인다: 歩きながらのスマホ."],"why":"동시 동작의 ながら에 명사 수식의 の가 붙은 형태다.","nu":"① 동사 ます형 + ながらの + 명사: '~하면서 하는 (행위)'로, 歩きながらのスマホ, テレビを見ながらの食事처럼 두 일을 동시에 하는 것을 하나의 명사로 묶는다. ② 昔ながらの, 生まれながらの처럼 관용적으로 '예전 그대로의, 타고난'이라는 뜻도 있다. 회화와 문장 모두에서 쓰인다. ながら 뒤에 바로 명사를 붙이지 말고 반드시 の를 넣는다.","cmp":[{"g":"～ながら","d":"동사를 꾸미는 부사적 용법(見ながら食べる). ながらの는 명사를 꾸민다."},{"g":"～ながらに","d":"涙ながらに처럼 상태가 유지됨을 나타내는 관용적 부사 용법이다."}],"ex":[{"jp":"歩[ある]きながらのスマホは危[あぶ]ないです。","ko":"걸으면서 스마트폰을 보는 것은 위험합니다."},{"jp":"テレビを見[み]ながらの食事[しょくじ]はやめなさい。","ko":"텔레비전을 보면서 하는 식사는 그만둬라."},{"jp":"この店[みせ]では、昔[むかし]ながらの方法[ほうほう]でみそを作[つく]っている。","ko":"이 가게에서는 옛날 그대로의 방법으로 된장을 만들고 있다."}],"dr":[{"t":"make","q":"運転する → ～ながらの電話","a":"運転しながらの電話","hint":"ます형(し) + ながら + の + 명사"},{"t":"make","q":"聞く → ～ながらの勉強","a":"聞きながらの勉強","hint":"く → き(ます형) + ながらの"},{"t":"fill","q":"音楽[おんがく]を聞[き]き（　）勉強[べんきょう]は集中[しゅうちゅう]できない。","a":"ながらの","opts":["ながらの","たての","かけの","つつある"]}],"src":[],"vf":0,"u":7,"g":1,"gp":"gg_N1_02"},{"id":"g1_228","t":"～びた","ko":"~티가 나는, ~다워진, ~한 느낌이 든","cat":"명사화·수식","conn":[{"w":"명사","f":"大人 + びた → 大人びた顔"},{"w":"い형용사 어간","f":"古い → 古びた家"}],"rule":["1. い형용사는 어미 い를 떼고 어간만 남긴다(古い → 古), 명사는 그대로 둔다(大人).","2. 접미사 びる를 붙여 2그룹 동사를 만든다: 古びる, 大人びる.","3. びる의 る를 떼고 た를 붙여 명사를 꾸민다: 古びた家, 大人びた顔."],"why":"","nu":"접미사 びる의 た형으로, 명사 앞에서 '~한 상태가 된, ~다운 모습의'라는 뜻으로 쓴다. 서술할 때는 古びている, 大人びている처럼 ている형을 쓴다. 붙는 말은 大人, 古い, ひなびる(시골스럽다) 등 몇 개로 정해져 있어 새로 만들어 쓰지 않는다. 大人びた는 아이가 나이에 비해 어른스럽다는 뜻이다.","cmp":[{"g":"～ぶった","d":"실제로는 아닌데 '~인 척하는'이라는 부정적 뜻(学者ぶった態度). びた는 실제로 그런 모습·상태가 되었다는 뜻."},{"g":"～らしい","d":"그 성질을 제대로 갖췄다는 뜻(子どもらしい). 大人びた는 아이가 어른처럼 보인다는 뜻으로 대상이 다르다."}],"ex":[{"jp":"駅[えき]の前[まえ]に古[ふる]びた喫茶店[きっさてん]がある。","ko":"역 앞에 낡은 찻집이 있다."},{"jp":"彼女[かのじょ]は中学生[ちゅうがくせい]なのに大人[おとな]びた顔[かお]をしている。","ko":"그녀는 중학생인데 어른스러운 얼굴을 하고 있다."},{"jp":"祖父[そふ]の古[ふる]びたカメラを、今[いま]も大切[たいせつ]に使[つか]っている。","ko":"할아버지의 낡은 카메라를 지금도 소중히 쓰고 있다."}],"dr":[{"t":"make","q":"古い + 本 → ～びた","a":"古びた本","hint":"い를 떼고 びる, る를 떼고 た + 명사"},{"t":"make","q":"大人 + 口調 → ～びた","a":"大人びた口調","hint":"명사 + びる → びた + 명사"},{"t":"fill","q":"あの子[こ]は小学生[しょうがくせい]なのに、大人[おとな]（　）話[はな]し方[かた]をする。","a":"びた","opts":["びた","らしく","っぽさ","がち"]}],"src":[],"vf":0,"u":8,"g":1,"gp":"gg_N1_02"},{"id":"g1_230","t":"～ぶった","ko":"~인 척하는, ~인 체한","cat":"명사화·수식","conn":[{"w":"명사","f":"学者 + ぶった → 学者ぶった口調"},{"w":"い형용사 어간","f":"偉い → 偉ぶった態度"},{"w":"な형용사 어간","f":"上品 + ぶった"}],"rule":["1. 명사·な형용사는 어간 그대로, い형용사는 어미 い를 뗀다: 偉い → 偉.","2. 접미사 ぶる(1그룹 동사)를 붙인다: 偉ぶる.","3. ぶる의 る를 っ로 바꾸고(촉음편) た를 붙인다: 偉ぶった. 명사를 꾸미면 偉ぶった態度."],"why":"","nu":"ぶる의 た형으로, 주로 명사 앞에서 '실제로는 그렇지 않으면서 ~인 척하는'이라는 비난의 뜻으로 쓴다(学者ぶった口調, 大人ぶった言い方). 상대를 깎아내리는 말이므로 자기 자신이나 윗사람에게 직접 쓰지 않는다. 偉そう처럼 そう가 붙은 말에는 ぶる를 붙이지 않는다(偉ぶった 또는 偉そうな가 맞다).","cmp":[{"g":"～びた","d":"실제로 그런 모습이 된(大人びた: 어른스러운). ぶった는 그런 척하는(大人ぶった: 어른인 척하는)."},{"g":"～ふりをした","d":"동사·형용사 보통형 + ふりをする로 '~하는 척'을 말하는 일반 표현. ぶった는 명사·형용사 어간에 붙고 거드름이라는 부정적 느낌이 강하다."}],"ex":[{"jp":"彼[かれ]の偉[えら]ぶった態度[たいど]にはうんざりだ。","ko":"그의 잘난 체하는 태도에는 질렸다."},{"jp":"彼女[かのじょ]は大人[おとな]ぶった口調[くちょう]で話[はな]すが、まだ中学生[ちゅうがくせい]だ。","ko":"그녀는 어른인 척하는 말투로 말하지만 아직 중학생이다."},{"jp":"学者[がくしゃ]ぶった説明[せつめい]はやめて、わかりやすく話[はな]してほしい。","ko":"학자인 척하는 설명은 그만두고 알기 쉽게 말해 줬으면 한다."}],"dr":[{"t":"make","q":"偉い + 言い方 → ～ぶった","a":"偉ぶった言い方","hint":"い를 떼고 ぶる, る를 っ로 + た + 명사"},{"t":"make","q":"先生 + 態度 → ～ぶった","a":"先生ぶった態度","hint":"명사 + ぶる → ぶった + 명사"},{"t":"fill","q":"何[なん]でも知[し]っているような、学者[がくしゃ]（　）話[はな]し方[かた]が嫌[きら]いだ。","a":"ぶった","opts":["ぶった","びた","らしく","っぽさ"]}],"src":[],"vf":0,"u":8,"g":1,"gp":"gg_N1_02"},{"id":"g1_244","t":"～に足る","ko":"~할 만한, ~하기에 충분한","cat":"명사화·수식","conn":[{"w":"명사(する동사의 명사)","f":"信頼 + に足る + 人物"},{"w":"동사 사전형","f":"読む + に足る + 本"}],"rule":["1. 명사 또는 동사 사전형 뒤에 조사 に를 붙인다: 信頼に.","2. 그 뒤에 足る를 붙인다: 信頼に足る.","3. 마지막에 꾸밀 명사를 둔다: 信頼に足る人物."],"why":"足る는 足りる(충분하다)의 문어형이다. '~하기에 충분하다'에서 '~할 만한 가치가 있다'는 뜻이 된다.","nu":"주로 명사를 꾸미는 형태(～に足る + 명사)로 쓰며, 信頼, 尊敬, 満足, 検討 같은 평가를 나타내는 말과 잘 어울린다. 매우 딱딱한 문어체로 논설·뉴스·공식 문서에 쓴다. 부정은 ～に足りない(に足らない)이다. 일상 회화라면 信頼できる人 처럼 말하는 것이 자연스럽다.","cmp":[{"g":"～に値する","d":"'~할 가치가 있다'로 뜻이 매우 가깝다(注目に値する). 문말에도 자연스럽게 쓴다."},{"g":"～に足りない","d":"부정형으로 '~할 가치가 없다'(取るに足りない)."}],"ex":[{"jp":"彼[かれ]は信頼[しんらい]に足[た]る人物[じんぶつ]だ。","ko":"그는 신뢰할 만한 인물이다."},{"jp":"これは一度[いちど]読[よ]むに足[た]る本[ほん]だと思[おも]う。","ko":"이것은 한 번 읽어 볼 만한 책이라고 생각한다."},{"jp":"今回[こんかい]の調査[ちょうさ]では、満足[まんぞく]に足[た]る結果[けっか]が得[え]られなかった。","ko":"이번 조사에서는 만족할 만한 결과를 얻지 못했다."}],"dr":[{"t":"make","q":"尊敬 → ～に足る + 先輩","a":"尊敬に足る先輩","hint":"명사 + に足る + 명사"},{"t":"make","q":"検討する → ～に足る + データ","a":"検討するに足るデータ","hint":"동사 사전형 + に足る + 명사"},{"t":"fill","q":"彼[かれ]こそ、このチームを任[まか]せる（　）人物[じんぶつ]だ。","a":"に足る","opts":["に足る","に反する","に沿った","に先立つ"]}],"src":[],"vf":0,"u":8,"g":1,"gp":"gg_N1_02"},{"id":"g1_100","t":"～を余儀なくされる","ko":"어쩔 수 없이 ~하게 되다","cat":"수수·사역·수동","conn":[{"w":"동작성 명사","f":"中止 + を余儀なくされる"},{"w":"동사 사전형 + こと","f":"中止すること + を余儀なくされる"}],"rule":["1. い형용사 余儀ない의 어미 い를 く로 바꾼다(부사형): 余儀ない → 余儀なく.","2. する의 수동형 される를 붙인다: 余儀なくされる.","3. 동작성 명사 + を 뒤에 둔다: 中止を余儀なくされる."],"why":"余儀ない(달리 방법이 없다)의 연용형 余儀なく에 する의 수동형 される가 붙은 것이다.","nu":"문어적인 표현으로 뉴스·보고서에 많이 나온다. 자연재해·사고·경제 사정 같은 외부 요인 때문에 원치 않는 일을 할 수밖에 없게 되었다는 뜻이다. 앞에는 中止・延期・変更・入院・退学・避難 같은 동작성 명사가 온다. 동사를 그대로 붙이지 않는다(中止する余儀なく는 틀리고, 中止を 또는 中止することを로 한다). 원인을 주어로 하면 ～を余儀なくさせる가 된다.","cmp":[{"g":"～ざるを得ない","d":"동사 ない형 + ざるを得ない로 '~하지 않을 수 없다'. 화자 자신의 판단에도 쓰며 を余儀なくされる보다 덜 딱딱하다."},{"g":"～を余儀なくさせる","d":"사역형으로, 원인(台風 등)이 주어가 되어 누군가를 그렇게 만든다는 뜻이다."}],"ex":[{"jp":"大雨[おおあめ]のため、試合[しあい]は中止[ちゅうし]を余儀[よぎ]なくされた。","ko":"큰비 때문에 시합은 어쩔 수 없이 중지되었다."},{"jp":"けがで、彼[かれ]は一[いっ]か月[げつ]の入院[にゅういん]を余儀[よぎ]なくされた。","ko":"부상 때문에 그는 어쩔 수 없이 한 달간 입원하게 되었다."},{"jp":"不景気[ふけいき]で、多[おお]くの店[みせ]が閉店[へいてん]を余儀[よぎ]なくされた。","ko":"불경기로 많은 가게가 어쩔 수 없이 문을 닫았다."}],"dr":[{"t":"make","q":"中止 → ～を余儀なくされた","a":"中止を余儀なくされた","hint":"명사 + を + 余儀なく + された"},{"t":"make","q":"余儀ない → 부사형","a":"余儀なく","hint":"い형용사 어미 い → く"},{"t":"fill","q":"台風[たいふう]のため、旅行[りょこう]の予定[よてい]は変更[へんこう]を（　）。","a":"余儀なくされた","opts":["余儀なくされた","禁じ得なかった","ものともしなかった","皮切りにした"]}],"src":["https://bunpro.jp/grammar_points/737"],"vf":1,"u":8,"g":1,"gp":"gg_N1_02"},{"id":"g1_116","t":"～させられる","ko":"(억지로) ~하게 되다, 시킴을 당하다","cat":"수수·사역·수동","conn":[{"w":"1그룹 동사","f":"飲む → 飲ませられる / 飲まされる"},{"w":"1그룹 す로 끝나는 동사","f":"話す → 話させられる (줄임형 없음)"},{"w":"2그룹 동사","f":"食べる → 食べさせられる"},{"w":"불규칙 する","f":"する → させられる"},{"w":"불규칙 来る","f":"来る → 来させられる"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾼다: 飲む → 飲ま.","2. 사역의 せ(る)를 붙인다: 飲ませる.","3. 사역형의 る를 떼고 수동의 られる를 붙인다: 飲ませられる.","4. 1그룹은 せられる를 される로 줄인 형태도 많이 쓴다: 飲まされる (す로 끝나는 동사는 줄이지 않는다).","5. 2그룹은 る를 떼고 させられる, する는 させられる, 来る는 来(こ)させられる가 된다."],"why":"사역 조동사 せる・させる 뒤에 수동 조동사 られる가 이어진 사역수동형이다.","nu":"주어(주로 나)가 남이 시켜서 하기 싫은 일을 억지로 하게 됨을 나타내며, 시킨 사람은 に로 표시한다. 考えさせられる(깊이 생각하게 되다), 感心させられる처럼 무언가에 의해 저절로 그런 마음이 드는 뜻으로도 쓴다. 회화에서는 1그룹의 줄임형(待たされる, 飲まされる)이 자연스럽다. 한국어 화자는 사역(飲ませる: 마시게 하다)과 방향을 헷갈리기 쉬우니 주의한다.","cmp":[{"g":"～させる","d":"사역형으로, 주어가 남에게 시키는 쪽이다(母が子供に野菜を食べさせる). させられる는 시킴을 당하는 쪽이 주어다(子供が母に野菜を食べさせられる)."}],"ex":[{"jp":"子[こ]どものころ、毎日[まいにち]ピアノを練習[れんしゅう]させられた。","ko":"어릴 때 매일 피아노 연습을 해야 했다(시켜서 했다)."},{"jp":"飲[の]み会[かい]で先輩[せんぱい]にお酒[さけ]を飲[の]まされた。","ko":"회식에서 선배가 억지로 술을 마시게 했다."},{"jp":"嫌[きら]いな野菜[やさい]を母[はは]に食[た]べさせられた。","ko":"싫어하는 채소를 엄마 때문에 억지로 먹었다."}],"dr":[{"t":"make","q":"書く → 사역수동(긴 형태)","a":"書かせられる","hint":"く → か(あ단) + せ + られる"},{"t":"make","q":"待つ → 사역수동(줄임형)","a":"待たされる","hint":"つ → た(あ단) + される"},{"t":"fill","q":"子[こ]どものころ、嫌[きら]いなピーマンを無理[むり]やり（　）。","a":"食べさせられた","opts":["食べさせられた","食べられた","食べたがった","食べてほしかった"]}],"src":["https://bunpro.jp/ja/grammar_points/causative-passive","https://laits.utexas.edu/japanese/joshu/grammar/glist/y2/ch6/gl_y2_ch6_causativepassive.php"],"vf":1,"u":8,"g":1,"gp":"gg_N1_03"},{"id":"g1_117","t":"～ざるを得ない","ko":"~하지 않을 수 없다, ~할 수밖에 없다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사 ない형","f":"行か + ざるを得ない"},{"w":"2그룹 동사 ない형","f":"やめ + ざるを得ない"},{"w":"불규칙 する","f":"する → せざるを得ない"},{"w":"불규칙 来る","f":"来る → 来(こ)ざるを得ない"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꿔 ない형을 만든다: 行く → 行か.","2. ない 대신 옛 부정형 ざる를 붙인다: 行かざる.","3. を得ない를 붙인다: 行かざるを得ない.","4. 2그룹은 る를 떼고 붙이며, する는 しざる가 아니라 せざるを得ない가 된다."],"why":"ざる는 고전 부정 조동사 ず의 연체형이고, を得ない는 得る(할 수 있다)의 부정이다. '하지 않는 것을 할 수 없다', 곧 '할 수밖에 없다'는 이중 부정 구조다.","nu":"내키지 않지만 상황이나 사정 때문에 어쩔 수 없이 그렇게 한다(또는 그렇게 판단한다)는 뜻이다. 격식 있는 문어적 표현이며, 회화에서는 しかない가 더 가볍다. 認めざるを得ない(인정할 수밖에 없다)처럼 판단에도 자주 쓴다. する를 しざる로 만드는 실수가 흔하다.","cmp":[{"g":"～しかない","d":"동사 사전형 + しかない로, 다른 방법이 없다는 뜻의 회화적 표현이다."},{"g":"～ないわけにはいかない","d":"사회적 상식이나 의리·책임 때문에 안 할 수 없다는 뜻이 강하다(招待されたから行かないわけにはいかない)."}],"ex":[{"jp":"雨[あめ]が強[つよ]いので、試合[しあい]は中止[ちゅうし]せざるを得[え]ない。","ko":"비가 거세서 경기는 중지할 수밖에 없다."},{"jp":"部長[ぶちょう]の命令[めいれい]だから、行[い]かざるを得[え]ない。","ko":"부장님의 명령이니 가지 않을 수 없다."},{"jp":"悔[くや]しいが、彼[かれ]の意見[いけん]が正[ただ]しいと認[みと]めざるを得[え]ない。","ko":"분하지만 그의 의견이 옳다고 인정할 수밖에 없다."}],"dr":[{"t":"make","q":"諦める → ～ざるを得ない","a":"諦めざるを得ない","hint":"2그룹: る를 떼고 + ざるを得ない"},{"t":"make","q":"延期する → ～ざるを得ない","a":"延期せざるを得ない","hint":"する → せ + ざるを得ない"},{"t":"fill","q":"台風[たいふう]が来[く]るので、旅行[りょこう]は中止[ちゅうし]せ（　）。","a":"ざるを得ない","opts":["ざるを得ない","ずにはいられない","ずじまいだ","ずとも"]}],"src":["https://bunpro.jp/grammar_points/397"],"vf":1,"u":9,"g":1,"gp":"gg_N1_03"},{"id":"g1_121","t":"～ずにはすまない","ko":"~하지 않고는 끝나지 않는다, ~해야만 한다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사 ない형","f":"謝ら + ずにはすまない"},{"w":"2그룹 동사 ない형","f":"認め + ずにはすまない"},{"w":"불규칙 する","f":"する → せずにはすまない"},{"w":"불규칙 来る","f":"来る → 来(こ)ずにはすまない"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꿔 ない형을 만든다: 謝る → 謝ら.","2. 부정의 ず를 붙이고 이어서 には를 붙인다: 謝らずには.","3. すまない(済まない)를 붙인다: 謝らずにはすまない.","4. 2그룹은 る를 떼고 붙이며, する는 せずにはすまない가 된다."],"why":"ずに(~하지 않고)에 は가 붙고, 済む(일이 해결되다, 끝나다)의 부정 済まない가 이어진 형태다. '하지 않고는 일이 끝나지 않는다'는 뜻이다.","nu":"그 상황이나 사회적 상식으로 볼 때 그 일을 하지 않고는 해결되지 않는다, 곧 반드시 해야 한다는 뜻이다. 사과, 책임, 변상 같은 의무적인 행동과 잘 어울린다. 딱딱한 문어체이며, 회화에서는 ないではすまない나 ないといけない를 많이 쓴다. 작품이 감정을 일으키거나 강한 결의를 나타내는 ずにはおかない와 구별한다.","cmp":[{"g":"～ないではすまない","d":"같은 뜻으로 ない형 + ないではすまない 형태이며 조금 더 회화적이다."},{"g":"～ずにはおかない","d":"대상이 사람에게 어떤 감정을 반드시 일으키거나 화자가 반드시 하겠다는 결의를 나타낸다. ずにはすまない는 상황상 해야 하는 의무다."}],"ex":[{"jp":"部長[ぶちょう]の大切[たいせつ]な花瓶[かびん]を割[わ]ったのだから、謝[あやま]らずにはすまない。","ko":"부장님의 소중한 꽃병을 깼으니 사과하지 않고는 끝나지 않는다."},{"jp":"これほどのミスをしたら、責任者[せきにんしゃ]は説明[せつめい]せずにはすまないだろう。","ko":"이 정도의 실수를 했다면 책임자는 설명하지 않고는 넘어갈 수 없을 것이다."},{"jp":"借[か]りた車[くるま]を壊[こわ]したので、修理代[しゅうりだい]を払[はら]わずにはすまない。","ko":"빌린 차를 망가뜨렸으니 수리비를 내지 않을 수 없다."}],"dr":[{"t":"make","q":"払う → ～ずにはすまない","a":"払わずにはすまない","hint":"う → わ(ない형) + ずにはすまない"},{"t":"make","q":"説明する → ～ずにはすまない","a":"説明せずにはすまない","hint":"する → せ + ずにはすまない"},{"t":"fill","q":"人[ひと]に迷惑[めいわく]をかけたのだから、謝[あやま]ら（　）。","a":"ずにはすまない","opts":["ずにはすまない","ずとも","ずじまいだ","んばかりだ"]}],"src":["https://bunpro.jp/es/grammar_points/%E3%81%9A%E3%81%AB%E3%81%AF%E3%81%99%E3%81%BE%E3%81%AA%E3%81%84"],"vf":1,"u":9,"g":1,"gp":"gg_N1_03"},{"id":"g1_139","t":"～ないではすまない","ko":"~하지 않고는 끝나지 않는다, ~해야만 한다","cat":"가능·의무·허가","conn":[{"w":"동사 ない형","f":"謝らない + ではすまない"},{"w":"불규칙 する","f":"しない + ではすまない"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾼다: 謝る → 謝ら.","2. 그 뒤에 ない를 붙인다: 謝らない.","3. ない형 뒤에 ではすまない를 붙인다: 謝らないではすまない.","4. 2그룹은 る를 ない로 바꾼다: 届ける → 届けない. する는 しない가 된다."],"why":"ない형 + では + 済む(すむ, 해결되다·끝나다)의 부정형으로, '~하지 않고서는 일이 끝나지 않는다'는 뜻이다.","nu":"상황이나 사회적 상식으로 볼 때 그렇게 하지 않으면 용납되지 않으니 반드시 해야 한다는 뜻이다. 말하는 사람의 개인적 감정이 아니라 주변 사정에서 오는 의무를 말한다. 딱딱한 표현이며, 같은 뜻의 ～ずにはすまない도 많이 쓴다(する → せずにはすまない). 감정이 저절로 생긴다는 ～ないではいられない(泣かないではいられない)와 혼동하지 않도록 주의한다.","cmp":[{"g":"～ないではいられない","d":"감정이나 충동 때문에 저절로 하게 된다는 뜻. ないではすまない는 상황상 꼭 해야 한다는 의무다."},{"g":"～ずにはすまない","d":"같은 뜻의 문어적 형태."}],"ex":[{"jp":"人[ひと]の花瓶[かびん]を割[わ]ったのだから、謝[あやま]らないではすまない。","ko":"남의 꽃병을 깼으니 사과하지 않고는 넘어갈 수 없다."},{"jp":"これだけ大[おお]きな問題[もんだい]になったら、社長[しゃちょう]に報告[ほうこく]しないではすまないだろう。","ko":"이만큼 큰 문제가 되었으니 사장에게 보고하지 않을 수 없을 것이다."},{"jp":"借[か]りた本[ほん]をなくしたので、弁償[べんしょう]しないではすまない。","ko":"빌린 책을 잃어버렸으니 변상하지 않고는 끝나지 않는다."}],"dr":[{"t":"make","q":"払う → ～ないではすまない","a":"払わないではすまない","hint":"う → わ(あ단으로 바꿀 때 う는 わ), + ない + ではすまない"},{"t":"make","q":"説明する → ～ないではすまない","a":"説明しないではすまない","hint":"する → しない, + ではすまない"},{"t":"fill","q":"約束[やくそく]を破[やぶ]ったのだから、謝[あやま]らないでは（　）。","a":"すまない","opts":["すまない","いられない","おかない","たまらない"]}],"src":["https://bunpro.jp/es/grammar_points/%E3%81%9A%E3%81%AB%E3%81%AF%E3%81%99%E3%81%BE%E3%81%AA%E3%81%84"],"vf":1,"u":9,"g":1,"gp":"gg_N1_03"},{"id":"g1_150","t":"～ようがない","ko":"~할 방법이 없다, ~할 수가 없다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사 ます형","f":"直し + ようがない"},{"w":"2그룹 동사 ます형","f":"答え + ようがない"},{"w":"する동사","f":"連絡し + ようがない"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다: 直す → 直し.","2. 2그룹 동사는 る를 뺀다: 答える → 答え. する는 し가 된다.","3. ます형 뒤에 ようがない를 붙인다: 直しようがない.","4. 의향형(直そう)이 아니라 ます형에 붙는다."],"why":"ます형 + よう(様, 방법) + が + ない. 여기서 よう는 '방법'이라는 뜻의 명사다.","nu":"하고 싶어도 방법·수단이 없어서 할 수 없다는 뜻이다. 능력 부족보다 상황 때문에 손쓸 수 없음을 나타낸다. 答えよう・しよう처럼 2그룹과 する에서는 의향형과 모양이 같아 1그룹도 의향형(×直そうがない)에 붙이는 실수가 많다.","cmp":[{"g":"～ようもない","d":"ようがない를 も로 강조한 형태로 뜻은 거의 같다."},{"g":"～ことができない","d":"일반적인 불가능. ようがない는 '방법이 없어서'라는 이유가 들어 있다."}],"ex":[{"jp":"連絡先[れんらくさき]が分[わ]からないので、連絡[れんらく]しようがない。","ko":"연락처를 모르니 연락할 방법이 없다."},{"jp":"ここまで壊[こわ]れていては、直[なお]しようがない。","ko":"이렇게까지 망가져서는 고칠 방법이 없다."},{"jp":"何[なに]も聞[き]いていないので、答[こた]えようがない。","ko":"아무것도 듣지 못해서 대답할 수가 없다."}],"dr":[{"t":"make","q":"説明する → ～ようがない","a":"説明しようがない","hint":"する → し + ようがない"},{"t":"make","q":"書く → ～ようがない","a":"書きようがない","hint":"1그룹: く → き(ます형) + ようがない"},{"t":"fill","q":"住所[じゅうしょ]が分[わ]からないので、手紙[てがみ]を送[おく]り（　）。","a":"ようがない","opts":["ようがない","ようになる","たがる","なさい"]}],"src":["https://bunpro.jp/grammar_points/434"],"vf":1,"u":9,"g":1,"gp":"gg_N1_03"},{"id":"g1_153","t":"～ようにも～られない","ko":"~하려고 해도 ~할 수 없다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"歩こう + にも + 歩けない"},{"w":"2그룹 동사","f":"寝よう + にも + 寝られない"},{"w":"する","f":"しよう + にも + できない"}],"rule":["1. 의향형을 만든다. 2그룹은 る를 빼고 よう(寝る → 寝よう), 1그룹은 어미 う단을 お단 + う(歩く → 歩こう).","2. 의향형 뒤에 にも를 붙인다: 寝ようにも.","3. 같은 동사의 가능형 부정을 붙인다. 2그룹은 る → られない(寝られない), 1그룹은 う단 → え단 + ない(歩けない), する는 できない."],"why":"","nu":"'하려고 해도 (사정이 있어) 할 수 없다'를 같은 동사를 두 번 써서 강조한다. 앞에 이유(足が痛くて, 隣がうるさくて)가 오는 경우가 많다. 2그룹의 가능형은 회화에서 ら를 뺀 寝れない도 들리지만 표준형은 寝られない다.","cmp":[{"g":"～ようにも","d":"뒤에 같은 동사를 반복하지 않고 이유만 말하는 형태(帰ろうにも、仕事が多い)."},{"g":"～たくても～ない","d":"'~하고 싶어도 못 한다'. 회화적이다."}],"ex":[{"jp":"隣[となり]がうるさくて、寝[ね]ようにも寝[ね]られない。","ko":"옆집이 시끄러워서 자려고 해도 잘 수가 없다."},{"jp":"財布[さいふ]を忘[わす]れたので、買[か]おうにも買[か]えない。","ko":"지갑을 두고 와서 사려고 해도 살 수가 없다."},{"jp":"足[あし]が痛[いた]くて、歩[ある]こうにも歩[ある]けない。","ko":"다리가 아파서 걸으려고 해도 걸을 수가 없다."}],"dr":[{"t":"make","q":"忘れる → ～ようにも～られない","a":"忘れようにも忘れられない","hint":"2그룹: 忘れよう + にも + 忘れられない"},{"t":"make","q":"行く → ～ようにも～ない(가능)","a":"行こうにも行けない","hint":"行こう + にも + 가능형 부정 行けない"},{"t":"fill","q":"お金[かね]がなくて、旅行[りょこう]に行[い]こうにも（　）。","a":"行けない","opts":["行けない","行きたい","行こう","行くべきだ"]}],"src":["https://bunpro.jp/grammar_points/839"],"vf":1,"u":10,"g":1,"gp":"gg_N1_03"},{"id":"g1_154","t":"～ようもない","ko":"~할 방법도 없다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사 ます형","f":"聞き + ようもない"},{"w":"2그룹 동사 ます형","f":"確かめ + ようもない"},{"w":"する","f":"し + ようもない (どうしようもない)"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다: 聞く → 聞き.","2. 2그룹 동사는 る를 뺀다: 確かめる → 確かめ. する는 し가 된다.","3. ます형 뒤에 よう(방법) + も + ない를 붙인다: 聞きようもない."],"why":"ます형 + よう(様, 방법) + も + ない. ようがない의 が 자리에 강조의 も가 들어간 형태다.","nu":"방법이 전혀 없어 할 수 없다는 뜻으로 ようがない보다 체념의 느낌이 강하다. どうしようもない(어찌할 도리가 없다)는 관용적으로 아주 자주 쓴다. ようがない와 마찬가지로 의향형이 아니라 ます형에 붙는다(×聞こうもない).","cmp":[{"g":"～ようがない","d":"기본형. ようもない는 も로 '~조차 없다'를 강조한다."},{"g":"～わけがない","d":"'~할 리가 없다'는 가능성 부정. ようもない는 방법이 없음을 말한다."}],"ex":[{"jp":"本人[ほんにん]がいないのだから、聞[き]きようもない。","ko":"본인이 없으니 물어볼 방법도 없다."},{"jp":"証拠[しょうこ]がないので、確[たし]かめようもない。","ko":"증거가 없어서 확인할 방법도 없다."},{"jp":"終[お]わったことは、今[いま]さらどうしようもない。","ko":"끝난 일은 이제 와서 어찌할 도리가 없다."}],"dr":[{"t":"make","q":"探す → ～ようもない","a":"探しようもない","hint":"1그룹: す → し(ます형) + ようもない"},{"t":"make","q":"止める(とめる) → ～ようもない","a":"止めようもない","hint":"2그룹: る를 빼고 + ようもない"},{"t":"fill","q":"終[お]わったことは、今[いま]さらどうし（　）。","a":"ようもない","opts":["ようもない","そうもない","てもいい","たがる"]}],"src":["https://bunpro.jp/grammar_points/434"],"vf":1,"u":10,"g":1,"gp":"gg_N1_03"},{"id":"g1_168","t":"～べからざる","ko":"~해서는 안 될, ~할 수 없는","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"欠く + べからざる + 存在"},{"w":"する","f":"する → す + べからざる"}],"rule":["1. 동사는 사전형 그대로 둔다: 欠く.","2. 사전형 뒤에 べからざる를 붙인다: 欠くべからざる.","3. べからざる 뒤에는 반드시 명사를 둔다: 欠くべからざる存在.","4. する는 す로 바꾸어 すべからざる가 된다."],"why":"고전 조동사 べし의 미연형 べから에 부정 조동사 ず의 연체형 ざる가 붙은 형태로, '~해서는 안 되는, ~할 수 없는'이라는 뜻의 명사 수식형이다.","nu":"매우 딱딱한 문어체로, 연설·논설문·관용구에서 쓴다. 명사 앞에서만 쓰며 문장 끝에 오지 않는다. 欠くべからざる(없어서는 안 될), 許すべからざる(용서해서는 안 될), 侵すべからざる(침해해서는 안 될) 같은 굳어진 조합이 대부분이다. 하는 사람을 주어로 하는 문장(人を裏切るべからざる 등)으로 자유롭게 만들지 않도록 주의한다.","cmp":[{"g":"～べからず","d":"같은 べし + ず지만 문장을 끝맺는 금지 표현으로, 게시문에 쓴다(立ち入るべからず)."},{"g":"～てはならない","d":"현대어의 일반적인 금지·의무 표현으로, 문장 끝에도 명사 수식(してはならないこと)에도 쓸 수 있다."}],"ex":[{"jp":"水[みず]は人間[にんげん]にとって欠[か]くべからざるものだ。","ko":"물은 인간에게 없어서는 안 될 것이다."},{"jp":"弱[よわ]い者[もの]をいじめるのは許[ゆる]すべからざる行為[こうい]だ。","ko":"약한 사람을 괴롭히는 것은 용서해서는 안 될 행위다."},{"jp":"彼[かれ]はこのチームにとって欠[か]くべからざる存在[そんざい]になった。","ko":"그는 이 팀에게 없어서는 안 될 존재가 되었다."}],"dr":[{"t":"make","q":"欠く → ～べからざる + もの","a":"欠くべからざるもの","hint":"사전형 + べからざる + 명사"},{"t":"make","q":"許す → ～べからざる + 行為","a":"許すべからざる行為","hint":"사전형 + べからざる + 명사"},{"t":"fill","q":"健康[けんこう]は幸福[こうふく]に欠[か]く（　）条件[じょうけん]だ。","a":"べからざる","opts":["べからざる","べからず","べく","べきだ"]}],"src":["https://dojglite.github.io/main/grammar/dojg_pages/advancedべからずべからざる.html","https://bunpro.jp/grammar_points/855"],"vf":1,"u":10,"g":1,"gp":"gg_N1_03"},{"id":"g1_169","t":"～べからず","ko":"~하지 말 것, ~해서는 안 된다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"入る + べからず"},{"w":"する","f":"する → す + べからず (するべからず도 씀)"}],"rule":["1. 동사는 사전형 그대로 둔다: 入る.","2. 사전형 뒤에 べからず를 붙여 문장을 끝낸다: 入るべからず.","3. 장소·대상은 조사와 함께 앞에 둔다: 芝生に入るべからず.","4. する는 주로 す로 바꾸어 すべからず가 된다."],"why":"고전 조동사 べし의 미연형 べから에 부정 조동사 ず가 붙은 형태로, '~해서는 안 된다'는 강한 금지를 나타낸다.","nu":"게시판·표지·규칙·격언 등에 쓰이는 매우 딱딱한 금지 표현으로, 일상 대화에서는 쓰지 않는다. 문장 끝에만 오고 명사를 꾸밀 때는 べからざる를 쓴다. 働かざる者食うべからず(일하지 않는 자는 먹지도 말라) 같은 격언이 유명하다. 회화에서는 ~てはいけない, ~ないでください를 쓴다.","cmp":[{"g":"～べからざる","d":"명사를 꾸미는 형태(欠くべからざる人材). べからず는 문장을 끝맺는다."},{"g":"～てはいけない","d":"일상적인 금지 표현으로 대화·문장 어디에나 쓸 수 있다."}],"ex":[{"jp":"芝生[しばふ]に入[はい]るべからず。","ko":"잔디밭에 들어가지 말 것."},{"jp":"ここにごみを捨[す]てるべからず。","ko":"이곳에 쓰레기를 버리지 말 것."},{"jp":"「働[はたら]かざる者[もの]食[く]うべからず」という言葉[ことば]がある。","ko":"'일하지 않는 자는 먹지도 말라'라는 말이 있다."}],"dr":[{"t":"make","q":"触る → ～べからず","a":"触るべからず","hint":"동사 사전형 + べからず"},{"t":"make","q":"忘れる → ～べからず","a":"忘れるべからず","hint":"사전형을 그대로 두고 べからず를 붙인다"},{"t":"fill","q":"関係者[かんけいしゃ]以外[いがい]、立[た]ち入[い]る（　）。","a":"べからず","opts":["べからず","べからざる","べく","べくもない"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%B9%E3%81%8B%E3%82%89%E3%81%9A"],"vf":1,"u":10,"g":1,"gp":"gg_N1_03"},{"id":"g1_171","t":"～べくもない","ko":"(도저히) ~할 수 없다, ~할 리가 없다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"望む + べくもない"},{"w":"동사 사전형","f":"知る + べくもない"}],"rule":["1. 동사는 사전형 그대로 둔다: 望む.","2. 사전형 뒤에 べくもない를 붙인다: 望むべくもない.","3. 쓰이는 동사는 望む・知る・比べる・疑う 등으로 한정된다."],"why":"고전 조동사 べし의 연용형 べく에 も + ない가 붙은 형태로, '~할 수 있는 여지도 없다'는 뜻이 된다.","nu":"애초에 그럴 가능성이 전혀 없다는 뜻의 딱딱한 문어체다. 望むべくもない(바랄 수도 없다), 知るべくもない(알 길이 없다), 比べるべくもない(비교도 안 된다), 疑うべくもない(의심할 여지도 없다)처럼 굳어진 조합으로 쓰며, 아무 동사에나 붙이지 않는다. 解く・書く 같은 일반 동사로 만들지 않도록 주의한다.","cmp":[{"g":"～ようがない","d":"방법이 없어서 할 수 없다는 일반적 표현으로, 대부분의 동사에 쓸 수 있다."},{"g":"～わけがない","d":"말하는 사람의 강한 부정 판단 '~할 리가 없다'로 회화에서도 쓴다."}],"ex":[{"jp":"この給料[きゅうりょう]では、広[ひろ]い家[いえ]など望[のぞ]むべくもない。","ko":"이 월급으로는 넓은 집 같은 건 바랄 수도 없다."},{"jp":"当時[とうじ]の私[わたし]には、彼[かれ]の本当[ほんとう]の気持[きも]ちなど知[し]るべくもなかった。","ko":"당시의 나로서는 그의 진짜 마음 따위 알 길이 없었다."},{"jp":"プロの演奏[えんそう]は、私[わたし]たちのとは比[くら]べるべくもない。","ko":"프로의 연주는 우리 것과는 비교도 되지 않는다."}],"dr":[{"t":"make","q":"望む → ～べくもない","a":"望むべくもない","hint":"동사 사전형 + べくもない"},{"t":"make","q":"比べる → ～べくもない","a":"比べるべくもない","hint":"사전형 + べくもない"},{"t":"fill","q":"彼[かれ]が犯人[はんにん]であることは、疑[うたが]う（　）。","a":"べくもない","opts":["べくもない","べからず","べく","べからざる"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%B9%E3%81%8F%E3%82%82%E3%81%AA%E3%81%84"],"vf":1,"u":10,"g":1,"gp":"gg_N1_03"},{"id":"g1_178","t":"～が + 가능형","ko":"~을 ~할 수 있다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"水が + 飲む → 飲める"},{"w":"2그룹 동사","f":"刺身が + 食べる → 食べられる"},{"w":"する / 来る","f":"運転が + する → できる / 来る → 来られる"}],"rule":["1. 1그룹 동사는 어미 う단을 え단으로 바꾸고 る를 붙인다: 飲む → 飲める.","2. 2그룹 동사는 る를 떼고 られる를 붙인다: 食べる → 食べられる.","3. する는 できる, 来る는 来(こ)られる가 된다.","4. 대상을 나타내는 조사 を는 보통 が로 바꾼다: 水を飲む → 水が飲める."],"why":"","nu":"가능형은 '할 수 있다'는 상태를 나타내므로 대상을 が로 나타내는 것이 전통적인 형태다. 현대 회화에서는 を를 그대로 쓰는 경우(水を飲める)도 많다. 2그룹 동사와 来る에서 ら를 빼는 'ら抜き'(食べれる, 来れる)는 회화에서 흔하지만 표준 문법으로는 피하는 것이 좋다. られる에는 수동·존경의 뜻도 있으므로 문맥으로 구별한다.","cmp":[{"g":"～ことができる","d":"사전형 + ことができる로 가능을 나타내는 더 딱딱한 표현이다. 대상은 を를 그대로 쓴다(水を飲むことができる)."},{"g":"～が見える / 聞こえる","d":"의지와 상관없이 자연히 보이고 들린다는 뜻으로, 見られる・聞ける(의지로 볼 수 있다/들을 수 있다)와 다르다."}],"ex":[{"jp":"この川[かわ]の水[みず]はきれいなので、そのまま飲[の]める。","ko":"이 강물은 깨끗해서 그대로 마실 수 있다."},{"jp":"子[こ]どものころは、刺身[さしみ]が食[た]べられなかった。","ko":"어릴 때는 회를 먹지 못했다."},{"jp":"兄[あに]は車[くるま]の運転[うんてん]ができる。","ko":"형은 차를 운전할 수 있다."}],"dr":[{"t":"make","q":"漢字を書く → 가능형","a":"漢字が書ける","hint":"を → が, く → ける"},{"t":"make","q":"納豆を食べる → 가능형","a":"納豆が食べられる","hint":"を → が, る를 떼고 られる"},{"t":"fill","q":"私[わたし]はピアノ（　）弾[ひ]ける。","a":"が","opts":["が","に","へ","から"]}],"src":["https://www.tofugu.com/japanese-grammar/verb-potential-form-reru/"],"vf":1,"u":11,"g":1,"gp":"gg_N1_03"},{"id":"g1_185","t":"～ずにすんだ","ko":"~하지 않고 끝났다, ~하지 않아도 됐다","cat":"가능·의무·허가","conn":[{"w":"1그룹 동사","f":"払う → 払わ + ずに済んだ"},{"w":"2그룹 동사","f":"濡れる → 濡れ + ずに済んだ"},{"w":"する","f":"する → せ + ずに済んだ"},{"w":"来る","f":"来る → 来(こ) + ずに済んだ"}],"rule":["1. 동사를 ない형으로 바꿀 때의 형태(ない 앞부분)를 만든다. 2그룹은 어미 る를 뗀다: 濡れる → 濡れ.","2. 1그룹은 어미 う단을 あ단으로 바꾼다: 払う → 払わ.","3. 그 뒤에 ずに와 済んだ를 붙인다: 濡れずに済んだ.","4. する는 せずに済んだ, 来る는 来(こ)ずに済んだ가 된다."],"why":"ず는 부정의 뜻을 가진 문어 조동사이고, 済んだ는 동사 済む(일이 끝나다, 해결되다)의 과거형이다.","nu":"걱정하던 나쁜 일이나 하기 싫은 일을 하지 않아도 되어 다행이라는 안도감을 나타낸다. 회화에서는 ～ないで済んだ를 더 자주 쓴다. する를 しずに로 쓰는 실수에 주의한다(정답은 せずに).","cmp":[{"g":"～ないで済んだ","d":"뜻은 같고 더 구어적이다."},{"g":"～ずにはすまない","d":"'~하지 않고는 끝나지 않는다', 즉 반드시 해야 한다는 반대 방향의 뜻이다."}],"ex":[{"jp":"傘[かさ]を持[も]っていたので、濡[ぬ]れずに済[す]んだ。","ko":"우산을 가지고 있어서 젖지 않고 끝났다."},{"jp":"友達[ともだち]が手伝[てつだ]ってくれたので、徹夜[てつや]せずに済[す]んだ。","ko":"친구가 도와줘서 밤을 새우지 않아도 됐다."},{"jp":"早[はや]く気[き]づいたおかげで、修理代[しゅうりだい]を払[はら]わずに済[す]んだ。","ko":"일찍 알아챈 덕분에 수리비를 내지 않아도 됐다."}],"dr":[{"t":"make","q":"待つ → ～ずにすんだ","a":"待たずに済んだ","hint":"1그룹: つ → た(あ단) + ずに済んだ"},{"t":"make","q":"入院する → ～ずにすんだ","a":"入院せずに済んだ","hint":"する → せ + ずに済んだ"},{"t":"fill","q":"薬[くすり]が効[き]いて、手術[しゅじゅつ]を受[う]け（　）。","a":"ずに済んだ","opts":["ずに済んだ","ずにはいられない","ずじまいだった","ざるを得ない"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%9A%E3%81%AB%E6%B8%88%E3%82%80","https://jlptsensei.com/learn-japanese-grammar/ずに済む-zu-ni-sumu-meaning/"],"vf":1,"u":11,"g":1,"gp":"gg_N1_03"},{"id":"g1_219","t":"～には及ばない","ko":"~할 필요는 없다, ~할 것까지는 없다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형","f":"来る + には及ばない"},{"w":"명사(주로 する동사 명사)","f":"心配 + には及ばない"}],"rule":["1. 동사는 사전형 그대로 둔다: 来る.","2. 조사 には를 붙인다: 来るには.","3. 동사 及ぶ(1그룹)의 어미 ぶ를 あ단 ば로 바꾸고 ない를 붙인다: 及ぶ → 及ばない.","4. 합치면 来るには及ばない. 정중형은 及びません."],"why":"及ぶ(미치다, 이르다)의 부정형이다. '거기까지 갈 것까지는 없다'는 뜻에서 '~할 필요가 없다'가 되었다.","nu":"상대가 하려는 일에 대해 '그렇게까지 할 필요는 없다'고 말할 때 쓰는 딱딱한 표현이다. ご心配には及びません(걱정하실 필요 없습니다)처럼 정중한 장면에서 자주 쓴다. 같은 형태로 명사 + には及ばない가 '(능력·수준이) ~에는 미치지 못한다'는 뜻으로도 쓰이므로(兄には及ばない) 문맥으로 구별한다. 일상 회화에서는 ～なくてもいい, ～ことはない가 자연스럽다.","cmp":[{"g":"～ことはない","d":"동사 사전형 + ことはない. 같은 '~할 필요 없다'지만 회화적이다."},{"g":"～までもない","d":"너무 당연해서 ~할 필요도 없다(言うまでもない). には及ばない는 상대의 수고를 덜어 주는 느낌이 강하다."}],"ex":[{"jp":"わざわざ来[く]るには及[およ]ばないよ。電話[でんわ]で十分[じゅうぶん]だ。","ko":"일부러 올 필요는 없어. 전화로 충분해."},{"jp":"軽[かる]いけがなので、ご心配[しんぱい]には及[およ]びません。","ko":"가벼운 상처이니 걱정하실 필요 없습니다."},{"jp":"この程度[ていど]の問題[もんだい]なら、専門家[せんもんか]に聞[き]くには及[およ]ばない。","ko":"이 정도 문제라면 전문가에게 물어볼 것까지는 없다."}],"dr":[{"t":"make","q":"謝る → ～には及ばない","a":"謝るには及ばない","hint":"사전형 + には + 及ぶ의 ぶ를 ば로 + ない"},{"t":"make","q":"お礼 → ～には及びません","a":"お礼には及びません","hint":"명사 + には + 及ぶ의 ます형 及び + ません"},{"t":"fill","q":"大[たい]したことではないので、お見舞[みま]いに来[く]る（　）。","a":"には及ばない","opts":["には及ばない","に違いない","に過ぎない","に相違ない"]}],"src":[],"vf":0,"u":11,"g":1,"gp":"gg_N1_04"},{"id":"g1_221","t":"～に堪える","ko":"~할 만하다, ~할 가치가 있다, ~을 감당할 만하다","cat":"가능·의무·허가","conn":[{"w":"동사 사전형(読む・見る・鑑賞する 등)","f":"読む + に堪える"},{"w":"명사(鑑賞・批判・使用 등)","f":"鑑賞 + に堪える"}],"rule":["1. 동사 사전형 또는 명사에 조사 に를 붙인다: 読むに.","2. 2그룹 동사 堪える(たえる)를 그대로 붙인다: 読むに堪える.","3. 명사를 꾸밀 때도 그대로 쓴다: 読むに堪える本, 鑑賞に堪える作品."],"why":"堪える(견디다, 감당하다)를 그대로 쓴 형태로, '읽는 것을 감당할 수 있을 만한 수준이다'에서 '~할 가치가 있다'는 뜻이 된다.","nu":"작품·의견·제품 등이 일정한 수준에 이르러 '~할 만한 가치가 있다', '~을 견뎌 낼 만하다'고 평가할 때 쓰는 딱딱한 문어체이다. 鑑賞に堪える, 批判に堪える, 使用に堪える처럼 명사와 함께 쓰는 경우가 많고, 十分 등과 어울린다. 부정형 に堪えない가 더 자주 쓰인다. 고통을 참는다는 뜻의 '~에 견디다'는 보통 耐える로 쓴다.","cmp":[{"g":"～に堪えない","d":"부정형. '차마 ~할 수 없다' 또는 '~을 금할 수 없다'."},{"g":"～に値する","d":"~할 가치가 있다(注目に値する). 뜻이 가깝고, に堪える는 '수준이 그만큼 버틴다'는 느낌이 있다."}],"ex":[{"jp":"これは大人[おとな]の鑑賞[かんしょう]にも十分[じゅうぶん]堪[た]える作品[さくひん]だ。","ko":"이것은 어른이 감상하기에도 충분한 작품이다."},{"jp":"学生[がくせい]の論文[ろんぶん]だが、専門家[せんもんか]が読[よ]むに堪[た]える内容[ないよう]だ。","ko":"학생 논문이지만 전문가가 읽을 만한 내용이다."},{"jp":"この古[ふる]い机[つくえ]はまだ使用[しよう]に堪[た]える。","ko":"이 낡은 책상은 아직 쓸 만하다."}],"dr":[{"t":"make","q":"見る → ～に堪える (명사 映画를 꾸밈)","a":"見るに堪える映画","hint":"사전형 + に + 堪える + 명사"},{"t":"make","q":"批判 → ～に堪える","a":"批判に堪える","hint":"명사 + に + 堪える"},{"t":"fill","q":"このカメラは古[ふる]いが、まだ十分[じゅうぶん]使用[しよう]に（　）。","a":"堪える","opts":["堪える","過ぎない","限る","違いない"]}],"src":[],"vf":0,"u":11,"g":1,"gp":"gg_N1_04"},{"id":"g1_225","t":"～に難くない","ko":"~하기 어렵지 않다, 쉽게 ~할 수 있다","cat":"가능·의무·허가","conn":[{"w":"명사(想像・理解 등)","f":"想像 + に難くない"},{"w":"동사 사전형(察する 등)","f":"察する + に難くない"}],"rule":["1. 想像, 理解 같은 명사나 察する 같은 동사 사전형에 조사 に를 붙인다: 想像に.","2. い형용사 難い(かたい)의 어미 い를 く로 바꾼다: 難い → 難く.","3. ない를 붙인다: 想像に難くない."],"why":"難い(かたい, 어렵다)의 부정형 難くない로, '~하는 데 어렵지 않다'는 뜻이다.","nu":"정황으로 보아 '쉽게 짐작·이해할 수 있다'는 뜻의 딱딱한 문어체이다. 앞에 오는 말은 想像, 理解, 察する, 推測 정도로 거의 정해져 있어서 '쉽게 할 수 있다'는 일반적인 뜻으로 아무 동사에나 쓰지 않는다(×作るに難くない). 難い를 むずかしい로 읽지 않도록 주의한다.","cmp":[{"g":"～やすい","d":"동사 ます형 + やすい로 '~하기 쉽다'를 말하는 일반 표현. に難くない는 상상·이해 계열에만 쓰는 문어."}],"ex":[{"jp":"彼[かれ]がどれほど喜[よろこ]んだかは想像[そうぞう]に難[かた]くない。","ko":"그가 얼마나 기뻐했을지는 쉽게 상상할 수 있다."},{"jp":"家族[かぞく]を失[うしな]った彼女[かのじょ]の悲[かな]しみは察[さっ]するに難[かた]くない。","ko":"가족을 잃은 그녀의 슬픔은 헤아리기 어렵지 않다."},{"jp":"準備[じゅんび]不足[ぶそく]が失敗[しっぱい]の原因[げんいん]であることは理解[りかい]に難[かた]くない。","ko":"준비 부족이 실패의 원인이라는 것은 쉽게 이해할 수 있다."}],"dr":[{"t":"make","q":"理解 → ～に難くない","a":"理解に難くない","hint":"명사 + に + 難い의 い를 く로 + ない"},{"t":"make","q":"察する → ～に難くない","a":"察するに難くない","hint":"동사 사전형 + に難くない"},{"t":"fill","q":"突然[とつぜん]仕事[しごと]を失[うしな]った彼[かれ]の不安[ふあん]は想像[そうぞう]（　）。","a":"に難くない","opts":["に難くない","に越したことはない","には及ばない","に至った"]}],"src":[],"vf":0,"u":12,"g":1,"gp":"gg_N1_04"},{"id":"g1_239","t":"～差し支えない","ko":"~해도 지장 없다, ~해도 괜찮다","cat":"가능·의무·허가","conn":[{"w":"동사 て형","f":"書いて + も差し支えない"},{"w":"い형용사","f":"遅い → 遅くて + も差し支えない"},{"w":"な형용사","f":"簡単 + でも差し支えない"},{"w":"명사","f":"鉛筆 + でも差し支えない"}],"rule":["1. 동사를 て형으로 만든다. 書く는 어미 く가 い로 바뀌고(イ음편) て가 붙는다: 書く → 書いて.","2. て형 뒤에 조사 も를 붙인다: 書いても.","3. 마지막에 差し支えない를 붙인다: 書いても差し支えない.","4. 명사·な형용사는 でも, い형용사는 くても 뒤에 差し支えない를 붙인다."],"why":"差し支える(지장이 생기다)의 부정형 差し支えない에 '~해도'의 ても가 결합한 것이다. '해도 지장이 생기지 않는다'는 글자 그대로의 뜻이다.","nu":"てもいい, てもかまわない와 같은 허가·용인의 뜻이지만 더 격식 있고 정중하다. 공문·안내·비즈니스 장면에서 差し支えありません 형태로 많이 쓴다. 差し支えなければ(괜찮으시다면)는 정중하게 부탁할 때의 관용 표현이다. 친한 사이의 회화에 쓰면 지나치게 딱딱하게 들린다.","cmp":[{"g":"～てもかまわない","d":"뜻은 거의 같지만 일상 회화에도 쓰는 표현. 差し支えない가 더 격식 있다."},{"g":"～てもいい","d":"가장 일반적인 허가 표현으로 정중도가 가장 낮다."}],"ex":[{"jp":"申込書[もうしこみしょ]は鉛筆[えんぴつ]で書[か]いても差[さ]し支[つか]えありません。","ko":"신청서는 연필로 써도 지장 없습니다."},{"jp":"お返事[へんじ]は来週[らいしゅう]になっても差[さ]し支[つか]えありません。","ko":"답변은 다음 주가 되어도 괜찮습니다."},{"jp":"差[さ]し支[つか]えなければ、お名前[なまえ]を教[おし]えていただけますか。","ko":"괜찮으시다면 성함을 알려 주시겠습니까?"}],"dr":[{"t":"make","q":"使う → ～ても差し支えない","a":"使っても差し支えない","hint":"う → って(촉음편) + も差し支えない"},{"t":"make","q":"休む → ～ても差し支えない","a":"休んでも差し支えない","hint":"む → んで(발음편) + も差し支えない"},{"t":"fill","q":"この部屋[へや]は自由[じゆう]に使[つか]っても（　）。","a":"差し支えありません","opts":["差し支えありません","いけません","なりません","しかたありません"]}],"src":[],"vf":0,"u":12,"g":1,"gp":"gg_N1_04"},{"id":"g1_003","t":"～かたわら","ko":"~하는 한편, ~하는 틈틈이","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"働く + かたわら"},{"w":"명사","f":"会社員の + かたわら / 仕事の + かたわら"}],"rule":["1. 명사 뒤에는 조사 の를 넣는다. 会社員 → 会社員の.","2. 그 뒤에 かたわら를 붙인다. 会社員のかたわら.","3. 동사는 사전형에 바로 かたわら를 붙인다. 働く → 働くかたわら."],"why":"かたわら(傍ら)는 원래 '곁, 옆'이라는 뜻의 명사다.","nu":"본업(직업・학업)을 하면서 그 곁에서 다른 활동도 꾸준히 한다는 뜻. 한 번의 동시 동작이 아니라 장기간에 걸친 생활을 말한다. 문어적이며, 주어는 앞뒤가 같은 사람이다. '밥을 먹으면서 TV를 본다' 같은 순간적 동시 동작에는 ～ながら를 쓴다.","cmp":[{"g":"～ながら","d":"같은 순간에 두 동작을 함께 하는 것. かたわら는 긴 기간 동안 본업과 다른 일을 병행하는 것."},{"g":"～かたがた","d":"한 번의 행동이 두 목적을 겸하는 것(お礼かたがた伺う). かたわら는 꾸준한 병행."}],"ex":[{"jp":"彼[かれ]は会社員[かいしゃいん]のかたわら、絵[え]を描[か]いている。","ko":"그는 회사원으로 일하는 한편 그림을 그리고 있다."},{"jp":"母[はは]は家事[かじ]をするかたわら、近所[きんじょ]の子供[こども]に英語[えいご]を教[おし]えている。","ko":"어머니는 집안일을 하는 한편 이웃 아이들에게 영어를 가르치고 있다."},{"jp":"彼女[かのじょ]は大学[だいがく]で研究[けんきゅう]するかたわら、小説[しょうせつ]を書[か]いている。","ko":"그녀는 대학에서 연구하는 한편 소설을 쓰고 있다."}],"dr":[{"t":"make","q":"仕事 → ～かたわら","a":"仕事のかたわら","hint":"명사 + の + かたわら"},{"t":"make","q":"店を経営する → ～かたわら","a":"店を経営するかたわら","hint":"동사 사전형 + かたわら"},{"t":"fill","q":"父[ちち]は教師[きょうし]の（　）、野菜[やさい]を育[そだ]てている。","a":"かたわら","opts":["かたわら","くせに","とたんに","あげく"]}],"src":["https://nihongokyoshi-net.com/2019/02/15/jlptn1-grammar-katawara/","https://bunpro.jp/grammar_points/747"],"vf":1,"u":12,"g":1,"gp":"gg_N1_04"},{"id":"g1_059","t":"～にして初めて","ko":"~이 되어서야 비로소, ~이기에 비로소","cat":"시간·순서","conn":[{"w":"명사(나이·단계)","f":"60歳 + にして初めて"},{"w":"명사(사람)","f":"名人 + にして初めて"}],"rule":["1. 나이·단계나 사람을 나타내는 명사를 쓴다(60歳).","2. 그 뒤에 にして初めて를 붙인다(60歳にして初めて).","3. 뒤에 그때 처음 일어난 일이나 그 사람만 할 수 있는 일을 쓴다(60歳にして初めて海を見た)."],"why":"にして(~에 이르러) 뒤에 初めて(처음으로, 비로소)가 붙은 구성이라 '~에 이르러서야 비로소'라는 뜻이 된다.","nu":"문어적이다. 나이·단계에 붙으면 '그때가 되어서야 처음으로'라는 뜻이고, 名人・一流の料理人처럼 뛰어난 사람에 붙으면 '그런 사람이기에 비로소 가능하다'는 뜻이 된다. 뒤에는 '처음 ~했다', '~할 수 있다', '~를 알 수 있다' 같은 내용이 온다.","cmp":[{"g":"～てはじめて","d":"동사 て형에 붙는다(経験してはじめて分かる). にして初めて는 명사에 붙는다."}],"ex":[{"jp":"祖母[そぼ]は60歳[ろくじゅっさい]にして初[はじ]めて海[うみ]を見[み]た。","ko":"할머니는 60세가 되어서야 처음으로 바다를 보았다."},{"jp":"この味[あじ]は、一流[いちりゅう]の料理人[りょうりにん]にして初[はじ]めて出[だ]せるものだ。","ko":"이 맛은 일류 요리사이기에 비로소 낼 수 있는 것이다."},{"jp":"彼[かれ]は三回目[さんかいめ]の試験[しけん]にして初[はじ]めて合格[ごうかく]した。","ko":"그는 세 번째 시험에서야 비로소 합격했다."}],"dr":[{"t":"make","q":"60歳 → ～にして初めて","a":"60歳にして初めて","hint":"명사 + にして初めて"},{"t":"make","q":"名人 → ～にして初めて（できる技）","a":"名人にして初めて","hint":"사람 명사 + にして初めて"},{"t":"fill","q":"この技[わざ]は、彼[かれ]のような名人[めいじん]（　）できるものだ。","a":"にして初めて","opts":["にして初めて","にひきかえ","にあるまじき","にとどまらず"]}],"src":["https://bunpro.jp/grammar_points/780"],"vf":1,"u":12,"g":1,"gp":"gg_N1_04"},{"id":"g1_065","t":"～に先駆けて","ko":"~에 앞서, ~보다 먼저","cat":"시간·순서","conn":[{"w":"명사","f":"他社 + に先駆けて"},{"w":"명사(지역·범위)","f":"全国 + に先駆けて"}],"rule":["1. 비교 대상이 되는 명사를 쓴다(他社).","2. 명사 뒤에 に + 先駆けて를 붙인다(他社に先駆けて).","3. 先駆けて는 先駆ける(앞장서다)의 て형으로, 뒤에 먼저 한 행동이 온다(他社に先駆けて発売した)."],"why":"先駆ける(앞장서다, 선구가 되다)의 て형이다.","nu":"문어적이며 뉴스·비즈니스 문장에서 자주 쓴다. 다른 회사·지역·사람들보다 먼저, 선두에 서서 어떤 일을 했다는 의미다. 명사를 꾸밀 때는 に先駆けた(世界に先駆けた技術)를 쓴다.","cmp":[{"g":"～に先立って","d":"어떤 일을 하기 '전에' 준비로 한다는 뜻(開会に先立って挨拶する). に先駆けて는 다른 것들보다 '먼저, 앞장서서' 한다는 뜻."}],"ex":[{"jp":"この映画[えいが]は日本[にほん]に先駆[さきが]けて、アメリカで公開[こうかい]された。","ko":"이 영화는 일본보다 먼저 미국에서 공개되었다."},{"jp":"A社[えーしゃ]は他社[たしゃ]に先駆[さきが]けて、新[あたら]しいサービスを始[はじ]めた。","ko":"A사는 다른 회사들에 앞서 새로운 서비스를 시작했다."},{"jp":"全国[ぜんこく]に先駆[さきが]けて、この町[まち]でごみの分別[ぶんべつ]が始[はじ]まった。","ko":"전국에 앞서 이 마을에서 쓰레기 분리수거가 시작되었다."}],"dr":[{"t":"make","q":"他社 → ～に先駆けて","a":"他社に先駆けて","hint":"명사 + に + 先駆けて"},{"t":"make","q":"世界・技術 → ～に先駆けた～","a":"世界に先駆けた技術","hint":"명사를 꾸밀 때는 先駆けた"},{"t":"fill","q":"A社[えーしゃ]は他社[たしゃ]（　）、新製品[しんせいひん]を発売[はつばい]した。","a":"に先駆けて","opts":["に先駆けて","にひきかえ","にすら","にあるまじき"]}],"src":["https://bunpro.jp/grammar_points/993"],"vf":1,"u":12,"g":1,"gp":"gg_N1_04"},{"id":"g1_103","t":"～を境に（して）","ko":"~을 경계로, ~을 기점으로","cat":"시간·순서","conn":[{"w":"명사 (시점·사건)","f":"あの日 + を境にして"},{"w":"명사 (장소)","f":"川 + を境にして"}],"rule":["1. 境(경계) 뒤에 조사 に를 붙인다: 境に.","2. する의 る를 떼고 し로 바꾼 뒤 て를 붙인다: する → して (생략 가능).","3. 기준이 되는 명사 + を 뒤에 둔다: あの日を境にして."],"why":"境(경계) + に + して(する의 て형)로 이루어져 '~을 경계로 하여'라는 뜻이 된다.","nu":"어떤 시점·사건을 경계로 그 전과 후의 상태가 크게 달라졌다는 뜻이다. 뒤에는 변화를 나타내는 표현(変わった, ～ようになった, 一変した)이 온다. 변화가 없는 단순한 예정(試験を境に休む 등)에는 쓰지 않는다. 장소에 쓰면 川を境にして처럼 공간을 둘로 나누는 경계를 나타낸다. して를 뺀 を境に가 더 자주 쓰인다.","cmp":[{"g":"～を機に","d":"그 일을 좋은 기회로 삼아 스스로 무언가를 시작·결심한다는 뜻(의지적 행동). を境に는 전후의 상태 변화에 초점이 있다."}],"ex":[{"jp":"父[ちち]の死[し]を境[さかい]に、彼[かれ]の性格[せいかく]はすっかり変[か]わった。","ko":"아버지의 죽음을 기점으로 그의 성격은 완전히 바뀌었다."},{"jp":"あの日[ひ]を境[さかい]にして、彼女[かのじょ]は毎朝[まいあさ]走[はし]るようになった。","ko":"그날을 경계로 그녀는 매일 아침 달리게 되었다."},{"jp":"この川[かわ]を境[さかい]にして、東[ひがし]と西[にし]で言葉[ことば]が少[すこ]し違[ちが]う。","ko":"이 강을 경계로 동쪽과 서쪽의 말이 조금 다르다."}],"dr":[{"t":"make","q":"あの事故 → ～を境にして","a":"あの事故を境にして","hint":"명사 + を + 境 + に + して"},{"t":"make","q":"結婚 → ～を境に","a":"結婚を境に","hint":"명사 + を + 境 + に"},{"t":"fill","q":"四十歳[よんじゅっさい]（　）、急[きゅう]に体力[たいりょく]が落[お]ちた。","a":"を境に","opts":["を境に","をよそに","をおいて","を余儀なく"]}],"src":["https://bunpro.jp/grammar_points/1099","https://nihongokyoshi-net.com/2019/09/15/jlptn1-grammar-sakaini/"],"vf":1,"u":13,"g":1,"gp":"gg_N1_04"},{"id":"g1_104","t":"～を機に（して）","ko":"~을 계기로, ~을 기회로","cat":"시간·순서","conn":[{"w":"명사","f":"卒業 + を機にして"},{"w":"동사 보통형 + の","f":"子どもが生まれたの + を機に"}],"rule":["1. 機(기회) 뒤에 조사 に를 붙인다: 機に.","2. する의 る를 떼고 し로 바꾼 뒤 て를 붙인다: する → して (생략 가능).","3. 계기가 되는 명사 + を 뒤에 둔다: 卒業を機にして."],"why":"機(기회, 때) + に + して(する의 て형)로 이루어져 '~을 기회로 하여'라는 뜻이 된다.","nu":"졸업·취직·결혼·이사 같은 일을 좋은 기회로 삼아 새로운 행동을 시작하거나 그만둔다는 뜻이다. 뒤에는 화자나 주어의 의지적인 행동(始めた, やめた, ～ことにした)이 자주 온다. 다소 격식 있는 표현이며, して를 뺀 を機に가 더 많이 쓰인다. を機として도 같은 뜻이다.","cmp":[{"g":"～をきっかけに","d":"회화에서도 널리 쓰며, 우연한 일이나 나쁜 일이 계기가 되는 경우에도 자연스럽다. を機に는 '좋은 기회로 삼는다'는 느낌이 강하다."},{"g":"～を境に","d":"그 시점 전후의 상태 변화를 말한다."}],"ex":[{"jp":"引[ひ]っ越[こ]しを機[き]に、家具[かぐ]を全部[ぜんぶ]新[あたら]しくした。","ko":"이사를 계기로 가구를 전부 새로 바꿨다."},{"jp":"子[こ]どもが生[う]まれたのを機[き]にして、たばこをやめた。","ko":"아이가 태어난 것을 계기로 담배를 끊었다."},{"jp":"定年[ていねん]を機[き]に、田舎[いなか]で暮[く]らすことにした。","ko":"정년퇴직을 계기로 시골에서 살기로 했다."}],"dr":[{"t":"make","q":"卒業 → ～を機にして","a":"卒業を機にして","hint":"명사 + を + 機 + に + して"},{"t":"make","q":"入社 → ～を機に","a":"入社を機に","hint":"명사 + を + 機 + に"},{"t":"fill","q":"就職[しゅうしょく]（　）、一人暮[ひとりぐ]らしを始[はじ]めた。","a":"を機に","opts":["を機に","をよそに","をおいて","を禁じ得ず"]}],"src":["https://bunpro.jp/grammar_points/994"],"vf":1,"u":13,"g":1,"gp":"gg_N1_04"},{"id":"g1_105","t":"～を皮切りに","ko":"~을 시작으로, ~을 필두로","cat":"시간·순서","conn":[{"w":"명사","f":"東京公演 + を皮切りに"},{"w":"동사 보통형 + の","f":"一人が話したの + を皮切りに"}],"rule":["1. 출발점이 되는 명사 뒤에 조사 を를 붙인다: 東京 → 東京を.","2. 皮切り(시작) + に를 붙인다: 東京を皮切りに.","3. 뒤에 같은 종류의 일이 잇따라 일어나는 내용을 쓴다."],"why":"","nu":"그것을 첫 번째로 같은 종류의 일이 차례차례 이어지거나 번져 간다는 뜻이다. 공연 투어·행사·발매·발언 등에 자주 쓰며, 뒤에는 次々と, 各地で, 全国で 같은 연속·확대 표현이 어울린다. 하나만 일어나고 끝나는 일에는 쓰지 않는다. を皮切りとして, を皮切りにして로도 쓴다.","cmp":[{"g":"～をきっかけに","d":"그 일이 원인이 되어 변화가 생겼다는 뜻. を皮切りに는 같은 종류의 일이 연속되는 출발점을 말한다."},{"g":"～をはじめ(として)","d":"대표적인 예를 하나 들고 나머지를 묶는 표현으로, 시간 순서의 뜻은 없다."}],"ex":[{"jp":"東京[とうきょう]公演[こうえん]を皮切[かわき]りに、全国[ぜんこく]ツアーが始[はじ]まる。","ko":"도쿄 공연을 시작으로 전국 투어가 시작된다."},{"jp":"彼[かれ]の発言[はつげん]を皮切[かわき]りに、反対[はんたい]の意見[いけん]が次々[つぎつぎ]と出[で]た。","ko":"그의 발언을 시작으로 반대 의견이 잇따라 나왔다."},{"jp":"この映画[えいが]を皮切[かわき]りに、彼女[かのじょ]は次々[つぎつぎ]と主役[しゅやく]を演[えん]じるようになった。","ko":"이 영화를 시작으로 그녀는 잇달아 주역을 맡게 되었다."}],"dr":[{"t":"make","q":"大阪 → ～を皮切りに","a":"大阪を皮切りに","hint":"명사 + を + 皮切り + に"},{"t":"make","q":"東京公演 → ～を皮切りに","a":"東京公演を皮切りに","hint":"명사 + を + 皮切り + に"},{"t":"fill","q":"札幌[さっぽろ]（　）、全国[ぜんこく]十[じゅっ]か所[しょ]でコンサートを行[おこな]う。","a":"を皮切りに","opts":["を皮切りに","をよそに","を余儀なく","をものともせず"]}],"src":["https://bunpro.jp/grammar_points/748","https://nihongokyoshi-net.com/2019/07/26/jlptn1-grammar-wokawakirini/"],"vf":1,"u":13,"g":1,"gp":"gg_N1_04"},{"id":"g1_106","t":"～を皮切りにして","ko":"~을 시작으로 해서","cat":"시간·순서","conn":[{"w":"명사","f":"初日 + を皮切りにして"},{"w":"동사 보통형 + の","f":"手を挙げたの + を皮切りにして"}],"rule":["1. 皮切り(시작) 뒤에 조사 に를 붙인다: 皮切りに.","2. する의 る를 떼고 し로 바꾼 뒤 て를 붙인다: する → して.","3. 출발점이 되는 명사 + を 뒤에 둔다: 初日を皮切りにして."],"why":"皮切り(시작) + に + して(する의 て형)로 이루어진 '~을 시작으로 해서'라는 뜻이다.","nu":"を皮切りに와 뜻이 같고 して가 붙은 형태다. 그것을 출발점으로 같은 종류의 일이 잇따라 일어나거나 퍼져 나간다는 뜻이며, 단 한 번으로 끝나는 일에는 쓰지 않는다. 문장과 회화 양쪽에서 쓸 수 있는 표준적인 표현이다.","cmp":[{"g":"～を皮切りに","d":"뜻은 같고 더 짧고 흔한 형태다."},{"g":"～をはじめ(として)","d":"대표 예를 들어 나머지를 묶는 표현으로 시간 순서의 뜻이 없다."}],"ex":[{"jp":"新年会[しんねんかい]を皮切[かわき]りにして、今年[ことし]もいろいろな行事[ぎょうじ]が続[つづ]く。","ko":"신년회를 시작으로 해서 올해도 여러 행사가 이어진다."},{"jp":"一号店[いちごうてん]の成功[せいこう]を皮切[かわき]りにして、店[みせ]は全国[ぜんこく]に広[ひろ]がった。","ko":"1호점의 성공을 시작으로 해서 가게는 전국으로 퍼졌다."},{"jp":"一人[ひとり]が手[て]を挙[あ]げたのを皮切[かわき]りにして、次々[つぎつぎ]と質問[しつもん]が出[で]た。","ko":"한 사람이 손을 든 것을 시작으로 해서 잇따라 질문이 나왔다."}],"dr":[{"t":"make","q":"初日 → ～を皮切りにして","a":"初日を皮切りにして","hint":"명사 + を + 皮切り + に + して"},{"t":"make","q":"皮切りにする → て형","a":"皮切りにして","hint":"する → して"},{"t":"fill","q":"デビュー曲[きょく]のヒット（　）、彼[かれ]らは次々[つぎつぎ]とヒット曲[きょく]を出[だ]した。","a":"を皮切りにして","opts":["を皮切りにして","をよそに","を禁じ得ず","をおいて"]}],"src":["https://bunpro.jp/grammar_points/748"],"vf":1,"u":13,"g":1,"gp":"gg_N1_04"},{"id":"g1_108","t":"～を経て","ko":"~을 거쳐","cat":"시간·순서","conn":[{"w":"명사 (장소)","f":"名古屋 + を経て"},{"w":"명사 (과정·기간)","f":"話し合い + を経て"}],"rule":["1. 2그룹 동사 経る(へる, 거치다)의 어미 る를 뗀다: 経る → 経.","2. て를 붙여 て형 経て(へて)를 만든다.","3. 거쳐 가는 장소나 과정을 나타내는 명사 + を 뒤에 둔다: 名古屋を経て."],"why":"동사 経る(へる, 거치다·지나다)의 て형이다.","nu":"다소 문어적인 표현이다. ① 장소: 名古屋を経て大阪へ처럼 경유지를 나타낸다. ② 과정·단계·기간: 長い議論を経て, 三年の修業を経て처럼 어떤 과정을 거친 뒤에 결과에 이른다는 뜻이다. 経て는 へて로 읽으며 けいて로 읽지 않도록 주의한다.","cmp":[{"g":"～を通して / ～を通じて","d":"매개·수단(友人を通して知り合う)이나 기간 전체(一年を通して)를 나타낸다. を経て는 거쳐 지나간 뒤 다음 단계에 이른다는 순서의 뜻이다."}],"ex":[{"jp":"この電車[でんしゃ]は名古屋[なごや]を経[へ]て大阪[おおさか]へ行[い]く。","ko":"이 전철은 나고야를 거쳐 오사카로 간다."},{"jp":"長[なが]い話[はな]し合[あ]いを経[へ]て、ようやく結論[けつろん]が出[で]た。","ko":"긴 논의를 거쳐 겨우 결론이 났다."},{"jp":"彼[かれ]は三年[さんねん]の修業[しゅぎょう]を経[へ]て、自分[じぶん]の店[みせ]を開[ひら]いた。","ko":"그는 3년의 수련을 거쳐 자기 가게를 열었다."}],"dr":[{"t":"make","q":"名古屋 → ～を経て","a":"名古屋を経て","hint":"명사 + を + 経る의 て형(る → て)"},{"t":"make","q":"経る → て형","a":"経て","hint":"2그룹: る를 떼고 て"},{"t":"fill","q":"二度[にど]の手術[しゅじゅつ]（　）、彼[かれ]はやっと歩[ある]けるようになった。","a":"を経て","opts":["を経て","をよそに","をおいて","を禁じ得ず"]}],"src":["https://bunpro.jp/grammar_points/790"],"vf":1,"u":14,"g":1,"gp":"gg_N1_04"},{"id":"g1_110","t":"～を限りに","ko":"~을 마지막으로, ~을 끝으로","cat":"시간·순서","conn":[{"w":"명사(시점)","f":"今日 + を限りに"},{"w":"명사(시점)","f":"本日 + を限りに"}],"rule":["1. 1그룹 동사 限る(한정하다)의 어미 る를 り로 바꿔 ます형 限り를 만든다: 限る → 限り.","2. 그 뒤에 に를 붙인다: 限りに.","3. 마지막이 되는 시점 명사에 を를 붙여 앞에 둔다: 今日を限りに."],"why":"","nu":"今日・今月・今年度・本日 같은 시점을 나타내는 명사에 붙어, 그때까지 계속되던 일이 그 시점을 끝으로 끝난다(그만두다, 은퇴하다, 폐점하다)는 뜻이다. 공지, 인사말 등 격식 있는 장면에서 많이 쓴다. 미래의 한 시점부터 새로 시작하는 일에는 쓰지 않는다. 관용구 声を限りに(목청껏)는 '한계까지'라는 다른 뜻이므로 구별한다.","cmp":[{"g":"～をもって","d":"'~으로써, ~부로'라는 뜻의 더 딱딱한 공문서 표현으로, 끝나는 일뿐 아니라 시작에도 쓴다(4月1日をもって施行する). を限りに는 끝나는 일에만 쓴다."}],"ex":[{"jp":"今日[きょう]を限[かぎ]りに、たばこをやめます。","ko":"오늘을 마지막으로 담배를 끊겠습니다."},{"jp":"当店[とうてん]は本日[ほんじつ]を限[かぎ]りに閉店[へいてん]いたします。","ko":"저희 가게는 오늘을 끝으로 폐점합니다."},{"jp":"彼[かれ]は今[こん]シーズンを限[かぎ]りに引退[いんたい]すると発表[はっぴょう]した。","ko":"그는 이번 시즌을 마지막으로 은퇴한다고 발표했다."}],"dr":[{"t":"make","q":"今月 → ～を限りに","a":"今月を限りに","hint":"시점 명사 + を + 限り(限る의 ます형) + に"},{"t":"make","q":"本日 → ～を限りに","a":"本日を限りに","hint":"명사 + を限りに"},{"t":"fill","q":"本日[ほんじつ]を（　）、この店[みせ]は閉店[へいてん]します。","a":"限りに","opts":["限りに","通して","めぐって","踏まえて"]}],"src":["https://bunpro.jp/grammar_points/946"],"vf":1,"u":14,"g":1,"gp":"gg_N1_05"},{"id":"g1_114","t":"～がてら","ko":"~하는 김에, ~을 겸해서","cat":"시간·순서","conn":[{"w":"명사(동작성)","f":"散歩 + がてら"},{"w":"동사 ます형","f":"送り + がてら"}],"rule":["1. 동작을 나타내는 명사 뒤에 그대로 がてら를 붙인다: 散歩がてら.","2. 동사는 ます형에 붙인다. 1그룹은 어미 う단을 い단으로 바꾼다: 送る → 送り → 送りがてら.","3. 그 뒤에 겸해서 하는 행동(주로 이동: 行く, 寄る)을 둔다: 散歩がてら郵便局へ行く."],"why":"","nu":"앞의 행동을 하는 기회를 이용해 뒤의 행동도 함께 한다는 뜻이며, 두 행동의 주어는 같다. 뒤에는 行く, 寄る, 出かける처럼 이동하는 동사가 자주 온다. 散歩, 買い物 같은 명사와 함께 쓰는 경우가 많다. 다소 문어적이다. 사전형에 붙이는 것(×散歩するがてら)은 틀린 형태다.","cmp":[{"g":"～ついでに","d":"동사 사전형·た형, 명사+の에 붙고 회화에서 넓게 쓴다. 본래 목적의 행동에 덧붙여 다른 일을 한다는 뜻이 중심이다. がてら는 명사·ます형에만 붙고 두 행동을 겸한다는 느낌이다."},{"g":"～かたがた","d":"お礼かたがた처럼 인사·사과 등 명사에 붙는 더 격식 있는 표현으로, 편지나 비즈니스에서 쓴다."}],"ex":[{"jp":"散歩[さんぽ]がてら、パンを買[か]いに行[い]った。","ko":"산책하는 김에 빵을 사러 갔다."},{"jp":"駅[えき]まで友達[ともだち]を送[おく]りがてら、本屋[ほんや]に寄[よ]った。","ko":"역까지 친구를 배웅하는 김에 서점에 들렀다."},{"jp":"買[か]い物[もの]がてら、新[あたら]しくできた公園[こうえん]を見[み]てきた。","ko":"장 보는 김에 새로 생긴 공원을 보고 왔다."}],"dr":[{"t":"make","q":"散歩 → ～がてら","a":"散歩がてら","hint":"동작 명사 + がてら"},{"t":"make","q":"遊ぶ → ～がてら","a":"遊びがてら","hint":"ぶ → び(ます형) + がてら"},{"t":"fill","q":"買[か]い物[もの]（　）、郵便局[ゆうびんきょく]に寄[よ]った。","a":"がてら","opts":["がてら","ながらに","ばかりに","ものなら"]}],"src":["https://bunpro.jp/grammar_points/836"],"vf":1,"u":14,"g":1,"gp":"gg_N1_05"},{"id":"g1_124","t":"～そばから","ko":"~하자마자 곧 (또), ~하는 족족","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"片付ける + そばから"},{"w":"동사 た형","f":"習った + そばから"}],"rule":["1. 동사는 사전형을 활용하지 않고 그대로 둔다: 片付ける.","2. 바로 뒤에 そばから를 붙인다: 片付けるそばから.","3. 그 뒤에 앞의 행동을 헛되게 만드는 일을 둔다: 片付けるそばから散らかす.","4. 끝난 직후를 강조할 때는 た형에 붙인다: 習ったそばから."],"why":"","nu":"앞의 행동을 하자마자 곧바로 그것을 무효로 만드는 일이 일어나는 상황이 되풀이됨을 나타내며, 불만이나 한탄의 느낌이 있다. 한 번만 일어난 일에는 잘 쓰지 않고 반복되는 일에 쓴다. ます형에 붙이는 것은 틀린 형태다. 다소 문어적이다.","cmp":[{"g":"～たとたん(に)","d":"~한 순간 예상 밖의 일이 일어났다는 한 번의 사건에 쓴다. そばから는 같은 일이 되풀이되는 데 쓴다."}],"ex":[{"jp":"片付[かたづ]けるそばから、子[こ]どもが部屋[へや]を散[ち]らかす。","ko":"치우는 족족 아이가 방을 어지럽힌다."},{"jp":"単語[たんご]を習[なら]ったそばから忘[わす]れてしまう。","ko":"단어를 배우자마자 바로 잊어버린다."},{"jp":"稼[かせ]ぐそばから使[つか]ってしまうので、お金[かね]がたまらない。","ko":"버는 족족 써 버려서 돈이 모이지 않는다."}],"dr":[{"t":"make","q":"覚える → ～そばから（た형）","a":"覚えたそばから","hint":"る → た(た형) + そばから"},{"t":"make","q":"洗う → ～そばから（사전형）","a":"洗うそばから","hint":"사전형 그대로 + そばから"},{"t":"fill","q":"雪[ゆき]をかく（　）、また雪[ゆき]が積[つ]もっていく。","a":"そばから","opts":["そばから","がてら","かたわら","限りに"]}],"src":["https://nihongokyoshi-net.com/2019/07/09/jlptn1-grammar-sobakara/"],"vf":1,"u":14,"g":1,"gp":"gg_N1_05"},{"id":"g1_131","t":"～てからというもの","ko":"~하고 나서부터 줄곧","cat":"시간·순서","conn":[{"w":"동사 て형","f":"飼って + からというもの"},{"w":"する동사","f":"入学して + からというもの"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 う동사는 어미 う가 っ로 바뀌고(촉음편) て가 붙는다: 飼う → 飼って.","2. て형 뒤에 から를 붙인다: 飼ってから.","3. 그 뒤에 というもの를 붙인다: 飼ってからというもの.","4. 2그룹은 る를 빼고 て, する는 して가 된다: 始める → 始めて, 入学する → 入学して."],"why":"","nu":"어떤 일을 계기로 그 뒤 지금까지 상태가 크게 바뀌어 계속되고 있다는 뜻이다. 뒤에는 한 번의 동작이 아니라 계속되는 상태나 변화(～ようになった, ～ている 등)가 온다. 말하는 사람의 감정이 담긴 문어적인 표현이며, 일상 회화에서는 ～てから(ずっと)를 쓴다.","cmp":[{"g":"～てから","d":"단순히 순서(~한 후에)를 말한다. てからというもの는 그 후로 줄곧 이어진 큰 변화를 강조한다."},{"g":"～て以来","d":"~한 이래로. 뜻은 비슷하지만 감정의 색채가 적고 객관적이다."}],"ex":[{"jp":"犬[いぬ]を飼[か]ってからというもの、毎朝[まいあさ]散歩[さんぽ]するようになった。","ko":"개를 기르고 나서부터 줄곧 매일 아침 산책하게 되었다."},{"jp":"子[こ]どもが生[う]まれてからというもの、自分[じぶん]の時間[じかん]がほとんどない。","ko":"아이가 태어나고 나서부터 줄곧 내 시간이 거의 없다."},{"jp":"日本[にほん]に来[き]てからというもの、毎日[まいにち]が新[あたら]しい発見[はっけん]の連続[れんぞく]だ。","ko":"일본에 오고 나서부터 매일이 새로운 발견의 연속이다."}],"dr":[{"t":"make","q":"始める → ～てからというもの","a":"始めてからというもの","hint":"る → て, + からというもの"},{"t":"make","q":"会う → ～てからというもの","a":"会ってからというもの","hint":"う → って(촉음편), + からというもの"},{"t":"fill","q":"たばこをやめて（　）、体[からだ]の調子[ちょうし]がいい。","a":"からというもの","opts":["からというもの","からといって","からには","からして"]}],"src":["https://nihongokyoshi-net.com/2019/11/15/jlptn1-grammar-tekaratoiumono/"],"vf":1,"u":14,"g":1,"gp":"gg_N1_05"},{"id":"g1_133","t":"～ては","ko":"~했다가는 (또) ~하고, ~하고는 ~하고","cat":"시간·순서","conn":[{"w":"동사 て형","f":"書いて + は + 消し"},{"w":"동사 て형 (ん음편)","f":"読んで + は + 忘れ"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 く동사는 어미 く가 い로 바뀌고(イ음편) て가 붙는다: 書く → 書いて.","2. て형 뒤에 조사 は를 붙인다: 書いては.","3. 뒤에 이어지는 동작을 ます형(중지형)으로 잇고, 같은 짝을 한 번 더 되풀이하는 일이 많다: 書いては消し、書いては消し.","4. ぬ·ぶ·む동사는 ん으로 바뀌어 で가 되므로 では가 된다: 読む → 読んでは."],"why":"","nu":"A를 하고 나면 B가 일어나는 일이 몇 번이고 되풀이된다는 뜻으로, 같은 구절을 반복해 쓰는 경우가 많다(降っては止み、降っては止み). 좀처럼 진전이 없거나 답답한 상황을 묘사할 때 자주 쓴다. 문어적이며 이야기·묘사문에 많다. 과거의 일에도 현재의 일에도 쓴다.","cmp":[{"g":"～ては (부정적 조건)","d":"そんなに食べては太る처럼 '~해서는 (곤란하다)'는 조건 용법도 있다. 반복 용법은 뒤에 같은 짝이 되풀이되거나 연속 동작이 이어진다."},{"g":"～たり～たり","d":"동작을 예로 들어 나열한다. ては는 A 다음 B가 일어나는 순서와 반복을 강조한다."}],"ex":[{"jp":"手紙[てがみ]を書[か]いては消[け]し、書[か]いては消[け]し、やっと書[か]き終[お]えた。","ko":"편지를 썼다 지웠다, 썼다 지웠다 하다가 겨우 다 썼다."},{"jp":"雨[あめ]は降[ふ]っては止[や]み、降[ふ]っては止[や]みしている。","ko":"비가 왔다 그쳤다를 반복하고 있다."},{"jp":"単語[たんご]を覚[おぼ]えては忘[わす]れ、また覚[おぼ]える。","ko":"단어를 외웠다가는 잊어버리고 또 외운다."}],"dr":[{"t":"make","q":"読む → ～ては","a":"読んでは","hint":"む → んで(발음편), + は"},{"t":"make","q":"寝る → ～ては","a":"寝ては","hint":"る → て, + は"},{"t":"fill","q":"作文[さくぶん]を書[か]い（　）直[なお]し、書[か]い（　）直[なお]した。","a":"ては","opts":["ては","ても","たら","てから"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ては～ては-tewa-tewa-meaning/"],"vf":1,"u":15,"g":1,"gp":"gg_N1_05"},{"id":"g1_134","t":"～ては～","ko":"~할 때마다 ~하곤 하다","cat":"시간·순서","conn":[{"w":"동사 て형","f":"会って + は + 話す"},{"w":"来る (불규칙)","f":"来て + は + くれた"}],"rule":["1. 동사를 て형으로 바꾼다. 来る는 불규칙 동사로 来て(きて)가 된다.","2. て형 뒤에 조사 は를 붙인다: 来ては.","3. 뒤에 그때마다 일어나는 일을 쓴다: 来ては、お菓子をくれた.","4. 1그룹 う동사는 っ로 바뀐다: 会う → 会っては."],"why":"","nu":"같은 사람이 같은 행동을 할 때마다 늘 같은 일이 따른다는 습관적 반복을 나타낸다. 한 번뿐인 일에는 쓰지 않는다. 앞뒤 동작의 주어는 같은 경우가 많으며, 과거의 습관(～ては～たものだ)을 회상할 때 자주 쓴다. 다소 문어적이다.","cmp":[{"g":"～たびに","d":"'~할 때마다'라는 뜻의 일반적인 표현으로 회화에도 자연스럽다. ては는 같은 행동이 되풀이되는 모습을 묘사하는 문어적 느낌이 있다."}],"ex":[{"jp":"祖父[そふ]は遊[あそ]びに来[き]ては、お菓子[かし]をくれた。","ko":"할아버지는 놀러 오실 때마다 과자를 주셨다."},{"jp":"彼[かれ]は暇[ひま]を見[み]つけては、絵[え]を描[か]いている。","ko":"그는 짬이 날 때마다 그림을 그리고 있다."},{"jp":"学生[がくせい]のころは友達[ともだち]と会[あ]っては、朝[あさ]まで話[はな]したものだ。","ko":"학생 때는 친구와 만나기만 하면 아침까지 이야기하곤 했다."}],"dr":[{"t":"make","q":"見つける → ～ては","a":"見つけては","hint":"る → て, + は"},{"t":"make","q":"会う → ～ては","a":"会っては","hint":"う → って(촉음편), + は"},{"t":"fill","q":"兄[あに]は休[やす]みのたびに帰[かえ]って（　）、母[はは]の料理[りょうり]を食[た]べている。","a":"きては","opts":["きては","きても","くると","くるなら"]}],"src":[],"vf":0,"u":15,"g":1,"gp":"gg_N1_05"},{"id":"g1_156","t":"～が早いか","ko":"~하자마자","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"鳴る + が早いか"}],"rule":["1. 동사는 주로 사전형을 그대로 쓴다(た형 鳴った도 쓰지만 사전형이 더 일반적이다): 鳴る.","2. 사전형 뒤에 が早いか를 붙인다: 鳴るが早いか.","3. 뒤 문장은 과거형으로, 곧바로 일어난 일을 쓴다."],"why":"","nu":"앞의 일이 일어나자마자 거의 동시에 뒤의 일이 일어났다는 뜻으로, 그 빠름에 대한 놀라움이 담긴다. 문어적이며 주로 소설이나 글에서 쓴다. 뒤에는 이미 일어난 사실이 오고, 말하는 사람의 의지·명령·권유는 올 수 없다.","cmp":[{"g":"～や否や","d":"뜻이 거의 같은 문어 표현(ベルが鳴るや否や)."},{"g":"～とたん(に)","d":"た형에 붙고(鳴ったとたん) 회화에서도 쓴다. 뜻밖의 변화에 자주 쓴다."}],"ex":[{"jp":"ベルが鳴[な]るが早[はや]いか、子[こ]どもたちは教室[きょうしつ]を飛[と]び出[だ]していった。","ko":"벨이 울리자마자 아이들은 교실을 뛰쳐나갔다."},{"jp":"彼[かれ]は家[いえ]に帰[かえ]るが早[はや]いか、テレビをつけた。","ko":"그는 집에 돌아오자마자 텔레비전을 켰다."},{"jp":"父[ちち]は布団[ふとん]に入[はい]るが早[はや]いか、いびきをかき始[はじ]めた。","ko":"아버지는 이불에 들어가자마자 코를 골기 시작했다."}],"dr":[{"t":"make","q":"着きます → ～が早いか","a":"着くが早いか","hint":"ます형을 사전형으로(着き → 着く) + が早いか"},{"t":"make","q":"見ます → ～が早いか","a":"見るが早いか","hint":"2그룹: 見 + る(사전형) + が早いか"},{"t":"fill","q":"彼[かれ]は席[せき]に着[つ]く（　）、弁当[べんとう]を食[た]べ始[はじ]めた。","a":"が早いか","opts":["が早いか","くせに","ばかりか","からには"]}],"src":["https://bunpro.jp/grammar_points/931","https://guidetojapanese.org/learn/?p=331"],"vf":1,"u":15,"g":1,"gp":"gg_N1_05"},{"id":"g1_163","t":"～なり","ko":"~하자마자","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"帰る + なり"},{"w":"동사 사전형","f":"見る + なり"}],"rule":["1. 동사는 활용하지 않고 사전형 그대로 둔다: 帰る.","2. 사전형 바로 뒤에 なり를 붙인다: 帰るなり.","3. 뒤 문장에는 그 직후에 일어난 일을 과거형으로 쓴다: 帰るなり寝た."],"why":"","nu":"문어적 느낌이 있는 표현으로, 앞 동작이 끝나자마자 곧바로, 흔히 예상 밖의 다음 동작이 이어졌음을 나타낸다. 앞뒤 주어가 같은 경우가 많고, 주로 제3자의 행동을 묘사하며 말하는 사람 자신의 일에는 잘 쓰지 않는다. 뒤 문장은 과거형이 보통이고, 의지·명령·권유(~しよう, ~しなさい)는 올 수 없다. 'する+なり' 형태의 'AなりBなり(A든 B든)'와는 다른 문법이다.","cmp":[{"g":"～や否や","d":"역시 '~하자마자'이지만 더 딱딱한 문어체이며, 앞뒤 주어가 달라도 자연스럽다."},{"g":"～たとたん(に)","d":"회화에서도 쓰는 일반적 표현으로, 의외의 일이 일어났다는 느낌이 강하다. 동사 た형에 붙는다."}],"ex":[{"jp":"息子[むすこ]は家[いえ]に帰[かえ]るなり、自分[じぶん]の部屋[へや]に入[はい]ってしまった。","ko":"아들은 집에 오자마자 자기 방으로 들어가 버렸다."},{"jp":"彼女[かのじょ]は手紙[てがみ]を読[よ]むなり、泣[な]き出[だ]した。","ko":"그녀는 편지를 읽자마자 울기 시작했다."},{"jp":"父[ちち]は私[わたし]の顔[かお]を見[み]るなり、「どうしたんだ」と聞[き]いた。","ko":"아버지는 내 얼굴을 보자마자 '무슨 일이냐'고 물었다."}],"dr":[{"t":"make","q":"座る → ～なり","a":"座るなり","hint":"동사 사전형 + なり"},{"t":"make","q":"聞く → ～なり","a":"聞くなり","hint":"사전형을 그대로 두고 なり를 붙인다"},{"t":"fill","q":"彼[かれ]は部屋[へや]に入[はい]る（　）、窓[まど]を開[あ]けた。","a":"なり","opts":["なり","ために","ばかりか","ように"]}],"src":["https://www.mlcjapanese.co.jp/img/nari_n1.pdf"],"vf":1,"u":15,"g":1,"gp":"gg_N1_05"},{"id":"g1_174","t":"～や否や","ko":"~하자마자","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"鳴る + や否や"},{"w":"동사 사전형","f":"着く + や否や"}],"rule":["1. 동사는 사전형 그대로 둔다: 鳴る.","2. 사전형 뒤에 や否や(やいなや)를 붙인다: 鳴るや否や.","3. 뒤 문장에는 곧바로 일어난 일을 과거형으로 쓴다: ベルが鳴るや否や、走り出した."],"why":"","nu":"매우 딱딱한 문어체로 소설·기사 등에서 쓴다. 앞 일이 일어난 바로 그 순간 다음 일이 일어났음을 나타내며, 앞뒤 주어가 달라도 된다. 뒤 문장은 과거형이 보통이고 의지·명령·권유는 올 수 없다. 표기는 や否や와 やいなや 둘 다 쓴다.","cmp":[{"g":"～なり","d":"같은 '~하자마자'지만 앞뒤 주어가 같은 경우가 대부분이다."},{"g":"～たとたん(に)","d":"회화에서도 쓰는 일반적 표현으로, 동사 た형에 붙는다."}],"ex":[{"jp":"ベルが鳴[な]るや否[いな]や、子供[こども]たちは教室[きょうしつ]を飛[と]び出[だ]した。","ko":"벨이 울리자마자 아이들은 교실을 뛰쳐나갔다."},{"jp":"彼[かれ]は空港[くうこう]に着[つ]くや否[いな]や、会社[かいしゃ]に電話[でんわ]をかけた。","ko":"그는 공항에 도착하자마자 회사에 전화를 걸었다."},{"jp":"新[あたら]しいゲームは発売[はつばい]されるや否[いな]や、売[う]り切[き]れた。","ko":"새 게임은 발매되자마자 품절되었다."}],"dr":[{"t":"make","q":"開く → ～や否や","a":"開くや否や","hint":"동사 사전형 + や否や"},{"t":"make","q":"始まる → ～や否や","a":"始まるや否や","hint":"사전형을 그대로 두고 や否や를 붙인다"},{"t":"fill","q":"ドアが開[ひら]く（　）、客[きゃく]が店[みせ]に入[はい]ってきた。","a":"や否や","opts":["や否や","からには","ものなら","とあれば"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/200906.html","https://bunpro.jp/grammar_points/や否や"],"vf":1,"u":15,"g":1,"gp":"gg_N1_05"},{"id":"g1_197","t":"～ところを","ko":"~하는 중에, ~한 상황인데 (폐를 끼쳐서)","cat":"시간·순서","conn":[{"w":"い형용사","f":"お忙しい + ところを"},{"w":"명사","f":"お休みの + ところを"},{"w":"동사 ている형","f":"寝ている + ところを"}],"rule":["1. い형용사 忙しい를 둔다.","2. 상대를 높이기 위해 앞에 お를 붙인다: お忙しい.","3. 그 뒤에 ところを를 붙인다: お忙しいところを.","4. 명사는 の를 붙여 잇는다: お休みのところを."],"why":"명사 ところ(때, 상황)에 조사 を가 붙은 형태이다.","nu":"두 가지 쓰임이 있다. ①상대가 바쁘거나 쉬는 상황인데 폐를 끼쳐 미안·감사하다는 정중한 인사: お忙しいところをありがとうございます. ②어떤 상황에 있는 장면을 보거나 붙잡거나 방해할 때: たばこを吸っているところを先生に見られた. 뒤에는 見る, 見つかる, 起こす, 助ける, 邪魔する 같은 동사나 인사말이 온다.","cmp":[{"g":"～ところに / ～ところへ","d":"'마침 ~하는 때에 (무엇이 왔다)'처럼 다른 일이 일어난 타이밍을 나타낸다. ところを는 그 상황 자체를 동작의 대상으로 삼거나 폐를 끼치는 인사에 쓴다."},{"g":"～最中に","d":"'한창 ~하는 중에'로, 진행 중인 동작의 한가운데를 나타낸다."}],"ex":[{"jp":"お忙[いそが]しいところを、ありがとうございました。","ko":"바쁘신 와중에 감사했습니다."},{"jp":"お休[やす]みのところを申[もう]し訳[わけ]ありません。","ko":"쉬시는 중에 죄송합니다."},{"jp":"授業中[じゅぎょうちゅう]に寝[ね]ているところを先生[せんせい]に見[み]られた。","ko":"수업 중에 자고 있는 것을 선생님에게 들켰다."}],"dr":[{"t":"make","q":"お食事中 → ～ところを","a":"お食事中のところを","hint":"명사 + の + ところを"},{"t":"make","q":"遊んでいる → ～ところを","a":"遊んでいるところを","hint":"동사 ている형 + ところを"},{"t":"fill","q":"お疲[つか]れの（　）、お越[こ]しいただきありがとうございます。","a":"ところを","opts":["ところを","わりに","くせに","からには"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%93%E3%82%8D%E3%82%92"],"vf":1,"u":16,"g":1,"gp":"gg_N1_05"},{"id":"g1_209","t":"～とみると","ko":"~라고 보자마자, ~라고 판단하면 (곧)","cat":"시간·순서","conn":[{"w":"동사 보통형","f":"負ける + とみると"},{"w":"い형용사","f":"弱い + とみると"},{"w":"な형용사","f":"不利だ + とみると"},{"w":"명사","f":"子どもだ + とみると"}],"rule":["1. 판단한 내용을 보통형 문장으로 둔다: 降りそうだ.","2. と + みる(見る, 판단하다)를 붙인다: 降りそうだとみる.","3. 끝에 조건의 と를 붙인다: 降りそうだとみると."],"why":"'~라고 보다(판단하다)'라는 ～とみる에 조건의 と가 붙은 형태다.","nu":"어떤 상황을 '~라고 판단하자 곧바로' 행동을 바꾸거나 대응하는 것을 나타낸다. 뒤 문장의 주어(판단한 사람)의 재빠른 반응이 초점이다. 주로 제3자의 행동을 서술하며 문장체에 가깝다. 단순히 '보면'이라는 뜻의 見ると(窓から見ると…)와 구별한다.","cmp":[{"g":"～とわかると","d":"사실을 알게 되면. とみると는 확실하지 않아도 스스로 그렇게 판단했다는 점이 다르다."},{"g":"～たとたん(に)","d":"동작 직후 예상 밖의 일이 일어남. とみると는 판단에 따른 의도적인 대응이다."}],"ex":[{"jp":"雨[あめ]が降[ふ]りそうだとみると、母[はは]はすぐに洗濯物[せんたくもの]を取[と]り込[こ]んだ。","ko":"비가 올 것 같다고 보자마자 어머니는 곧바로 빨래를 걷었다."},{"jp":"彼[かれ]は相手[あいて]が弱[よわ]いとみると、急[きゅう]に強気[つよき]になる。","ko":"그는 상대가 약하다고 판단하면 갑자기 기세등등해진다."},{"jp":"店員[てんいん]は客[きゃく]が外国人[がいこくじん]だとみると、英語[えいご]で話[はな]しかけてきた。","ko":"점원은 손님이 외국인이라고 보자 영어로 말을 걸어왔다."}],"dr":[{"t":"make","q":"勝てない → ～とみると","a":"勝てないとみると","hint":"보통형 + と + みる + と"},{"t":"make","q":"危険だ → ～とみると","a":"危険だとみると","hint":"な형용사는 だ를 넣고 + とみると"},{"t":"fill","q":"犯人[はんにん]は警察[けいさつ]が来[き]た（　）、裏口[うらぐち]から逃[に]げ出[だ]した。","a":"とみると","opts":["とみると","とはいえ","としても","とおりに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/とみると-to-miru-to-meaning/"],"vf":1,"u":16,"g":1,"gp":"gg_N1_05"},{"id":"g1_223","t":"～に至った","ko":"(결국) ~에 이르렀다, ~하기에 이르렀다","cat":"시간·순서","conn":[{"w":"명사","f":"結論 + に至った"},{"w":"동사 사전형","f":"辞任する + に至った"}],"rule":["1. 도달한 결과를 명사 또는 동사 사전형으로 두고 조사 に를 붙인다: 結論に.","2. 1그룹 동사 至る의 어미 る를 촉음 っ로 바꾼다(촉음편): 至る → 至っ.","3. 과거 た를 붙인다: 至った. 합치면 結論に至った."],"why":"至る(이르다, 도달하다)의 과거형이다. 어떤 과정을 거쳐 그 지점에 도달했다는 동사 뜻이 그대로 살아 있다.","nu":"오랜 경과나 여러 사정을 거친 끝에 어떤 결과·단계에 도달했다는 것을 나타내는 딱딱한 문어체이다. 뉴스나 보고서에서 많이 쓰며, 앞에 ついに, ようやく, さまざまな経緯を経て 등이 자주 온다. 사람이 장소에 도착했다는 뜻으로 쓰면 어색하므로 일상에서는 着いた를 쓴다. 현재형 に至る, 연체형 に至った経緯 등으로도 쓰인다.","cmp":[{"g":"～に至っては","d":"극단적인 예를 들 때 쓰는 별개의 표현(弟に至っては一度も来ない)."},{"g":"～から～に至るまで","d":"범위의 끝을 강조하는 표현(子どもから大人に至るまで)."}],"ex":[{"jp":"話[はな]し合[あ]いを重[かさ]ねて、ようやく合意[ごうい]に至[いた]った。","ko":"논의를 거듭해서 마침내 합의에 이르렀다."},{"jp":"小[ちい]さなミスが続[つづ]き、ついに大[おお]きな事故[じこ]に至[いた]った。","ko":"작은 실수가 이어져 결국 큰 사고에 이르렀다."},{"jp":"社長[しゃちょう]は責任[せきにん]を取[と]って辞任[じにん]するに至[いた]った。","ko":"사장은 책임을 지고 사임하기에 이르렀다."}],"dr":[{"t":"make","q":"解決 → ～に至った","a":"解決に至った","hint":"명사 + に + 至る의 る를 っ로 바꾸고 た"},{"t":"make","q":"閉店する → ～に至った","a":"閉店するに至った","hint":"동사 사전형 + に + 至った"},{"t":"fill","q":"長[なが]い議論[ぎろん]の末[すえ]、ついに結論[けつろん]（　）。","a":"に至った","opts":["に至った","に限った","に過ぎなかった","に反した"]}],"src":[],"vf":0,"u":16,"g":1,"gp":"gg_N1_05"},{"id":"g1_232","t":"～ぶり","ko":"~만에","cat":"시간·순서","conn":[{"w":"기간을 나타내는 명사","f":"三年 + ぶりに"},{"w":"명사 수식","f":"十年 + ぶりの + 再会"},{"w":"관용 표현","f":"久しぶり (오랜만)"}],"rule":["1. 지난 기간을 나타내는 말을 둔다: 三年.","2. ぶり를 붙인다: 三年ぶり.","3. 동사로 이어질 때는 に(三年ぶりに会った), 명사를 꾸밀 때는 の(三年ぶりの再会), 문장 끝은 だ(三年ぶりだ)를 붙인다."],"why":"","nu":"마지막으로 그 일이 있은 뒤 어느 정도의 기간이 지나 다시 일어났음을 나타낸다. 말하는 사람이 '오래간만'이라고 느끼는 기간에 쓰며, 보통의 짧은 간격에는 쓰지 않는다. 한국어 '~만에'와 달리 '3분 만에 끝냈다'처럼 소요 시간을 말할 때는 쓸 수 없다(그때는 三分で). 동사 ます형·명사 + ぶり(話しぶり, 仕事ぶり)는 '~하는 모습'이라는 다른 뜻이다.","cmp":[{"g":"～で","d":"걸린 시간을 말한다(三分で終わった: 3분 만에 끝났다). ぶり는 다시 일어나기까지의 간격."},{"g":"～ぶり(모습)","d":"話しぶり, 働きぶり처럼 동작의 모습·상태를 말하는 별개의 용법."}],"ex":[{"jp":"三年[さんねん]ぶりに国[くに]へ帰[かえ]った。","ko":"3년 만에 고국에 돌아갔다."},{"jp":"今日[きょう]は一週間[いっしゅうかん]ぶりのいい天気[てんき]だ。","ko":"오늘은 일주일 만의 좋은 날씨다."},{"jp":"久[ひさ]しぶりに友達[ともだち]と食事[しょくじ]をした。","ko":"오랜만에 친구와 식사를 했다."}],"dr":[{"t":"make","q":"十年 / 会う(과거) → ～ぶりに","a":"十年ぶりに会った","hint":"기간 + ぶり + に + 동사"},{"t":"make","q":"五年 / 優勝(명사) → ～ぶりの","a":"五年ぶりの優勝","hint":"명사를 꾸밀 때는 ぶり + の"},{"t":"fill","q":"雨[あめ]が続[つづ]いたが、今日[きょう]は十日[とおか]（　）晴[は]れた。","a":"ぶりに","opts":["ぶりに","ごとに","おきに","までに"]}],"src":[],"vf":0,"u":16,"g":1,"gp":"gg_N1_06"},{"id":"g1_240","t":"～折に","ko":"~할 때에, ~한 기회에","cat":"시간·순서","conn":[{"w":"동사 사전형","f":"行く + 折に"},{"w":"동사 た형","f":"行った + 折に"},{"w":"명사","f":"上京 + の折に"}],"rule":["1. 동사는 사전형 또는 た형을 쓴다. 行く의 た형은 く가 っ로 바뀌고(촉음편) た가 붙는다: 行く → 行った.","2. 그 뒤에 折に를 붙인다: 行った折に.","3. 명사는 の를 넣어 잇는다: 上京の折に."],"why":"折(おり)는 '때, 기회'를 뜻하는 명사이고, 여기에 시간을 나타내는 조사 に가 붙은 것이다.","nu":"時に와 비슷하지만 더 격식 있고 정중한 표현으로, 편지·인사말·비즈니스 회화에 잘 어울린다. '좋은 기회'라는 느낌이 있어 즐겁거나 중립적인 장면에 쓰며, 사고·재해 같은 불쾌한 일에는 잘 쓰지 않는다. お越しの折には(오실 때에는)처럼 には를 붙여 권유·부탁을 이끄는 일이 많다.","cmp":[{"g":"～時に","d":"가장 일반적인 '~할 때'. 좋고 나쁜 일 모두에 쓰며 격식의 느낌이 없다."},{"g":"～際に","d":"격식 있는 '~할 때'로 안내문·주의사항에 많이 쓴다(ご利用の際に). 折に는 기회의 느낌과 인사말 같은 부드러움이 있다."}],"ex":[{"jp":"京都[きょうと]へ行[い]った折に、昔[むかし]の友人[ゆうじん]に会[あ]った。","ko":"교토에 갔을 때 옛 친구를 만났다."},{"jp":"今度[こんど]お会[あ]いする折に、詳[くわ]しくお話[はな]しします。","ko":"다음에 뵐 때 자세히 말씀드리겠습니다."},{"jp":"近[ちか]くにお越[こ]しの折には、ぜひお立[た]ち寄[よ]りください。","ko":"근처에 오실 때에는 꼭 들러 주세요."}],"dr":[{"t":"make","q":"帰国した → ～折に","a":"帰国した折に","hint":"た형 + 折に"},{"t":"make","q":"上京 → ～折に","a":"上京の折に","hint":"명사 + の + 折に"},{"t":"fill","q":"大阪[おおさか]に出張[しゅっちょう]した（　）、取引先[とりひきさき]の方[かた]にご挨拶[あいさつ]した。","a":"折に","opts":["折に","うちに","ばかりに","あまり"]}],"src":[],"vf":0,"u":17,"g":1,"gp":"gg_N1_06"},{"id":"g1_027","t":"～じゃあるまいし","ko":"~도 아니고, ~도 아닐 텐데","cat":"원인·이유","conn":[{"w":"명사","f":"子供 + じゃあるまいし"},{"w":"동사 보통형 + ん / わけ","f":"死ぬ + わけじゃあるまいし"}],"rule":["1. 명사 뒤의 では를 회화체 じゃ로 줄인다(子供では → 子供じゃ).","2. ある에 부정 추량의 まい를 붙인다(あるまい).","3. 이유의 し를 붙인다(子供じゃあるまいし)."],"why":"では의 축약 じゃ + ある + まい(부정 추량, ~아닐 것이다) + し(이유). '~도 아닐 테니'라는 구성.","nu":"회화체. '~인 것도 아닌데'라며 상대를 비판하거나 충고할 때 쓴다. 뒤에는 명령·충고·비판 같은 화자의 판단이 온다. 격식 있는 장면에서는 ではあるまいし.","cmp":[{"g":"～ではあるまいし","d":"같은 뜻으로 조금 딱딱한 형태."},{"g":"～わけじゃないんだから","d":"'~인 것도 아니니까'라는 뜻의 더 일상적인 표현."}],"ex":[{"jp":"子供[こども]じゃあるまいし、一人[ひとり]で帰[かえ]れるでしょう。","ko":"어린애도 아니고 혼자 돌아갈 수 있잖아."},{"jp":"神様[かみさま]じゃあるまいし、明日[あした]のことなんて分[わ]からないよ。","ko":"신도 아니고 내일 일 같은 건 모르지."},{"jp":"夏休[なつやす]みじゃあるまいし、毎日[まいにち]遊[あそ]んでいてはだめだ。","ko":"여름 방학도 아니고 매일 놀고 있으면 안 된다."}],"dr":[{"t":"make","q":"子供 → ～じゃあるまいし","a":"子供じゃあるまいし","hint":"명사 + じゃ + あるまい + し"},{"t":"make","q":"プロ → ～じゃあるまいし","a":"プロじゃあるまいし","hint":"명사 + じゃ + あるまい + し"},{"t":"fill","q":"赤[あか]ちゃん（　）、自分[じぶん]で食[た]べなさい。","a":"じゃあるまいし","opts":["じゃあるまいし","にしては","だけあって","からといって"]}],"src":["https://bunpro.jp/grammar_points/743"],"vf":1,"u":17,"g":1,"gp":"gg_N1_06"},{"id":"g1_034","t":"～ではあるまいし","ko":"~도 아니고, ~도 아닐 텐데","cat":"원인·이유","conn":[{"w":"명사","f":"子供 + ではあるまいし"}],"rule":["1. ある에 부정 추량의 まい를 붙인다(あるまい = 아닐 것이다).","2. 명사 + では 뒤에 둔다(子供ではあるまい).","3. 이유의 し를 붙인다(子供ではあるまいし)."],"why":"では + ある + まい(부정 추량) + し(이유). '~도 아닐 테니'라는 구성.","nu":"'~인 것도 아닌데'라며 상대를 비판하거나 충고할 때 쓴다. 뒤에는 명령·충고·비판이 온다. じゃあるまいし보다 조금 딱딱하지만 회화에서도 쓴다.","cmp":[{"g":"～じゃあるまいし","d":"같은 뜻의 더 회화적인 형태."},{"g":"～わけではあるまいし","d":"동사·형용사 문장에 붙일 때 쓰는 형태(一生会えないわけではあるまいし)."}],"ex":[{"jp":"子供[こども]ではあるまいし、自分[じぶん]のことは自分[じぶん]でしなさい。","ko":"어린애도 아니고, 자기 일은 스스로 해라."},{"jp":"新入社員[しんにゅうしゃいん]ではあるまいし、そんなことも知[し]らないのか。","ko":"신입 사원도 아니고 그런 것도 모르나?"},{"jp":"素人[しろうと]ではあるまいし、こんな簡単[かんたん]なミスをしてはいけない。","ko":"초보자도 아니고 이런 쉬운 실수를 하면 안 된다."}],"dr":[{"t":"make","q":"子供じゃあるまいし → 딱딱한 형태","a":"子供ではあるまいし","hint":"じゃ를 では로"},{"t":"make","q":"素人 → ～ではあるまいし","a":"素人ではあるまいし","hint":"명사 + では + あるまい + し"},{"t":"fill","q":"ロボット（　）、休[やす]まずに働[はたら]けるわけがない。","a":"ではあるまいし","opts":["ではあるまいし","に限らず","にとって","をはじめ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ではあるまいし-dewa-arumai-shi-meaning/"],"vf":1,"u":17,"g":1,"gp":"gg_N1_06"},{"id":"g1_081","t":"～のことだから","ko":"~(의 성격)이니까 (분명)","cat":"원인·이유","conn":[{"w":"명사(사람)","f":"彼 + のことだから"},{"w":"수식어 + 명사(사람)","f":"真面目な田中さん + のことだから"}],"rule":["1. 사람(또는 조직)을 나타내는 명사 뒤에 の를 넣는다: 彼の.","2. こと와 だから를 붙인다: 彼のことだから.","3. 뒤에는 그 사람의 평소 성격·행동으로 미루어 본 판단(きっと～だろう, ～に違いない)을 쓴다."],"why":"명사 + の + こと(~에 관한 것) + だから(~이니까)로 이루어져 '그 사람에 관한 것이니까'라는 뜻이 된다.","nu":"말하는 사람과 듣는 사람이 모두 그 사람의 성격이나 습관을 알고 있을 때 쓴다. 좋은 판단(きっと成功する)에도 나쁜 판단(また遅れる)에도 쓴다. 뒤에는 추측·확신 표현이 자연스럽게 따라온다. 앞에는 대개 사람이 오며, 단순한 사물·사건에는 잘 쓰지 않는다.","cmp":[{"g":"～だから","d":"단순히 이유를 말한다. のことだから는 그 사람의 평소 모습을 근거로 한 추측이라는 점이 다르다."}],"ex":[{"jp":"真面目[まじめ]な田中[たなか]さんのことだから、約束[やくそく]の時間[じかん]には必[かなら]ず来[く]るよ。","ko":"성실한 다나카 씨니까 약속 시간에는 반드시 올 거야."},{"jp":"時間[じかん]にルーズな彼[かれ]のことだから、また遅[おく]れてくるだろう。","ko":"시간 개념이 없는 그 사람이니까 또 늦게 오겠지."},{"jp":"料理[りょうり]が好[す]きな母[はは]のことだから、ごちそうをたくさん作[つく]って待[ま]っているに違[ちが]いない。","ko":"요리를 좋아하는 엄마니까 맛있는 음식을 잔뜩 만들어 놓고 기다리고 있을 게 분명하다."}],"dr":[{"t":"make","q":"彼 → ～のことだから","a":"彼のことだから","hint":"사람 명사 + の + ことだから"},{"t":"make","q":"優しい姉 → ～のことだから","a":"優しい姉のことだから","hint":"수식어 + 사람 명사 + のことだから"},{"t":"fill","q":"泣[な]き虫[むし]のあの子[こ]（　）、きっと泣[な]いて帰[かえ]ってくるだろう。","a":"のことだから","opts":["のことだから","のくせに","のおかげで","の手前"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%93%E3%81%A8%E3%81%A0%E3%81%8B%E3%82%89"],"vf":1,"u":17,"g":1,"gp":"gg_N1_06"},{"id":"g1_083","t":"～手前","ko":"~앞이라 체면상, ~한 이상 체면 때문에","cat":"원인·이유","conn":[{"w":"명사","f":"子どもの + 手前"},{"w":"동사 た형","f":"約束した + 手前"},{"w":"동사 사전형/ている형","f":"先生をしている + 手前"}],"rule":["1. 명사는 の를 넣어 手前를 붙인다: 子どもの手前.","2. 동사는 보통형(주로 た형)에 手前를 바로 붙인다: 約束する → 約束した → 約束した手前.","3. 뒤에는 체면 때문에 해야 하는 일이나 할 수 없는 일(～わけにはいかない, ～しかない)을 쓴다."],"why":"手前는 원래 '자기 바로 앞(쪽)'을 뜻하는 명사다(駅の手前).","nu":"남의 눈이나 자기 입장·체면 때문에 마음과 달리 그렇게 해야 한다는 뜻이다. 뒤에 ～わけにはいかない・～しかない・～ざるを得ない가 자주 온다. 장소를 나타내는 '바로 앞'(駅の手前で降りる)과는 다른 용법이니 문맥으로 구별한다.","cmp":[{"g":"～以上(は)","d":"~한 이상 당연히 ~해야 한다는 책임·결의를 말한다. 手前는 남의 눈과 체면이 이유라는 점이 중심이다."},{"g":"～の前で","d":"단순히 물리적으로 '~앞에서'라는 뜻이다(子どもの前で喧嘩しない)."}],"ex":[{"jp":"子[こ]どもの手前[てまえ]、親[おや]が約束[やくそく]を破[やぶ]るわけにはいかない。","ko":"아이 앞이라 체면상 부모가 약속을 깰 수는 없다."},{"jp":"「任[まか]せてください」と言[い]った手前[てまえ]、今[いま]さら断[ことわ]れない。","ko":"'맡겨 주세요'라고 말한 이상 체면 때문에 이제 와서 거절할 수 없다."},{"jp":"部下[ぶか]の手前[てまえ]、上司[じょうし]の私[わたし]が弱音[よわね]を吐[は]くわけにはいかない。","ko":"부하들 앞이라 상사인 내가 약한 소리를 할 수는 없다."}],"dr":[{"t":"make","q":"約束する → ～手前","a":"約束した手前","hint":"する를 した로 바꾼 た형 + 手前"},{"t":"make","q":"先生 → ～手前","a":"先生の手前","hint":"명사 + の + 手前"},{"t":"fill","q":"自分[じぶん]から誘[さそ]った（　）、遅[おく]れて行[い]くわけにはいかない。","a":"手前","opts":["手前","くせに","あげく","ついでに"]}],"src":["https://bunpro.jp/grammar_points/手前","https://jlptsensei.com/learn-japanese-grammar/手前-てまえ-temae-meaning/"],"vf":1,"u":17,"g":1,"gp":"gg_N1_06"},{"id":"g1_095","t":"～も相まって","ko":"~도 어우러져, ~와 맞물려","cat":"원인·이유","conn":[{"w":"명사","f":"好天 + も相まって"},{"w":"명사 (두 요인)","f":"才能と努力 + が相まって"}],"rule":["1. 1그룹 동사 相まつ(相俟つ)의 어미 つ를 っ로 바꾼다(촉음편): 相まつ → 相まっ.","2. て를 붙여 て형을 만든다: 相まって.","3. 함께 작용한 요인인 명사에 も를 붙여 앞에 둔다: 好天も相まって."],"why":"동사 相まつ(相俟つ, 서로 어울려 작용하다)의 て형이다.","nu":"문어적인 표현이다. 이미 있는 다른 요인에 명사의 요인이 더해져 어떤 결과가 생겼다는 뜻으로, 결과는 좋은 일·나쁜 일 모두 가능하다. 뒤에는 결과를 서술하는 문장이 오며 명령·의뢰·의지 표현은 오지 않는다. 두 요인을 모두 쓸 때는 'AとBが相まって', 'Aと相まって'로 쓴다.","cmp":[{"g":"～と相まって","d":"상대 요인을 명시해 'A와 어우러져'라고 말한다. も相まって는 앞 문맥의 요인에 '그것도 더해져'라는 느낌이다."},{"g":"～おかげで / ～せいで","d":"하나의 원인과 그 결과에 대한 화자의 평가(고마움·불만)를 나타낸다. 相まって는 여러 요인이 겹친다는 점에 초점이 있다."}],"ex":[{"jp":"好天[こうてん]も相[あい]まって、祭[まつ]りは大勢[おおぜい]の人[ひと]でにぎわった。","ko":"좋은 날씨도 어우러져 축제는 많은 사람들로 붐볐다."},{"jp":"疲[つか]れも相[あい]まって、その日[ひ]はすぐに寝[ね]てしまった。","ko":"피로까지 겹쳐서 그날은 바로 잠들어 버렸다."},{"jp":"彼[かれ]の努力[どりょく]は才能[さいのう]と相[あい]まって、大[おお]きな成果[せいか]を生[う]んだ。","ko":"그의 노력은 재능과 맞물려 큰 성과를 낳았다."}],"dr":[{"t":"make","q":"天気 → ～も相まって","a":"天気も相まって","hint":"명사 + も + 相まつ의 て형(つ → って)"},{"t":"make","q":"相まつ → て형","a":"相まって","hint":"1그룹: 어미 つ → っ + て"},{"t":"fill","q":"円安[えんやす]（　）相[あい]まって、外国人[がいこくじん]観光客[かんこうきゃく]が増[ふ]えた。","a":"も","opts":["も","を","で","に"]}],"src":["https://bunpro.jp/grammar_points/853","https://nihongokyoshi-net.com/2019/06/26/jlptn1-grammar-amatte/"],"vf":1,"u":18,"g":1,"gp":"gg_N1_06"},{"id":"g1_180","t":"～がゆえに","ko":"~이기 때문에, ~인 까닭에","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"知っている + がゆえに"},{"w":"い형용사","f":"若い + がゆえに"},{"w":"な형용사","f":"自由 + であるがゆえに"},{"w":"명사","f":"子供 + であるがゆえに / 子供 + ゆえに"}],"rule":["1. 동사·い형용사는 보통형 그대로 둔다: 若い.","2. 그 뒤에 がゆえに를 붙인다: 若いがゆえに.","3. な형용사·명사는 だ를 である로 바꾸어 붙인다: 自由であるがゆえに.","4. 명사를 꾸밀 때는 がゆえの가 된다: 若いがゆえの失敗."],"why":"","nu":"이유를 강조하는 딱딱한 문어체로, 논설문·연설·소설 등에서 쓴다. 일상 대화에서는 ~から, ~ので를 쓴다. が를 빼고 ゆえに만 쓰기도 하며, 명사에는 주로 명사 + ゆえに(貧しさゆえに) 또는 명사 + であるがゆえに 형태로 붙는다. 뒤에 명령·의뢰 같은 표현은 잘 오지 않는다.","cmp":[{"g":"～ため(に)","d":"이유를 나타내는 일반적인 문장체 표현으로, がゆえに보다 덜 딱딱하다."},{"g":"～ばかりに","d":"그것 하나 때문에 나쁜 결과가 생겼다는 후회·유감이 담긴다."}],"ex":[{"jp":"若[わか]いがゆえに、失敗[しっぱい]を恐[おそ]れず挑戦[ちょうせん]できる。","ko":"젊기 때문에 실패를 두려워하지 않고 도전할 수 있다."},{"jp":"彼[かれ]は真面目[まじめ]であるがゆえに、一人[ひとり]で悩[なや]んでしまう。","ko":"그는 성실하기 때문에 혼자서 고민해 버린다."},{"jp":"本当[ほんとう]のことを知[し]っているがゆえに、何[なに]も言[い]えなかった。","ko":"진실을 알고 있기 때문에 아무 말도 할 수 없었다."}],"dr":[{"t":"make","q":"貧しい → ～がゆえに","a":"貧しいがゆえに","hint":"い형용사 보통형 + がゆえに"},{"t":"make","q":"有名だ → ～がゆえに","a":"有名であるがゆえに","hint":"な형용사는 だ → である + がゆえに"},{"t":"fill","q":"彼女[かのじょ]は優[やさ]しい（　）、頼[たの]みを断[ことわ]れない。","a":"がゆえに","opts":["がゆえに","にもかかわらず","どころか","ものの"]}],"src":["https://bunpro.jp/grammar_points/ゆえに","https://nihongokyoshi-net.com/2019/02/19/jlptn1-grammar-yueni/"],"vf":1,"u":18,"g":1,"gp":"gg_N1_06"},{"id":"g1_181","t":"～がゆえの","ko":"~이기 때문의, ~인 탓의","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"知らない + がゆえの + 誤解"},{"w":"い형용사","f":"若い + がゆえの + 失敗"},{"w":"な형용사","f":"未熟である + がゆえの + ミス"},{"w":"명사","f":"子どもである + がゆえの + 悩み"}],"rule":["1. 이유가 되는 말을 보통형으로 둔다: 若い.","2. 그 뒤에 がゆえ를 붙인다: 若いがゆえ.","3. 뒤의 명사를 꾸미기 위해 の를 붙이고 명사를 잇는다: 若いがゆえの失敗.","4. な형용사·명사는 である를 거쳐 잇는다: 未熟であるがゆえの."],"why":"ゆえ(故)는 '까닭, 이유'라는 뜻의 명사이고, 뒤의 명사를 꾸미기 위해 の가 붙은 형태이다.","nu":"딱딱한 문어체로 논설·소설·연설 등에서 쓰고 일상 회화에는 거의 쓰지 않는다. 뒤에 반드시 명사가 온다(～がゆえの悩み). 문장을 이어 갈 때는 ～がゆえに를 쓴다. 명사는 若さゆえの過ち처럼 がを 빼고 명사 + ゆえの로 쓰는 경우도 많다.","cmp":[{"g":"～がゆえに","d":"같은 이유 표현이지만 뒤에 절(문장)이 이어진다. がゆえの는 뒤에 명사가 온다."},{"g":"～ための","d":"회화에서도 쓰는 일반적인 표현이고 주로 목적(試験のための勉強)을 나타낸다. がゆえの는 원인을 딱딱하게 나타낸다."}],"ex":[{"jp":"それは若[わか]いがゆえの失敗[しっぱい]だった。","ko":"그것은 젊기 때문의(젊어서 한) 실수였다."},{"jp":"事情[じじょう]を知[し]らないがゆえの誤解[ごかい]もあるだろう。","ko":"사정을 모르기 때문에 생긴 오해도 있을 것이다."},{"jp":"親[おや]であるがゆえの悩[なや]みは尽[つ]きない。","ko":"부모이기 때문에 겪는 고민은 끝이 없다."}],"dr":[{"t":"make","q":"忙しい / ミス → ～がゆえの","a":"忙しいがゆえのミス","hint":"い형용사 보통형 + がゆえの + 명사"},{"t":"make","q":"学生 / 悩み → ～がゆえの","a":"学生であるがゆえの悩み","hint":"명사 + である + がゆえの + 명사"},{"t":"fill","q":"それは経験[けいけん]が浅[あさ]い（　）判断[はんだん]ミスだった。","a":"がゆえの","opts":["がゆえの","にしては","ものの","とはいえ"]}],"src":["https://bunpro.jp/grammar_points/ゆえに"],"vf":1,"u":18,"g":1,"gp":"gg_N1_06"},{"id":"g1_184","t":"～こととて","ko":"~이라서, ~인 탓에","cat":"원인·이유","conn":[{"w":"동사 보통형","f":"慣れない + こととて"},{"w":"い형용사","f":"慌ただしい + こととて"},{"w":"な형용사","f":"不慣れな + こととて"},{"w":"명사","f":"子どもの + こととて"}],"rule":["1. な형용사는 어간 뒤에 な를 붙인다: 不慣れ → 不慣れな.","2. 그 뒤에 こととて를 붙인다: 不慣れなこととて.","3. 명사는 の를, 동사·い형용사는 보통형을 그대로 앞에 둔다: 子どものこととて, 慣れないこととて."],"why":"","nu":"고풍스러운 문어체로, 편지나 격식 있는 인사에서 쓴다. 주로 '그런 사정이니 양해해 달라'는 사과·변명의 이유를 말할 때 쓰며, 뒤에 お許しください, 申し訳ありません 같은 사과나 '어쩔 수 없었다'는 결과가 온다. 말하는 사람의 적극적인 의지·계획의 이유(그래서 ~하겠다)로는 쓰지 않는다.","cmp":[{"g":"～ので","d":"이유를 나타내는 일반적인 표현. こととて는 사정을 내세워 양해를 구하는 딱딱한 표현이다."}],"ex":[{"jp":"不慣[ふな]れなこととて、ご迷惑[めいわく]をおかけしました。","ko":"익숙하지 않은 탓에 폐를 끼쳤습니다."},{"jp":"何分[なにぶん]子[こ]どものしたこととて、どうかお許[ゆる]しください。","ko":"아무래도 아이가 한 일이라서, 부디 용서해 주십시오."},{"jp":"急[きゅう]なこととて、十分[じゅうぶん]な準備[じゅんび]ができませんでした。","ko":"갑작스러운 일이라 충분한 준비를 하지 못했습니다."}],"dr":[{"t":"make","q":"新人 → ～こととて","a":"新人のこととて","hint":"명사 + の + こととて"},{"t":"make","q":"知らない → ～こととて","a":"知らないこととて","hint":"동사 보통형 + こととて"},{"t":"fill","q":"慣[な]れない（　）、失礼[しつれい]をいたしました。","a":"こととて","opts":["こととて","ことには","ことなく","ことだし"]}],"src":["https://nihongokyoshi-net.com/2019/09/12/jlptn1-grammar-kototote/","https://bunpro.jp/grammar_points/こととて"],"vf":1,"u":18,"g":1,"gp":"gg_N1_06"},{"id":"g1_190","t":"～とあって","ko":"~라서, ~인 만큼 (특별한 상황이라)","cat":"원인·이유","conn":[{"w":"명사","f":"連休 + とあって"},{"w":"동사 보통형","f":"人気歌手が来る + とあって"},{"w":"い형용사","f":"値段が安い + とあって"}],"rule":["1. 특별한 상황을 나타내는 명사나 보통형을 둔다: 連休.","2. 그 뒤에 とあって를 붙인다: 連休とあって.","3. 뒤에는 그 상황 때문에 생긴, 눈에 보이는 결과를 쓴다: 道路が込んでいる."],"why":"","nu":"보도·문장체에서 '~라는 특별한 사정이 있어서 (당연히) ~하다'를 객관적으로 묘사할 때 쓴다. 뒤에는 관찰된 사실이 오고, 말하는 사람의 의지·희망·명령·권유는 오지 않는다. 일상적인 이유(雨だから)에는 어색하다. 명사·な형용사에는 보통 だ를 붙이지 않는다.","cmp":[{"g":"～だけあって","d":"'~인 만큼 (역시)'로, 기대에 걸맞은 평가를 나타낸다. とあって는 특별한 상황이 낳은 결과를 묘사한다."},{"g":"～とあれば","d":"'~라면 (특별히)'라는 조건 표현. 뒤에 의지가 올 수 있다."}],"ex":[{"jp":"連休[れんきゅう]とあって、高速道路[こうそくどうろ]はひどく込[こ]んでいる。","ko":"연휴라서 고속도로는 몹시 붐비고 있다."},{"jp":"人気[にんき]歌手[かしゅ]が来[く]るとあって、会場[かいじょう]の前[まえ]には朝[あさ]から長[なが]い列[れつ]ができた。","ko":"인기 가수가 온다고 하니 회장 앞에는 아침부터 긴 줄이 생겼다."},{"jp":"値段[ねだん]が半額[はんがく]とあって、店[みせ]は客[きゃく]でいっぱいだった。","ko":"가격이 반값이라서 가게는 손님으로 가득했다."}],"dr":[{"t":"make","q":"夏休み → ～とあって","a":"夏休みとあって","hint":"명사 + とあって (だ 없이)"},{"t":"make","q":"有名な先生が話す → ～とあって","a":"有名な先生が話すとあって","hint":"동사 보통형 + とあって"},{"t":"fill","q":"初日[しょにち]（　）、映画館[えいがかん]は満員[まんいん]だった。","a":"とあって","opts":["とあって","とはいえ","といえども","としたら"]}],"src":["https://www.mlcjapanese.co.jp/n1_04_14.html","https://bunpro.jp/grammar_points/832"],"vf":1,"u":19,"g":1,"gp":"gg_N1_06"},{"id":"g1_016","t":"～かたがた","ko":"~할 겸, ~을 겸하여","cat":"목적","conn":[{"w":"동작성 명사","f":"お礼 + かたがた / ご挨拶 + かたがた / 散歩 + かたがた"}],"rule":["1. 동작을 나타내는 명사 뒤에 바로 かたがた를 붙인다. お礼 → お礼かたがた.","2. 그 뒤에 伺う・訪ねる 같은 방문 동작이나 申し上げる 같은 겸양 표현이 이어진다. お礼かたがた伺う."],"why":"","nu":"한 번의 방문이나 외출로 두 가지 목적을 함께 이룬다는 뜻. 편지・인사말 같은 격식 있는 장면에서 주로 쓰며 お礼かたがた, ご挨拶かたがた, ご報告かたがた가 대표적이다. 뒤에는 伺う 같은 방문 동사가 자주 오며, 주어는 말하는 사람 자신이다. 명사에 の를 넣지 않는다(お礼のかたがた는 틀림).","cmp":[{"g":"～がてら","d":"뜻이 비슷하지만 일상적이고 동사 ます형에도 붙는다. かたがた는 격식체로 명사에만 붙는다."},{"g":"～かたわら","d":"긴 기간 동안 본업과 다른 일을 병행. かたがた는 한 번의 행동이 두 목적을 겸함."}],"ex":[{"jp":"お礼[れい]かたがた、近[ちか]いうちにお伺[うかが]いします。","ko":"감사 인사도 드릴 겸 조만간 찾아뵙겠습니다."},{"jp":"ご挨拶[あいさつ]かたがた、新[あたら]しい担当者[たんとうしゃ]を連[つ]れて参[まい]りました。","ko":"인사도 드릴 겸 새 담당자를 데리고 왔습니다."},{"jp":"散歩[さんぽ]かたがた、駅前[えきまえ]の本屋[ほんや]まで行[い]ってきた。","ko":"산책도 할 겸 역 앞 서점까지 다녀왔다."}],"dr":[{"t":"make","q":"ご報告 → ～かたがた","a":"ご報告かたがた","hint":"명사 + かたがた (の 없음)"},{"t":"make","q":"お見舞い → ～かたがた","a":"お見舞いかたがた","hint":"명사 + かたがた (の 없음)"},{"t":"fill","q":"先日[せんじつ]のお礼[れい]（　）、ご挨拶[あいさつ]に伺[うかが]いました。","a":"かたがた","opts":["かたがた","かたわら","ばかりに","あまり"]}],"src":["https://www.kanshudo.com/grammar/%E3%81%8B%E3%81%9F%E3%81%8C%E3%81%9F"],"vf":1,"u":19,"g":1,"gp":"gg_N1_06"},{"id":"g1_017","t":"～がてら","ko":"~하는 김에, ~할 겸","cat":"목적","conn":[{"w":"동작성 명사","f":"散歩 + がてら"},{"w":"동사 ます형","f":"送る → 送り + がてら"}],"rule":["1. 명사는 바로 がてら를 붙인다. 散歩 → 散歩がてら.","2. 1그룹 동사는 어미 う단을 い단으로 바꾼 ます형을 만든다. 送る → 送り.","3. ます형 뒤에 がてら를 붙인다. 送り → 送りがてら."],"why":"","nu":"A를 하는 기회에 B도 함께 한다는 뜻. 뒤에는 行く・寄る・出かける・歩く 같은 이동 동작이 자주 온다. 회화와 글 모두 쓰지만 かたがた보다 덜 딱딱하다. 주된 목적은 A이고 B는 덤이다.","cmp":[{"g":"～ついでに","d":"가장 일반적인 표현으로 이동 동작이 아니어도 쓸 수 있다."},{"g":"～かたがた","d":"격식체이며 명사에만 붙는다(お礼かたがた)."}],"ex":[{"jp":"散歩[さんぽ]がてら、手紙[てがみ]を出[だ]してきた。","ko":"산책하는 김에 편지를 부치고 왔다."},{"jp":"駅[えき]まで友達[ともだち]を送[おく]りがてら、本屋[ほんや]に寄[よ]った。","ko":"역까지 친구를 배웅하는 김에 서점에 들렀다."},{"jp":"買[か]い物[もの]がてら、新[あたら]しくできたカフェを見[み]てきた。","ko":"장 보는 김에 새로 생긴 카페를 보고 왔다."}],"dr":[{"t":"make","q":"遊ぶ → ～がてら","a":"遊びがてら","hint":"1그룹 ぶ → び (ます형) + がてら"},{"t":"make","q":"買い物 → ～がてら","a":"買い物がてら","hint":"명사 + がてら"},{"t":"fill","q":"天気[てんき]がいいので、散歩[さんぽ]（　）郵便局[ゆうびんきょく]まで歩[ある]いた。","a":"がてら","opts":["がてら","ばかりか","とたん","ものの"]}],"src":["https://bunpro.jp/grammar_points/836"],"vf":1,"u":19,"g":1,"gp":"gg_N1_07"},{"id":"g1_035","t":"～と～を兼ねて","ko":"~와 ~을 겸해서","cat":"목적","conn":[{"w":"명사 + 명사","f":"散歩 と 買い物 + を兼ねて"},{"w":"명사 수식","f":"寝室と書斎を + 兼ねた + 部屋"}],"rule":["1. 兼ねる의 어미 る를 떼고 て를 붙인다(兼ねる → 兼ねて).","2. 명사1 + と + 명사2 + を 뒤에 둔다(散歩と買い物を兼ねて).","3. 명사를 꾸밀 때는 た형 兼ねた를 쓴다(寝室と書斎を兼ねた部屋)."],"why":"兼ねる(겸하다, 한 가지가 두 가지 역할을 하다)의 て형.","nu":"하나의 행동이 두 가지 목적을, 또는 하나의 사람·물건이 두 가지 역할을 함께 한다는 뜻. 회화와 글 모두에서 쓴다. '~도 겸해서'처럼 부수적 목적을 덧붙일 때는 ～も兼ねて.","cmp":[{"g":"～も兼ねて","d":"주된 목적 외에 다른 목적을 덧붙인다(運動も兼ねて歩いて行く)."}],"ex":[{"jp":"散歩[さんぽ]と買[か]い物[もの]を兼[か]ねて、駅[えき]まで歩[ある]いた。","ko":"산책과 장보기를 겸해서 역까지 걸었다."},{"jp":"出張[しゅっちょう]と観光[かんこう]を兼[か]ねて京都[きょうと]へ行[い]った。","ko":"출장과 관광을 겸해서 교토에 갔다."},{"jp":"この部屋[へや]は寝室[しんしつ]と書斎[しょさい]を兼[か]ねている。","ko":"이 방은 침실과 서재를 겸하고 있다."}],"dr":[{"t":"make","q":"兼ねる → て형","a":"兼ねて","hint":"る를 떼고 て"},{"t":"make","q":"散歩 / 買い物 → ～と～を兼ねて","a":"散歩と買い物を兼ねて","hint":"명사1 + と + 명사2 + を兼ねて"},{"t":"fill","q":"旅行[りょこう]と勉強[べんきょう]を（　）、留学[りゅうがく]した。","a":"兼ねて","opts":["兼ねて","込めて","問わず","除いて"]}],"src":["https://nihongokyoshi-net.com/2020/02/11/jlptn1-grammar-wokanete/"],"vf":1,"u":19,"g":1,"gp":"gg_N1_07"},{"id":"g1_094","t":"～も兼ねて","ko":"~도 겸해서","cat":"목적","conn":[{"w":"명사","f":"散歩 + も兼ねて"}],"rule":["1. 2그룹 동사 兼ねる(겸하다)의 어미 る를 뗀다: 兼ねる → 兼ね.","2. て를 붙여 て형을 만든다: 兼ね → 兼ねて.","3. 덧붙는 목적을 나타내는 명사에 も를 붙여 앞에 둔다: 運動も兼ねて."],"why":"동사 兼ねる(겸하다)의 て형에 조사 も(~도)가 붙은 것이다.","nu":"주된 목적이 따로 있고, 거기에 명사의 목적도 함께 이룬다는 뜻이다. 회화와 글 모두에서 쓴다. も 대신 を를 써서 ～を兼ねて라고도 하며 뜻은 거의 같다. 명사 + も兼ねた + 명사(趣味も兼ねた仕事)처럼 명사를 꾸미기도 한다.","cmp":[{"g":"～を兼ねて","d":"ダイエットを兼ねて처럼 명사가 함께 이루는 부가 목적을 나타내며, も兼ねて와 거의 같은 뜻이다. も를 쓰면 '그것도 겸해서'라는 느낌이 더해진다."},{"g":"～ついでに","d":"어떤 일을 하는 기회에 다른 일도 한다는 뜻으로, 동사·명사(買い物のついでに)에 붙는다."}],"ex":[{"jp":"運動[うんどう]も兼[か]ねて、駅[えき]まで歩[ある]いて行[い]く。","ko":"운동도 겸해서 역까지 걸어간다."},{"jp":"気分転換[きぶんてんかん]も兼[か]ねて、週末[しゅうまつ]は海[うみ]へ行[い]った。","ko":"기분 전환도 겸해서 주말에는 바다에 갔다."},{"jp":"下見[したみ]も兼[か]ねて、会場[かいじょう]の近[ちか]くのホテルに泊[と]まった。","ko":"사전 답사도 겸해서 행사장 근처 호텔에 묵었다."}],"dr":[{"t":"make","q":"運動 → ～も兼ねて","a":"運動も兼ねて","hint":"명사 + も + 兼ねる의 て형(る → て)"},{"t":"make","q":"勉強 → ～も兼ねて","a":"勉強も兼ねて","hint":"명사 + も + 兼ねて"},{"t":"fill","q":"ダイエット（　）兼[か]ねて、自転車[じてんしゃ]で通勤[つうきん]している。","a":"も","opts":["も","で","に","が"]}],"src":["https://bunpro.jp/grammar_points/850","https://www.vnjpclub.com/en/n1-grammar/mo-kanete.html"],"vf":1,"u":19,"g":1,"gp":"gg_N1_07"},{"id":"g1_147","t":"～ように","ko":"~하도록, ~한 대로","cat":"목적","conn":[{"w":"동사 사전형","f":"間に合う + ように"},{"w":"동사 ない형","f":"忘れない + ように"},{"w":"가능동사","f":"読める + ように"},{"w":"동사 た형(방식)","f":"言った + ように"}],"rule":["1. 2그룹 동사는 る를 빼고 ない를 붙여 ない형을 만든다: 忘れる → 忘れない.","2. 사전형이나 ない형 뒤에 ように를 붙인다: 忘れないように.","3. 목적의 ように 앞에는 주로 의지가 들어가지 않는 말(가능형, ない형, 自動詞)이 온다.","4. た형 + ように는 '~한 대로'라는 방식을 나타낸다: 先生が言ったように."],"why":"よう(様, 모양·방식) + 조사 に.","nu":"'~하도록'은 어떤 상태가 되기를 바라며 하는 행동을 나타낸다. 한국어 '~하기 위해'를 모두 ために로 옮기는 실수가 많은데, 뒤 행동을 하는 사람의 의지로 직접 이룰 수 없는 상태(聞こえる, できる, 忘れない)에는 ように를 쓴다. 문장 끝 ようにする는 '~하도록 노력하다', ようになる는 '~하게 되다'라는 별도 표현이다.","cmp":[{"g":"～ために","d":"의지동사와 함께 목적을 직접 나타낸다(合格するために勉強する). 가능형·ない형 같은 상태에는 ように를 쓴다."},{"g":"～ようにする","d":"습관이나 노력을 나타내는 문말 표현(毎日歩くようにしている)."}],"ex":[{"jp":"忘[わす]れないように、手帳[てちょう]に書[か]いておいた。","ko":"잊지 않도록 수첩에 적어 두었다."},{"jp":"後[うし]ろの席[せき]の人[ひと]にも聞[き]こえるように、大[おお]きな声[こえ]で話[はな]してください。","ko":"뒷자리 사람에게도 들리도록 큰 소리로 말해 주세요."},{"jp":"先生[せんせい]が言[い]ったように、もう一度[いちど]やってみましょう。","ko":"선생님이 말한 대로 한 번 더 해 봅시다."}],"dr":[{"t":"make","q":"間に合う → ～ように","a":"間に合うように","hint":"사전형 + ように"},{"t":"make","q":"風邪をひく(부정) → ～ように","a":"風邪をひかないように","hint":"1그룹 ない형: く → か + ない, 그 뒤에 ように"},{"t":"fill","q":"子[こ]どもにも分[わ]かる（　）、やさしい言葉[ことば]で説明[せつめい]した。","a":"ように","opts":["ように","ために","くせに","ばかりに"]}],"src":["https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201310.html"],"vf":1,"u":20,"g":1,"gp":"gg_N1_07"},{"id":"g1_159","t":"～ことのないように","ko":"~하는 일이 없도록","cat":"목적","conn":[{"w":"동사 사전형","f":"忘れる + ことのないように"},{"w":"동사 수동형","f":"だまされる + ことのないように"}],"rule":["1. 동사는 사전형을 그대로 쓴다: 忘れる.","2. 사전형 뒤에 こと를 붙인다: 忘れること.","3. 그 뒤에 の + ない를 붙인다: 忘れることのない.","4. 마지막으로 ように를 붙인다: 忘れることのないように."],"why":"","nu":"'~하는 일이 없도록'이라는 격식 있는 표현으로, 안내문·주의 사항·공지에서 자주 보인다. 바람직하지 않은 일을 막기 위한 주의나 다짐을 나타낸다. 일상 회화에서는 ～ないように가 더 자연스럽다.","cmp":[{"g":"～ないように","d":"같은 뜻의 일반적인 표현(忘れないように). ことのないように는 더 격식 있고 딱딱하다."},{"g":"～ことがないように","d":"の 대신 が를 쓴 형태로 뜻은 같다."}],"ex":[{"jp":"二度[にど]と同[おな]じミスをすることのないように、注意[ちゅうい]してください。","ko":"두 번 다시 같은 실수를 하는 일이 없도록 주의해 주세요."},{"jp":"忘[わす]れ物[もの]をすることのないように、出[で]かける前[まえ]に確認[かくにん]しよう。","ko":"물건을 두고 가는 일이 없도록 나가기 전에 확인하자."},{"jp":"事故[じこ]が起[お]きることのないように、安全運転[あんぜんうんてん]を心[こころ]がけている。","ko":"사고가 나는 일이 없도록 안전 운전을 유념하고 있다."}],"dr":[{"t":"make","q":"遅れる → ～ことのないように","a":"遅れることのないように","hint":"사전형 + こと + の + ない + ように"},{"t":"make","q":"だまされます → ～ことのないように","a":"だまされることのないように","hint":"ます형을 사전형으로(される) + ことのないように"},{"t":"fill","q":"風邪[かぜ]をひく（　）、手[て]をよく洗[あら]いましょう。","a":"ことのないように","opts":["ことのないように","ことになって","ことだから","ことはない"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ことのないように-koto-no-nai-you-ni-meaning","https://aiueo.cc/pages_v2/en/grammar/web/606.php"],"vf":1,"u":20,"g":1,"gp":"gg_N1_07"},{"id":"g1_170","t":"～べく","ko":"~하기 위해, ~하고자","cat":"목적","conn":[{"w":"동사 사전형","f":"伝える + べく"},{"w":"する","f":"合格する → 合格す + べく (合格するべく도 씀)"}],"rule":["1. 동사는 사전형 그대로 둔다: 伝える → 伝えるべく.","2. する동사는 する를 す로 바꾸는 경우가 많다: 合格する → 合格す.","3. 그 뒤에 べく를 붙인다: 合格すべく.","4. 뒤 문장에는 목적을 위해 하는 행동을 쓴다."],"why":"고전 조동사 べし의 연용형 べく로, '~해야 할 것으로, ~하려고'라는 뜻에서 목적을 나타내게 되었다.","nu":"딱딱한 문어체로 뉴스·보고서·연설 등에서 쓴다. 의지적인 목적을 나타내므로 앞뒤 주어가 같고 의지로 할 수 있는 동작에 쓴다. 뒤 문장에 의뢰·명령·권유(~てください, ~しよう)는 오지 않는다. 일상 대화에서는 ~ために를 쓴다.","cmp":[{"g":"～ために","d":"일반적인 목적 표현으로 회화·문장 모두 쓰며, 뒤에 의뢰·명령도 올 수 있다."},{"g":"～ように","d":"가능형·무의지 동사나 부정형에 붙어 그런 상태가 되도록 한다는 뜻이다. べく는 의지 동사에 붙는다."}],"ex":[{"jp":"試験[しけん]に合格[ごうかく]すべく、毎晩[まいばん]遅[おそ]くまで勉強[べんきょう]している。","ko":"시험에 합격하기 위해 매일 밤 늦게까지 공부하고 있다."},{"jp":"彼[かれ]は夢[ゆめ]をかなえるべく、一人[ひとり]で東京[とうきょう]へ出[で]た。","ko":"그는 꿈을 이루고자 혼자 도쿄로 떠났다."},{"jp":"事故[じこ]の原因[げんいん]を調[しら]べるべく、専門家[せんもんか]が現場[げんば]に向[む]かった。","ko":"사고 원인을 조사하기 위해 전문가가 현장으로 향했다."}],"dr":[{"t":"make","q":"確認する → ～べく","a":"確認すべく","hint":"する → す + べく"},{"t":"make","q":"助ける → ～べく","a":"助けるべく","hint":"동사 사전형 + べく"},{"t":"fill","q":"記録[きろく]を更新[こうしん]す（　）、彼[かれ]は練習[れんしゅう]を重[かさ]ねた。","a":"べく","opts":["べく","べからず","べくもない","べきだ"]}],"src":["https://nihongokyoshi-net.com/2019/06/23/jlptn1-grammar-beku/","https://bunpro.jp/grammar_points/べく"],"vf":1,"u":20,"g":1,"gp":"gg_N1_07"},{"id":"g1_188","t":"～つもりで","ko":"~할 생각으로, ~한 셈 치고","cat":"목적","conn":[{"w":"동사 사전형","f":"住む + つもりで"},{"w":"동사 た형","f":"行った + つもりで"},{"w":"명사","f":"旅行の + つもりで"}],"rule":["1. 사전형 + つもりで는 '~할 생각으로': 住むつもりで.","2. 1그룹 동사 行く는 어미 く를 った로 바꿔 た형을 만든다: 行く → 行った.","3. た형 뒤에 つもりで를 붙이면 '(실제로는 안 했지만) ~한 셈 치고'가 된다: 行ったつもりで.","4. 명사는 の를 붙여 잇는다: 旅行のつもりで."],"why":"명사 つもり(의도)에 수단·상태를 나타내는 で가 붙은 형태로, 'つもり를 가지고' 뒤의 행동을 한다는 뜻이다.","nu":"뒤에는 그 생각을 가지고 하는 행동이 온다. た형 + つもりで는 '~했다 치고'라는 가정이며 죽을 각오를 나타내는 死んだつもりで(죽을 각오로)도 자주 쓴다. 명사 + のつもりで는 '~인 셈 치고, ~라는 생각으로'(先生のつもりで教えてみて).","cmp":[{"g":"～ために","d":"객관적인 목적을 나타낸다. つもりで는 마음속 의도나 '~한 셈 치는' 가정을 나타낸다."}],"ex":[{"jp":"日本[にほん]に住[す]むつもりで、日本語[にほんご]を勉強[べんきょう]している。","ko":"일본에 살 생각으로 일본어를 공부하고 있다."},{"jp":"旅行[りょこう]に行[い]ったつもりで、そのお金[かね]を貯金[ちょきん]した。","ko":"여행을 간 셈 치고 그 돈을 저금했다."},{"jp":"死[し]んだつもりで、もう一度[いちど]頑張[がんば]ってみよう。","ko":"죽을 각오로 한 번 더 힘내 보자."}],"dr":[{"t":"make","q":"買う → ～た형 + つもりで","a":"買ったつもりで","hint":"1그룹: う → った + つもりで"},{"t":"make","q":"遊び → ～つもりで","a":"遊びのつもりで","hint":"명사 + の + つもりで"},{"t":"fill","q":"外食[がいしょく]した（　）、家[いえ]で節約[せつやく]した料理[りょうり]を作[つく]った。","a":"つもりで","opts":["つもりで","ばかりに","とたんに","あげく"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A4%E3%82%82%E3%82%8A%E3%81%A7"],"vf":1,"u":20,"g":1,"gp":"gg_N1_07"},{"id":"g1_237","t":"～んがために","ko":"~하고자, ~하기 위해서(라면)","cat":"목적","conn":[{"w":"동사 ない형 어간","f":"勝つ → 勝た + んがために"},{"w":"する (불규칙)","f":"する → せ + んがために"}],"rule":["1. 동사를 ない형 어간(未然形)으로 만든다. 1그룹은 어미 う단을 あ단으로 바꾼다: 勝つ → 勝た.","2. 그 뒤에 んがために를 붙인다: 勝たんがために.","3. 2그룹은 る를 빼고 붙인다: 生きる → 生きんがために.","4. する는 し가 아니라 せ가 되어 せんがために가 된다."],"why":"ん은 부정의 ん이 아니라 고어의 의지·추량 조동사 む가 변한 것이고, が는 '~의'를 뜻하는 옛 조사, ため는 '위함'이다. 그래서 '~하려 하기 위해'라는 강한 목적의 뜻이 된다.","nu":"'무슨 일이 있어도 ~하려고'라는 강한 의지가 담긴 목적 표현으로, 매우 딱딱한 문어체다. 일상 회화에서는 거의 쓰지 않고 연설·소설·논설에서 볼 수 있다. 앞에는 의지로 할 수 있는 동작이 온다. ん을 보고 부정('~하지 않기 위해')으로 해석하는 실수가 많으니 주의한다. 끝의 に는 생략하여 んがため라고도 한다.","cmp":[{"g":"～ために","d":"일반적인 목적 표현으로 회화·문장 모두에 쓴다. んがために는 같은 뜻을 훨씬 강하고 예스럽게 말한다."},{"g":"～んばかりに","d":"모양은 비슷하지만 '금방이라도 ~할 듯이'라는 모습의 비유이며 목적이 아니다."}],"ex":[{"jp":"試合[しあい]に勝[か]たんがために、彼[かれ]らは毎日[まいにち]厳[きび]しい練習[れんしゅう]を続[つづ]けた。","ko":"시합에서 이기고자 그들은 매일 혹독한 연습을 계속했다."},{"jp":"生[い]きんがために、彼[かれ]はどんな仕事[しごと]でも引[ひ]き受[う]けた。","ko":"살아남기 위해 그는 어떤 일이든 떠맡았다."},{"jp":"合格[ごうかく]せんがために、彼女[かのじょ]は一年間[いちねんかん]遊[あそ]びを我慢[がまん]した。","ko":"합격하고자 그녀는 1년 동안 노는 것을 참았다."}],"dr":[{"t":"make","q":"守る → ～んがために","a":"守らんがために","hint":"1그룹: る(う단) → ら(あ단) + んがために"},{"t":"make","q":"成功する → ～んがために","a":"成功せんがために","hint":"する는 せ + んがために"},{"t":"fill","q":"夢[ゆめ]をかなえ（　）、彼[かれ]は故郷[こきょう]を離[はな]れた。","a":"んがために","opts":["んがために","んばかりに","ずにはいられず","てからでないと"]}],"src":[],"vf":0,"u":21,"g":1,"gp":"gg_N1_07"},{"id":"g1_045","t":"～ともなると","ko":"~쯤 되면, ~ 정도가 되면","cat":"접속·조건","conn":[{"w":"명사(시기·연령·지위)","f":"冬 + ともなると"},{"w":"동사 사전형","f":"一人で海外に住む + ともなると"}],"rule":["1. 특별한 단계(시기·나이·지위)를 나타내는 명사를 놓는다(冬).","2. 그 뒤에 ともなると를 그대로 붙인다(冬ともなると).","3. 뒤에는 그 단계가 되면 자연히 생기는 변화나 상황이 온다(湖が凍る)."],"why":"","nu":"평소와 다른 단계에 이르면 그에 맞게 상황이 달라진다는 것을 말한다. 앞에는 계절·시기, 나이·학년, 지위 같은 말이 주로 온다. 뒤에는 그 결과로 일반적으로 일어나는 일이나 판단이 온다. 약간 딱딱한 말투이지만 회화에서도 쓴다.","cmp":[{"g":"～ともなれば","d":"뜻은 거의 같다. と 대신 ば 조건형을 쓴 형태다."}],"ex":[{"jp":"冬[ふゆ]ともなると、この湖[みずうみ]は凍[こお]ってしまう。","ko":"겨울쯤 되면 이 호수는 얼어 버린다."},{"jp":"大学生[だいがくせい]ともなると、自分[じぶん]のことは自分[じぶん]で決[き]めなければならない。","ko":"대학생쯤 되면 자기 일은 스스로 정해야 한다."},{"jp":"一人[ひとり]で海外[かいがい]に住[す]むともなると、準備[じゅんび]が大変[たいへん]だ。","ko":"혼자 해외에서 살게 되면 준비가 큰일이다."}],"dr":[{"t":"make","q":"冬 → ～ともなると","a":"冬ともなると","hint":"명사 + ともなると"},{"t":"make","q":"社長 → ～ともなると","a":"社長ともなると","hint":"명사 + ともなると"},{"t":"fill","q":"12月[じゅうにがつ]（　）、町[まち]はどこも忙[いそが]しくなる。","a":"ともなると","opts":["ともなると","ともあろう","といわず","なしには"]}],"src":["https://nihongokyoshi-net.com/2019/06/27/jlptn1-grammar-tomonaruto-tomonareba/","https://bunpro.jp/grammar_points/752"],"vf":1,"u":21,"g":1,"gp":"gg_N1_07"},{"id":"g1_046","t":"～ともなれば","ko":"~쯤 되면, ~ 정도가 되면","cat":"접속·조건","conn":[{"w":"명사(시기·연령·지위)","f":"休日 + ともなれば"},{"w":"동사 사전형","f":"家を建てる + ともなれば"}],"rule":["1. 특별한 단계(시기·지위 등)를 나타내는 명사를 놓는다(休日).","2. 그 뒤에 ともなれば를 그대로 붙인다(休日ともなれば).","3. 뒤에는 그 단계가 되면 당연히 생기는 상황이 온다(人でいっぱいになる)."],"why":"","nu":"그 단계에 이르면 그에 걸맞은 상황이 당연히 따른다는 것을 말한다. 앞에는 시기·나이·지위 같은 말이 주로 온다. 약간 딱딱한 말투이지만 회화에서도 쓴다.","cmp":[{"g":"～ともなると","d":"뜻은 거의 같다. ば 대신 と를 쓴 형태다."}],"ex":[{"jp":"休日[きゅうじつ]ともなれば、駅前[えきまえ]は人[ひと]でいっぱいになる。","ko":"휴일쯤 되면 역 앞은 사람으로 가득해진다."},{"jp":"プロともなれば、毎日[まいにち]何時間[なんじかん]も練習[れんしゅう]するのは当然[とうぜん]だ。","ko":"프로쯤 되면 매일 몇 시간씩 연습하는 것은 당연하다."},{"jp":"家[いえ]を建[た]てるともなれば、かなりのお金[かね]が必要[ひつよう]だ。","ko":"집을 짓게 되면 꽤 많은 돈이 필요하다."}],"dr":[{"t":"make","q":"休日 → ～ともなれば","a":"休日ともなれば","hint":"명사 + ともなれば"},{"t":"make","q":"プロ → ～ともなれば","a":"プロともなれば","hint":"명사 + ともなれば"},{"t":"fill","q":"社長[しゃちょう]（　）、責任[せきにん]も重[おも]くなる。","a":"ともなれば","opts":["ともなれば","なりとも","ならいざ知らず","なくして"]}],"src":["https://nihongokyoshi-net.com/2019/06/27/jlptn1-grammar-tomonaruto-tomonareba/","https://bunpro.jp/grammar_points/752"],"vf":1,"u":21,"g":1,"gp":"gg_N1_07"},{"id":"g1_048","t":"～なくして～はない","ko":"~없이는 ~도 없다","cat":"접속·조건","conn":[{"w":"명사 + 명사","f":"努力 + なくして + 成功 + はない"}],"rule":["1. 꼭 필요한 것을 명사로 놓고 なくして를 붙인다(努力なくして).","2. 그 뒤에 이룰 수 없는 결과를 명사로 놓는다(成功).","3. 마지막에 はない를 붙인다(努力なくして成功はない). はありえない・できない 등 부정 표현도 온다."],"why":"ない(없다)의 연용형 なく + して로 '~이 없이'라는 뜻이 된다.","nu":"문어적이고 격식 있는 표현이다. 앞에는 노력·협력·사랑처럼 꼭 필요한 것이 오고, 뒤는 반드시 부정('~은 없다, ~할 수 없다')으로 끝난다. なくしては 형태로도 쓴다.","cmp":[{"g":"～なしでは～ない","d":"뜻은 비슷하지만 회화에서도 널리 쓰는 일반적인 표현이다. なくして는 더 딱딱하고 격언 같은 느낌을 준다."}],"ex":[{"jp":"努力[どりょく]なくして成功[せいこう]はない。","ko":"노력 없이는 성공도 없다."},{"jp":"皆[みな]さんの協力[きょうりょく]なくして、この計画[けいかく]の成功[せいこう]はありえなかった。","ko":"여러분의 협력 없이는 이 계획의 성공은 있을 수 없었다."},{"jp":"健康[けんこう]なくして、幸[しあわ]せな生活[せいかつ]はない。","ko":"건강 없이는 행복한 생활도 없다."}],"dr":[{"t":"make","q":"努力・成功 → ～なくして～はない","a":"努力なくして成功はない","hint":"명사 + なくして + 명사 + はない"},{"t":"make","q":"練習・上達 → ～なくして～はない","a":"練習なくして上達はない","hint":"명사 + なくして + 명사 + はない"},{"t":"fill","q":"信頼[しんらい]（　）、本当[ほんとう]の友情[ゆうじょう]はない。","a":"なくして","opts":["なくして","ならでは","ともあろう","と相まって"]}],"src":["https://bunpro.jp/grammar_points/825"],"vf":1,"u":21,"g":1,"gp":"gg_N1_07"},{"id":"g1_049","t":"～なしでは～ない","ko":"~없이는 ~할 수 없다","cat":"접속·조건","conn":[{"w":"명사 + 부정 표현(주로 가능형 부정)","f":"水 + なしでは + 生きられない"}],"rule":["1. 꼭 필요한 것을 명사로 놓고 なしでは를 붙인다(水なしでは).","2. 뒤의 동사를 가능형 부정으로 바꾼다. 2그룹 동사 生きる는 어미 る를 られない로 바꾼다(生きられない).","3. 1그룹 동사는 어미 う단을 え단으로 바꾸고 ない를 붙인다(読む → 読めない)."],"why":"なし(無し, 없음) + では로 '~이 없는 상태에서는'이라는 뜻이 된다.","nu":"그것이 없으면 성립하지 않을 만큼 꼭 필요하다는 것을 말한다. 뒤는 반드시 부정 표현(できない, 生きられない, 成り立たない 등)으로 끝난다. 회화와 글 모두에서 쓴다. なしで(~없이)만 쓰면 부정 없이 '~없이 하다'라는 뜻이 된다(砂糖なしで飲む).","cmp":[{"g":"～なしには～ない","d":"뜻은 거의 같고 조금 더 딱딱하다."},{"g":"～なくして～はない","d":"문어적이고 격언 같은 느낌이 강하다."}],"ex":[{"jp":"人[ひと]は水[みず]なしでは生[い]きられない。","ko":"사람은 물 없이는 살 수 없다."},{"jp":"眼鏡[めがね]なしでは、何[なに]も見[み]えない。","ko":"안경 없이는 아무것도 안 보인다."},{"jp":"彼[かれ]の助[たす]けなしでは、この仕事[しごと]は終[お]わらなかった。","ko":"그의 도움 없이는 이 일은 끝나지 않았다."}],"dr":[{"t":"make","q":"水・生きる → ～なしでは～ない","a":"水なしでは生きられない","hint":"명사 + なしでは + 가능 부정(る → られない)"},{"t":"make","q":"辞書・読む → ～なしでは～ない","a":"辞書なしでは読めない","hint":"명사 + なしでは + 가능 부정(む → めない)"},{"t":"fill","q":"携帯電話[けいたいでんわ]（　）生活[せいかつ]できない。","a":"なしでは","opts":["なしでは","ならでは","ともなれば","といわず"]}],"src":["https://nihongokyoshi-net.com/2019/06/24/jlptn1-grammar-nashini/","https://bunpro.jp/ja/grammar_points/%E3%81%AA%E3%81%8F%E3%81%97%E3%81%A6-%E3%81%AF"],"vf":1,"u":21,"g":1,"gp":"gg_N1_07"},{"id":"g1_050","t":"～なしには～ない","ko":"~없이는 ~할 수 없다","cat":"접속·조건","conn":[{"w":"명사 + 부정 표현(주로 가능형 부정)","f":"涙 + なしには + 見られない"}],"rule":["1. 꼭 따르거나 필요한 것을 명사로 놓고 なしには를 붙인다(涙なしには).","2. 뒤의 동사를 가능형 부정으로 바꾼다. 2그룹 동사 見る는 어미 る를 られない로 바꾼다(見られない).","3. 1그룹 동사는 어미 う단을 え단으로 바꾸고 ない를 붙인다(入る → 入れない)."],"why":"なし(無し, 없음) + には로 '~이 없이는'이라는 뜻이 된다.","nu":"なしでは보다 조금 딱딱하다. 뒤는 반드시 부정 표현으로 끝난다. '涙なしには見られない・語れない(눈물 없이는 볼 수 없다·이야기할 수 없다)'처럼 감동을 강조하는 관용적 쓰임이 많다.","cmp":[{"g":"～なしでは～ない","d":"뜻은 거의 같고 회화에서 더 자주 쓴다."}],"ex":[{"jp":"この映画[えいが]は涙[なみだ]なしには見[み]られない。","ko":"이 영화는 눈물 없이는 볼 수 없다."},{"jp":"家族[かぞく]の支[ささ]えなしには、ここまで来[こ]られなかった。","ko":"가족의 뒷받침 없이는 여기까지 올 수 없었다."},{"jp":"準備[じゅんび]なしには、いい発表[はっぴょう]はできない。","ko":"준비 없이는 좋은 발표를 할 수 없다."}],"dr":[{"t":"make","q":"涙・見る → ～なしには～ない","a":"涙なしには見られない","hint":"명사 + なしには + 가능 부정(る → られない)"},{"t":"make","q":"許可・入る → ～なしには～ない","a":"許可なしには入れない","hint":"1그룹 入る: る → れない"},{"t":"fill","q":"皆[みな]さんの協力[きょうりょく]（　）、成功[せいこう]できなかった。","a":"なしには","opts":["なしには","にしては","ときたら","ならでは"]}],"src":["https://nihongokyoshi-net.com/2019/06/24/jlptn1-grammar-nashini/"],"vf":1,"u":22,"g":1,"gp":"gg_N1_08"},{"id":"g1_075","t":"～いかんだ","ko":"~에 달려 있다, ~나름이다","cat":"접속·조건","conn":[{"w":"명사","f":"結果 + (の)いかんだ"}],"rule":["1. 명사 뒤에 の를 넣고 いかん을 붙인다. の는 생략할 수 있다: 結果のいかん / 結果いかん.","2. 문장 끝에서는 だ(です)를 붙인다: 結果いかんだ.","3. 문장 중간에서 이어 갈 때는 で를 붙인다: 結果いかんで決まる."],"why":"いかん은 한자로 如何라고 쓰며 '어떠함, 어떤 상태인지'를 뜻한다. 명사 + の + いかん은 '그 명사가 어떠한가'라는 뜻이 된다.","nu":"딱딱한 문어체로 공지, 비즈니스 문서, 뉴스 등에서 쓴다. 앞에는 結果・成績・努力・内容・態度・条件처럼 좋고 나쁨이나 정도에 폭이 있는 명사가 온다. 뜻은 次第だ와 같지만 더 격식 있는 표현이며, 일상 회화에서는 次第だ나 によって決まる를 주로 쓴다.","cmp":[{"g":"～次第だ","d":"같은 뜻이며 회화에서도 쓴다. 단, 동사 ます형 + 次第(着き次第)는 '~하는 대로 곧'이라는 다른 뜻이다."},{"g":"～いかんでは","d":"여러 경우 중 어떤 특정한 결과(주로 예외적·불리한 일)가 생길 수 있음을 말한다."}],"ex":[{"jp":"合格[ごうかく]できるかどうかは、面接[めんせつ]の結果[けっか]いかんだ。","ko":"합격할 수 있을지는 면접 결과에 달려 있다."},{"jp":"優勝[ゆうしょう]できるかは、選手[せんしゅ]たちの努力[どりょく]いかんだ。","ko":"우승할 수 있을지는 선수들의 노력에 달려 있다."},{"jp":"今後[こんご]の計画[けいかく]は、会議[かいぎ]の結論[けつろん]いかんで変[か]わる。","ko":"앞으로의 계획은 회의 결론에 따라 바뀐다."}],"dr":[{"t":"make","q":"努力 → ～いかんだ（の 생략형）","a":"努力いかんだ","hint":"명사 + いかん + だ"},{"t":"make","q":"結果 → ～いかんで（문장 중간, の 생략형）","a":"結果いかんで","hint":"명사 + いかん + で"},{"t":"fill","q":"成功[せいこう]するかどうかは、本人[ほんにん]の努力[どりょく]（　）だ。","a":"いかん","opts":["いかん","ついで","ぐるみ","がてら"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/いかんだ-いかんでは-いかんによっては-ikan-dewa-meaning/"],"vf":1,"u":22,"g":1,"gp":"gg_N1_08"},{"id":"g1_076","t":"～いかんでは","ko":"~여하에 따라서는","cat":"접속·조건","conn":[{"w":"명사","f":"天候 + (の)いかんでは"}],"rule":["1. 명사 뒤에 の(생략 가능)와 いかん을 붙인다: 天候のいかん.","2. 그 뒤에 で와 は를 붙여 いかんでは로 만든다.","3. 뒤에는 그 경우에 일어날 수 있는 특정 결과(주로 예외적·불리한 일)를 쓴다."],"why":"いかん(如何, 어떠함) + で + は로 이루어져 '그 내용이 어떠냐에 따라서는'이라는 뜻이 된다.","nu":"여러 가능성 가운데 하나, 특히 중지·처분처럼 예외적이거나 불리한 조치가 있을 수 있음을 알릴 때 쓴다. 뒤에 ～こともある・～かもしれない・～場合もある 같은 가능성 표현이 자주 온다. 공지문 등의 딱딱한 문어체다.","cmp":[{"g":"～いかんで / ～次第で","d":"내용에 따라 결과가 정해진다는 중립적인 말이다. では가 붙으면 그중 특정 경우를 꺼내어 말한다."},{"g":"～いかんによっては","d":"いかんでは와 거의 같은 뜻으로 바꿔 쓸 수 있다."}],"ex":[{"jp":"天候[てんこう]のいかんでは、試合[しあい]が中止[ちゅうし]になることもある。","ko":"날씨 여하에 따라서는 경기가 취소될 수도 있다."},{"jp":"検査[けんさ]の結果[けっか]いかんでは、入院[にゅういん]が必要[ひつよう]になるかもしれない。","ko":"검사 결과에 따라서는 입원이 필요해질지도 모른다."},{"jp":"違反[いはん]の内容[ないよう]いかんでは、退学[たいがく]処分[しょぶん]もあり得[え]る。","ko":"위반 내용에 따라서는 퇴학 처분도 있을 수 있다."}],"dr":[{"t":"make","q":"成績 → ～いかんでは（の 생략형）","a":"成績いかんでは","hint":"명사 + いかん + では"},{"t":"make","q":"体調 → ～のいかんでは","a":"体調のいかんでは","hint":"명사 + の + いかん + では"},{"t":"fill","q":"交渉[こうしょう]の結果[けっか]（　）、計画[けいかく]を中止[ちゅうし]することもあり得[え]る。","a":"いかんでは","opts":["いかんでは","をよそに","はおろか","ならでは"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/いかんだ-いかんでは-いかんによっては-ikan-dewa-meaning/"],"vf":1,"u":22,"g":1,"gp":"gg_N1_08"},{"id":"g1_077","t":"～いかんにかかわらず","ko":"~여하에 관계없이","cat":"접속·조건","conn":[{"w":"명사","f":"理由 + のいかんにかかわらず"}],"rule":["1. 명사 뒤에 の와 いかん을 붙인다: 理由のいかん.","2. 그 뒤에 に와 かかわらず(関わらず)를 붙인다: 理由のいかんにかかわらず.","3. 뒤에는 앞의 내용과 상관없이 바뀌지 않는 규칙·결정을 쓴다."],"why":"いかん(如何, 어떠함) + に + かかわらず(관계없이)로 이루어져 '어떠한지에 관계없이'라는 뜻이 된다.","nu":"규정, 공지, 안내문에서 쓰는 딱딱한 문어체다. 앞에는 理由・結果・事情・国籍・年齢처럼 내용이 여러 가지일 수 있는 명사가 온다. 같은 뜻으로 ～のいかんを問わず, ～のいかんによらず가 있다. 한국어의 '여하를 막론하고'에 가깝다.","cmp":[{"g":"～にかかわらず","d":"天候にかかわらず・有無にかかわらず처럼 명사에 바로 붙으며 더 넓게 쓰인다. いかんにかかわらず는 더 격식 있다."},{"g":"～のいかんを問わず","d":"거의 같은 뜻으로 바꿔 쓸 수 있다."}],"ex":[{"jp":"理由[りゆう]のいかんにかかわらず、一度[いちど]払[はら]った料金[りょうきん]はお返[かえ]しできません。","ko":"이유 여하에 관계없이 한번 지불한 요금은 돌려드릴 수 없습니다."},{"jp":"結果[けっか]のいかんにかかわらず、参加者[さんかしゃ]全員[ぜんいん]に記念品[きねんひん]を差[さ]し上[あ]げます。","ko":"결과에 관계없이 참가자 전원에게 기념품을 드립니다."},{"jp":"国籍[こくせき]のいかんにかかわらず、誰[だれ]でも応募[おうぼ]できる。","ko":"국적에 관계없이 누구나 응모할 수 있다."}],"dr":[{"t":"make","q":"事情 → ～のいかんにかかわらず","a":"事情のいかんにかかわらず","hint":"명사 + の + いかん + に + かかわらず"},{"t":"make","q":"年齢 → ～のいかんにかかわらず","a":"年齢のいかんにかかわらず","hint":"명사 + の + いかんにかかわらず"},{"t":"fill","q":"理由[りゆう]の（　）、遅刻[ちこく]は認[みと]めません。","a":"いかんにかかわらず","opts":["いかんにかかわらず","極みで","手前で","ごとく"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%84%E3%81%8B%E3%82%93-%E3%81%9A","https://jlptsensei.com/learn-japanese-grammar/いかんにかかわらず-いかんによらず-ikan-ni-kakawarazu-meaning/"],"vf":1,"u":22,"g":1,"gp":"gg_N1_08"},{"id":"g1_078","t":"～いかんによっては","ko":"~여하에 따라서는","cat":"접속·조건","conn":[{"w":"명사","f":"症状 + のいかんによっては"}],"rule":["1. 명사 뒤에 の와 いかん을 붙인다: 症状のいかん.","2. 그 뒤에 に와 よって(よる의 て형), は를 붙인다: 症状のいかんによっては.","3. 뒤에는 그 경우에 일어날 수 있는 특정 결과를 쓴다."],"why":"いかん(如何, 어떠함) + によって(~에 따라) + は로 이루어져 '어떠한지에 따라서는'이라는 뜻이 된다.","nu":"いかんでは와 같은 뜻으로, 여러 가능성 가운데 어떤 특정한 결과가 생길 수 있음을 말한다. 뒤에 ～こともある・～場合もある・～かもしれない가 자주 온다. 딱딱한 문어체다.","cmp":[{"g":"～いかんによって","d":"は가 없으면 '~에 따라 (정해진다)'는 중립적인 뜻이다(結果のいかんによって決める)."},{"g":"～によっては","d":"いかん 없이 명사에 바로 붙는 일반적인 표현으로 회화에서도 쓴다(人によっては)."}],"ex":[{"jp":"症状[しょうじょう]のいかんによっては、手術[しゅじゅつ]が必要[ひつよう]になる場合[ばあい]もある。","ko":"증상에 따라서는 수술이 필요해지는 경우도 있다."},{"jp":"今後[こんご]の売[う]り上[あ]げのいかんによっては、店[みせ]を閉[し]めることも考[かんが]えている。","ko":"앞으로의 매출에 따라서는 가게를 닫는 것도 생각하고 있다."},{"jp":"説明[せつめい]のいかんによっては、彼[かれ]も納得[なっとく]してくれるだろう。","ko":"설명 여하에 따라서는 그도 납득해 줄 것이다."}],"dr":[{"t":"make","q":"回答 → ～のいかんによっては","a":"回答のいかんによっては","hint":"명사 + の + いかん + によって + は"},{"t":"make","q":"天候 → ～のいかんによっては","a":"天候のいかんによっては","hint":"명사 + の + いかんによっては"},{"t":"fill","q":"調査[ちょうさ]の結果[けっか]の（　）、計画[けいかく]を見直[みなお]すこともある。","a":"いかんによっては","opts":["いかんによっては","ごとき","くせに","ついでに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/いかんだ-いかんでは-いかんによっては-ikan-dewa-meaning/"],"vf":1,"u":23,"g":1,"gp":"gg_N1_08"},{"id":"g1_079","t":"～いかんによらず","ko":"~여하에 상관없이","cat":"접속·조건","conn":[{"w":"명사","f":"理由 + のいかんによらず"}],"rule":["1. 명사 뒤에 の와 いかん을 붙인다: 理由のいかん.","2. に를 붙이고 동사 よる를 쓴다.","3. よる의 어미 る를 ら로 바꾼 ない형 よら에 부정의 ず를 붙인다: よる → よら → よらず.","4. 뒤에는 앞의 내용과 상관없이 똑같이 적용되는 일을 쓴다."],"why":"いかん(如何, 어떠함) + に + よらず(よる의 ない형 よら + 부정 ず)로 이루어져 '어떠한지에 의하지 않고'라는 뜻이 된다.","nu":"규정·공지 등의 딱딱한 문어체다. ～のいかんにかかわらず, ～のいかんを問わず와 같은 뜻으로 바꿔 쓸 수 있다. 앞에는 理由・結果・事情・年齢처럼 내용이 여러 가지일 수 있는 명사가 온다.","cmp":[{"g":"～のいかんにかかわらず","d":"거의 같은 뜻이다. 둘 다 격식 있는 문어체다."},{"g":"～によらず","d":"何事によらず처럼 いかん 없이 명사에 바로 붙어 '~에 관계없이'라는 뜻을 나타낸다."}],"ex":[{"jp":"理由[りゆう]のいかんによらず、暴力[ぼうりょく]は許[ゆる]されない。","ko":"이유 여하에 상관없이 폭력은 용납되지 않는다."},{"jp":"経験[けいけん]のいかんによらず、やる気[き]のある人[ひと]を採用[さいよう]したい。","ko":"경험 여하에 상관없이 의욕 있는 사람을 채용하고 싶다."},{"jp":"事情[じじょう]のいかんによらず、締[し]め切[き]りを過[す]ぎた申[もう]し込[こ]みは受[う]け付[つ]けない。","ko":"사정 여하에 상관없이 마감이 지난 신청은 받지 않는다."}],"dr":[{"t":"make","q":"結果 → ～のいかんによらず","a":"結果のいかんによらず","hint":"명사 + の + いかん + に + よらず(よる → よら + ず)"},{"t":"make","q":"国籍 → ～のいかんによらず","a":"国籍のいかんによらず","hint":"명사 + の + いかんによらず"},{"t":"fill","q":"理由[りゆう]の（　）、無断[むだん]欠席[けっせき]は認[みと]めない。","a":"いかんによらず","opts":["いかんによらず","ごとき","極みで","至りで"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%84%E3%81%8B%E3%82%93-%E3%81%9A","https://jlptsensei.com/learn-japanese-grammar/いかんにかかわらず-いかんによらず-ikan-ni-kakawarazu-meaning/"],"vf":1,"u":23,"g":1,"gp":"gg_N1_08"},{"id":"g1_112","t":"～前提で","ko":"~(하는) 것을 전제로","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"行く + 前提で"},{"w":"명사 + という","f":"参加者は十人 + という + 前提で"},{"w":"한자어 명사(복합어)","f":"結婚 + 前提で"}],"rule":["1. 동사는 보통형(사전형, た형, ない형) 그대로 前提で 앞에 둔다: 行く前提で.","2. 주어가 필요하면 が를 붙여 앞에 둔다: 彼が行く前提で.","3. 명사 내용을 전제로 할 때는 という를 넣거나(〜という前提で) 結婚前提で처럼 한 단어로 붙인다."],"why":"前提(전제, 미리 깔고 가는 조건)라는 명사에 수단·상태를 나타내는 조사 で가 붙은 형태다.","nu":"앞의 일이 성립한다고 미리 정해 두고 뒤의 행동을 한다는 뜻이다. 회화와 업무 장면 모두에서 쓴다. 뒤 문장에는 계획을 세우다, 이야기를 진행하다 등 그 전제 위에서 하는 행동이 온다. 같은 뜻을 명사로 받을 때는 を前提に(して)를 쓴다(結婚を前提に付き合う).","cmp":[{"g":"～を前提に(して)","d":"명사 + を前提に의 형태로, 앞이 명사일 때 일반적으로 쓴다. 前提で는 동사 보통형이나 という를 받아 '그렇다는 전제로'라는 뜻을 나타낸다."}],"ex":[{"jp":"彼[かれ]も一緒[いっしょ]に行[い]く前提[ぜんてい]で、旅行[りょこう]の計画[けいかく]を立[た]てた。","ko":"그도 같이 간다는 전제로 여행 계획을 세웠다."},{"jp":"雨[あめ]が降[ふ]らない前提[ぜんてい]で準備[じゅんび]するのは危[あぶ]ない。","ko":"비가 오지 않는다는 전제로 준비하는 것은 위험하다."},{"jp":"二人[ふたり]は結婚[けっこん]前提[ぜんてい]で付[つ]き合[あ]っている。","ko":"두 사람은 결혼을 전제로 사귀고 있다."}],"dr":[{"t":"make","q":"全員が参加する → ～前提で","a":"全員が参加する前提で","hint":"동사 보통형 + 前提で"},{"t":"make","q":"予算は増えない → ～前提で","a":"予算は増えない前提で","hint":"ない형도 보통형 그대로 + 前提で"},{"t":"fill","q":"全員[ぜんいん]が来[く]る（　）、料理[りょうり]を注文[ちゅうもん]した。","a":"前提で","opts":["前提で","ばかりに","どころか","限りに"]}],"src":[],"vf":0,"u":23,"g":1,"gp":"gg_N1_08"},{"id":"g1_113","t":"～限り(は)","ko":"~하는 한, ~인 이상은","cat":"접속·조건","conn":[{"w":"동사 사전형","f":"続ける + 限り"},{"w":"동사 ている형","f":"生きている + 限り"},{"w":"동사 ない형","f":"謝らない + 限り"},{"w":"い형용사","f":"若い + 限り"},{"w":"な형용사","f":"健康な / 健康である + 限り"},{"w":"명사","f":"学生である + 限り"}],"rule":["1. 2그룹 동사 生きる는 어미 る를 て로 바꿔 て형을 만든다: 生きる → 生きて.","2. いる를 붙여 상태를 나타내는 生きている로 만든다.","3. 그 뒤에 限り를 붙인다: 生きている限り. 강조하면 限りは.","4. 명사는 である를 넣어 学生である限り로 쓴다."],"why":"","nu":"앞의 조건이나 상태가 계속되는 동안은 뒤의 일도 계속 성립한다는 뜻이다. 뒤에는 의지, 판단, 계속되는 상태가 온다. ない限り는 '~하지 않는 한(~하지 않으면)'이 되어 조건을 강하게 나타낸다(謝らない限り許さない). 私の知る限り(내가 아는 한)처럼 범위를 나타내는 쓰임도 있다. 다소 딱딱한 표현이다.","cmp":[{"g":"～うちは","d":"'~하는 동안은'이라는 시간 범위가 중심이며 회화적이다. 限り는 '그 조건이 유지되는 한'이라는 조건의 의미가 강하다."}],"ex":[{"jp":"私[わたし]が生[い]きている限[かぎ]り、この店[みせ]は続[つづ]けます。","ko":"내가 살아 있는 한 이 가게는 계속하겠습니다."},{"jp":"練習[れんしゅう]を続[つづ]ける限[かぎ]り、必[かなら]ず上手[じょうず]になる。","ko":"연습을 계속하는 한 반드시 능숙해진다."},{"jp":"学生[がくせい]である限[かぎ]りは、勉強[べんきょう]が一番[いちばん]大事[だいじ]だ。","ko":"학생인 이상은 공부가 가장 중요하다."}],"dr":[{"t":"make","q":"住む → ～ている限り","a":"住んでいる限り","hint":"む → んで(ン음편) + いる + 限り"},{"t":"make","q":"子供 → ～である限り","a":"子供である限り","hint":"명사 + である + 限り"},{"t":"fill","q":"体[からだ]が元気[げんき]な（　）、仕事[しごと]を続[つづ]けたい。","a":"限り","opts":["限り","くせに","わりに","ものの"]}],"src":["https://bunpro.jp/grammar_points/限り"],"vf":1,"u":23,"g":1,"gp":"gg_N1_08"},{"id":"g1_125","t":"～たが最後","ko":"일단 ~했다 하면 (끝이다)","cat":"접속·조건","conn":[{"w":"2그룹 동사 た형","f":"始めた + が最後"},{"w":"1그룹 동사 た형","f":"読んだ + が最後"},{"w":"불규칙 する","f":"した + が最後"},{"w":"불규칙 来る","f":"来た + が最後"}],"rule":["1. 2그룹 동사는 어미 る를 た로 바꿔 た형을 만든다: 始める → 始めた.","2. 1그룹은 음편을 거친 た형을 쓴다: 読む → 読んだ.","3. た형 뒤에 が를 붙인다: 始めたが.","4. 最後를 붙인다: 始めたが最後."],"why":"","nu":"일단 그 일이 일어나면 그 뒤에는 반드시 (대개 곤란하거나 통제할 수 없는) 결과가 된다는 뜻이다. 뒤에는 やめられない, 二度と~ない처럼 피할 수 없는 결과가 오며 화자의 희망이나 의뢰는 오지 않는다. 문어적인 표현이고, 회화에서는 たら最後를 자주 쓴다.","cmp":[{"g":"～たら最後","d":"뜻은 같고 더 회화적이다."},{"g":"～たとたん(に)","d":"~한 순간 곧바로라는 시간 관계만 나타내며, '돌이킬 수 없다'는 뜻은 없다."}],"ex":[{"jp":"このゲームは始[はじ]めたが最後[さいご]、朝[あさ]までやめられない。","ko":"이 게임은 일단 시작했다 하면 아침까지 그만둘 수 없다."},{"jp":"父[ちち]は一度[いちど]話[はな]し始[はじ]めたが最後[さいご]、二時間[にじかん]は止[と]まらない。","ko":"아버지는 한번 말을 시작했다 하면 두 시간은 멈추지 않는다."},{"jp":"秘密[ひみつ]を話[はな]したが最後[さいご]、二度[にど]と信用[しんよう]されないだろう。","ko":"비밀을 말했다가는 두 번 다시 신용받지 못할 것이다."}],"dr":[{"t":"make","q":"寝る → ～たが最後","a":"寝たが最後","hint":"る → た + が最後"},{"t":"make","q":"飲む → ～たが最後","a":"飲んだが最後","hint":"む → んだ(음편) + が最後"},{"t":"fill","q":"あの店[みせ]のパンは一度[いちど]食[た]べた（　）、もう他[ほか]の店[みせ]では買[か]えなくなる。","a":"が最後","opts":["が最後","きり","ところで","ばかりに"]}],"src":["https://nihongokyoshi-net.com/?p=7167"],"vf":1,"u":23,"g":1,"gp":"gg_N1_08"},{"id":"g1_129","t":"～たら最後","ko":"일단 ~했다 하면 (끝장)","cat":"접속·조건","conn":[{"w":"동사 た형","f":"寝た + ら最後"},{"w":"する동사","f":"勉強した + ら最後"}],"rule":["1. 동사를 た형으로 바꾼다. 2그룹 동사는 어미 る를 た로 바꾼다: 寝る → 寝た.","2. た형 뒤에 조건의 ら를 붙인다: 寝たら.","3. 그 뒤에 最後를 붙인다: 寝たら最後.","4. 1그룹 동사는 음편을 거친다: 飲む → 飲んだら最後."],"why":"","nu":"어떤 일이 한번 일어나면 돌이킬 수 없는 상태가 반드시 이어진다는 뜻이다. 뒤에는 '멈추지 않는다, 일어나지 않는다, 돌아올 수 없다' 같은 부정적이거나 곤란한 결과가 온다. 비슷한 문어체 표현으로 ～たが最後가 있다. 좋은 결과를 기대하는 문장에는 쓰지 않는다.","cmp":[{"g":"～たが最後","d":"뜻은 거의 같고 더 문어적이다."},{"g":"～たら","d":"단순 조건이다. たら最後는 '그러면 끝장'이라는 강한 결과를 강조한다."}],"ex":[{"jp":"弟[おとうと]は寝[ね]たら最後[さいご]、朝[あさ]まで起[お]きない。","ko":"남동생은 일단 잠들면 아침까지 일어나지 않는다."},{"jp":"このゲームは始[はじ]めたら最後[さいご]、やめられなくなる。","ko":"이 게임은 일단 시작하면 그만둘 수 없게 된다."},{"jp":"彼[かれ]にお金[かね]を貸[か]したら最後[さいご]、二度[にど]と返[かえ]ってこない。","ko":"그에게 돈을 빌려주면 끝이다, 두 번 다시 돌아오지 않는다."}],"dr":[{"t":"make","q":"飲む → ～たら最後","a":"飲んだら最後","hint":"む → んだ(발음편), ら + 最後"},{"t":"make","q":"見る → ～たら最後","a":"見たら最後","hint":"る → た, ら + 最後"},{"t":"fill","q":"この本[ほん]は読[よ]み始[はじ]めたら（　）、止[と]まらない。","a":"最後","opts":["最後","最初","以来","次第"]}],"src":["https://nihongokyoshi-net.com/?p=7167"],"vf":1,"u":24,"g":1,"gp":"gg_N1_08"},{"id":"g1_145","t":"～もしないで","ko":"~하지도 않고","cat":"접속·조건","conn":[{"w":"동사 ます형","f":"読み + もしないで"},{"w":"する동사(명사+する)","f":"確認 + もしないで"},{"w":"2그룹 동사","f":"調べ + もしないで"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다: 読む → 読み.","2. 2그룹 동사는 る를 뺀다: 調べる → 調べ. する동사는 する 앞의 명사만 남긴다: 確認する → 確認.","3. 그 뒤에 강조의 조사 も와 しないで(する의 ない형 + で)를 붙인다: 読みもしないで."],"why":"동사 ます형 + 조사 も(~조차) + しないで(하지 않고). 동사를 명사처럼 세운 뒤 しない로 부정하고, も로 '그것조차'를 강조한 구조다.","nu":"당연히 해야 할 일을 하지도 않고 다음 행동을 했다는 비난·놀람이 담긴다. 회화와 글 모두에 쓴다. ろくに・よく와 자주 함께 온다. 사전형이 아니라 ます형에 붙는다는 점(×読むもしないで)에 주의한다.","cmp":[{"g":"～ないで","d":"단순히 '~하지 않고'. もしないで는 '~조차 하지 않고'라는 강조와 비난이 더해진다."},{"g":"～ずに","d":"ないで의 문어적 표현(読まずに). 강조의 뜻은 없다."}],"ex":[{"jp":"彼[かれ]は説明書[せつめいしょ]を読[よ]みもしないで、すぐに使[つか]い始[はじ]めた。","ko":"그는 설명서를 읽지도 않고 바로 쓰기 시작했다."},{"jp":"よく調[しら]べもしないで、高[たか]い買[か]い物[もの]をしてしまった。","ko":"잘 알아보지도 않고 비싼 물건을 사 버렸다."},{"jp":"ろくに練習[れんしゅう]もしないで、試合[しあい]に勝[か]てるはずがない。","ko":"제대로 연습도 하지 않고 시합에 이길 리가 없다."}],"dr":[{"t":"make","q":"見る → ～もしないで","a":"見もしないで","hint":"2그룹: る를 빼고 + もしないで"},{"t":"make","q":"確認する → ～もしないで","a":"確認もしないで","hint":"する동사: 명사 + もしないで"},{"t":"fill","q":"ろくに考[かんが]え（　）、すぐに返事[へんじ]をしてしまった。","a":"もしないで","opts":["もしないで","てから","ながら","たら"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/もしないで-mo-shinai-de-meaning/"],"vf":1,"u":24,"g":1,"gp":"gg_N1_08"},{"id":"g1_158","t":"～ことなしに","ko":"~하지 않고(는)","cat":"접속·조건","conn":[{"w":"동사 사전형","f":"努力する + ことなしに"},{"w":"동사 사전형","f":"知る + ことなしに"}],"rule":["1. 동사는 사전형을 그대로 쓴다: 努力する.","2. 사전형 뒤에 명사화의 こと를 붙인다: 努力すること.","3. 그 뒤에 なしに를 붙인다: 努力することなしに."],"why":"こと(일) + なし(無し, 없음) + に. '~하는 일 없이'라는 구성이다.","nu":"'~하지 않고(는)'이라는 뜻의 딱딱한 문어 표현이다. 뒤에 부정이나 불가능(～できない, ～ない)이 와서 '~하지 않고는 ~할 수 없다'는 조건을 나타내는 경우가 많다. 일상 회화에서는 ～しないで, ～せずに를 쓴다.","cmp":[{"g":"～ことなく","d":"'~하는 일 없이'로 뜻이 가깝다. 뒤에 부정이 오지 않는 단순 서술(休むことなく働いた)에 많이 쓴다."},{"g":"～ずに / ～ないで","d":"같은 뜻의 일반적인 표현."}],"ex":[{"jp":"努力[どりょく]することなしに、夢[ゆめ]をかなえることはできない。","ko":"노력하지 않고는 꿈을 이룰 수 없다."},{"jp":"失敗[しっぱい]を経験[けいけん]することなしに、本当[ほんとう]の成長[せいちょう]はない。","ko":"실패를 경험하지 않고는 진정한 성장은 없다."},{"jp":"彼[かれ]は誰[だれ]にも相談[そうだん]することなしに、会社[かいしゃ]を辞[や]めた。","ko":"그는 누구와도 상담하지 않고 회사를 그만두었다."}],"dr":[{"t":"make","q":"学ぶ → ～ことなしに","a":"学ぶことなしに","hint":"사전형 + こと + なしに"},{"t":"make","q":"確認します → ～ことなしに","a":"確認することなしに","hint":"ます형을 사전형으로(し → する) + ことなしに"},{"t":"fill","q":"練習[れんしゅう]を重[かさ]ねる（　）、上達[じょうたつ]はありえない。","a":"ことなしに","opts":["ことなしに","ことにして","ことから","ことだから"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ことなしに-koto-nashi-ni-meaning/"],"vf":1,"u":24,"g":1,"gp":"gg_N1_08"},{"id":"g1_186","t":"～だろうとなかろうと","ko":"~이든 아니든","cat":"접속·조건","conn":[{"w":"명사","f":"雨 + だろうとなかろうと"},{"w":"명사","f":"学生 + だろうとなかろうと"},{"w":"な형용사","f":"好き + だろうとなかろうと"}],"rule":["1. 명사(또는 な형용사 어간)를 놓는다: 雨.","2. だ의 추량형 だろう에 と를 붙여 잇는다: 雨だろうと.","3. 이어서 ない의 추량형 なかろう에 と를 붙인다: 雨だろうとなかろうと."],"why":"だろう(だ의 추량형) + と와 なかろう(ない의 추량형) + と를 나란히 놓아 '~이든 ~이 아니든'을 나타낸 형태이다.","nu":"어느 쪽이든 뒤의 결과·결심은 변하지 않는다는 뜻으로, 뒤에는 말하는 사람의 의지나 판단이 온다. 다소 딱딱한 표현이며, 더 문어적으로는 であろうとなかろうと를 쓴다. 동사나 い형용사에는 이 형태를 쓰지 않고 行こうと行くまいと, 高かろうと安かろうと 같은 다른 형태를 쓴다.","cmp":[{"g":"～にかかわらず","d":"'~에 관계없이'. 晴雨にかかわらず처럼 명사에 바로 붙고, 대립하는 두 가지를 반복하지 않아도 된다."},{"g":"～(よ)うと～まいと","d":"동사에 쓰는 같은 뜻의 형태(行こうと行くまいと)."}],"ex":[{"jp":"雨[あめ]だろうとなかろうと、試合[しあい]は予定通[よていどお]り行[おこな]う。","ko":"비가 오든 안 오든 시합은 예정대로 한다."},{"jp":"学生[がくせい]だろうとなかろうと、料金[りょうきん]は同[おな]じです。","ko":"학생이든 아니든 요금은 같습니다."},{"jp":"好[す]きだろうとなかろうと、この仕事[しごと]は最後[さいご]までやるしかない。","ko":"좋든 싫든 이 일은 끝까지 할 수밖에 없다."}],"dr":[{"t":"make","q":"本当 → ～だろうとなかろうと","a":"本当だろうとなかろうと","hint":"명사 + だろうと + なかろうと"},{"t":"make","q":"日本人 → ～だろうとなかろうと","a":"日本人だろうとなかろうと","hint":"명사 + だろうとなかろうと"},{"t":"fill","q":"会員[かいいん]（　）、誰[だれ]でも参加[さんか]できます。","a":"だろうとなかろうと","opts":["だろうとなかろうと","であるがゆえに","ともなると","ならではの"]}],"src":[],"vf":0,"u":24,"g":1,"gp":"gg_N1_09"},{"id":"g1_191","t":"～とあれば","ko":"~라면 (특별한 경우라면)","cat":"접속·조건","conn":[{"w":"명사","f":"子どものため + とあれば"},{"w":"동사 보통형","f":"社長が来る + とあれば"},{"w":"い형용사","f":"そんなに安い + とあれば"}],"rule":["1. 특별한 조건이 되는 명사나 보통형을 둔다: 子どものため.","2. 그 뒤에 とあれば를 붙인다: 子どものためとあれば.","3. 뒤에는 '그런 경우라면 ~하겠다/~할 수 있다'는 의지·판단을 쓴다."],"why":"","nu":"'다른 경우라면 몰라도 ~라는 특별한 사정이라면' 하고 그 조건을 강조한다. 뒤에 말하는 사람의 각오·의지(どんなことでもする, 行くしかない)가 자주 온다. 딱딱한 표현이며, 명사에는 보통 だ를 붙이지 않는다.","cmp":[{"g":"～なら","d":"일반적인 조건 표현. とあれば는 '그 특별한 사정이라면 기꺼이'라는 강조가 있다."},{"g":"～とあって","d":"이미 일어난 상황의 원인을 묘사한다. とあれば는 가정 조건이다."}],"ex":[{"jp":"子[こ]どものためとあれば、どんなことでもする。","ko":"아이를 위해서라면 무슨 일이든 한다."},{"jp":"社長[しゃちょう]の命令[めいれい]とあれば、従[したが]うしかない。","ko":"사장의 명령이라면 따를 수밖에 없다."},{"jp":"君[きみ]が困[こま]っているとあれば、すぐに手伝[てつだ]いに行[い]くよ。","ko":"네가 곤란하다면 바로 도우러 갈게."}],"dr":[{"t":"make","q":"家族のため → ～とあれば","a":"家族のためとあれば","hint":"명사 + とあれば"},{"t":"make","q":"先生が言う → ～とあれば","a":"先生が言うとあれば","hint":"동사 보통형 + とあれば"},{"t":"fill","q":"お客様[きゃくさま]の頼[たの]み（　）、断[ことわ]るわけにはいかない。","a":"とあれば","opts":["とあれば","とあって","ときたら","といったら"]}],"src":["https://bunpro.jp/grammar_points/とあれば","https://jlptsensei.com/learn-japanese-grammar/とあれば-to-areba-meaning/"],"vf":1,"u":25,"g":1,"gp":"gg_N1_09"},{"id":"g1_200","t":"～とすると","ko":"~라고 하면, ~라고 가정하면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"来る + とすると"},{"w":"い형용사","f":"遠い + とすると"},{"w":"な형용사","f":"必要だ + とすると"},{"w":"명사","f":"本当だ + とすると"}],"rule":["1. 명사·な형용사에는 だ를 붙인다: 本当 → 本当だ (동사·い형용사는 보통형 그대로).","2. 가정의 と + する를 붙인다: 本当だとする.","3. 끝에 조건의 と를 붙인다: 本当だとすると."],"why":"'~라고 가정하다'라는 ～とする에 조건의 と가 붙은 형태다.","nu":"어떤 일을 가정하거나, 들은 정보·주어진 조건을 사실로 놓고 '그렇다면 ~이다'라고 추론할 때 쓴다. 뒤에는 추측·판단(はずだ, だろう, ことになる 등)이 자주 온다. 의지형 + とすると(行こうとすると)는 '~하려고 하면'이라는 다른 표현이므로 혼동하지 않는다.","cmp":[{"g":"～とすれば","d":"뜻은 거의 같다. とすれば는 뒤에 화자의 판단·제안이 오기 쉽고, とすると는 자연스럽게 뒤따르는 결과를 말할 때 많이 쓰인다."},{"g":"～となると","d":"상황이 실제로 그렇게 될 때의 결과를 말한다. とすると는 순수한 가정이나 추론에 무게가 있다."}],"ex":[{"jp":"その話[はなし]が本当[ほんとう]だとすると、大変[たいへん]なことになる。","ko":"그 이야기가 사실이라고 하면 큰일이 난다."},{"jp":"毎日[まいにち]2時間[じかん]勉強[べんきょう]するとすると、1か月[げつ]で60時間[じかん]になる。","ko":"매일 2시간 공부한다고 하면 한 달에 60시간이 된다."},{"jp":"駅[えき]から遠[とお]いとすると、自転車[じてんしゃ]が必要[ひつよう]だろう。","ko":"역에서 멀다고 하면 자전거가 필요하겠지."}],"dr":[{"t":"make","q":"雨 → ～とすると","a":"雨だとすると","hint":"명사 + だ + とする + と"},{"t":"make","q":"高い → ～とすると","a":"高いとすると","hint":"い형용사는 그대로 + とすると"},{"t":"fill","q":"彼[かれ]が犯人[はんにん]だ（　）、動機[どうき]は何[なん]だろう。","a":"とすると","opts":["とすると","にしては","くせに","どころか"]}],"src":["https://bunpro.jp/ja/grammar_points/251"],"vf":1,"u":25,"g":1,"gp":"gg_N1_09"},{"id":"g1_201","t":"～とすれば","ko":"~라고 한다면, ~라고 가정하면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"行く + とすれば / 当たった + とすれば"},{"w":"い형용사","f":"高い + とすれば"},{"w":"な형용사","f":"無理だ + とすれば"},{"w":"명사","f":"彼だ + とすれば"}],"rule":["1. 명사·な형용사에는 だ를 붙인다: 彼 → 彼だ (동사·い형용사는 보통형 그대로).","2. 가정의 と + する를 붙인다: 彼だとする.","3. する를 가정형 すれ로 바꾸고 ば를 붙인다: 彼だとすれば."],"why":"'~라고 가정하다'라는 ～とする를 ば 조건형(すれば)으로 만든 형태다.","nu":"어떤 일을 가정하거나 주어진 사실을 근거로 '그렇다면'이라고 판단할 때 쓴다. 뒤에는 화자의 판단·추측·제안·질문이 잘 온다. 문장 첫머리에서 とすれば、… 처럼 접속사로도 쓴다. 약간 딱딱한 말투다.","cmp":[{"g":"～とすると","d":"뜻은 거의 같다. とすると는 자연스러운 결과·추론, とすれば는 화자의 판단이나 제안이 뒤에 오기 쉽다."},{"g":"～なら","d":"상대가 말한 것을 받아 조언할 때 가장 일반적인 표현. とすれば는 '가정'이라는 느낌이 더 분명하다."}],"ex":[{"jp":"犯人[はんにん]が彼[かれ]だとすれば、すべて説明[せつめい]がつく。","ko":"범인이 그라고 한다면 모든 게 설명된다."},{"jp":"明日[あした]行[い]くとすれば、朝[あさ]早[はや]く出[で]たほうがいい。","ko":"내일 간다고 하면 아침 일찍 나가는 게 좋다."},{"jp":"宝[たから]くじが当[あ]たったとすれば、何[なに]に使[つか]いますか。","ko":"복권에 당첨되었다고 한다면 무엇에 쓰겠습니까?"}],"dr":[{"t":"make","q":"本当 → ～とすれば","a":"本当だとすれば","hint":"명사 + だ + と + すれば(する의 가정형)"},{"t":"make","q":"留学する → ～とすれば","a":"留学するとすれば","hint":"동사 보통형 + とすれば"},{"t":"fill","q":"この話[はなし]が事実[じじつ]だ（　）、会社[かいしゃ]は大変[たいへん]なことになる。","a":"とすれば","opts":["とすれば","ものの","からには","ばかりか"]}],"src":["https://bunpro.jp/ja/grammar_points/251"],"vf":1,"u":25,"g":1,"gp":"gg_N1_09"},{"id":"g1_202","t":"～となったら","ko":"~하게 되면, ~라는 상황이 되면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"行く + となったら"},{"w":"명사","f":"一人暮らし + となったら"}],"rule":["1. 동사는 보통형 그대로, 명사는 그대로 둔다: 行く.","2. と + なる를 붙인다: 行くとなる.","3. なる의 어미 る를 っ으로 바꾸고(촉음편) たら를 붙인다: 行くとなったら."],"why":"'~라는 상태가 되다'라는 ～となる의 たら 조건형이다.","nu":"어떤 일이 정해지거나 실제로 그런 상황이 되었을 때를 가정하고, 그때 해야 할 일·각오·당연한 결과를 말한다. 회화에서 자주 쓰인다. やるとなったら(하기로 했으면) 처럼 강한 결심을 나타낼 때가 많다. いざとなったら(막상 그때가 되면)는 굳은 관용구다.","cmp":[{"g":"～となると","d":"뜻이 거의 같으나 となると는 객관적인 결과 서술에 쓰이기 쉽고, となったら는 회화적이며 뒤에 의지·명령도 자연스럽다."},{"g":"～たら","d":"단순한 조건. となったら는 '그런 사태가 되면'이라는 상황 변화와 각오가 강조된다."}],"ex":[{"jp":"やるとなったら、最後[さいご]まで頑張[がんば]ろう。","ko":"하기로 했으면 끝까지 열심히 하자."},{"jp":"留学[りゅうがく]するとなったら、お金[かね]をためなければならない。","ko":"유학하게 되면 돈을 모아야 한다."},{"jp":"一人暮[ひとりぐ]らしとなったら、料理[りょうり]も自分[じぶん]でしなくてはならない。","ko":"혼자 살게 되면 요리도 스스로 해야 한다."}],"dr":[{"t":"make","q":"結婚する → ～となったら","a":"結婚するとなったら","hint":"보통형 + と + なったら(なる → なっ + たら)"},{"t":"make","q":"引っ越す → ～となったら","a":"引っ越すとなったら","hint":"동사 보통형 + となったら"},{"t":"fill","q":"会社[かいしゃ]を辞[や]める（　）、家族[かぞく]に相談[そうだん]しなければ。","a":"となったら","opts":["となったら","にしては","ものの","わりに"]}],"src":["https://nihongokyoshi-net.com/2019/05/29/jlptn2-grammar-tonaruto/","https://jlptsensei.com/learn-japanese-grammar/となると-となれば-となったら-to-naru-to-nareba-meaning/"],"vf":1,"u":25,"g":1,"gp":"gg_N1_09"},{"id":"g1_203","t":"～となると","ko":"~하게 되면, ~라고 하면, ~에 관해서라면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"住む + となると"},{"w":"명사","f":"料理 + となると / 明日 + となると"}],"rule":["1. 앞말은 동사 보통형 또는 명사 그대로 둔다: 料理.","2. と + なる를 붙인다: 料理となる.","3. 끝에 조건의 と를 붙인다: 料理となると."],"why":"'~라는 상태가 되다'라는 ～となる에 조건의 と가 붙은 형태다.","nu":"① 어떤 상황이 되면(그렇다고 하면) 당연히 따르는 결과를 말한다(東京に住むとなると、家賃が高い). ② 명사 + となると로 '~에 관한 일이라면 (평소와 달리)'라는 화제 제시로도 쓴다(料理となると真剣になる). 뒤에는 객관적 판단이나 사실이 자주 온다.","cmp":[{"g":"～となれば","d":"뜻이 거의 같으나 となれば는 뒤에 화자의 의지·판단이 오기 쉽다."},{"g":"～とすると","d":"순수한 가정·추론. となると는 실제로 그 상황이 되는 일을 전제로 한다."}],"ex":[{"jp":"東京[とうきょう]に住[す]むとなると、家賃[やちん]がかなり高[たか]くなる。","ko":"도쿄에 살게 되면 집세가 꽤 비싸진다."},{"jp":"試験[しけん]が明日[あした]となると、今夜[こんや]は寝[ね]られない。","ko":"시험이 내일이라고 하면 오늘 밤은 잘 수 없다."},{"jp":"父[ちち]は料理[りょうり]となると、誰[だれ]よりも真剣[しんけん]になる。","ko":"아버지는 요리에 관해서라면 누구보다 진지해진다."}],"dr":[{"t":"make","q":"一人で行く → ～となると","a":"一人で行くとなると","hint":"동사 보통형 + と + なる + と"},{"t":"make","q":"野球 → ～となると","a":"野球となると","hint":"명사 + となると"},{"t":"fill","q":"彼[かれ]は普段[ふだん]静[しず]かだが、サッカーの話[はなし]（　）、急[きゅう]によく話[はな]す。","a":"となると","opts":["となると","によって","にとって","として"]}],"src":["https://nihongokyoshi-net.com/2019/05/29/jlptn2-grammar-tonaruto/","https://jlptsensei.com/learn-japanese-grammar/となると-となれば-となったら-to-naru-to-nareba-meaning/"],"vf":1,"u":25,"g":1,"gp":"gg_N1_09"},{"id":"g1_204","t":"～となれば","ko":"~하게 되면, ~라고 하면","cat":"접속·조건","conn":[{"w":"동사 보통형","f":"来る + となれば"},{"w":"명사","f":"雨 + となれば"}],"rule":["1. 앞말은 동사 보통형 또는 명사 그대로 둔다: 雨.","2. と + なる를 붙인다: 雨となる.","3. なる를 가정형 なれ로 바꾸고 ば를 붙인다: 雨となれば."],"why":"'~라는 상태가 되다'라는 ～となる의 ば 조건형이다.","nu":"그런 상황이 된다면 당연히 이렇게 된다·이렇게 해야 한다는 판단을 말한다. 뒤에는 화자의 판단·의지·의무(なければならない, しよう 등)가 자주 온다. 회화와 문장 모두에서 쓰인다.","cmp":[{"g":"～となると","d":"뜻은 거의 같다. となると는 객관적 결과, となれば는 화자의 판단·결심이 뒤에 오기 쉽다."},{"g":"～ば","d":"단순한 가정 조건. となれば는 '그런 사태가 되면'이라는 상황 변화가 강조된다."}],"ex":[{"jp":"雨[あめ]となれば、試合[しあい]は中止[ちゅうし]だ。","ko":"비가 오게 되면 경기는 중지다."},{"jp":"社長[しゃちょう]が来[く]るとなれば、掃除[そうじ]しないわけにはいかない。","ko":"사장님이 오신다고 하면 청소하지 않을 수 없다."},{"jp":"海外[かいがい]に行[い]くとなれば、パスポートを用意[ようい]しなければならない。","ko":"해외에 가게 되면 여권을 준비해야 한다."}],"dr":[{"t":"make","q":"引っ越す → ～となれば","a":"引っ越すとなれば","hint":"보통형 + と + なれば(なる의 가정형 なれ + ば)"},{"t":"make","q":"本番 → ～となれば","a":"本番となれば","hint":"명사 + となれば"},{"t":"fill","q":"お客[きゃく]さんが来[く]る（　）、部屋[へや]を片付[かたづ]けなければ。","a":"となれば","opts":["となれば","くせに","ばかりに","にもかかわらず"]}],"src":["https://nihongokyoshi-net.com/2019/05/29/jlptn2-grammar-tonaruto/","https://jlptsensei.com/learn-japanese-grammar/となると-となれば-となったら-to-naru-to-nareba-meaning/"],"vf":1,"u":26,"g":1,"gp":"gg_N1_09"},{"id":"g1_001","t":"～うが～うが","ko":"~하든 ~하든 (관계없이)","cat":"역접","conn":[{"w":"동사 의지형","f":"降ろう + が / 降る + まい + が"},{"w":"い형용사","f":"高かろう + が"},{"w":"な형용사","f":"静かだろう + が / 静かであろう + が"},{"w":"명사","f":"学生だろう + が / 学生であろう + が"}],"rule":["1. い형용사는 어미 い를 かろう로 바꾼다. 高い → 高かろう.","2. 동사는 의지형으로 바꾼다. 1그룹은 어미 う단을 お단+う로(降る → 降ろう), 2그룹은 る를 빼고 よう(食べる → 食べよう), する → しよう, 来る → 来よう.","3. 그 뒤에 が를 붙이고, 같은 꼴을 하나 더(반대말이나 ～まい) 이어 쓴다. 高かろうが安かろうが / 降ろうが降るまいが.","4. 명사·な형용사는 だろう 또는 であろう를 붙인 뒤 が를 붙인다."],"why":"","nu":"앞의 두 경우 중 어느 쪽이든 뒤의 결과나 의지는 변하지 않는다는 뜻. 문어적이고 딱딱한 표현이며 회화에서는 ～ても～ても를 많이 쓴다. 뒤에는 '상관없다・변하지 않는다・반드시 한다' 같은 내용이 온다. 한국어 '-든'에 끌려 ～が를 한 번만 쓰지 않도록 주의(두 번 반복이 기본).","cmp":[{"g":"～うと～うと","d":"의미와 접속이 거의 같고 が 대신 と를 쓴다. 바꿔 써도 대부분 자연스럽다."},{"g":"～ても～ても","d":"같은 뜻의 일반적인 표현으로 회화체."}],"ex":[{"jp":"高[たか]かろうが安[やす]かろうが、必要[ひつよう]なものは買[か]う。","ko":"비싸든 싸든 필요한 것은 산다."},{"jp":"雨[あめ]が降[ふ]ろうが降[ふ]るまいが、試合[しあい]は行[おこな]われる。","ko":"비가 오든 안 오든 시합은 열린다."},{"jp":"子供[こども]だろうが大人[おとな]だろうが、ルールは守[まも]らなければならない。","ko":"아이든 어른이든 규칙은 지켜야 한다."}],"dr":[{"t":"make","q":"高い・安い → ～うが～うが","a":"高かろうが安かろうが","hint":"い형용사는 い를 かろう로 바꾸고 が"},{"t":"make","q":"行く・行く(부정) → ～うが～まいが","a":"行こうが行くまいが","hint":"1그룹 く → こう(의지형) + が, 사전형 + まい + が"},{"t":"fill","q":"誰[だれ]が反対[はんたい]しよう（　）、私[わたし]は計画[けいかく]を進[すす]める。","a":"が","opts":["が","から","ので","なら"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ようが～ようが-ようと～ようと-you-ga-you-to-meaning","https://bunpro.jp/ja/grammar_points/-%E3%82%88%E3%81%86--%E3%81%86-%E3%81%BE%E3%81%84-%E3%81%8C-%E3%81%A8"],"vf":1,"u":26,"g":1,"gp":"gg_N1_09"},{"id":"g1_002","t":"～うと～うと","ko":"~하든 ~하든 (관계없이)","cat":"역접","conn":[{"w":"동사 의지형","f":"晴れよう + と / 降ろう + と"},{"w":"い형용사","f":"難しかろう + と"},{"w":"な형용사","f":"便利だろう + と / 便利であろう + と"},{"w":"명사","f":"学生だろう + と / 学生であろう + と"}],"rule":["1. 2그룹 동사는 어미 る를 빼고 よう를 붙인다. 晴れる → 晴れよう.","2. 1그룹 동사는 어미 う단을 お단+う로 바꾼다(降る → 降ろう). する → しよう, 来る → 来よう.","3. い형용사는 い를 かろう로 바꾼다(難しい → 難しかろう). 명사·な형용사는 だろう/であろう를 붙인다.","4. 그 뒤에 と를 붙이고, 짝이 되는 말을 같은 꼴로 한 번 더 이어 쓴다. 降ろうと晴れようと."],"why":"","nu":"두 경우 중 어느 쪽이 되어도 뒤 내용은 변하지 않는다는 뜻. 문어적이고 딱딱하다. 회화에서는 ～ても～ても가 자연스럽다. 뒤에는 '상관없다・자유다・반드시 한다' 같은 말이 온다. ～ようと～まいと(하든 안 하든)의 형태도 자주 쓴다.","cmp":[{"g":"～うが～うが","d":"의미·접속이 거의 같고 と 대신 が를 쓴다."},{"g":"～であれ～であれ","d":"명사를 두 개 늘어놓는 데 주로 쓰고, 동사 의지형은 쓰지 않는다."}],"ex":[{"jp":"雨[あめ]が降[ふ]ろうと晴[は]れようと、毎朝[まいあさ]ジョギングをする。","ko":"비가 오든 날이 개든 매일 아침 조깅을 한다."},{"jp":"仕事[しごと]が難[むずか]しかろうと易[やさ]しかろうと、最後[さいご]までやるつもりだ。","ko":"일이 어렵든 쉽든 끝까지 할 생각이다."},{"jp":"君[きみ]が行[い]こうと行[い]くまいと、僕[ぼく]は行[い]く。","ko":"네가 가든 안 가든 나는 간다."}],"dr":[{"t":"make","q":"晴れる・降る → ～うと～うと","a":"晴れようと降ろうと","hint":"2그룹 る → よう, 1그룹 る → ろう, 각각 + と"},{"t":"make","q":"寒い・暑い → ～うと～うと","a":"寒かろうと暑かろうと","hint":"い형용사는 い를 かろう로 바꾸고 と"},{"t":"fill","q":"人[ひと]に何[なに]を言[い]われよう（　）、気[き]にしない。","a":"と","opts":["と","に","で","へ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ようが～ようが-ようと～ようと-you-ga-you-to-meaning","https://bunpro.jp/ja/grammar_points/-%E3%82%88%E3%81%86--%E3%81%86-%E3%81%BE%E3%81%84-%E3%81%8C-%E3%81%A8"],"vf":1,"u":26,"g":1,"gp":"gg_N1_09"},{"id":"g1_006","t":"～であれ～であれ","ko":"~든 ~든, ~이든 ~이든","cat":"역접","conn":[{"w":"명사","f":"雨 + であれ"},{"w":"な형용사","f":"好き + であれ"},{"w":"의문사","f":"何 + であれ / 誰 + であれ"}],"rule":["1. 명사 뒤에 であれ를 붙인다. 雨 → 雨であれ.","2. 짝이 되는 명사에도 であれ를 붙여 이어 쓴다. 雨であれ雪であれ.","3. な형용사는 어간에 바로 であれ를 붙인다(好きであれ嫌いであれ)."],"why":"で(だ의 연용형)에 ある의 명령형 あれ가 붙은 꼴이다.","nu":"A든 B든 어느 경우에도 뒤 내용이 똑같이 성립한다는 뜻. 문어적이고 딱딱하다. 회화에서는 ～でも～でも를 쓴다. 何であれ(무엇이든), 誰であれ(누구든)처럼 의문사와 한 번만 쓰는 꼴도 많다.","cmp":[{"g":"～にしろ～にしろ","d":"뜻은 비슷하나 にしろ는 동사・형용사 보통형에도 자유롭게 붙고 조금 더 회화적이다."}],"ex":[{"jp":"雨[あめ]であれ雪[ゆき]であれ、試合[しあい]は予定[よてい]どおり行[おこな]う。","ko":"비든 눈이든 시합은 예정대로 진행한다."},{"jp":"子供[こども]であれ大人[おとな]であれ、ルールは同[おな]じだ。","ko":"아이든 어른이든 규칙은 같다."},{"jp":"理由[りゆう]は何[なん]であれ、遅刻[ちこく]はよくない。","ko":"이유가 무엇이든 지각은 좋지 않다."}],"dr":[{"t":"make","q":"男・女 → ～であれ～であれ","a":"男であれ女であれ","hint":"명사 + であれ를 두 번"},{"t":"make","q":"好きだ・嫌いだ → ～であれ～であれ","a":"好きであれ嫌いであれ","hint":"な형용사 어간 + であれ"},{"t":"fill","q":"相手[あいて]が誰（　）、失礼[しつれい]な態度[たいど]はいけない。","a":"であれ","opts":["であれ","ばかりか","どころか","ながら"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%A7%E3%81%82%E3%82%8C-%E3%81%A7%E3%81%82%E3%82%8C"],"vf":1,"u":26,"g":1,"gp":"gg_N1_09"},{"id":"g1_009","t":"～にしろ～にしろ","ko":"~하든 ~하든, ~이든 ~이든","cat":"역접","conn":[{"w":"동사 보통형","f":"行く + にしろ / 行かない + にしろ"},{"w":"い형용사","f":"暑い + にしろ"},{"w":"な형용사","f":"好き + にしろ"},{"w":"명사","f":"ビール + にしろ"}],"rule":["1. 첫 번째 말(보통형) 뒤에 にしろ를 붙인다. 行く → 行くにしろ.","2. 짝이 되는 두 번째 말(반대말이나 부정형)에도 にしろ를 붙인다. 行かない → 行かないにしろ.","3. 명사·な형용사는 어간에 바로 にしろ를 붙인다(ビールにしろ, 好きにしろ)."],"why":"","nu":"A의 경우든 B의 경우든 뒤의 판단은 똑같다는 뜻. 뒤에는 말하는 사람의 판단·요구·의지가 많이 온다. 회화와 글 모두에 쓰며, 같은 뜻의 にせよ보다 조금 덜 딱딱하다. 앞에는 대립하거나 같은 종류의 두 말이 온다.","cmp":[{"g":"～にせよ～にせよ","d":"뜻과 접속이 같고 조금 더 문어적·격식적이다."},{"g":"～であれ～であれ","d":"주로 명사에 쓰는 문어 표현. にしろ는 동사·형용사에도 자유롭게 붙는다."}],"ex":[{"jp":"行[い]くにしろ行[い]かないにしろ、早[はや]めに連絡[れんらく]してください。","ko":"가든 안 가든 일찍 연락해 주세요."},{"jp":"ビールにしろワインにしろ、飲[の]みすぎは体[からだ]に悪[わる]い。","ko":"맥주든 와인이든 과음은 몸에 나쁘다."},{"jp":"好[す]きにしろ嫌[きら]いにしろ、この仕事[しごと]は誰[だれ]かがやらなければならない。","ko":"좋든 싫든 이 일은 누군가 해야 한다."}],"dr":[{"t":"make","q":"買う・買わない → ～にしろ～にしろ","a":"買うにしろ買わないにしろ","hint":"보통형 + にしろ를 두 번"},{"t":"make","q":"大人・子供 → ～にしろ～にしろ","a":"大人にしろ子供にしろ","hint":"명사 + にしろ를 두 번"},{"t":"fill","q":"電車[でんしゃ]（　）バス（　）、時間[じかん]はあまり変[か]わらない。","a":"にしろ","opts":["にしろ","にとって","につれて","にかけて"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%97%E3%82%8D-%E3%81%AB%E3%81%97%E3%82%8D"],"vf":1,"u":27,"g":1,"gp":"gg_N1_09"},{"id":"g1_010","t":"～にせよ～にせよ","ko":"~하든 ~하든, ~이든 ~이든","cat":"역접","conn":[{"w":"동사 보통형","f":"参加する + にせよ / しない + にせよ"},{"w":"い형용사","f":"大きい + にせよ"},{"w":"な형용사","f":"便利 + にせよ"},{"w":"명사","f":"賛成 + にせよ"}],"rule":["1. 명사 뒤에 にせよ를 붙인다. 賛成 → 賛成にせよ.","2. 짝이 되는 명사에도 にせよ를 붙여 이어 쓴다. 賛成にせよ反対にせよ.","3. 동사·い형용사는 보통형에, な형용사는 어간에 にせよ를 붙인다."],"why":"","nu":"A든 B든 뒤의 판단·요구는 변하지 않는다는 뜻. にしろ와 뜻이 같지만 더 문어적·격식적이라 글이나 공적인 자리에서 많이 쓴다. 뒤에는 말하는 사람의 판단, 의무, 의뢰가 자주 온다.","cmp":[{"g":"～にしろ～にしろ","d":"같은 뜻이고 조금 더 회화적이다."},{"g":"～にしても～にしても","d":"같은 뜻이지만 어감이 더 부드럽다. にせよ는 더 강하고 딱딱한 느낌이다."}],"ex":[{"jp":"賛成[さんせい]にせよ反対[はんたい]にせよ、理由[りゆう]を書[か]いてください。","ko":"찬성이든 반대든 이유를 써 주세요."},{"jp":"参加[さんか]するにせよしないにせよ、今日中[きょうじゅう]に返事[へんじ]をください。","ko":"참가하든 안 하든 오늘 중으로 답을 주세요."},{"jp":"大[おお]きいにせよ小[ちい]さいにせよ、ミスはミスだ。","ko":"크든 작든 실수는 실수다."}],"dr":[{"t":"make","q":"晴れ・雨 → ～にせよ～にせよ","a":"晴れにせよ雨にせよ","hint":"명사 + にせよ를 두 번"},{"t":"make","q":"勝つ・負ける → ～にせよ～にせよ","a":"勝つにせよ負けるにせよ","hint":"동사 보통형 + にせよ를 두 번"},{"t":"fill","q":"進学[しんがく]する（　）就職[しゅうしょく]する（　）、自分[じぶん]で決[き]めなさい。","a":"にせよ","opts":["にせよ","にあたって","に際して","に先立って"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%9B%E3%82%88-%E3%81%AB%E3%81%97%E3%82%8D","https://bunpro.jp/grammar_points/%E3%81%AB%E3%81%97%E3%82%8D-%E3%81%AB%E3%81%97%E3%82%8D"],"vf":1,"u":27,"g":1,"gp":"gg_N1_09"},{"id":"g1_023","t":"～こそあれ","ko":"~은 있을지언정, ~은 있어도","cat":"역접","conn":[{"w":"명사","f":"程度の差 + こそあれ"},{"w":"명사 (～こそあれ、～はない)","f":"感謝 + こそあれ"}],"rule":["1. 명사 뒤에 강조의 こそ를 붙인다(差こそ).","2. ある를 고전 문법의 已然形 あれ로 바꿔 붙인다(差こそあれ = 차이는 있지만).","3. 뒤에는 앞과 반대되는 내용이 온다. 'XこそあれYはない' 형태는 'X는 있어도 Y는 없다'는 뜻이 된다."],"why":"고전 문법의 계결(係り結び): こそ가 오면 문장 끝이 已然形이 되므로 ある(고어 あり)의 已然形 あれ가 왔다. 명령형 あれ가 아니다.","nu":"딱딱한 문어체. 대부분 程度の差こそあれ・大小の差こそあれ 같은 관용구나 感謝こそあれ、不満はない 형태로 쓴다. 명령형 'あれ(있어라)'로 해석하는 실수에 주의.","cmp":[{"g":"～こそすれ","d":"동사 ます형이나 する 동사 명사에 붙어 'X하면 했지 Y는 하지 않는다'. こそあれ는 명사 + ある 계열."},{"g":"～はあっても","d":"같은 뜻의 일반적인 표현. こそあれ가 더 문어적이고 강조가 강하다."}],"ex":[{"jp":"程度[ていど]の差[さ]こそあれ、誰[だれ]にでも悩[なや]みはある。","ko":"정도의 차이는 있을지언정 누구에게나 고민은 있다."},{"jp":"大小[だいしょう]の違[ちが]いこそあれ、どの会社[かいしゃ]も同[おな]じ問題[もんだい]を抱[かか]えている。","ko":"크고 작은 차이는 있어도 어느 회사나 같은 문제를 안고 있다."},{"jp":"彼[かれ]には感謝[かんしゃ]こそあれ、恨[うら]みなど少[すこ]しもない。","ko":"그에게는 감사하는 마음은 있어도 원망 따위는 조금도 없다."}],"dr":[{"t":"make","q":"程度の差がある（～が）→ こそあれ","a":"程度の差こそあれ","hint":"명사 + こそ + ある의 已然形 あれ"},{"t":"make","q":"感謝はあるが、不満はない → こそあれ","a":"感謝こそあれ、不満はない","hint":"は 대신 こそ, ある를 あれ로"},{"t":"fill","q":"大小[だいしょう]の差[さ]（　）、失敗[しっぱい]しない人[ひと]はいない。","a":"こそあれ","opts":["こそあれ","ばかりか","どころか","さえ"]}],"src":["https://bunpro.jp/grammar_points/991"],"vf":1,"u":27,"g":1,"gp":"gg_N1_10"},{"id":"g1_024","t":"～こそ～が","ko":"~은 분명 …지만","cat":"역접","conn":[{"w":"명사","f":"体 + こそ + 小さいが"},{"w":"명사","f":"給料 + こそ + 安いが"}],"rule":["1. 인정하는 부분의 명사 뒤의 は를 こそ로 바꾼다(体は → 体こそ).","2. 그 술어(小さい) 뒤에 역접의 が를 붙인다(体こそ小さいが).","3. 뒤에 앞의 내용과 반대되는, 더 중요한 평가를 말한다."],"why":"","nu":"앞에서 한 가지 사실을 '그건 분명 그렇다'고 인정한 뒤, 뒤에서 반대되는 평가를 강조한다. 약간 문어적. これこそ本物だ처럼 こそ만 쓰는 강조('~야말로')와 달리, 뒤에 が(けれど)가 이어져 양보의 뜻이 된다.","cmp":[{"g":"～こそ（단독）","d":"これこそ本物だ처럼 '~야말로'라는 강조. 뒤에 역접이 없다."},{"g":"～は～が","d":"일반적인 대비. こそ를 쓰면 앞부분을 인정하는 느낌이 더 강하다."}],"ex":[{"jp":"体[からだ]こそ小[ちい]さいが、力[ちから]は誰[だれ]よりも強[つよ]い。","ko":"몸집은 분명 작지만 힘은 누구보다도 세다."},{"jp":"給料[きゅうりょう]こそ安[やす]いが、やりがいのある仕事[しごと]だ。","ko":"월급은 분명 적지만 보람 있는 일이다."},{"jp":"見[み]た目[め]こそ悪[わる]いが、この料理[りょうり]はとてもおいしい。","ko":"겉보기는 분명 별로지만 이 요리는 아주 맛있다."}],"dr":[{"t":"make","q":"体は小さいが → こそ","a":"体こそ小さいが","hint":"は를 こそ로 바꾼다"},{"t":"make","q":"値段は高いが → こそ","a":"値段こそ高いが","hint":"は를 こそ로 바꾼다"},{"t":"fill","q":"この店[みせ]は場所[ばしょ]（　）不便[ふべん]だが、いつも客[きゃく]でいっぱいだ。","a":"こそ","opts":["こそ","ので","ために","ように"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/こそ～が～けれど-koso-ga-keredo-meaning/"],"vf":1,"u":27,"g":1,"gp":"gg_N1_10"},{"id":"g1_051","t":"～ならいざ知らず","ko":"~라면 몰라도","cat":"역접","conn":[{"w":"명사","f":"子供 + ならいざ知らず"},{"w":"동사 보통형 + の","f":"知らなかったの + ならいざ知らず"}],"rule":["1. 예외로 봐줄 수 있는 경우를 명사로 놓는다(子供).","2. 그 뒤에 ならいざ知らず를 그대로 붙인다(子供ならいざ知らず).","3. 뒤에는 본론이 되는 명사(大人が)와 그에 대한 놀람·비난이 온다."],"why":"","nu":"문어적이다. 'A라면 이해할 수 있지만, B인데 그렇다니'라며 뒤 상황을 비난하거나 놀라워한다. 뒤의 B가 A보다 정도가 심하거나 더 그래서는 안 되는 경우다. 문장 끝에 なんて・とは・べきだ 등이 자주 온다.","cmp":[{"g":"～はいざ知らず","d":"명사 + は + いざ知らず 형태의 변형으로, 뜻은 거의 같다(昔はいざ知らず). 둘 다 앞의 경우는 판단을 보류하고 뒤의 경우를 강조한다."}],"ex":[{"jp":"子供[こども]ならいざ知らず、大人[おとな]がそんなことで泣[な]くなんて。","ko":"아이라면 몰라도 어른이 그런 일로 울다니."},{"jp":"初心者[しょしんしゃ]ならいざ知らず、プロがこんなミスをするとは信[しん]じられない。","ko":"초보자라면 몰라도 프로가 이런 실수를 하다니 믿을 수 없다."},{"jp":"知[し]らなかったのならいざ知らず、知[し]っていて黙[だま]っていたのは許[ゆる]せない。","ko":"몰랐다면 몰라도 알면서 잠자코 있었던 것은 용서할 수 없다."}],"dr":[{"t":"make","q":"子供 → ～ならいざ知らず","a":"子供ならいざ知らず","hint":"명사 + ならいざ知らず"},{"t":"make","q":"初心者 → ～ならいざ知らず","a":"初心者ならいざ知らず","hint":"명사 + ならいざ知らず"},{"t":"fill","q":"小学生[しょうがくせい]（　）、大学生[だいがくせい]がこんな問題[もんだい]もできないとは。","a":"ならいざ知らず","opts":["ならいざ知らず","ならでは","なりとも","ともなれば"]}],"src":["https://bunpro.jp/grammar_points/933"],"vf":1,"u":27,"g":1,"gp":"gg_N1_10"},{"id":"g1_086","t":"～はいざ知らず","ko":"~라면 몰라도","cat":"역접","conn":[{"w":"명사","f":"子ども + はいざ知らず"},{"w":"명사(なら형)","f":"初心者 + ならいざ知らず"}],"rule":["1. 비교 대상이 되는 명사A 뒤에 は(또는 なら)를 붙인다: 子どもは.","2. いざ知らず를 붙인다: 子どもはいざ知らず.","3. 뒤에는 대비되는 명사B와, B에 대해서는 그럴 수 없다는 판단(놀람, 비판)을 쓴다."],"why":"知らず는 知る의 ない형 知ら에 부정의 ず가 붙은 형태로, 'A는 (어떤지) 모르겠지만'이라는 뜻을 만든다.","nu":"'A라면 그럴 수도 있겠지만, B는 그렇지 않다(그래서는 안 된다)'는 뜻으로 뒤의 B를 강조한다. 뒤에는 놀람·비판·당연함을 나타내는 내용이 온다. 문어적이고 딱딱한 표현이며, 회화에서는 ～ならともかく를 많이 쓴다.","cmp":[{"g":"～ならともかく","d":"거의 같은 뜻으로 회화에서도 쓴다."},{"g":"～はともかく(として)","d":"'A는 일단 제쳐 두고'라는 화제 보류의 뜻으로도 쓰인다. いざ知らず는 A와 B를 대비해 B가 의외라는 점을 강조한다."}],"ex":[{"jp":"子[こ]どもならいざ知[し]らず、大人[おとな]がこんなことで泣[な]くなんて。","ko":"아이라면 몰라도 어른이 이런 일로 울다니."},{"jp":"昔[むかし]はいざ知[し]らず、今[いま]は誰[だれ]でもスマホで写真[しゃしん]が撮[と]れる。","ko":"옛날이라면 몰라도 지금은 누구나 스마트폰으로 사진을 찍을 수 있다."},{"jp":"初心者[しょしんしゃ]ならいざ知[し]らず、プロがこんなミスをするとは信[しん]じられない。","ko":"초보자라면 몰라도 프로가 이런 실수를 하다니 믿을 수 없다."}],"dr":[{"t":"make","q":"昔 → ～はいざ知らず","a":"昔はいざ知らず","hint":"명사 + は + いざ知らず"},{"t":"make","q":"素人 → ～ならいざ知らず","a":"素人ならいざ知らず","hint":"명사 + なら + いざ知らず"},{"t":"fill","q":"夏[なつ]（　）、冬[ふゆ]に海[うみ]で泳[およ]ぐ人[ひと]は少[すく]ない。","a":"はいざ知らず","opts":["はいざ知らず","はおろか","のごとく","の手前"]}],"src":["https://bunpro.jp/grammar_points/933","https://jlptsensei.com/learn-japanese-grammar/ならいざしらず-はいざしらず-nara-iza-shirazu-meaning"],"vf":1,"u":28,"g":1,"gp":"gg_N1_10"},{"id":"g1_091","t":"～はどうであれ","ko":"~이 어떻든, ~와 상관없이","cat":"역접","conn":[{"w":"명사","f":"理由 + はどうであれ"}],"rule":["1. 명사 뒤에 주제 조사 は를 붙인다: 結果 → 結果は.","2. 그 뒤에 どうであれ(어떻든)를 그대로 붙인다: 結果はどうであれ.","3. 뒤 문장에는 그 명사와 관계없이 성립하는 판단·의지를 쓴다."],"why":"どう(어떻게) + である의 명령형 であれ로 이루어진다. であれ는 'AであれBであれ'처럼 '~이든'이라는 방임의 뜻으로 쓰이는 문어 형태다.","nu":"문어적이고 딱딱한 표현이다. 앞의 명사(이유, 결과, 형식 등)가 어떤 상태이든 뒤의 판단은 변하지 않는다는 뜻으로, 뒤에는 화자의 주장·의지·당위(~べきだ, ~いけない, ~つもりだ)가 자주 온다. 理由はどうであれ가 특히 관용적으로 많이 쓰인다. 명사 대신 '~がどうであれ'로 쓰기도 한다.","cmp":[{"g":"～にかかわらず","d":"天候にかかわらず처럼 조건의 변화와 무관함을 객관적으로 말한다. はどうであれ는 그 명사의 내용을 일단 문제 삼지 않겠다는 화자의 태도가 강하다."},{"g":"～はともかく","d":"앞의 것을 일단 미뤄 두고 뒤를 우선한다는 뜻으로, 회화에서도 흔히 쓴다."}],"ex":[{"jp":"理由[りゆう]はどうであれ、暴力[ぼうりょく]はいけない。","ko":"이유야 어떻든 폭력은 안 된다."},{"jp":"結果[けっか]はどうであれ、最後[さいご]までやるつもりだ。","ko":"결과가 어떻든 끝까지 할 생각이다."},{"jp":"見[み]た目[め]はどうであれ、味[あじ]がよければ客[きゃく]は来[く]る。","ko":"겉모습이 어떻든 맛이 좋으면 손님은 온다."}],"dr":[{"t":"make","q":"理由 → ～はどうであれ","a":"理由はどうであれ","hint":"명사 + は + どうであれ"},{"t":"make","q":"結果 → ～はどうであれ","a":"結果はどうであれ","hint":"명사 + は + どうであれ"},{"t":"fill","q":"形[かたち]は（　）、気持[きも]ちがこもっていればうれしい。","a":"どうであれ","opts":["どうであれ","おろか","ばかりか","おかげで"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/はどうであれ-wa-dou-de-are-meaning/","https://bunpro.jp/ja/grammar_points/%E3%81%A7%E3%81%82%E3%82%8C"],"vf":1,"u":28,"g":1,"gp":"gg_N1_10"},{"id":"g1_098","t":"～をものともせずに","ko":"~을 아랑곳하지 않고, ~에도 굴하지 않고","cat":"역접","conn":[{"w":"명사","f":"雨 + をものともせずに"}],"rule":["1. 관용구 ものともする의 する를 부정형 어간 せ로 바꾼다.","2. 문어 부정 ず를 붙인다: ものともせず.","3. に를 붙이고(생략 가능), 어려움을 나타내는 명사 + を 뒤에 둔다: 雨をものともせずに."],"why":"'대수롭지 않게 여기다'라는 관용구 ものともしない의 문어 부정형 ものともせず(に)이다.","nu":"문어적인 표현이다. 악천후·부상·병·반대 같은 어려움에 굴하지 않고 용감하게 해낸 다른 사람의 행동을 칭찬하듯 묘사할 때 쓴다. 화자 자신의 행동에는 잘 쓰지 않으며, 뒤에 명령·의지·권유 표현은 오지 않는다. に 없이 をものともせず로도 쓴다.","cmp":[{"g":"～をよそに","d":"주위의 걱정·기대·반대를 무시하고 행동한다는 뜻으로 비난의 느낌이 들 수 있다. をものともせず는 어려움을 이겨내는 것을 높이 평가한다."},{"g":"～にもかかわらず","d":"'~인데도'라는 일반적인 역접으로 평가의 뜻이 없다."}],"ex":[{"jp":"選手[せんしゅ]たちは激[はげ]しい雨[あめ]をものともせずに走[はし]り続[つづ]けた。","ko":"선수들은 거센 비에도 아랑곳하지 않고 계속 달렸다."},{"jp":"彼[かれ]はけがをものともせず、最後[さいご]まで試合[しあい]に出[で]た。","ko":"그는 부상에도 굴하지 않고 끝까지 시합에 나갔다."},{"jp":"彼女[かのじょ]は周囲[しゅうい]の反対[はんたい]をものともせずに、自分[じぶん]の店[みせ]を開[ひら]いた。","ko":"그녀는 주위의 반대에도 굴하지 않고 자기 가게를 열었다."}],"dr":[{"t":"make","q":"寒さ → ～をものともせずに","a":"寒さをものともせずに","hint":"명사 + を + ものとも + せず + に"},{"t":"make","q":"する → 문어 부정형(～ず)","a":"せず","hint":"する의 부정 어간 せ + ず"},{"t":"fill","q":"彼[かれ]は病気[びょうき]（　）、毎日[まいにち]練習[れんしゅう]を続[つづ]けた。","a":"をものともせずに","opts":["をものともせずに","をおいて","をもって","を前提にして"]}],"src":["https://nihongokyoshi-net.com/2019/06/12/jlptn1-grammar-womonotomosezu/"],"vf":1,"u":28,"g":1,"gp":"gg_N1_10"},{"id":"g1_099","t":"～をよそに","ko":"~을 아랑곳하지 않고, ~은 남의 일처럼","cat":"역접","conn":[{"w":"명사","f":"親の心配 + をよそに"},{"w":"동사·형용사 보통형 + の","f":"試験が近いの + をよそに"}],"rule":["1. 명사 뒤에 조사 を를 붙인다: 心配 → 心配を.","2. 그 뒤에 よそに를 붙인다: 心配をよそに.","3. 동사·형용사 문장은 の로 명사화한 뒤 붙인다: 試験が近いのをよそに."],"why":"よそ(余所, 자기와 관계없는 곳)에 に가 붙어 '~을 자기와 상관없는 것으로 두고'라는 뜻이 된다.","nu":"문어적인 표현이다. 주위 사람의 걱정·기대·반대·비판이나 주변 상황을 무시하고 행동하는 제3자를 묘사하며, 비난하는 느낌이 들기 쉽다. 화자 자신의 행동에는 잘 쓰지 않는다. 동사를 직접 붙이지 않도록 주의한다(試験が迫るをよそに는 틀리고, 試験が迫っているのをよそに로 한다).","cmp":[{"g":"～をものともせずに","d":"어려움에 굴하지 않는 행동을 긍정적으로 평가한다. をよそに는 주위의 감정·상황을 무시한다는 점에 초점이 있다."},{"g":"～にもかかわらず","d":"중립적인 역접으로, 무시한다는 뜻은 없다."}],"ex":[{"jp":"親[おや]の心配[しんぱい]をよそに、息子[むすこ]は毎晩[まいばん]遅[おそ]くまで遊[あそ]んでいる。","ko":"부모의 걱정은 아랑곳하지 않고 아들은 매일 밤 늦게까지 놀고 있다."},{"jp":"住民[じゅうみん]の反対[はんたい]をよそに、工事[こうじ]が始[はじ]まった。","ko":"주민들의 반대를 아랑곳하지 않고 공사가 시작되었다."},{"jp":"試験[しけん]が近[ちか]いのをよそに、弟[おとうと]はゲームばかりしている。","ko":"시험이 코앞인데도 남의 일인 양 남동생은 게임만 하고 있다."}],"dr":[{"t":"make","q":"親の心配 → ～をよそに","a":"親の心配をよそに","hint":"명사 + を + よそに"},{"t":"make","q":"周囲の期待 → ～をよそに","a":"周囲の期待をよそに","hint":"명사 + を + よそに"},{"t":"fill","q":"家族[かぞく]の心配[しんぱい]（　）、彼[かれ]は一人[ひとり]で冬[ふゆ]の山[やま]に登[のぼ]った。","a":"をよそに","opts":["をよそに","をおいて","を前提に","をもって"]}],"src":["https://bunpro.jp/grammar_points/884","https://nihongokyoshi-net.com/2019/06/28/jlptn1-grammar-woyosoni/"],"vf":1,"u":28,"g":1,"gp":"gg_N1_10"},{"id":"g1_119","t":"～ずとも","ko":"~하지 않아도","cat":"역접","conn":[{"w":"1그룹 동사 ない형","f":"言わ + ずとも"},{"w":"2그룹 동사 ない형","f":"見 + ずとも"},{"w":"불규칙 する","f":"する → せずとも"},{"w":"불규칙 来る","f":"来る → 来(こ)ずとも"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꿔 ない형을 만든다. う는 わ가 된다: 言う → 言わ.","2. ない 대신 옛 부정형 ず를 붙인다: 言わず.","3. '~해도'를 뜻하는 とも를 붙인다: 言わずとも.","4. 2그룹은 る를 떼고 ずとも, する는 せずとも가 된다."],"why":"고전 부정 조동사 ず에 역접 가정('~하더라도')의 접속 조사 とも가 이어진 형태로, 현대어 なくても에 해당한다.","nu":"'~하지 않아도 (괜찮다, 된다, 알 수 있다)'라는 뜻의 문어적·고풍스러운 표현이다. 言わずとも分かる(말하지 않아도 안다), 急がずとも間に合う처럼 뒤에 충분하다, 가능하다는 내용이 온다. 일상 회화에서는 なくても를 쓰는 것이 자연스럽다.","cmp":[{"g":"～なくても","d":"같은 뜻의 일반적인 표현으로 동사·형용사·명사 모두에 쓰고 회화에 적합하다. ずとも는 주로 동사에 붙는 딱딱한 표현이다."}],"ex":[{"jp":"言[い]わずとも、彼[かれ]の気持[きも]ちはよく分[わ]かる。","ko":"말하지 않아도 그의 마음은 잘 안다."},{"jp":"そんなに急[いそ]がずとも、電車[でんしゃ]には間[ま]に合[あ]う。","ko":"그렇게 서두르지 않아도 전철 시간에는 늦지 않는다."},{"jp":"わざわざ来[こ]ずとも、電話[でんわ]で十分[じゅうぶん]です。","ko":"일부러 오지 않아도 전화로 충분합니다."}],"dr":[{"t":"make","q":"急ぐ → ～ずとも","a":"急がずとも","hint":"ぐ → が(ない형) + ずとも"},{"t":"make","q":"心配する → ～ずとも","a":"心配せずとも","hint":"する → せ + ずとも"},{"t":"fill","q":"説明[せつめい]され（　）、見[み]ればすぐ分[わ]かる。","a":"ずとも","opts":["ずとも","ずじまい","ざるを得ず","ずにはおかず"]}],"src":["https://bunpro.jp/grammar_points/831"],"vf":1,"u":28,"g":1,"gp":"gg_N1_10"},{"id":"g1_127","t":"～たら～たで","ko":"~하면 ~한 대로","cat":"역접","conn":[{"w":"동사 た형","f":"作った + ら + 作った + で"},{"w":"い형용사 과거형","f":"広かった + ら + 広かった + で"}],"rule":["1. 동사를 た형으로 바꾼다. 1그룹 る동사는 어미 る가 っ로 바뀌고(촉음편) た가 붙는다: 作る → 作った.","2. た형 뒤에 조건의 ら를 붙인다: 作ったら.","3. 같은 た형을 한 번 더 쓰고 で를 붙인다: 作ったら作ったで.","4. い형용사는 い를 かった로 바꿔 같은 방식으로 반복한다: 広い → 広かったら広かったで."],"why":"","nu":"어떤 일이 실현되면 그것대로 또 다른 문제나 사정이 생긴다는 뜻이다. 앞부분과 같은 말을 반복하는 것이 핵심이며, 다른 동사를 넣으면 틀린다. 뒤에는 주로 곤란함·불만이 오지만 '그건 그거대로 괜찮다'는 뜻으로도 쓴다. 'A하면 A한 대로, A하지 않으면 A하지 않은 대로'처럼 긍정·부정을 짝지어 쓰는 경우가 많다. 회화와 글 모두에서 쓰는 일반적인 표현이다.","cmp":[{"g":"～ば～で / ～なら～で","d":"같은 뜻의 조건 반복형이다(あればあったで, 暇なら暇で). な형용사·명사는 보통 なら～で 형태를 쓴다."}],"ex":[{"jp":"料理[りょうり]は作[つく]ったら作[つく]ったで、片付[かたづ]けが大変[たいへん]だ。","ko":"요리는 만들면 만든 대로 뒷정리가 힘들다."},{"jp":"家[いえ]が広[ひろ]かったら広[ひろ]かったで、掃除[そうじ]に時間[じかん]がかかる。","ko":"집이 넓으면 넓은 대로 청소에 시간이 걸린다."},{"jp":"行[い]ったら行[い]ったで疲[つか]れるし、行[い]かなかったら行[い]かなかったで後悔[こうかい]しそうだ。","ko":"가면 간 대로 피곤하고, 안 가면 안 간 대로 후회할 것 같다."}],"dr":[{"t":"make","q":"買う → ～たら～たで","a":"買ったら買ったで","hint":"う → った(촉음편), ら를 붙이고 같은 た형 + で"},{"t":"make","q":"寒い → ～たら～たで","a":"寒かったら寒かったで","hint":"い → かった, ら + 寒かった + で"},{"t":"fill","q":"お金[かね]があったら（　）、心配[しんぱい]なこともある。","a":"あったで","opts":["あったで","あるので","あっても","あるから"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%9F%E3%82%89-%E3%81%A7"],"vf":1,"u":29,"g":1,"gp":"gg_N1_10"},{"id":"g1_140","t":"～ないまでも","ko":"~까지는 아니더라도","cat":"역접","conn":[{"w":"동사 ない형","f":"できない + までも"},{"w":"～とは言わない","f":"毎日とは言わない + までも"}],"rule":["1. 동사를 ない형으로 바꾼다. 2그룹 동사는 어미 る를 ない로 바꾼다: できる → できない.","2. ない형 뒤에 までも를 붙인다: できないまでも.","3. 1그룹 동사는 う단을 あ단으로 바꾸고 ない: 行く → 行かないまでも."],"why":"","nu":"높은 수준(앞부분)까지는 이르지 못하더라도, 그보다 낮은 수준(뒷부분)만큼은 이루고 싶다·이루어야 한다는 뜻이다. 뒤에는 せめて, 少なくとも, ～くらいは와 함께 희망(～たい), 의무(～べきだ), 명령·의뢰가 자주 온다. ～とは言わないまでも 형태가 특히 흔하다. 약간 딱딱한 표현이다.","cmp":[{"g":"～ないにしても","d":"'~하지 않는다 하더라도'라는 양보로 쓰임이 넓다. ないまでも는 앞뒤가 정도의 높고 낮음으로 대비될 때 쓴다."}],"ex":[{"jp":"優勝[ゆうしょう]できないまでも、三位[さんい]には入[はい]りたい。","ko":"우승까지는 못 하더라도 3위 안에는 들고 싶다."},{"jp":"毎日[まいにち]とは言[い]わないまでも、週[しゅう]に一度[いちど]は運動[うんどう]したほうがいい。","ko":"매일까지는 아니더라도 일주일에 한 번은 운동하는 게 좋다."},{"jp":"会[あ]いに行[い]かないまでも、せめて電話[でんわ]くらいはしなさい。","ko":"만나러 가지는 않더라도 적어도 전화 정도는 해라."}],"dr":[{"t":"make","q":"手伝う → ～ないまでも","a":"手伝わないまでも","hint":"う → わ, + ない + までも"},{"t":"make","q":"全部覚える → ～ないまでも","a":"全部覚えないまでも","hint":"る → ない, + までも"},{"t":"fill","q":"満点[まんてん]は取[と]れない（　）、八十点[はちじゅってん]は取[と]りたい。","a":"までも","opts":["までも","からこそ","ばかりか","からには"]}],"src":["https://bunpro.jp/es/grammar_points/%E3%81%AA%E3%81%84%E3%81%BE%E3%81%A7%E3%82%82"],"vf":1,"u":29,"g":1,"gp":"gg_N1_10"},{"id":"g1_149","t":"～ようが～まいが","ko":"~하든 말든","cat":"역접","conn":[{"w":"1그룹 동사","f":"降ろう + が + 降る + まいが"},{"w":"2그룹 동사","f":"信じよう + が + 信じまい + が"},{"w":"する / 来る","f":"しよう + が + しまい + が / 来(こ)よう + が + 来(く)るまい + が"}],"rule":["1. 1그룹 동사는 어미 う단을 お단으로 바꾸고 う를 붙여 의향형을 만든다: 降る → 降ろう.","2. 의향형 뒤에 が를 붙인다: 降ろうが.","3. 같은 동사에 まい를 붙이고(1그룹은 사전형 + まい) 다시 が를 붙인다: 降るまいが.","4. 뒤 문장에는 '그래도 변하지 않는다·상관없다'는 내용이 온다."],"why":"","nu":"'~하든 안 하든 결과는 같다'는 뜻으로, 뒤에는 말하는 사람의 변함없는 결심이나 영향받지 않는 사실이 온다. 문어적이고 딱딱하며 회화에서는 ～ても～なくても를 많이 쓴다. ～ようと～まいと와 뜻이 거의 같다.","cmp":[{"g":"～ようと～まいと","d":"뜻과 쓰임이 거의 같다."},{"g":"～ても～なくても","d":"같은 뜻의 회화적 표현(降っても降らなくても)."}],"ex":[{"jp":"雨[あめ]が降[ふ]ろうが降[ふ]るまいが、試合[しあい]は行[おこな]われる。","ko":"비가 오든 말든 시합은 열린다."},{"jp":"君[きみ]が賛成[さんせい]しようがしまいが、私[わたし]の考[かんが]えは変[か]わらない。","ko":"네가 찬성하든 말든 내 생각은 변하지 않는다."},{"jp":"彼[かれ]が来[こ]ようが来[く]るまいが、時間[じかん]になったら始[はじ]めます。","ko":"그가 오든 말든 시간이 되면 시작합니다."}],"dr":[{"t":"make","q":"行く → ～ようが～まいが","a":"行こうが行くまいが","hint":"의향형 行こう + が + 사전형 + まいが"},{"t":"make","q":"買う → ～ようが～まいが","a":"買おうが買うまいが","hint":"う → おう + が + 買う + まいが"},{"t":"fill","q":"君[きみ]が信[しん]じ（　）信[しん]じまいが、これは事実[じじつ]だ。","a":"ようが","opts":["ようが","ようか","ように","ようで"]}],"src":["https://bunpro.jp/grammar_points/744","https://bunpro.jp/grammar_points/343"],"vf":1,"u":29,"g":1,"gp":"gg_N1_10"},{"id":"g1_151","t":"～ようと～まいと","ko":"~하든 말든","cat":"역접","conn":[{"w":"1그룹 동사","f":"行こう + と + 行く + まいと"},{"w":"2그룹 동사","f":"出よう + と + 出まい + と"},{"w":"来る / する","f":"来(こ)よう + と + 来(く)るまい + と / しよう + と + しまい + と"}],"rule":["1. 의향형을 만든다. 1그룹은 어미 う단을 お단으로 바꾸고 う(行く → 行こう), 2그룹은 る를 빼고 よう(出る → 出よう), 来る는 来(こ)よう, する는 しよう.","2. 의향형 뒤에 と를 붙인다: 来ようと.","3. 같은 동사에 まい를 붙이고(1그룹과 来る는 사전형 + まい: 来(く)るまい) 다시 と를 붙인다: 来ようと来るまいと.","4. 뒤 문장에는 '그래도 변하지 않는다'는 내용이 온다."],"why":"","nu":"'~하든 안 하든 상관없이'라는 뜻으로, 뒤에는 변하지 않는 결정·사실·의지가 온다. 문어적이고 딱딱한 표현이며 회화에서는 ～ても～なくても가 자연스럽다. ～ようが～まいが와 바꿔 쓸 수 있다. 来る는 앞이 こよう, 뒤가 くるまい로 읽기가 달라지는 점에 주의한다.","cmp":[{"g":"～ようが～まいが","d":"뜻과 쓰임이 거의 같다."},{"g":"～ても～なくても","d":"같은 뜻의 회화적 표현(来ても来なくても)."}],"ex":[{"jp":"彼[かれ]が来[こ]ようと来[く]るまいと、パーティーは七時[しちじ]に始[はじ]める。","ko":"그가 오든 말든 파티는 7시에 시작한다."},{"jp":"結果[けっか]が出[で]ようと出[で]まいと、最後[さいご]までやるつもりだ。","ko":"결과가 나오든 말든 끝까지 할 생각이다."},{"jp":"君[きみ]が賛成[さんせい]しようとしまいと、私[わたし]は留学[りゅうがく]する。","ko":"네가 찬성하든 말든 나는 유학 간다."}],"dr":[{"t":"make","q":"読む → ～ようと～まいと","a":"読もうと読むまいと","hint":"む → もう(의향형) + と + 読む + まいと"},{"t":"make","q":"降る → ～ようと～まいと","a":"降ろうと降るまいと","hint":"る → ろう(의향형) + と + 降る + まいと"},{"t":"fill","q":"彼[かれ]が謝[あやま]ろうと謝[あやま]る（　）、許[ゆる]すつもりはない。","a":"まいと","opts":["まいと","まいか","ものか","ことか"]}],"src":["https://bunpro.jp/grammar_points/744","https://bunpro.jp/grammar_points/343"],"vf":1,"u":29,"g":1,"gp":"gg_N1_10"},{"id":"g1_152","t":"～ようにも","ko":"~하려고 해도 (할 수 없다)","cat":"역접","conn":[{"w":"1그룹 동사","f":"帰ろう + にも"},{"w":"2그룹 동사","f":"出かけよう + にも"},{"w":"する","f":"相談しよう + にも"}],"rule":["1. 1그룹 동사는 어미 う단을 お단으로 바꾸고 う를 붙여 의향형을 만든다: 帰る → 帰ろう. 2그룹은 る를 빼고 よう, する는 しよう.","2. 의향형 뒤에 にも를 붙인다: 帰ろうにも.","3. 뒤 문장에는 할 수 없는 이유나 가능형 부정(帰れない)이 온다."],"why":"","nu":"하려는 마음은 있지만 어떤 사정 때문에 실현할 수 없다는 뜻이다. 뒤에는 대개 '할 수 없다'는 내용(가능형 부정, ない, 무리다 등)이나 할 수 없는 이유가 온다. 같은 동사를 가능형 부정으로 반복하는 ～ようにも～られない 형태가 특히 많다.","cmp":[{"g":"～ようとしても","d":"'~하려고 해도'의 일반적인 표현. ようにも는 뒤에 불가능이 거의 정해져 있다."},{"g":"～たくても","d":"'~하고 싶어도'. 바람을 나타내며 회화적이다."}],"ex":[{"jp":"早[はや]く帰[かえ]ろうにも、仕事[しごと]が多[おお]くて帰[かえ]れない。","ko":"일찍 퇴근하려고 해도 일이 많아서 갈 수가 없다."},{"jp":"相談[そうだん]しようにも、周[まわ]りに話[はな]せる人[ひと]がいない。","ko":"상담하려고 해도 주위에 이야기할 수 있는 사람이 없다."},{"jp":"出[で]かけようにも、外[そと]はひどい雨[あめ]だ。","ko":"외출하려고 해도 밖은 비가 심하게 온다."}],"dr":[{"t":"make","q":"連絡する → ～ようにも","a":"連絡しようにも","hint":"する → しよう(의향형) + にも"},{"t":"make","q":"休む → ～ようにも","a":"休もうにも","hint":"1그룹: む → もう + にも"},{"t":"fill","q":"電話[でんわ]しよう（　）、番号[ばんごう]が分[わ]からない。","a":"にも","opts":["にも","とも","ものの","からには"]}],"src":["https://bunpro.jp/grammar_points/839","https://www.vnjpclub.com/en/n2-grammar/younimo.html"],"vf":1,"u":30,"g":1,"gp":"gg_N1_11"},{"id":"g1_166","t":"～にも（동사 사전형）","ko":"~하려고 해도, ~하는 데에도","cat":"역접","conn":[{"w":"동사 사전형","f":"買う + にも"},{"w":"동사 사전형","f":"引っ越す + にも"}],"rule":["1. 하고 싶은 동작의 동사를 사전형 그대로 둔다: 買う.","2. 사전형 뒤에 にも를 붙인다: 買うにも.","3. 뒤에는 그 동작을 막는 사정이나 필요한 조건을 쓴다: 買うにもお金がない."],"why":"","nu":"'어떤 일을 하려고 해도 (사정 때문에 못 한다)', '어떤 일을 하는 데에도 (~가 필요하다)'라는 뜻이다. 뒤에는 장애가 되는 사정(お金がない, 時間がない)이나 필요한 것(お金がかかる)이 온다. 같은 동사를 반복해 '하려 해도 할 수 없다'고 할 때는 의지형 + にも(行こうにも行けない)가 일반적이다. 다소 딱딱한 표현이다.","cmp":[{"g":"～(よ)うにも～ない","d":"의지형 + にも + 같은 동사의 가능 부정으로, 하려고 시도해도 할 수 없다는 뜻이 더 강조된다."},{"g":"～ても","d":"단순한 양보·가정 '~해도'로, 동작 실행의 장애나 조건이라는 뜻에 한정되지 않는다."}],"ex":[{"jp":"新[あたら]しいパソコンを買[か]うにも、お金[かね]が足[た]りない。","ko":"새 컴퓨터를 사려고 해도 돈이 모자란다."},{"jp":"引[ひ]っ越[こ]すにも、かなりお金[かね]がかかる。","ko":"이사하는 데에도 꽤 돈이 든다."},{"jp":"相談[そうだん]するにも、話[はな]せる人[ひと]がいない。","ko":"상담하려고 해도 이야기할 수 있는 사람이 없다."}],"dr":[{"t":"make","q":"休む → ～にも","a":"休むにも","hint":"동사 사전형 + にも"},{"t":"make","q":"連絡する → ～にも","a":"連絡するにも","hint":"사전형을 그대로 두고 にも를 붙인다"},{"t":"fill","q":"病院[びょういん]へ行[い]く（　）、車[くるま]がない。","a":"にも","opts":["にも","ほど","ばかりに","まいと"]}],"src":[],"vf":0,"u":30,"g":1,"gp":"gg_N1_11"},{"id":"g1_167","t":"～(よ)うにも～ない","ko":"~하려고 해도 ~할 수 없다","cat":"역접","conn":[{"w":"1그룹 동사","f":"行く → 行こう + にも + 行けない"},{"w":"2그룹 동사","f":"寝る → 寝よう + にも + 寝られない"},{"w":"する / 来る","f":"連絡しよう + にも + 連絡できない / 来よう + にも + 来られない"}],"rule":["1. 1그룹 동사는 어미 う단을 お단으로 바꾸고 う를 붙여 의지형을 만든다: 行く → 行こう.","2. 2그룹 동사는 る를 떼고 よう를 붙인다: 寝る → 寝よう. する는 しよう, 来る는 来(こ)よう.","3. 의지형 뒤에 にも를 붙인다: 行こうにも.","4. 뒤에 같은 동사의 가능형 부정을 쓴다: 行こうにも行けない."],"why":"","nu":"하려고 마음먹고 시도해도 어떤 사정 때문에 할 수 없다는 답답함을 나타낸다. 앞뒤에 같은 동사를 반복하는 것이 보통이며, 이유(雨で, お金がなくて 등)를 앞에 함께 쓰는 경우가 많다. 한국어 화자는 사전형 + にも와 혼동하기 쉬운데, 같은 동사의 반복은 의지형 + にも가 일반적이다.","cmp":[{"g":"～たくても～ない","d":"'~하고 싶어도 못 한다'는 일상 표현으로 희망을 강조한다. (よ)うにも는 실제로 하려는 의지·시도를 강조한다."},{"g":"～にも（사전형）","d":"사전형 + にも 뒤에는 보통 다른 말로 장애나 조건(お金がない)을 쓴다."}],"ex":[{"jp":"大雪[おおゆき]で、外[そと]に出[で]ようにも出[で]られない。","ko":"폭설로 밖에 나가려고 해도 나갈 수 없다."},{"jp":"電話番号[でんわばんごう]を忘[わす]れたので、連絡[れんらく]しようにも連絡[れんらく]できない。","ko":"전화번호를 잊어버려서 연락하려고 해도 연락할 수 없다."},{"jp":"隣[となり]がうるさくて、寝[ね]ようにも寝[ね]られない。","ko":"옆집이 시끄러워서 자려고 해도 잘 수가 없다."}],"dr":[{"t":"make","q":"帰る → ～ようにも～ない","a":"帰ろうにも帰れない","hint":"る → ろう(의지형) + にも + 帰れない(가능 부정)"},{"t":"make","q":"食べる → ～ようにも～ない","a":"食べようにも食べられない","hint":"る를 떼고 よう + にも + 食べられない"},{"t":"fill","q":"足[あし]をけがして、走[はし]ろう（　）走[はし]れない。","a":"にも","opts":["にも","とも","ものの","からには"]}],"src":["https://bunpro.jp/grammar_points/839"],"vf":1,"u":30,"g":1,"gp":"gg_N1_11"},{"id":"g1_179","t":"～かと思いきや","ko":"~인가 했더니 (뜻밖에도)","cat":"역접","conn":[{"w":"동사 보통형","f":"晴れる + かと思いきや"},{"w":"い형용사","f":"高い + かと思いきや"},{"w":"な형용사","f":"簡単 + かと思いきや"},{"w":"명사","f":"雨 + かと思いきや"}],"rule":["1. 동사·い형용사는 보통형 그대로 둔다: 晴れる.","2. 보통형 뒤에 かと思いきや를 붙인다: 晴れるかと思いきや.","3. な형용사·명사는 보통 だ 없이 붙인다(だ를 넣어도 된다): 雨かと思いきや.","4. 뒤에는 예상과 반대되는 결과를 쓴다: 晴れるかと思いきや、雨が降った."],"why":"고어 思ふ의 연용형 思ひ에 과거 조동사 き와 조사 や가 붙은 말로, '~라고 생각했는데'라는 뜻이다.","nu":"말하는 사람이 당연히 그럴 거라 예상했는데 실제로는 반대였다는 놀라움을 나타낸다. 문어적이지만 글이나 다소 격식 있는 이야기에서 쓰인다. 뒤 문장은 이미 일어난 사실이며, 의지·명령은 오지 않는다. 자기 자신의 의지적 행동에는 쓰지 않는다.","cmp":[{"g":"～と思ったら","d":"회화체로 '~라고 생각했더니'. 예상 밖의 결과뿐 아니라 바로 이어진 변화(帰ってきたと思ったら、また出かけた)에도 쓴다."},{"g":"～のに","d":"예상과 다른 결과에 대한 불만을 나타내는 일반적 역접 표현이다."}],"ex":[{"jp":"今日[きょう]は晴[は]れるかと思[おも]いきや、午後[ごご]から雨[あめ]が降[ふ]り出[だ]した。","ko":"오늘은 맑을 줄 알았더니 오후부터 비가 내리기 시작했다."},{"jp":"高[たか]いかと思[おも]いきや、意外[いがい]に安[やす]かった。","ko":"비쌀 줄 알았더니 의외로 쌌다."},{"jp":"試験[しけん]は簡単[かんたん]かと思[おも]いきや、難[むずか]しい問題[もんだい]ばかりだった。","ko":"시험이 쉬울 줄 알았더니 어려운 문제뿐이었다."}],"dr":[{"t":"make","q":"勝つ → ～かと思いきや","a":"勝つかと思いきや","hint":"동사 보통형 + かと思いきや"},{"t":"make","q":"静かだ → ～かと思いきや","a":"静かかと思いきや","hint":"な형용사는 だ를 빼고 かと思いきや"},{"t":"fill","q":"もう帰[かえ]った（　）、彼[かれ]はまだ会社[かいしゃ]にいた。","a":"かと思いきや","opts":["かと思いきや","からには","とばかりに","ものなら"]}],"src":["https://bunpro.jp/grammar_points/818","https://jlptsensei.com/learn-japanese-grammar/かと思いきや-かとおもいきや-to-omoikiya-meaning/"],"vf":1,"u":30,"g":1,"gp":"gg_N1_11"},{"id":"g1_192","t":"～といえども","ko":"~라 할지라도, ~라고 해도","cat":"역접","conn":[{"w":"명사","f":"プロ + といえども"},{"w":"동사 보통형","f":"いくら急いでいる + といえども"},{"w":"い형용사","f":"小さい + といえども"}],"rule":["1. 인정하는 사실을 명사나 보통형으로 둔다: プロ.","2. 그 뒤에 といえども를 붙인다: プロといえども.","3. 뒤에는 그 사실에서 기대되는 것과 반대되는 내용을 쓴다: 失敗することはある."],"why":"と(인용) + いう(말하다)의 문어형 いえ + ども(문어 역접 조사)로 이루어져 '~라고 해도'라는 뜻이 된다.","nu":"딱딱한 문어체로 연설·논설에 쓴다. '~같은 대단한(특별한) 입장이라도 예외는 아니다'라는 뜻으로 명사와 자주 쓰이며, たとえ, いかに, いくら와 함께 쓰는 경우가 많다. 회화에서는 ～といっても, ～でも를 쓴다.","cmp":[{"g":"～とはいえ","d":"'~라고는 해도'로, 인정한 사실에서 예상과 다른 점을 덧붙인다. といえども가 더 딱딱하다."},{"g":"～ても","d":"일반적인 역접 조건. といえども는 문어적이고 강조가 강하다."}],"ex":[{"jp":"プロといえども、失敗[しっぱい]することはある。","ko":"프로라 할지라도 실수할 때는 있다."},{"jp":"子[こ]どもといえども、ルールは守[まも]らなければならない。","ko":"아이라 할지라도 규칙은 지켜야 한다."},{"jp":"いくら忙[いそが]しいといえども、連絡[れんらく]ぐらいはできるはずだ。","ko":"아무리 바쁘다 해도 연락 정도는 할 수 있을 것이다."}],"dr":[{"t":"make","q":"先生 → ～といえども","a":"先生といえども","hint":"명사 + といえども"},{"t":"make","q":"春 → ～といえども","a":"春といえども","hint":"명사 + といえども"},{"t":"fill","q":"天才[てんさい]（　）、努力[どりょく]なしでは成功[せいこう]できない。","a":"といえども","opts":["といえども","とあって","ならでは","ごとく"]}],"src":["https://bunpro.jp/grammar_points/736","https://jlptsensei.com/learn-japanese-grammar/といえども-to-ie-domo-meaning/"],"vf":1,"u":30,"g":1,"gp":"gg_N1_11"},{"id":"g1_199","t":"～としたところで","ko":"~라고 해도, ~라고 가정한들","cat":"역접","conn":[{"w":"동사 보통형","f":"急ぐ + としたところで / 急いだ + としたところで"},{"w":"い형용사","f":"安い + としたところで"},{"w":"な형용사","f":"便利だ + としたところで"},{"w":"명사","f":"冗談だ + としたところで"}],"rule":["1. 앞말은 보통형 그대로 둔다: 急ぐ.","2. 가정을 나타내는 と + する를 붙이고, する를 た형 した로 바꾼다: 急ぐとした.","3. 끝에 역접의 ところで를 붙인다: 急ぐとしたところで.","4. 명사·な형용사는 だ를 넣어 だとしたところで로 만든다."],"why":"가정을 나타내는 ～とする의 た형 ～とした에, '~해 봤자'를 뜻하는 ところで가 붙은 형태다.","nu":"'설령 ~라고 가정해도 결과는 마찬가지(별 효과 없음)'라는 뜻으로, 뒤에는 부정적·소극적인 판단이 온다. 딱딱한 문장체·논설체에 가깝다. 뒤에 희망이나 긍정적 결과를 두면 어색하다. 회화에서는 としても를 더 많이 쓴다.","cmp":[{"g":"～としても","d":"가정 역접의 가장 일반적인 표현으로 뒤에 긍정·부정 모두 올 수 있다. としたところで는 '해 봤자 소용없다'는 부정적 결론 쪽으로 기운다."},{"g":"～たところで","d":"동사 た형 + ところで(急いだところで)로, 아직 하지 않은 행동을 가정해 '해 봤자 소용없다'고 말한다. としたところで는 '~라고 가정해도 / ~의 입장이라도'라고 전제를 세운다."}],"ex":[{"jp":"今[いま]から急[いそ]いだとしたところで、終電[しゅうでん]にはもう間[ま]に合[あ]わない。","ko":"지금부터 서두른다고 해도 막차에는 이미 늦었다."},{"jp":"値段[ねだん]が安[やす]いとしたところで、今[いま]は買[か]う余裕[よゆう]がない。","ko":"가격이 싸다고 해도 지금은 살 여유가 없다."},{"jp":"冗談[じょうだん]だとしたところで、あれは言[い]い過[す]ぎだ。","ko":"농담이라고 해도 그건 너무 심한 말이다."}],"dr":[{"t":"make","q":"頼む → ～としたところで","a":"頼むとしたところで","hint":"보통형 + と + した(する의 た형) + ところで"},{"t":"make","q":"本当 → ～としたところで","a":"本当だとしたところで","hint":"명사는 だ를 넣어 だとしたところで"},{"t":"fill","q":"今[いま]から勉強[べんきょう]を始[はじ]める（　）、明日[あした]の試験[しけん]には間[ま]に合[あ]わない。","a":"としたところで","opts":["としたところで","からこそ","ばかりに","ついでに"]}],"src":["https://bunpro.jp/grammar_points/878","https://www.jpf.go.jp/j/project/japanese/teach/tsushin/grammar/201109.html"],"vf":1,"u":31,"g":1,"gp":"gg_N1_11"},{"id":"g1_206","t":"～とはいえ","ko":"~라고는 해도, ~이긴 하지만","cat":"역접","conn":[{"w":"동사 보통형","f":"慣れた + とはいえ"},{"w":"い형용사","f":"安い + とはいえ"},{"w":"な형용사","f":"便利(だ) + とはいえ"},{"w":"명사","f":"春(だ) + とはいえ"}],"rule":["1. 앞말은 보통형으로 둔다. 명사·な형용사는 だ 없이도, だ를 넣어도 된다: 春 / 春だ.","2. と + は를 붙인다: 春とは.","3. 끝에 いえ를 붙인다: 春とはいえ."],"why":"'말하다'를 뜻하는 言う에서 온 표현으로, 글자 그대로 '~라고는 말해도'라는 뜻이다(とは言え).","nu":"앞의 사실은 인정하면서, 그로부터 예상되는 것과 다른 현실을 뒤에 말한다. 문장체·격식 있는 회화에서 쓰인다. 문장 첫머리에서 とはいえ、… 처럼 접속사로도 자주 쓴다. 뒤에는 화자의 평가·사실이 오며, 명령·의뢰는 잘 오지 않는다.","cmp":[{"g":"～といっても","d":"뜻이 비슷하지만 회화적이고, '실제로는 대단치 않다'고 정도를 낮출 때 많이 쓴다(旅行といっても一泊だけだ)."},{"g":"～ものの","d":"앞의 사실을 인정하고 뒤에 기대와 다른 결과를 말한다는 점은 같다. ものの는 동사 た형 뒤에 잘 오고 접속사로 단독 사용하지 않는다."}],"ex":[{"jp":"春[はる]とはいえ、まだ寒[さむ]い日[ひ]が続[つづ]いている。","ko":"봄이라고는 해도 아직 추운 날이 이어지고 있다."},{"jp":"安[やす]いとはいえ、毎日[まいにち]外食[がいしょく]するのは無理[むり]だ。","ko":"싸다고는 해도 매일 외식하는 것은 무리다."},{"jp":"仕事[しごと]に慣[な]れたとはいえ、人前[ひとまえ]で話[はな]すのはやはり緊張[きんちょう]する。","ko":"일에 익숙해졌다고는 해도 남 앞에서 말하는 건 역시 긴장된다."}],"dr":[{"t":"make","q":"子ども → ～とはいえ","a":"子どもとはいえ","hint":"명사 + と + は + いえ"},{"t":"make","q":"便利だ → ～とはいえ","a":"便利だとはいえ","hint":"보통형 그대로 + とはいえ"},{"t":"fill","q":"夏休[なつやす]み（　）、宿題[しゅくだい]が多[おお]くて遊[あそ]べない。","a":"とはいえ","opts":["とはいえ","だからこそ","のおかげで","につれて"]}],"src":["https://www.mlcjapanese.co.jp/n1_04_08.html"],"vf":1,"u":31,"g":1,"gp":"gg_N1_11"},{"id":"g1_210","t":"どんなに～うが","ko":"아무리 ~하더라도","cat":"역접","conn":[{"w":"1그룹 동사","f":"どんなに 頑張る → 頑張ろう + が"},{"w":"2그룹 동사","f":"どんなに 食べる → 食べよう + が"},{"w":"する・来る","f":"どんなに 努力する → 努力しよう + が / 来る → 来よう + が"},{"w":"い형용사","f":"どんなに 寒い → 寒かろう + が"},{"w":"な형용사·명사","f":"どんなに 大変だ → 大変だろう + が"}],"rule":["1. 앞에 どんなに를 둔다.","2. 동사는 의지형으로 바꾼다: 1그룹은 어미를 お단 + う(頑張る → 頑張ろう), 2그룹은 る를 よう로(食べる → 食べよう).","3. い형용사는 어미 い를 かろう로 바꾼다: 寒い → 寒かろう. な형용사·명사는 だろう를 붙인다.","4. 끝에 が를 붙인다: どんなに寒かろうが."],"why":"","nu":"'정도가 아무리 심해도 결과(뒤 문장)는 변하지 않는다'는 강한 역접이다. 뒤에는 화자의 의지·판단이나 변하지 않는 사실이 온다. かろう 같은 형태 때문에 문어적·딱딱한 느낌이 있으며, 회화에서는 どんなに～ても가 일반적이다. ～うと(どんなに寒かろうと)도 같은 뜻이다.","cmp":[{"g":"どんなに～ても","d":"같은 뜻의 일반적인 회화 표현(どんなに寒くても)."},{"g":"～うが～まいが","d":"'~하든 ~하지 않든'으로 긍정·부정 두 경우를 모두 들어 상관없음을 나타낸다."}],"ex":[{"jp":"どんなに寒[さむ]かろうが、彼[かれ]は毎朝[まいあさ]走[はし]る。","ko":"아무리 춥더라도 그는 매일 아침 달린다."},{"jp":"どんなに頑張[がんば]ろうが、この仕事[しごと]は一日[いちにち]では終[お]わらない。","ko":"아무리 열심히 해도 이 일은 하루에는 끝나지 않는다."},{"jp":"どんなに大変[たいへん]だろうが、約束[やくそく]は守[まも]る。","ko":"아무리 힘들더라도 약속은 지킨다."}],"dr":[{"t":"make","q":"どんなに 高い → ～うが","a":"どんなに高かろうが","hint":"い형용사: い → かろう + が"},{"t":"make","q":"どんなに 待つ → ～うが","a":"どんなに待とうが","hint":"1그룹: つ → と + う (의지형) + が"},{"t":"fill","q":"どんなに反対[はんたい]され（　）、私[わたし]はこの道[みち]を選[えら]ぶ。","a":"ようが","opts":["ようが","たら","るなら","たので"]}],"src":["https://aiueo.cc/pages_v2/ja/grammar/web/516.php"],"vf":1,"u":31,"g":1,"gp":"gg_N1_11"},{"id":"g1_215","t":"～ながらも","ko":"~이면서도, ~지만","cat":"역접","conn":[{"w":"동사 ます형","f":"知る → 知り + ながらも / 知っている → 知ってい + ながらも"},{"w":"い형용사","f":"狭い + ながらも"},{"w":"な형용사 어간","f":"残念 + ながらも"},{"w":"명사","f":"子ども + ながらも"}],"rule":["1. 동사는 ます형으로 바꾼다: 1그룹은 어미 う단을 い단으로(知る → 知り).","2. 뒤에 ながらも를 붙인다: 知りながらも.","3. い형용사는 사전형 그대로(狭いながらも), な형용사는 어간(残念ながらも), 명사는 그대로(子どもながらも) 붙인다."],"why":"","nu":"앞의 사실·상태를 인정하면서 그와 맞지 않는 내용을 뒤에 말하는 역접이다. 앞과 뒤의 주어가 같은 것이 보통이다. 동사는 知る, 言う, 思う처럼 상태적인 말이나 ている형(知っていながらも)과 잘 어울린다. 문장체에 가깝고 회화에서는 けど・のに가 일반적이다. 狭いながらも楽しい我が家는 자주 쓰이는 표현이다.","cmp":[{"g":"～のに","d":"불만·의외의 감정이 강한 회화적 역접. ながらも는 담담하게 사실을 인정하는 문장체 느낌이다."},{"g":"～ながら(동시 동작)","d":"동작 동사 + ながら는 동시 동작이 되므로, 역접을 분명히 하려면 も를 붙인 ながらも를 쓴다."}],"ex":[{"jp":"体[からだ]に悪[わる]いと知[し]りながらも、たばこがやめられない。","ko":"몸에 나쁜 줄 알면서도 담배를 끊지 못한다."},{"jp":"狭[せま]いながらも、楽[たの]しい我[わ]が家[や]だ。","ko":"좁지만 즐거운 우리 집이다."},{"jp":"彼[かれ]は子[こ]どもながらも、しっかりした意見[いけん]を持[も]っている。","ko":"그는 아이이면서도 확실한 의견을 가지고 있다."}],"dr":[{"t":"make","q":"思う → ～ながらも","a":"思いながらも","hint":"1그룹: う → い(ます형) + ながらも"},{"t":"make","q":"小さい → ～ながらも","a":"小さいながらも","hint":"い형용사 사전형 + ながらも"},{"t":"fill","q":"悪[わる]いと思[おも]い（　）、つい嘘[うそ]をついてしまった。","a":"ながらも","opts":["ながらも","次第","たびに","ついでに"]}],"src":[],"vf":0,"u":31,"g":1,"gp":"gg_N1_11"},{"id":"g1_227","t":"～ば～ものを","ko":"~했으면 ~했을 것을 (후회·유감)","cat":"역접","conn":[{"w":"동사 ば형","f":"出る → 出れば + 間に合ったものを"},{"w":"1그룹 동사","f":"言う → 言えば + よかったものを"},{"w":"い형용사","f":"安い → 安ければ + 買ったものを"},{"w":"な형용사·명사","f":"暇なら(ば) + 行ったものを"}],"rule":["1. 앞 동사를 ば형으로 만든다. 2그룹은 る를 れ로 바꾸고 ば(出る → 出れば), 1그룹은 어미 う단을 え단으로 바꾸고 ば(言う → 言えば).","2. 뒤에 실제로는 일어나지 않은 결과를 た형으로 둔다: 間に合った.","3. 끝에 ものを를 붙인다: 出れば間に合ったものを."],"why":"","nu":"'그렇게 했으면 좋은 결과가 됐을 텐데 실제로는 그러지 않았다'는 후회·안타까움·불만을 나타낸다. 문장을 ものを로 끝내 뒤를 생략하는 경우가 많다. ～ばいいものを(하면 될 것을), ～ばよかったものを가 자주 쓰인다. 다소 문어적이고 예스러운 말투로, 회화에서는 ～のに가 일반적이다. 상대의 행동을 탓할 때도 쓴다(言ってくれればよかったものを).","cmp":[{"g":"～ば～のに","d":"뜻은 거의 같고 회화에서 흔하다. ものを는 더 문어적이고 감정이 짙다."}],"ex":[{"jp":"もう少[すこ]し早[はや]く家[いえ]を出[で]れば、間[ま]に合[あ]ったものを。","ko":"조금만 더 일찍 집을 나왔으면 시간에 맞췄을 것을."},{"jp":"困[こま]っているなら、言[い]ってくれればよかったものを。","ko":"곤란하면 말해 줬으면 좋았을 것을."},{"jp":"黙[だま]っていればいいものを、彼[かれ]は余計[よけい]なことを言[い]った。","ko":"가만히 있으면 될 것을, 그는 쓸데없는 말을 했다."}],"dr":[{"t":"make","q":"勉強する / 合格した → ～ば～ものを","a":"勉強すれば合格したものを","hint":"する는 すれば, 뒤는 た형 + ものを"},{"t":"make","q":"聞く / わかった → ～ば～ものを","a":"聞けばわかったものを","hint":"1그룹: く를 け로 바꾸고 ば + た형 + ものを"},{"t":"fill","q":"薬[くすり]を飲[の]めば治[なお]った（　）、彼[かれ]は飲[の]まなかった。","a":"ものを","opts":["ものを","ものの","ものだから","ものなら"]}],"src":[],"vf":0,"u":32,"g":1,"gp":"gg_N1_11"},{"id":"g1_018","t":"～からある","ko":"~이나 되는 (무게·길이·크기)","cat":"비교·정도","conn":[{"w":"수량(숫자 + 단위)","f":"50キロ + からある + 荷物"}],"rule":["1. 숫자와 단위로 된 수량 뒤에 からある를 붙인다. 50キロ → 50キロからある.","2. 그 뒤에 명사를 붙여 '그만큼이나 되는 ~'라고 꾸민다. 50キロからある荷物."],"why":"","nu":"수량이 크다는 것을 강조하며 '적어도 그 정도, 그 이상'이라는 느낌을 준다. 무게・길이・높이・크기에 주로 쓴다. 가격에는 からする(10万円からする時計), 사람 수에는 からの(1000人からの観客)를 많이 쓴다. 작은 수에는 쓰지 않는다. 문어적이다.","cmp":[{"g":"～からする","d":"금액에 쓴다(100万円からする車)."},{"g":"～からの","d":"사람 수나 개수에 많이 쓴다(1万人からの人)."}],"ex":[{"jp":"30[さんじゅっ]キロからある荷物[にもつ]を一人[ひとり]で運[はこ]んだ。","ko":"30킬로나 되는 짐을 혼자 옮겼다."},{"jp":"2[に]メートルからある大[おお]きな魚[さかな]が釣[つ]れた。","ko":"2미터나 되는 큰 물고기가 낚였다."},{"jp":"頂上[ちょうじょう]まで10[じゅっ]キロからある道[みち]を歩[ある]いて登[のぼ]った。","ko":"정상까지 10킬로나 되는 길을 걸어서 올랐다."}],"dr":[{"t":"make","q":"100キロ・岩 → ～からある～","a":"100キロからある岩","hint":"수량 + からある + 명사"},{"t":"make","q":"3メートル・壁 → ～からある～","a":"3メートルからある壁","hint":"수량 + からある + 명사"},{"t":"fill","q":"彼[かれ]は50[ごじゅっ]キロ（　）米[こめ]の袋[ふくろ]を軽々[かるがる]と持[も]ち上[あ]げた。","a":"からある","opts":["からある","からして","からといって","からには"]}],"src":["https://nihongokyoshi-net.com/2019/06/25/jlptn1-grammar-karaaru-karasuru-karano"],"vf":1,"u":32,"g":1,"gp":"gg_N1_11"},{"id":"g1_019","t":"～からする","ko":"(가격이) ~이나 하는","cat":"비교·정도","conn":[{"w":"명사(금액 수량)","f":"100万円 + からする"},{"w":"명사 수식","f":"100万円からする + 時計"}],"rule":["1. 금액을 나타내는 수량 명사를 그대로 둔다(100万円).","2. 바로 뒤에 から를 붙인다(100万円から).","3. 이어서 する를 붙인다(100万円からする). 명사를 꾸밀 때는 그대로 뒤에 명사를 둔다(100万円からする時計)."],"why":"기점의 から(~부터)에 동사 する가 붙은 꼴로, '그 수량에서부터 시작한다', 즉 적어도 그만큼이라는 뜻이 된다.","nu":"문어적인 표현. 주로 가격에 쓰며, 말하는 사람이 그 금액을 '많다, 비싸다'고 느낄 때만 쓴다. 적은 금액에는 쓰지 않는다. 무게·길이·크기에는 からある, 사람 수 등에는 からの를 주로 쓴다.","cmp":[{"g":"～からある","d":"무게·길이·크기가 많음을 강조한다(10キロからある荷物). からする는 주로 가격."},{"g":"～からの","d":"뒤에 명사를 바로 꾸미며 사람 수 등 많은 수량을 강조한다(1万人からの人)."}],"ex":[{"jp":"この着物[きもの]は百万円[ひゃくまんえん]からするそうだ。","ko":"이 기모노는 백만 엔이나 한다고 한다."},{"jp":"彼[かれ]は一台[いちだい]三千万円[さんぜんまんえん]からする車[くるま]に乗[の]っている。","ko":"그는 한 대에 3천만 엔이나 하는 차를 타고 있다."},{"jp":"一泊[いっぱく]十万円[じゅうまんえん]からするホテルに泊[と]まった。","ko":"1박에 10만 엔이나 하는 호텔에 묵었다."}],"dr":[{"t":"make","q":"百万円 → ～からする（時計を修飾）","a":"百万円からする時計","hint":"금액 + からする + 명사"},{"t":"make","q":"一泊五万円 → ～からする（ホテルを修飾）","a":"一泊五万円からするホテル","hint":"금액 + からする + 명사"},{"t":"fill","q":"この指輪[ゆびわ]は300万円[さんびゃくまんえん]（　）そうだ。","a":"からする","opts":["からする","からして","からには","からこそ"]}],"src":["https://nihongokyoshi-net.com/2019/06/25/jlptn1-grammar-karaaru-karasuru-karano","https://bunpro.jp/fr/grammar_points/%E3%81%8B%E3%82%89%E3%81%99%E3%82%8B"],"vf":1,"u":32,"g":1,"gp":"gg_N1_11"},{"id":"g1_020","t":"～からの","ko":"~이나 되는 (많은 수량)","cat":"비교·정도","conn":[{"w":"명사(수량) + 명사","f":"5万人 + からの + 観客"}],"rule":["1. 많은 수량을 나타내는 명사를 둔다(5万人).","2. 바로 뒤에 からの를 붙인다(5万人からの).","3. 그 뒤에 꾸밈을 받는 명사를 둔다(5万人からの観客)."],"why":"","nu":"문어적. 수가 예상보다 많다는 놀람을 담아 뒤의 명사를 꾸민다. 사람 수에 특히 많이 쓴다. からの의 기본 용법인 출발점·발신자(母からの手紙: 어머니로부터의 편지)는 초급 용법이고, 여기서는 N1의 수량 강조 용법이다.","cmp":[{"g":"～からの（기점）","d":"母からの手紙처럼 '~로부터의'라는 출발점·보낸 사람을 나타낸다. 수량 강조와는 앞에 오는 말(사람·장소인지 수량인지)로 구별한다."},{"g":"～からする","d":"주로 가격이 많음을 강조하며 문장 끝에도 온다."}],"ex":[{"jp":"5万人[ごまんにん]からの観客[かんきゃく]がスタジアムに集[あつ]まった。","ko":"5만 명이나 되는 관객이 경기장에 모였다."},{"jp":"彼[かれ]は一億円[いちおくえん]からの借金[しゃっきん]を抱[かか]えている。","ko":"그는 1억 엔이나 되는 빚을 지고 있다."},{"jp":"その祭[まつ]りには毎年[まいとし]百万人[ひゃくまんにん]からの人[ひと]が訪[おとず]れる。","ko":"그 축제에는 매년 백만 명이나 되는 사람이 찾아온다."}],"dr":[{"t":"make","q":"3万人 → ～からの（ファンを修飾）","a":"3万人からのファン","hint":"수량 + からの + 명사"},{"t":"make","q":"千人 → ～からの（署名を修飾）","a":"千人からの署名","hint":"수량 + からの + 명사"},{"t":"fill","q":"会場[かいじょう]には2万人[にまんにん]（　）人[ひと]が集[あつ]まった。","a":"からの","opts":["からの","からして","からといって","からには"]}],"src":["https://nihongokyoshi-net.com/2019/06/25/jlptn1-grammar-karaaru-karasuru-karano"],"vf":1,"u":32,"g":1,"gp":"gg_N1_12"},{"id":"g1_026","t":"～ごとく・～ごとき","ko":"~와 같이 / ~와 같은","cat":"비교·정도","conn":[{"w":"명사 + の (동사·형용사 수식)","f":"矢の + ごとく"},{"w":"명사 + の (명사 수식)","f":"鬼の + ごとき + 顔"},{"w":"동사 사전형・た형 + が","f":"眠る + がごとく"},{"w":"명사 바로 뒤 (낮춤)","f":"私 + ごとき"}],"rule":["1. 명사에 の를 붙이고, ように 자리를 ごとく로 바꾼다(矢のように → 矢のごとく).","2. 뒤에 동사나 형용사를 둔다(矢のごとく過ぎる).","3. 명사를 꾸밀 때는 ような 자리를 ごとき로 바꾼다(鬼のような顔 → 鬼のごとき顔)."],"why":"고전 비유 조동사 ごとし의 연용형이 ごとく, 연체형이 ごとき다. 현대어 ように・ような에 해당한다.","nu":"문어체. 소설·연설·속담 등에서 쓴다. 명사 바로 뒤에 붙는 ごとき(私ごとき, お前ごとき)는 비유가 아니라 '~따위'라는 낮춤·겸손의 뜻이다.","cmp":[{"g":"～ように・～ような","d":"같은 뜻의 일상 표현. ごとく・ごとき는 문어적이다."}],"ex":[{"jp":"時間[じかん]は矢[や]のごとく過[す]ぎていく。","ko":"시간은 화살과 같이 지나간다."},{"jp":"彼[かれ]は鬼[おに]のごとき顔[かお]で私[わたし]をにらんだ。","ko":"그는 도깨비 같은 얼굴로 나를 노려보았다."},{"jp":"私[わたし]ごときにそんな大役[たいやく]は務[つと]まりません。","ko":"저 같은 사람이 그런 큰 역할은 감당하지 못합니다."}],"dr":[{"t":"make","q":"雪のように白い → ごとく","a":"雪のごとく白い","hint":"ように를 ごとく로"},{"t":"make","q":"天使のような心 → ごとき","a":"天使のごとき心","hint":"ような를 ごとき로"},{"t":"fill","q":"嵐[あらし]の（　）拍手[はくしゅ]が起[お]こった。","a":"ごとき","opts":["ごとき","ごとく","ごとし","らしく"]}],"src":["https://bunpro.jp/grammar_points/732","https://jlptsensei.com/learn-japanese-grammar/ごとき-ごとく-ごとし-gotoki-gotoku-gotoshi-meaning/"],"vf":1,"u":32,"g":1,"gp":"gg_N1_12"},{"id":"g1_038","t":"～というところだ","ko":"대략 ~ 정도다, 기껏해야 ~다","cat":"비교·정도","conn":[{"w":"명사(수량·정도)","f":"8割 + というところだ"}],"rule":["1. 수량이나 단계를 나타내는 명사를 놓는다(8割).","2. 그 뒤에 というところだ를 그대로 붙인다. 앞 명사는 바뀌지 않는다.","3. 정중하게는 というところです, 추측을 더하면 というところだろう가 된다."],"why":"","nu":"수량·정도를 '대충 그 정도이고, 그렇게 많지는 않다'고 평가할 때 쓴다. 화자의 대략적인 판단이므로 정확한 수치 보고에는 맞지 않다. 회화와 글 모두에서 쓰며, 회화에서는 ってところだ로 줄이기도 한다.","cmp":[{"g":"～といったところだ","d":"뜻과 쓰임이 거의 같다. 둘 다 '대략 그 정도, 많아야 그 정도'라는 평가를 나타낸다."}],"ex":[{"jp":"仕事[しごと]の進[すす]み具合[ぐあい]は、まだ6割[わり]というところです。","ko":"일의 진척 상황은 아직 60% 정도입니다."},{"jp":"合格[ごうかく]できるかどうかは、五分五分[ごぶごぶ]というところだ。","ko":"합격할 수 있을지는 반반 정도다."},{"jp":"この店[みせ]のランチは、千円[せんえん]前後[ぜんご]というところだ。","ko":"이 가게 점심은 천 엔 안팎 정도다."}],"dr":[{"t":"make","q":"半分 → ～というところだ","a":"半分というところだ","hint":"명사 + というところだ"},{"t":"make","q":"7割 → ～というところだ","a":"7割というところだ","hint":"명사 + というところだ"},{"t":"fill","q":"完成度[かんせいど]はまだ6割[わり]（　）。","a":"というところだ","opts":["というところだ","ところだった","どころではない","わけにはいかない"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/というところだ-といったところだ-iu-tokoro-da-meaning/","https://bunpro.jp/grammar_points/866"],"vf":1,"u":33,"g":1,"gp":"gg_N1_12"},{"id":"g1_040","t":"～といったところだ","ko":"대략 ~ 정도다, 많아야 ~다","cat":"비교·정도","conn":[{"w":"명사(수량·정도)","f":"3時間 + といったところだ"}],"rule":["1. 수량이나 수준을 나타내는 명사를 놓는다(3時間).","2. 그 뒤에 といったところだ를 그대로 붙인다(3時間といったところだ).","3. 정중하게는 といったところです가 된다. 앞 명사는 바뀌지 않는다."],"why":"","nu":"'대충 그 정도이고 그 이상은 아니다'라고 대략 평가할 때 쓴다. せいぜい・多くても 등과 잘 어울린다. 정확한 값을 말하는 표현이 아니다. 회화와 글 모두에서 쓰며, 회화에서는 ってところだ로 줄이기도 한다.","cmp":[{"g":"～というところだ","d":"뜻과 쓰임이 거의 같다."}],"ex":[{"jp":"毎日[まいにち]の勉強時間[べんきょうじかん]は、せいぜい3時間[じかん]といったところだ。","ko":"매일 공부 시간은 기껏해야 3시간 정도다."},{"jp":"私[わたし]の英語[えいご]は、まだ初級[しょきゅう]といったところです。","ko":"제 영어는 아직 초급 정도입니다."},{"jp":"ここから駅[えき]までは、歩[ある]いて10分[ぷん]といったところだ。","ko":"여기서 역까지는 걸어서 10분 정도다."}],"dr":[{"t":"make","q":"3時間 → ～といったところだ","a":"3時間といったところだ","hint":"명사 + といったところだ"},{"t":"make","q":"初級 → ～といったところだ","a":"初級といったところだ","hint":"명사 + といったところだ"},{"t":"fill","q":"参加者[さんかしゃ]は、多[おお]くても30人[にん]（　）。","a":"といったところだ","opts":["といったところだ","というものではない","ところだった","ことにする"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/というところだ-といったところだ-iu-tokoro-da-meaning/","https://bunpro.jp/grammar_points/866"],"vf":1,"u":33,"g":1,"gp":"gg_N1_12"},{"id":"g1_043","t":"～とは比べものにならない","ko":"~와는 비교도 안 된다","cat":"비교·정도","conn":[{"w":"명사","f":"車 + とは比べものにならない"}],"rule":["1. 비교 대상이 되는 명사 뒤에 とは를 붙인다(車とは).","2. 그 뒤에 比べもの(비교할 거리)를 놓는다.","3. 마지막에 にならない(なる의 부정)를 붙여 車とは比べものにならない가 된다."],"why":"","nu":"주어와 비교 대상 사이의 차이가 너무 커서 견줄 수 없음을 강조한다. 어느 쪽이 뛰어난지는 문맥으로 정해지며, 주어 쪽이 훨씬 못한 경우에도 쓴다. 比べ物로도 쓴다. 뒤에 ほど를 붙여 '비교가 안 될 만큼 ~하다'로도 쓴다. 회화와 글 모두에서 쓴다.","cmp":[{"g":"～に比べて","d":"단순히 둘을 비교해 정도 차이를 말한다. 比べものにならない는 차이가 너무 커서 비교 자체가 안 된다는 강조다."}],"ex":[{"jp":"新幹線[しんかんせん]の速[はや]さは、車[くるま]とは比[くら]べものにならない。","ko":"신칸센의 속도는 자동차와는 비교도 안 된다."},{"jp":"今[いま]の生活[せいかつ]は、十年前[じゅうねんまえ]とは比[くら]べものにならないほど便利[べんり]だ。","ko":"지금 생활은 10년 전과는 비교가 안 될 만큼 편리하다."},{"jp":"プロの料理[りょうり]は、私[わたし]が作[つく]るものとは比[くら]べものにならない。","ko":"프로의 요리는 내가 만드는 것과는 비교도 안 된다."}],"dr":[{"t":"make","q":"車 → ～とは比べものにならない","a":"車とは比べものにならない","hint":"명사 + とは + 比べものにならない"},{"t":"make","q":"昔 → ～とは比べものにならない","a":"昔とは比べものにならない","hint":"명사 + とは + 比べものにならない"},{"t":"fill","q":"姉[あね]の歌[うた]のうまさは、私[わたし]（　）比[くら]べものにならない。","a":"とは","opts":["とは","より","まで","さえ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/とは比べものにならない-towa-kurabemono-ni-naranai-meaning/"],"vf":1,"u":33,"g":1,"gp":"gg_N1_12"},{"id":"g1_062","t":"～にひきかえ","ko":"~와는 대조적으로, ~와 달리","cat":"비교·정도","conn":[{"w":"명사","f":"兄 + にひきかえ"},{"w":"동사 보통형 + の","f":"よく働く + の + にひきかえ"},{"w":"い형용사 + の","f":"明るい + の + にひきかえ"},{"w":"な형용사 + なの","f":"まじめな + の + にひきかえ"}],"rule":["1. 비교의 기준이 되는 명사1 뒤에 にひきかえ를 붙인다(兄にひきかえ).","2. 뒤에 대조되는 명사2와 は를 쓴다(弟は).","3. 문장을 받을 때는 보통형에 の를 붙여 명사처럼 만든 뒤 にひきかえ를 붙인다(まじめなのにひきかえ)."],"why":"","nu":"문어적이며 두 대상을 맞세워 말하는 사람의 평가(좋다/나쁘다)를 강하게 드러낸다. 뒤 문장에는 앞과 반대되는 평가가 온다. 단순한 사실 비교(크기·숫자)에는 잘 쓰지 않는다.","cmp":[{"g":"～に比べて","d":"객관적인 비교에도 쓴다(去年に比べて人口が増えた). にひきかえ는 반대되는 성질을 대조하며 주관적 평가가 들어간다."}],"ex":[{"jp":"兄[あに]にひきかえ、弟[おとうと]は全然[ぜんぜん]勉強[べんきょう]しない。","ko":"형과는 대조적으로 남동생은 전혀 공부하지 않는다."},{"jp":"去年[きょねん]の夏[なつ]にひきかえ、今年[ことし]はずいぶん涼[すず]しい。","ko":"작년 여름과는 달리 올해는 꽤 시원하다."},{"jp":"姉[あね]がまじめなのにひきかえ、妹[いもうと]はのんびりしている。","ko":"언니가 성실한 것과는 대조적으로 여동생은 느긋하다."}],"dr":[{"t":"make","q":"兄 → ～にひきかえ","a":"兄にひきかえ","hint":"명사 + にひきかえ"},{"t":"make","q":"姉がまじめだ → ～にひきかえ","a":"姉がまじめなのにひきかえ","hint":"な형용사는 だ를 な로 바꾸고 の + にひきかえ"},{"t":"fill","q":"にぎやかな昼[ひる]（　）、夜[よる]の町[まち]は静[しず]かだ。","a":"にひきかえ","opts":["にひきかえ","にとどまらず","にすら","に先駆けて"]}],"src":["https://nihongokyoshi-net.com/2019/04/26/jlptn1-grammar-nihikikae/"],"vf":1,"u":33,"g":1,"gp":"gg_N1_12"},{"id":"g1_063","t":"～にもまして","ko":"~보다 더, ~이상으로","cat":"비교·정도","conn":[{"w":"명사","f":"去年 + にもまして"},{"w":"의문사","f":"何 + にもまして"},{"w":"의문사(때)","f":"いつ + にもまして"}],"rule":["1. 비교의 기준이 되는 명사 뒤에 にもまして를 붙인다(去年にもまして).","2. 뒤에 그 기준보다 정도가 더한 상태를 쓴다(去年にもまして暑い).","3. 의문사에 붙으면 '무엇보다도(何にもまして)', '평소보다 더(いつにもまして)'라는 뜻이 된다."],"why":"조사 に + も + 増す(늘다, 더해지다)의 て형 増して로 이루어져 '~보다도 더해져서'라는 뜻이 된다.","nu":"문어적이다. 기준이 되는 것도 이미 정도가 높다는 전제가 있다(작년도 더웠는데 올해는 그보다 더). 何にもまして・いつにもまして・誰にもまして는 굳어진 표현으로 자주 쓴다.","cmp":[{"g":"～より","d":"단순 비교. にもまして는 기준도 이미 정도가 높았음을 전제로 '그보다 더'를 강조한다."}],"ex":[{"jp":"今年[ことし]の夏[なつ]は去年[きょねん]にもまして暑[あつ]い。","ko":"올해 여름은 작년보다 더 덥다."},{"jp":"何[なに]にもまして健康[けんこう]が大切[たいせつ]だ。","ko":"무엇보다도 건강이 중요하다."},{"jp":"今日[きょう]の彼女[かのじょ]はいつにもまして元気[げんき]だ。","ko":"오늘 그녀는 평소보다 더 활기차다."}],"dr":[{"t":"make","q":"去年 → ～にもまして","a":"去年にもまして","hint":"명사 + にもまして"},{"t":"make","q":"何 → ～にもまして","a":"何にもまして","hint":"의문사 + にもまして = 무엇보다도"},{"t":"fill","q":"試験[しけん]が近[ちか]づき、彼[かれ]は以前[いぜん]（　）よく勉強[べんきょう]するようになった。","a":"にもまして","opts":["にもまして","にひきかえ","にすら","にあっては"]}],"src":["https://bunpro.jp/grammar_points/863"],"vf":1,"u":34,"g":1,"gp":"gg_N1_12"},{"id":"g1_080","t":"～のごとき＋명사","ko":"~와 같은 (명사)","cat":"비교·정도","conn":[{"w":"명사 + 명사","f":"天使のごとき + 笑顔"},{"w":"명사 + 동사(ごとく)","f":"矢のごとく + 過ぎる"}],"rule":["1. 비유할 명사 뒤에 の를 넣는다: 天使の.","2. ごとき를 붙이고 바로 뒤에 꾸밀 명사를 쓴다: 天使のごとき笑顔.","3. 동사·형용사를 꾸밀 때는 ごとき 대신 ごとく를 쓴다: 矢のごとく過ぎる."],"why":"ごとき는 고전어 조동사 ごとし의 연체형(명사를 꾸미는 형태)이고, ごとく는 연용형이다. 현대어의 ような / ように에 해당한다.","nu":"문어적이고 과장된 느낌을 주는 비유 표현으로, 소설·연설·관용구에서 쓴다. 'AのごときB'는 'AのようなB'와 같은 뜻이다. 명사 뒤에 の 없이 바로 붙는 '私ごとき・彼ごとき'는 '~따위'라는 겸손이나 깔봄의 뜻이 되므로 구별해야 한다.","cmp":[{"g":"～のような","d":"같은 뜻의 일반적인 표현으로 회화에서 쓴다. ごとき는 문어적이다."},{"g":"명사 + ごとき (の 없음)","d":"私ごときに는 '저 같은 사람에게'처럼 자기를 낮추거나 상대를 깔보는 뜻이다."}],"ex":[{"jp":"彼[かれ]は村人[むらびと]たちから神[かみ]のごとき存在[そんざい]として敬[うやま]われている。","ko":"그는 마을 사람들에게 신과 같은 존재로 공경받고 있다."},{"jp":"彼女[かのじょ]は天使[てんし]のごとき笑顔[えがお]で子[こ]どもたちを迎[むか]えた。","ko":"그녀는 천사 같은 미소로 아이들을 맞이했다."},{"jp":"楽[たの]しかった夏休[なつやす]みは、矢[や]のごとく過[す]ぎていった。","ko":"즐거웠던 여름방학은 화살처럼 지나갔다."}],"dr":[{"t":"make","q":"天使 + 笑顔 → ～のごとき～","a":"天使のごとき笑顔","hint":"명사1 + の + ごとき + 명사2"},{"t":"make","q":"矢 + 過ぎる → ～のごとく～","a":"矢のごとく過ぎる","hint":"동사를 꾸밀 때는 명사 + の + ごとく"},{"t":"fill","q":"彼[かれ]は鬼[おに]の（　）顔[かお]で怒[おこ]った。","a":"ごとき","opts":["ごとき","ごとく","ばかりに","ついでに"]}],"src":["https://bunpro.jp/grammar_points/732","https://www.vnjpclub.com/en/n1-grammar/no-gotoki.html"],"vf":1,"u":34,"g":1,"gp":"gg_N1_12"},{"id":"g1_084","t":"～の極み","ko":"~의 극치, 더없이 ~함","cat":"비교·정도","conn":[{"w":"명사(한정적)","f":"贅沢の + 極み"},{"w":"명사(감정)","f":"感激の + 極み"}],"rule":["1. 명사 뒤에 の를 넣는다: 贅沢の.","2. 極み를 붙인다: 贅沢の極み.","3. 문장 끝에서는 だ/です를 붙인다: 贅沢の極みだ."],"why":"極み는 '맨 끝, 극한'을 뜻하는 명사로, 동사 極める(극에 이르다)와 같은 한자를 쓴다.","nu":"격식 있는 문어적 표현으로, 어떤 상태나 감정이 더 이상 없을 만큼 극에 달했음을 말한다. 贅沢の極み・感激の極み・痛恨の極み・疲労の極み처럼 굳어진 조합으로 주로 쓰며, 아무 명사에나 붙이지 않는다(料理の極み처럼 단순한 사물 명사에는 어색하다). 좋은 일·나쁜 일 모두에 쓴다.","cmp":[{"g":"～の至り","d":"光栄の至り・恐縮の至り처럼 주로 말하는 사람의 감정을 나타내는 격식 인사말에 쓴다. 極み는 疲労の極み처럼 상태 묘사에도 쓴다."}],"ex":[{"jp":"一流[いちりゅう]ホテルで一週間[いっしゅうかん]過[す]ごすなんて、贅沢[ぜいたく]の極[きわ]みだ。","ko":"일류 호텔에서 일주일을 보내다니 더없는 사치다."},{"jp":"決勝[けっしょう]で敗[やぶ]れたのは、痛恨[つうこん]の極[きわ]みです。","ko":"결승에서 진 것은 통한의 극치입니다."},{"jp":"三日間[みっかかん]寝[ね]ずに働[はたら]いて、疲労[ひろう]の極[きわ]みに達[たっ]した。","ko":"사흘 동안 자지 않고 일해서 피로가 극에 달했다."}],"dr":[{"t":"make","q":"贅沢 → ～の極み","a":"贅沢の極み","hint":"명사 + の + 極み"},{"t":"make","q":"感激 → ～の極み","a":"感激の極み","hint":"명사 + の + 極み"},{"t":"fill","q":"このような賞[しょう]をいただき、感激[かんげき]の（　）です。","a":"極み","opts":["極み","手前","ごとき","くせ"]}],"src":["https://nihongokyoshi-net.com/2019/07/05/jlptn1-grammar-nokiwami/","https://Bunpro.jp/grammar_points/%E3%81%AE%E6%A5%B5%E3%81%BF"],"vf":1,"u":34,"g":1,"gp":"gg_N1_12"},{"id":"g1_085","t":"～の至り","ko":"더없이 ~함 (격식 인사말)","cat":"비교·정도","conn":[{"w":"명사(한정적)","f":"光栄の + 至り"},{"w":"명사(한정적)","f":"恐縮の + 至り"},{"w":"관용구","f":"若気の + 至り"}],"rule":["1. 동사 至る(이르다)의 어미 る를 り로 바꾸면 명사 至り가 된다(ます형이 명사로 쓰인 것).","2. 감정을 나타내는 명사 뒤에 の를 넣고 至り를 붙인다: 光栄の至り.","3. 문장 끝에서는 です / でございます를 붙인다: 光栄の至りです."],"why":"","nu":"수상 소감, 공식 인사, 편지 등에서 쓰는 매우 격식 있는 표현이다. 光栄の至り・恐縮の至り・感激の至り처럼 정해진 명사와만 굳어져 쓰이며, 아무 감정어에나 붙이지 않는다(驚きの至り는 어색하다). 若気の至り는 '젊은 혈기에 저지른 일'이라는 별도의 관용구다.","cmp":[{"g":"～の極み","d":"贅沢の極み・疲労の極み처럼 상태 묘사에도 쓴다. 至り는 주로 말하는 사람의 감정을 격식 있게 표현하는 인사말에 쓴다."}],"ex":[{"jp":"このような賞[しょう]をいただき、光栄[こうえい]の至[いた]りです。","ko":"이런 상을 받게 되어 더없는 영광입니다."},{"jp":"わざわざお越[こ]しいただき、恐縮[きょうしゅく]の至[いた]りでございます。","ko":"일부러 와 주셔서 송구하기 그지없습니다."},{"jp":"学生[がくせい]時代[じだい]のいたずらは、若気[わかげ]の至[いた]りだった。","ko":"학창 시절의 장난은 젊은 혈기 탓이었다."}],"dr":[{"t":"make","q":"光栄 → ～の至り","a":"光栄の至り","hint":"명사 + の + 至り(至る → 至り)"},{"t":"make","q":"恐縮 → ～の至り","a":"恐縮の至り","hint":"명사 + の + 至り"},{"t":"fill","q":"若[わか]い頃[ころ]の失敗[しっぱい]は、若気[わかげ]の（　）だ。","a":"至り","opts":["至り","手前","ごとき","いかん"]}],"src":["https://bunpro.jp/grammar_points/の至り"],"vf":1,"u":34,"g":1,"gp":"gg_N1_12"},{"id":"g1_111","t":"～並み","ko":"~수준, ~와 같은 정도","cat":"비교·정도","conn":[{"w":"명사 + 並みの + 명사","f":"プロ + 並みの + 腕前"},{"w":"명사 + 並みだ","f":"例年 + 並みだ"},{"w":"명사 + 並みに","f":"大人 + 並みに"}],"rule":["1. 비교 기준이 되는 명사 바로 뒤에 並み를 붙인다(활용 없음): プロ並み.","2. 뒤의 명사를 꾸밀 때는 の를 넣는다: プロ並みの腕前.","3. 문장 끝에서는 並みだ, 동사를 꾸밀 때는 並みに가 된다."],"why":"","nu":"앞 명사와 같은 수준·정도라는 뜻이다. プロ並み, 大人並み처럼 '그 정도로 대단하다'는 칭찬에도, 例年並み・平年並み(평년 수준)처럼 중립적인 비교에도 쓴다. 人並み(남들만큼), 世間並み(세상 보통 수준)처럼 굳어진 말도 많다. 회화와 문장 모두에 쓴다. 한국어 '~만큼'에 끌려 동사 뒤에 붙이는 실수에 주의한다(並み는 명사에만 붙는다).","cmp":[{"g":"～くらい / ～ほど","d":"동사·형용사 등 여러 품사에 붙는 정도 표현이다. 並み는 명사에만 붙으며 '그 기준과 같은 수준'이라는 뜻이 뚜렷하다."}],"ex":[{"jp":"彼女[かのじょ]の料理[りょうり]の腕[うで]はプロ並[な]みだ。","ko":"그녀의 요리 솜씨는 프로 수준이다."},{"jp":"今年[ことし]の夏[なつ]は例年[れいねん]並[な]みの暑[あつ]さになるそうだ。","ko":"올여름은 평년 수준의 더위가 될 것이라고 한다."},{"jp":"あの子[こ]は小学生[しょうがくせい]なのに、大人[おとな]並[な]みによく食[た]べる。","ko":"저 아이는 초등학생인데도 어른만큼 잘 먹는다."}],"dr":[{"t":"make","q":"プロ ＋ 実力 → ～並みの","a":"プロ並みの実力","hint":"명사 + 並み + の + 명사"},{"t":"make","q":"平年 → ～並みだ","a":"平年並みだ","hint":"명사 + 並み + だ"},{"t":"fill","q":"今年[ことし]の冬[ふゆ]は平年[へいねん]（　）の寒[さむ]さだった。","a":"並み","opts":["並み","ぶり","ずくめ","がてら"]}],"src":["https://bunpro.jp/grammar_points/992"],"vf":1,"u":34,"g":1,"gp":"gg_N1_12"},{"id":"g1_157","t":"～くらいなら","ko":"~할 바에는, ~할 정도라면","cat":"비교·정도","conn":[{"w":"동사 사전형","f":"並ぶ + くらいなら"},{"w":"동사 사전형(ぐらい)","f":"やめる + ぐらいなら"}],"rule":["1. 동사는 사전형을 그대로 쓴다: 並ぶ.","2. 사전형 뒤에 くらい(ぐらい)를 붙인다: 並ぶくらい.","3. 그 뒤에 なら를 붙인다: 並ぶくらいなら.","4. 뒤 문장에는 ほうがいい・ほうがましだ처럼 차라리 고르는 쪽이 온다."],"why":"くらい(정도) + なら(~라면).","nu":"앞의 일을 아주 싫은 것으로 내세우고 '그럴 바에는 차라리 뒤의 것이 낫다'는 말하는 사람의 선택·주장을 나타낸다. 뒤에는 ほうがいい, ほうがましだ, ～する(의지) 등이 온다. 회화와 글 모두에 쓰며 くらい와 ぐらい 둘 다 쓴다.","cmp":[{"g":"～より(は)","d":"단순 비교(並ぶより別の店に行く). くらいなら는 앞의 일을 강하게 꺼리는 느낌이 있다."},{"g":"～なら","d":"일반 조건. くらいなら는 '그 정도의 일을 할 바에는'이라는 비하·거부감이 더해진다."}],"ex":[{"jp":"一時間[いちじかん]も並[なら]ぶくらいなら、別[べつ]の店[みせ]に行[い]く。","ko":"한 시간이나 줄을 설 바에는 다른 가게에 가겠다."},{"jp":"途中[とちゅう]でやめるくらいなら、最初[さいしょ]からやらないほうがいい。","ko":"도중에 그만둘 바에는 처음부터 안 하는 게 낫다."},{"jp":"毎朝[まいあさ]満員電車[まんいんでんしゃ]に乗[の]るくらいなら、自転車[じてんしゃ]で通[かよ]ったほうがましだ。","ko":"매일 아침 만원 전철을 탈 바에는 자전거로 다니는 게 낫다."}],"dr":[{"t":"make","q":"負ける → ～くらいなら","a":"負けるくらいなら","hint":"사전형 + くらいなら"},{"t":"make","q":"借ります → ～くらいなら","a":"借りるくらいなら","hint":"ます형을 사전형으로(借り → 借りる) + くらいなら"},{"t":"fill","q":"あの人[ひと]に頭[あたま]を下[さ]げる（　）、自分[じぶん]でやったほうがましだ。","a":"くらいなら","opts":["くらいなら","ばかりか","おかげで","ついでに"]}],"src":["https://bunpro.jp/grammar_points/829"],"vf":1,"u":35,"g":1,"gp":"gg_N1_12"},{"id":"g1_183","t":"～ごとく","ko":"~처럼, ~와 같이","cat":"비교·정도","conn":[{"w":"명사","f":"風の + ごとく"},{"w":"동사 보통형","f":"前に述べた + ごとく"},{"w":"동사 보통형","f":"知らない + かのごとく"}],"rule":["1. 명사에는 の를 붙인다: 風の.","2. 그 뒤에 ごとく를 붙여 동사를 꾸민다: 風のごとく走る.","3. 동사는 보통형에 바로(또는 が를 끼워) 붙인다: 述べたごとく.","4. 명사를 꾸밀 때는 ごとき를 쓴다: 夢のごとき日々."],"why":"문어 조동사 ごとし(如し, ~와 같다)의 연용형이 ごとく이고, 연체형이 ごとき이다.","nu":"문어체로 소설·연설·논설에서 쓴다. 회화의 ～ように에 해당한다. 비유(風のごとく)와 '앞에서 말한 대로'(前述のごとく)의 두 용법이 있다. '마치 ~인 것처럼'은 かのごとく로 나타낸다. 동사 て형에는 붙지 않는다.","cmp":[{"g":"～ように","d":"같은 뜻의 일반적인 회화·문장 표현. ごとく는 딱딱하고 고풍스럽다."},{"g":"～かのように","d":"'실제는 아닌데 마치 ~인 것처럼'. 문어로 바꾸면 かのごとく가 된다."}],"ex":[{"jp":"彼[かれ]は風[かぜ]のごとく走[はし]り去[さ]った。","ko":"그는 바람처럼 달려가 버렸다."},{"jp":"前[まえ]に述[の]べたごとく、計画[けいかく]は来年[らいねん]から始[はじ]まる。","ko":"앞에서 말한 바와 같이 계획은 내년부터 시작된다."},{"jp":"彼[かれ]は何[なに]も知[し]らないかのごとく振[ふ]る舞[ま]った。","ko":"그는 마치 아무것도 모르는 것처럼 행동했다."}],"dr":[{"t":"make","q":"鳥 → ～ごとく","a":"鳥のごとく","hint":"명사 + の + ごとく"},{"t":"make","q":"夢 / 日々 → ～ごとき + 명사","a":"夢のごとき日々","hint":"명사를 꾸밀 때는 の + ごとき"},{"t":"fill","q":"時間[じかん]は矢[や]の（　）過[す]ぎていく。","a":"ごとく","opts":["ごとく","ところ","かぎり","うえで"]}],"src":["https://bunpro.jp/grammar_points/732","https://jlptsensei.com/learn-japanese-grammar/ごとき-ごとく-ごとし-gotoki-gotoku-gotoshi-meaning/"],"vf":1,"u":35,"g":1,"gp":"gg_N1_13"},{"id":"g1_224","t":"～に越したことはない","ko":"~하는 것이 제일 좋다, ~보다 나은 것은 없다","cat":"비교·정도","conn":[{"w":"동사 사전형","f":"用心する + に越したことはない"},{"w":"い형용사","f":"安い + に越したことはない"},{"w":"な형용사","f":"安全(である) + に越したことはない"},{"w":"명사","f":"健康(である) + に越したことはない"}],"rule":["1. 바람직한 내용을 동사·い형용사는 사전형, な형용사·명사는 어간·명사(또는 である)로 두고 조사 に를 붙인다: 安いに.","2. 1그룹 동사 越す의 어미 す를 し로 바꾸고 た를 붙인다: 越す → 越した.","3. ことはない를 붙인다: 安いに越したことはない."],"why":"越す(넘다)의 과거형 越した + こと + は + ない로, '그것을 넘어서는 것은 없다', 즉 '그것이 가장 좋다'는 뜻이 된다.","nu":"누구나 인정하는 상식적인 판단을 말할 때 쓴다. 뒤에 'しかし/でも ~' 같은 단서가 이어져 '물론 그게 제일이지만 반드시 그럴 수는 없다'는 흐름이 되는 경우가 많다. 개인적 취향이 아니라 일반론에 쓴다. 회화와 문장 모두에서 쓰이며 약간 딱딱하다.","cmp":[{"g":"～に限る","d":"'~하는 게 최고다'로 말하는 사람 개인의 강한 주장·취향(夏はビールに限る). に越したことはない는 일반적·상식적 판단."},{"g":"～ほうがいい","d":"일상적인 조언. に越したことはない는 '당연히 그게 제일'이라는 판단을 더 객관적으로 말한다."}],"ex":[{"jp":"値段[ねだん]は安[やす]いに越[こ]したことはないが、品質[ひんしつ]も大切[たいせつ]だ。","ko":"값은 싼 게 제일이지만 품질도 중요하다."},{"jp":"雨[あめ]が降[ふ]るかもしれないから、傘[かさ]を持[も]っていくに越[こ]したことはない。","ko":"비가 올지도 모르니 우산을 가져가는 게 제일 좋다."},{"jp":"体[からだ]は丈夫[じょうぶ]であるに越[こ]したことはない。","ko":"몸은 튼튼한 게 제일이다."}],"dr":[{"t":"make","q":"早く準備する → ～に越したことはない","a":"早く準備するに越したことはない","hint":"동사 사전형 + に + 越す의 す를 し로 + た + ことはない"},{"t":"make","q":"近い → ～に越したことはない","a":"近いに越したことはない","hint":"い형용사 사전형 + に越したことはない"},{"t":"fill","q":"お金[かね]はある（　）が、それだけで幸[しあわ]せになれるわけではない。","a":"に越したことはない","opts":["に越したことはない","に堪えない","には及ばない","に難くない"]}],"src":[],"vf":0,"u":35,"g":1,"gp":"gg_N1_13"},{"id":"g1_238","t":"～んばかりに","ko":"금방이라도 ~할 듯이","cat":"비교·정도","conn":[{"w":"동사 ない형 어간","f":"泣く → 泣か + んばかりに"},{"w":"する (불규칙)","f":"する → せ + んばかりに"},{"w":"명사 수식","f":"あふれ + んばかりの + 笑顔"}],"rule":["1. 동사를 ない형 어간(未然形)으로 만든다. 1그룹은 어미 う단을 あ단으로: 泣く → 泣か.","2. 그 뒤에 んばかりに를 붙인다: 泣かんばかりに.","3. 2그룹은 る를 빼고 붙인다: あふれる → あふれんばかり.","4. 명사를 꾸밀 때는 んばかりの + 명사, 문말에서는 んばかりだ가 된다."],"why":"ん은 부정이 아니라 고어의 추량·의지 조동사 む에서 온 것으로, '막 ~하려는' 모습을 나타낸다. 여기에 '거의 그 정도'를 뜻하는 ばかり가 붙어 '당장이라도 ~할 것 같은 기세로'가 된다.","nu":"실제로 그 동작을 하지는 않았지만 그 직전처럼 보일 정도라는 비유 표현이다. 문어적이며 소설·묘사문에서 자주 쓴다. 주로 다른 사람이나 사물의 모습을 묘사하고, 말하는 이 자신의 의지적 행동에는 쓰지 않는다. と言わんばかりに(마치 ~라고 말하려는 듯이)는 관용적으로 많이 쓰인다. ん을 부정으로 오해하지 않도록 주의한다.","cmp":[{"g":"～そうに","d":"'~할 것 같이'라는 일반적인 양태 표현. んばかりに는 정도가 극단적이라는 과장과 문어적 느낌이 강하다."},{"g":"～んがために","d":"같은 ん을 쓰지만 '~하고자'라는 목적 표현이다."}],"ex":[{"jp":"その子[こ]は泣[な]かんばかりに、母親[ははおや]に頼[たの]んだ。","ko":"그 아이는 금방이라도 울 듯이 엄마에게 부탁했다."},{"jp":"彼女[かのじょ]はあふれんばかりの笑顔[えがお]で私[わたし]を迎[むか]えた。","ko":"그녀는 넘쳐흐를 듯한 미소로 나를 맞이했다."},{"jp":"店員[てんいん]は早[はや]く帰[かえ]れと言[い]わんばかりに、片付[かたづ]けを始[はじ]めた。","ko":"점원은 빨리 가라고 말하려는 듯이 정리를 시작했다."}],"dr":[{"t":"make","q":"倒れる → ～んばかりに","a":"倒れんばかりに","hint":"2그룹: る를 빼고 んばかりに"},{"t":"make","q":"飛び上がる → ～んばかりに","a":"飛び上がらんばかりに","hint":"1그룹: る(う단) → ら(あ단) + んばかりに"},{"t":"fill","q":"合格[ごうかく]の知[し]らせに、彼[かれ]は踊[おど]り出[だ]さ（　）喜[よろこ]んだ。","a":"んばかりに","opts":["んばかりに","んがために","ないことには","ずじまいで"]}],"src":[],"vf":0,"u":35,"g":1,"gp":"gg_N1_13"},{"id":"g1_241","t":"～極まりない","ko":"더없이 ~하다, ~하기 짝이 없다","cat":"비교·정도","conn":[{"w":"な형용사 어간","f":"危険 + 極まりない"},{"w":"な형용사","f":"危険な + こと + 極まりない"},{"w":"い형용사","f":"腹立たしい + こと + 極まりない"}],"rule":["1. な형용사의 단정 だ를 뺀다: 危険だ → 危険.","2. 어간 뒤에 極まりない를 바로 붙인다: 危険極まりない.","3. な형용사는 なこと, い형용사는 こと를 사이에 넣을 수도 있다: 危険なこと極まりない."],"why":"極まり(극에 달함, 끝)에 ない가 붙어 '끝이 없다'는 뜻이 되고, 그래서 '더할 나위 없이 ~하다'가 된다.","nu":"정도가 극단적임을 강하게 말하는 딱딱한 문어체 표현으로, 失礼, 危険, 不愉快, 無責任 같은 부정적 평가의 한자어 な형용사와 주로 함께 쓴다. ない가 붙어 있지만 부정의 뜻이 아니라 강조라는 점에 주의한다. 말하는 이의 강한 비난·불쾌감이 담기므로 일상 회화보다는 글이나 공식적인 발언에 어울린다. 極まる와 뜻은 거의 같다.","cmp":[{"g":"～極まる","d":"뜻은 거의 같다. 極まりない 쪽이 더 자주 쓰이며, 極まる는 感極まる 같은 관용구로도 쓰인다."},{"g":"～の極み","d":"명사 + の極み(感激の極み)로 '최고조'를 말하며 좋은 감정에도 쓴다. 極まりない는 주로 부정적 평가에 쓴다."}],"ex":[{"jp":"雨[あめ]の日[ひ]にスピードを出[だ]すのは危険[きけん]極[きわ]まりない。","ko":"비 오는 날에 속도를 내는 것은 위험하기 짝이 없다."},{"jp":"約束[やくそく]を何度[なんど]も破[やぶ]るとは、失礼[しつれい]極[きわ]まりない人[ひと]だ。","ko":"약속을 몇 번이나 어기다니 더없이 무례한 사람이다."},{"jp":"毎朝[まいあさ]満員[まんいん]電車[でんしゃ]に乗[の]るのは、不愉快[ふゆかい]なこと極[きわ]まりない。","ko":"매일 아침 만원 전철을 타는 것은 불쾌하기 그지없다."}],"dr":[{"t":"make","q":"無責任だ → ～極まりない","a":"無責任極まりない","hint":"だ를 빼고 어간 + 極まりない"},{"t":"make","q":"不便だ → ～極まりない","a":"不便極まりない","hint":"だ를 빼고 어간 + 極まりない"},{"t":"fill","q":"客[きゃく]にあんな言葉[ことば]を使[つか]うなんて、失礼（　）。","a":"極まりない","opts":["極まりない","にすぎない","に限らない","とは限らない"]}],"src":[],"vf":0,"u":36,"g":1,"gp":"gg_N1_13"},{"id":"g1_242","t":"～極まる","ko":"더없이 ~하다, 극히 ~하다","cat":"비교·정도","conn":[{"w":"な형용사 어간","f":"退屈 + 極まる"},{"w":"명사 수식","f":"失礼 + 極まる + 態度"}],"rule":["1. な형용사의 단정 だ를 뺀다: 退屈だ → 退屈.","2. 어간 뒤에 極まる를 붙인다: 退屈極まる.","3. 명사를 꾸밀 때는 그대로 이어 쓴다: 退屈極まる会議."],"why":"동사 極まる(극에 달하다)를 な형용사 어간 뒤에 붙여 그 상태가 극에 이르렀음을 나타낸다.","nu":"極まりない와 같은 뜻의 딱딱한 문어체 표현으로, 失礼, 危険, 退屈, 不愉快 같은 부정적 평가에 주로 쓴다. 감정이 북받쳐 울컥하다는 感極まる(感極まって泣く)는 독립된 관용구로 자주 쓰인다. 회화에서 쓰면 과장되고 딱딱하게 들린다.","cmp":[{"g":"～極まりない","d":"뜻은 거의 같고 더 자주 쓰인다. ない가 붙어도 부정이 아니다."},{"g":"とても / 非常に","d":"일반적인 정도 부사. 極まる는 비난이나 강한 감정이 실린 문어적 강조다."}],"ex":[{"jp":"三時間[さんじかん]も続[つづ]いた会議[かいぎ]は退屈[たいくつ]極[きわ]まるものだった。","ko":"세 시간이나 계속된 회의는 더없이 지루한 것이었다."},{"jp":"彼[かれ]の失礼[しつれい]極[きわ]まる態度[たいど]に、みんな怒[おこ]った。","ko":"그의 무례하기 짝이 없는 태도에 모두 화가 났다."},{"jp":"優勝[ゆうしょう]が決[き]まった瞬間[しゅんかん]、選手[せんしゅ]は感[かん]極[きわ]まって泣[な]き出[だ]した。","ko":"우승이 정해진 순간 선수는 감정이 북받쳐 울기 시작했다."}],"dr":[{"t":"make","q":"危険だ → ～極まる","a":"危険極まる","hint":"だ를 빼고 어간 + 極まる"},{"t":"make","q":"不愉快だ → ～極まる","a":"不愉快極まる","hint":"だ를 빼고 어간 + 極まる"},{"t":"fill","q":"夜中[よなか]に大声[おおごえ]で騒[さわ]ぐとは、迷惑[めいわく]（　）行為[こうい]だ。","a":"極まる","opts":["極まる","がちな","気味の","っぽい"]}],"src":[],"vf":0,"u":36,"g":1,"gp":"gg_N1_13"},{"id":"g1_012","t":"～のやら～のやら","ko":"~인지 ~인지 (모르겠다)","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"行きたい + のやら"},{"w":"い형용사","f":"いい + のやら"},{"w":"な형용사","f":"好きな + のやら"},{"w":"명사","f":"本気な + のやら"}],"rule":["1. な형용사·명사는 뒤에 な를 넣는다. 好き → 好きな.","2. 그 뒤에 のやら를 붙인다. 好きな → 好きなのやら.","3. 동사·い형용사는 보통형에 바로 のやら를 붙이고, 반대 내용도 같은 꼴로 이어 쓴다. 好きなのやら嫌いなのやら."],"why":"","nu":"두 가지 중 어느 쪽인지 알 수 없어 갈피를 못 잡는 기분을 나타낸다. 뒤에 分からない・はっきりしない 같은 말이 자주 온다. 남의 마음이나 사정을 짐작하기 어려울 때 쓰고, 약간 어이없어하는 느낌도 있다. 명사・な형용사에 な를 빠뜨리는 실수에 주의.","cmp":[{"g":"～か～か","d":"선택지를 중립적으로 제시(行くか行かないか決める). のやら는 알 수 없어 답답해하는 느낌이 있다."},{"g":"～やら～やら","d":"の 없이 쓰면 '~랑 ~랑' 하는 나열이 된다(本やらノートやら)."}],"ex":[{"jp":"弟[おとうと]は行[い]きたいのやら行[い]きたくないのやら、はっきりしない。","ko":"남동생은 가고 싶은 건지 가기 싫은 건지 분명하지 않다."},{"jp":"あの二人[ふたり]は仲[なか]がいいのやら悪[わる]いのやら、よく分[わ]からない。","ko":"저 두 사람은 사이가 좋은 건지 나쁜 건지 잘 모르겠다."},{"jp":"彼女[かのじょ]が本気[ほんき]なのやら冗談[じょうだん]なのやら、判断[はんだん]できない。","ko":"그녀가 진심인지 농담인지 판단할 수가 없다."}],"dr":[{"t":"make","q":"好きだ・嫌いだ → ～のやら～のやら","a":"好きなのやら嫌いなのやら","hint":"な형용사는 어간 + な + のやら"},{"t":"make","q":"喜んでいる・怒っている → ～のやら～のやら","a":"喜んでいるのやら怒っているのやら","hint":"동사 보통형 + のやら"},{"t":"fill","q":"彼[かれ]が来[く]る（　）来[こ]ない（　）、まだ分[わ]からない。","a":"のやら","opts":["のやら","ものの","くせに","とたん"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/のやら～のやら-no-yara-no-yara/"],"vf":1,"u":36,"g":1,"gp":"gg_N1_13"},{"id":"g1_122","t":"～そうにない","ko":"~할 것 같지 않다","cat":"추량·전문","conn":[{"w":"1그룹 동사 ます형","f":"終わり + そうにない"},{"w":"2그룹 동사 ます형","f":"でき + そうにない"},{"w":"가능 동사","f":"行け + そうにない"},{"w":"불규칙 する","f":"する → しそうにない"},{"w":"불규칙 来る","f":"来る → 来(き)そうにない"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다: 終わる → 終わり.","2. 양태의 そう에 に를 붙인 そうに를 붙인다: 終わりそうに.","3. 부정의 ない를 붙인다: 終わりそうにない.","4. 2그룹은 る를 떼고 そうにない를 붙인다: できる → できそうにない."],"why":"","nu":"보거나 판단한 바로는 그 일이 일어날(될) 가능성이 거의 없다는 뜻이다. 동사에 쓰는 표현이며, 형용사의 부정 추측은 高くなさそう처럼 다른 형태를 쓴다. 行けそうにない처럼 가능 동사와 자주 쓴다. 회화와 문장 모두에 쓴다. も를 넣은 そうもない, そうにもない도 같은 뜻으로 쓴다.","cmp":[{"g":"～そうもない","d":"뜻은 거의 같고, も가 들어가 '전혀 ~할 것 같지 않다'는 느낌이 조금 강해진다."}],"ex":[{"jp":"この仕事[しごと]は今日中[きょうじゅう]に終[お]わりそうにない。","ko":"이 일은 오늘 안에 끝날 것 같지 않다."},{"jp":"熱[ねつ]があるので、明日[あした]のパーティーには行[い]けそうにない。","ko":"열이 있어서 내일 파티에는 못 갈 것 같다."},{"jp":"この問題[もんだい]は難[むずか]しすぎて、私[わたし]にはできそうにない。","ko":"이 문제는 너무 어려워서 나는 못 할 것 같다."}],"dr":[{"t":"make","q":"間に合う → ～そうにない","a":"間に合いそうにない","hint":"う → い(ます형) + そうにない"},{"t":"make","q":"できる → ～そうにない","a":"できそうにない","hint":"2그룹: る를 떼고 + そうにない"},{"t":"fill","q":"道[みち]が混[こ]んでいて、約束[やくそく]の時間[じかん]に間[ま]に合[あ]い（　）。","a":"そうにない","opts":["そうにない","ようがない","わけがない","ことはない"]}],"src":["https://bunpro.jp/es/grammar_points/%E3%81%9D%E3%81%86%E3%81%AB%E3%81%AA%E3%81%84"],"vf":1,"u":36,"g":1,"gp":"gg_N1_13"},{"id":"g1_123","t":"～そうもない","ko":"(전혀) ~할 것 같지도 않다","cat":"추량·전문","conn":[{"w":"1그룹 동사 ます형","f":"止み + そうもない"},{"w":"2그룹 동사 ます형","f":"解け + そうもない"},{"w":"불규칙 する","f":"する → しそうもない"},{"w":"불규칙 来る","f":"来る → 来(き)そうもない"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다: 止む → 止み.","2. 양태의 そう를 붙인다: 止みそう.","3. 강조의 も를 넣고 부정의 ない를 붙인다: 止みそうもない.","4. 2그룹은 る를 떼고, する는 しそうもない, 来る는 来(き)そうもない가 된다."],"why":"","nu":"그 일이 일어날 기미가 전혀 보이지 않는다는 뜻으로, そうにない보다 '조금도'라는 느낌이 강하다. 동사에만 붙는다. 비가 그치지 않는다, 일이 끝나지 않는다처럼 기대하던 일이 일어나지 않을 것 같을 때 자주 쓴다. 회화와 문장 모두에 쓴다.","cmp":[{"g":"～そうにない","d":"뜻은 거의 같다. そうもない는 も의 강조로 가능성이 더 낮다는 느낌을 준다."}],"ex":[{"jp":"雨[あめ]は当分[とうぶん]止[や]みそうもない。","ko":"비는 당분간 그칠 것 같지도 않다."},{"jp":"こんなに難[むずか]しい問題[もんだい]は、私[わたし]には解[と]けそうもない。","ko":"이렇게 어려운 문제는 나로서는 도저히 풀 수 있을 것 같지 않다."},{"jp":"あの二人[ふたり]は、なかなか結婚[けっこん]しそうもない。","ko":"저 두 사람은 좀처럼 결혼할 것 같지도 않다."}],"dr":[{"t":"make","q":"止む → ～そうもない","a":"止みそうもない","hint":"む → み(ます형) + そうもない"},{"t":"make","q":"来る → ～そうもない","a":"来そうもない","hint":"来る는 来(き) + そうもない"},{"t":"fill","q":"この渋滞[じゅうたい]では、今日中[きょうじゅう]に着[つ]き（　）。","a":"そうもない","opts":["そうもない","ようもない","わけもない","はずもない"]}],"src":["https://bunpro.jp/es/grammar_points/%E3%81%9D%E3%81%86%E3%82%82%E3%81%AA%E3%81%84"],"vf":1,"u":36,"g":1,"gp":"gg_N1_13"},{"id":"g1_142","t":"～ないものでもない","ko":"~못 할 것도 없다, ~하지 않는 것도 아니다","cat":"추량·전문","conn":[{"w":"동사 ない형","f":"間に合わない + ものでもない"},{"w":"동사 가능형의 ない형","f":"できない + ものでもない"}],"rule":["1. 1그룹 동사는 어미 う단을 あ단으로 바꾼다. 어미 う는 あ가 아니라 わ가 된다: 間に合う → 間に合わ.","2. 그 뒤에 ない를 붙인다: 間に合わない.","3. ない형 뒤에 ものでもない를 붙인다: 間に合わないものでもない.","4. 2그룹은 る를 ない로 바꾼다: 考える → 考えないものでもない."],"why":"","nu":"부정에 부정을 겹쳐 '전혀 불가능한 것은 아니다, 조건에 따라서는 그럴 수도 있다'는 소극적인 긍정을 나타낸다. 条件によっては, 急げば 같은 조건과 함께 자주 쓴다. 딱딱하고 다소 거드름스러운 느낌이 있으며, 회화에서는 ～ないこともない를 더 많이 쓴다.","cmp":[{"g":"～ないこともない","d":"뜻은 거의 같고 회화에서 더 자연스럽다."},{"g":"～ないわけではない","d":"'~하지 않는 것은 아니다'라고 전면 부정을 부분적으로 부정한다. 가능성보다는 사실 관계를 바로잡는 느낌이다."}],"ex":[{"jp":"今[いま]から急[いそ]げば、間[ま]に合[あ]わないものでもない。","ko":"지금부터 서두르면 시간에 못 댈 것도 없다."},{"jp":"条件[じょうけん]によっては、引[ひ]き受[う]けないものでもない。","ko":"조건에 따라서는 맡지 않을 것도 없다."},{"jp":"難[むずか]しいが、二人[ふたり]でやればできないものでもない。","ko":"어렵지만 둘이서 하면 못 할 것도 없다."}],"dr":[{"t":"make","q":"手伝う → ～ないものでもない","a":"手伝わないものでもない","hint":"う → わ, + ない + ものでもない"},{"t":"make","q":"考える → ～ないものでもない","a":"考えないものでもない","hint":"る → ない, + ものでもない"},{"t":"fill","q":"もう少[すこ]し安[やす]くしてくれれば、買[か]わない（　）。","a":"ものでもない","opts":["ものでもない","ものだろうか","ものか","ものだ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ないものでもない-nai-mono-demo-nai-meaning/"],"vf":1,"u":37,"g":1,"gp":"gg_N1_13"},{"id":"g1_176","t":"～きらいがある","ko":"~하는 (좋지 않은) 경향이 있다","cat":"추량·전문","conn":[{"w":"동사 사전형","f":"忘れる + きらいがある"},{"w":"동사 ない형","f":"人の話を聞かない + きらいがある"},{"w":"명사","f":"誇張の + きらいがある"}],"rule":["1. 동사는 사전형(또는 ない형)을 그대로 둔다: 忘れる.","2. 그 뒤에 きらいがある를 붙인다: 忘れるきらいがある.","3. 명사에 붙일 때는 の를 넣는다: 誇張のきらいがある."],"why":"","nu":"사람이나 사물이 좋지 않은 쪽으로 기우는 경향이 있다는 비판적 평가를 나타내는 딱딱한 표현이다. 좋은 경향에는 쓰지 않는다. 한자로 嫌いがある라고도 쓰지만 보통 가나로 쓴다. 말하는 사람 자신에 대해 쓰면 자기반성의 느낌이 된다. 한 번 일어난 일이 아니라 반복되는 성향에 쓴다.","cmp":[{"g":"～がちだ","d":"그렇게 되기 쉽다는 일상 표현으로, 회화에서도 자주 쓴다. きらいがある는 더 딱딱하고 평가적이다."},{"g":"～傾向がある","d":"좋고 나쁨에 상관없이 중립적으로 경향을 말한다."}],"ex":[{"jp":"兄[あに]は物事[ものごと]を大[おお]げさに言[い]うきらいがある。","ko":"형은 매사를 과장해서 말하는 경향이 있다."},{"jp":"彼[かれ]は人[ひと]の話[はなし]を最後[さいご]まで聞[き]かないきらいがある。","ko":"그는 남의 이야기를 끝까지 듣지 않는 경향이 있다."},{"jp":"私[わたし]は一人[ひとり]で何[なん]でも決[き]めてしまうきらいがある。","ko":"나는 혼자서 뭐든 정해 버리는 경향이 있다."}],"dr":[{"t":"make","q":"考えすぎる → ～きらいがある","a":"考えすぎるきらいがある","hint":"동사 사전형 + きらいがある"},{"t":"make","q":"誇張 → ～きらいがある","a":"誇張のきらいがある","hint":"명사 + の + きらいがある"},{"t":"fill","q":"彼女[かのじょ]は何[なん]でも悪[わる]い方[ほう]に考[かんが]える（　）。","a":"きらいがある","opts":["きらいがある","おそれがない","ことになる","わけにはいかない"]}],"src":["https://www.mlcjapanese.co.jp/n1_04_03.html","https://nihongokyoshi-net.com/2019/02/19/jlptn1-grammar-kiraigaaru/"],"vf":1,"u":37,"g":1,"gp":"gg_N1_13"},{"id":"g1_198","t":"～とされる","ko":"~라고 여겨진다, ~로 간주된다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"効果がある + とされる"},{"w":"い형용사","f":"古い + とされる"},{"w":"な형용사","f":"有害だ + とされる"},{"w":"명사","f":"世界一 + とされる"}],"rule":["1. 평가 내용을 보통형으로 둔다: 古い.","2. 인용의 と와 '간주하다'는 뜻의 する를 붙인다: 古いとする.","3. する를 수동형 される로 바꾼다: 古いとされる.","4. 명사·な형용사는 だ를 붙이거나 생략하고 잇는다: 有害だとされる, 世界一とされる."],"why":"인용의 と + する('~라고 간주하다')의 수동형 される로, '(일반적으로) ~라고 간주된다'는 뜻이 된다.","nu":"사회 일반이나 전문가 사이에서 그렇게 인정·평가되고 있다는 것을 객관적으로 전하는 문어체 표현이다. 뉴스·논문·설명문에 많고, とされている의 형태로 자주 쓴다. 개인의 생각을 말할 때는 쓰지 않는다.","cmp":[{"g":"～と言われている","d":"'~라고 일컬어진다'로, 소문이나 일반적인 말에도 쓰는 부드러운 표현이다. とされる는 더 딱딱하고 공식적인 평가에 쓴다."},{"g":"～と考えられている","d":"'~라고 생각되고 있다'로, 추론·학설의 느낌이 강하다."}],"ex":[{"jp":"この寺[てら]は日本[にほん]で最[もっと]も古[ふる]い寺[てら]の一[ひと]つとされている。","ko":"이 절은 일본에서 가장 오래된 절 중 하나로 여겨지고 있다."},{"jp":"たばこは体[からだ]に有害[ゆうがい]だとされている。","ko":"담배는 몸에 해롭다고 여겨지고 있다."},{"jp":"緑茶[りょくちゃ]には病気[びょうき]を防[ふせ]ぐ効果[こうか]があるとされる。","ko":"녹차에는 병을 막는 효과가 있다고 여겨진다."}],"dr":[{"t":"make","q":"安全だ → ～とされる","a":"安全だとされる","hint":"な형용사 + だ + とされる"},{"t":"make","q":"難しい → ～とされる","a":"難しいとされる","hint":"い형용사 보통형 + と + される(する의 수동)"},{"t":"fill","q":"この薬[くすり]は風邪[かぜ]に効[き]く（　）。","a":"とされている","opts":["とされている","ときている","とあって","といえども"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%95%E3%82%8C%E3%81%A6%E3%81%84%E3%82%8B"],"vf":1,"u":37,"g":1,"gp":"gg_N1_13"},{"id":"g1_205","t":"～とのことだ","ko":"~라고 한다, ~라는 전갈이다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"遅れる + とのことだ"},{"w":"い형용사","f":"忙しい + とのことだ"},{"w":"な형용사","f":"元気だ + とのことだ"},{"w":"명사","f":"休みだ + とのことだ"}],"rule":["1. 전할 내용을 보통형 문장으로 만든다: 遅れる.","2. 인용의 と를 붙인다: 遅れると.","3. の + こと + だ(정중하게는 です)를 붙인다: 遅れるとのことです."],"why":"인용의 と + の + こと(일, 내용) + だ로 이루어져 '~라는 내용이다'라는 뜻이 된다.","nu":"남에게서 들은 말이나 전해 달라는 말을 제3자에게 그대로 옮길 때 쓴다. 비즈니스에서 '~라고 하십니다'처럼 전갈을 전하는 데 특히 많이 쓰이며 そうだ(전문)보다 격식 있는 느낌이다. 화자 자신의 추측에는 쓰지 않는다. 문장 중간에서는 とのことで(~라고 해서)로 이어진다.","cmp":[{"g":"～そうだ(전문)","d":"보통형 + そうだ로 들은 정보를 전하는 일반적인 표현. とのことだ는 누군가의 말·연락 내용을 옮긴다는 느낌이 강하고 더 격식 있다."},{"g":"～ということだ","d":"전문 외에 결론·요약(つまり～ということだ)에도 쓴다. とのことだ는 전문에만 쓴다."}],"ex":[{"jp":"部長[ぶちょう]は会議[かいぎ]に少[すこ]し遅[おく]れるとのことです。","ko":"부장님은 회의에 조금 늦으신다고 합니다."},{"jp":"天気予報[てんきよほう]によると、週末[しゅうまつ]は晴[は]れるとのことだ。","ko":"일기예보에 따르면 주말은 맑다고 한다."},{"jp":"田中[たなか]さんから電話[でんわ]があって、明日[あした]は休[やす]みだとのことです。","ko":"다나카 씨에게서 전화가 왔는데, 내일은 쉰다고 합니다."}],"dr":[{"t":"make","q":"来ない → ～とのことです","a":"来ないとのことです","hint":"보통형 + と + のこと + です"},{"t":"make","q":"会議は三時からだ → ～とのことです","a":"会議は三時からだとのことです","hint":"문장 끝 보통형 그대로 + とのことです"},{"t":"fill","q":"先方[せんぽう]から連絡[れんらく]があり、書類[しょるい]は明日[あした]届[とど]く（　）。","a":"とのことです","opts":["とのことです","ようにします","ことにします","わけがないです"]}],"src":["https://nihongokyoshi-net.com/2020/02/04/jlptn3-grammar-tonokotoda/"],"vf":1,"u":37,"g":1,"gp":"gg_N1_13"},{"id":"g1_207","t":"～とみえて","ko":"~인 듯(~인 모양으로), ~인지","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"疲れた + とみえて"},{"w":"い형용사","f":"嬉しかった + とみえて"},{"w":"な형용사","f":"留守だ + とみえて"},{"w":"명사","f":"雨だ + とみえて"}],"rule":["1. 추측하는 내용을 보통형으로 둔다(명사·な형용사는 だ를 붙인다): 疲れた.","2. と + みえる(見える)를 붙인다: 疲れたとみえる.","3. みえる의 る를 떼고 て를 붙여 て형으로 만든다: 疲れたとみえて."],"why":"'~로 보이다'라는 見える의 て형이다. '~라고 보여서'가 원래 뜻이다.","nu":"눈에 보이는 모습(뒤 문장)을 근거로 '아무래도 ~인 모양이다'라고 추측하는 표현이다. 앞에는 추측한 내용, 뒤에는 근거가 된 관찰 사실이 온다. 화자 자신의 일에는 쓰지 않는다. 문장 끝에서는 とみえる(~인 모양이다)로 쓴다. 다소 문어적이다.","cmp":[{"g":"～らしく","d":"らしい의 연용형으로 비슷하게 추측을 잇는다. とみえて는 눈으로 본 모습에서 판단했다는 느낌이 더 강하다."},{"g":"～ようで","d":"회화에서 더 일반적인 추측 연결 표현이다."}],"ex":[{"jp":"子[こ]どもたちは疲[つか]れたとみえて、車[くるま]の中[なか]ですぐ寝[ね]てしまった。","ko":"아이들은 피곤했는지 차 안에서 금방 잠들어 버렸다."},{"jp":"彼[かれ]はよほど嬉[うれ]しかったとみえて、ずっとにこにこしている。","ko":"그는 꽤 기뻤던 모양인지 계속 싱글벙글하고 있다."},{"jp":"隣[となり]の家[いえ]は留守[るす]だとみえて、電気[でんき]が消[き]えている。","ko":"옆집은 집을 비운 모양인지 불이 꺼져 있다."}],"dr":[{"t":"make","q":"お腹がすいていた → ～とみえて","a":"お腹がすいていたとみえて","hint":"보통형 + と + みえて(みえる의 て형)"},{"t":"make","q":"忙しい → ～とみえて","a":"忙しいとみえて","hint":"い형용사 + とみえて"},{"t":"fill","q":"彼女[かのじょ]は急[いそ]いでいた（　）、挨拶[あいさつ]もしないで出[で]て行[い]った。","a":"とみえて","opts":["とみえて","としたら","とはいえ","とともに"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%BF%E3%81%88%E3%82%8B","https://jlptsensei.com/learn-japanese-grammar/%E3%81%A8%E3%81%BF%E3%81%88%E3%81%A6-miete-%E3%81%A8%E3%81%BF%E3%81%88%E3%82%8B-to-mieru-meaning/"],"vf":1,"u":38,"g":1,"gp":"gg_N1_14"},{"id":"g1_208","t":"～とみられる","ko":"~로 보인다, ~로 추정된다","cat":"추량·전문","conn":[{"w":"동사 보통형","f":"増える + とみられる"},{"w":"명사","f":"男性 + とみられる"}],"rule":["1. 추정하는 내용을 보통형 또는 명사로 둔다: 増える.","2. と + みる(見る)를 붙인다: 増えるとみる.","3. みる는 1단(2그룹) 동사이므로 る를 떼고 られる를 붙여 수동형으로 만든다: 増えるとみられる."],"why":"'~라고 보다(판단하다)'라는 ～とみる의 수동형이다.","nu":"뉴스·보도·논문 등에서 '(일반적으로·관계자에 의해) ~로 추정된다'고 객관적으로 말할 때 쓰는 문어적 표현이다. 일상 회화에는 거의 쓰지 않는다. 현재 그렇게 추정되고 있다는 상태는 とみられている로 나타낸다. 명사를 꾸밀 때는 30代とみられる男性처럼 쓴다.","cmp":[{"g":"～と思われる","d":"'~로 생각된다'는 자발·완곡한 판단. とみられる는 관찰·조사에 근거한 추정이라는 보도문 느낌이 강하다."},{"g":"～らしい","d":"회화에서 쓰는 추측·전문 표현이다."}],"ex":[{"jp":"事故[じこ]の原因[げんいん]は、スピードの出[だ]し過[す]ぎとみられる。","ko":"사고 원인은 과속으로 추정된다."},{"jp":"犯人[はんにん]は30代[だい]の男性[だんせい]とみられている。","ko":"범인은 30대 남성으로 보고 있다."},{"jp":"今年[ことし]は観光客[かんこうきゃく]がさらに増[ふ]えるとみられる。","ko":"올해는 관광객이 더욱 늘어날 것으로 보인다."}],"dr":[{"t":"make","q":"下がる → ～とみられる","a":"下がるとみられる","hint":"보통형 + と + み + られる(1단 동사 수동)"},{"t":"make","q":"放火 → ～とみられる","a":"放火とみられる","hint":"명사 + とみられる"},{"t":"fill","q":"火事[かじ]の原因[げんいん]はたばこの火[ひ]（　）。","a":"とみられる","opts":["とみられる","ことにする","ようにする","わけにはいかない"]}],"src":["https://jisho.org/search/%E3%81%A8%E3%81%BF%E3%82%89%E3%82%8C%E3%82%8B"],"vf":1,"u":38,"g":1,"gp":"gg_N1_14"},{"id":"g1_015","t":"～あっての","ko":"~가 있어야 (성립하는) ~, ~ 덕분에 있는 ~","cat":"강조·한정","conn":[{"w":"명사 + あっての + 명사","f":"お客様 + あっての + 商売"}],"rule":["1. 명사1 뒤에 あっての를 붙인다. お客様 → お客様あっての.","2. 그 뒤에 명사2를 붙여 'A가 있어야 B가 있다'는 뜻을 만든다. お客様あっての商売.","3. 문장 끝은 보통 명사2 + だ/です로 맺는다."],"why":"ある(있다)의 て형 あって에 の가 붙은 꼴이다.","nu":"A가 있기 때문에 비로소 B가 성립한다, A 없이는 B도 없다는 뜻으로 A의 소중함을 강조한다. 감사나 교훈의 문맥에서 자주 쓴다. 명사와 명사를 잇는 형태로만 쓴다. 문장 끝을 あってこそだ로 바꿔 말하기도 한다.","cmp":[{"g":"～があってこそ","d":"비슷하게 'A가 있어야 비로소'를 뜻하지만 뒤에 문장이 온다(健康があってこそ働ける). あっての는 바로 명사를 꾸민다."}],"ex":[{"jp":"お客様[きゃくさま]あっての商売[しょうばい]ですから、サービスを大切[たいせつ]にしています。","ko":"손님이 있어야 장사가 되니까 서비스를 소중히 하고 있습니다."},{"jp":"健康[けんこう]あっての仕事[しごと]だから、無理[むり]をしないでください。","ko":"건강해야 일도 할 수 있으니 무리하지 마세요."},{"jp":"ファンあっての私[わたし]たちです。","ko":"팬이 있기에 저희가 있습니다."}],"dr":[{"t":"make","q":"練習・成功 → ～あっての～","a":"練習あっての成功","hint":"명사1 + あっての + 명사2"},{"t":"make","q":"家族・私 → ～あっての～","a":"家族あっての私","hint":"명사1 + あっての + 명사2"},{"t":"fill","q":"選手[せんしゅ]はファン（　）プロスポーツだと言[い]った。","a":"あっての","opts":["あっての","にかぎらず","をよそに","ながらの"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%82%E3%81%A3%E3%81%A6%E3%81%AE"],"vf":1,"u":38,"g":1,"gp":"gg_N1_14"},{"id":"g1_022","t":"～ぐるみ","ko":"~전체가 함께, ~째로","cat":"강조·한정","conn":[{"w":"명사(집단)","f":"家族 + ぐるみ"},{"w":"명사 + で (부사)","f":"町ぐるみ + で"},{"w":"명사 + の (명사 수식)","f":"会社ぐるみ + の + 不正"}],"rule":["1. 집단을 나타내는 명사 뒤에 ぐるみ를 붙인다(家族ぐるみ).","2. 동사를 꾸밀 때는 で를 붙인다(家族ぐるみで付き合う).","3. 명사를 꾸밀 때는 の를 붙인다(家族ぐるみの付き合い)."],"why":"","nu":"家族・町・村・会社 같은 집단 명사와 굳어진 말이 대부분이며 아무 명사에나 붙지 않는다. '구성원 모두가 함께'라는 뜻으로 좋은 일에도, 会社ぐるみの不正처럼 나쁜 일에도 쓴다. 身ぐるみ(はがされる)는 '몸에 걸친 것 전부'라는 관용 표현이다.","cmp":[{"g":"～ごと","d":"皮ごと食べる처럼 물건을 '통째로' 포함한다는 뜻. 집단 구성원이 함께한다는 뜻은 없다."}],"ex":[{"jp":"隣[となり]の家[いえ]とは家族[かぞく]ぐるみで付[つ]き合[あ]っている。","ko":"옆집과는 가족끼리 다 같이 친하게 지낸다."},{"jp":"町[まち]ぐるみでごみを減[へ]らす運動[うんどう]をしている。","ko":"마을 전체가 함께 쓰레기를 줄이는 운동을 하고 있다."},{"jp":"会社[かいしゃ]ぐるみの不正[ふせい]が明[あき]らかになった。","ko":"회사 전체가 가담한 부정이 밝혀졌다."}],"dr":[{"t":"make","q":"家族 → ～ぐるみ（付き合いを修飾）","a":"家族ぐるみの付き合い","hint":"명사 + ぐるみ + の + 명사"},{"t":"make","q":"町 → ～ぐるみ（동사 수식）","a":"町ぐるみで","hint":"명사 + ぐるみ + で"},{"t":"fill","q":"その事件[じけん]は会社[かいしゃ]（　）の犯罪[はんざい]だった。","a":"ぐるみ","opts":["ぐるみ","ずくめ","まみれ","だらけ"]}],"src":["https://bunpro.jp/grammar_points/958"],"vf":1,"u":38,"g":1,"gp":"gg_N1_14"},{"id":"g1_025","t":"～こそすれ","ko":"~하면 했지 (결코 ~않는다)","cat":"강조·한정","conn":[{"w":"동사 ます형","f":"喜び + こそすれ"},{"w":"する 동사의 명사","f":"感謝 + こそすれ"}],"rule":["1. 동사를 ます형으로 바꾼다: 喜ぶ의 어미 ぶ를 び로(喜び). する 동사는 명사 부분만 쓴다(感謝).","2. 뒤에 강조의 こそ를 붙인다(喜びこそ).","3. する의 고전 已然形 すれ를 붙인다(喜びこそすれ).","4. 뒤에는 반대되는 내용의 부정(～ない, ～はしない)이 온다."],"why":"고전 문법의 계결(係り結び): こそ 뒤에서 문말이 已然形이 되므로 する(고어 す)의 已然形 すれ가 왔다.","nu":"딱딱한 문어체. '앞의 일은 있을 수 있어도 뒤의 일은 결코 없다'는 강한 대비. 뒤에 반드시 부정이 온다. 명사에 ある가 붙는 こそあれ와 혼동하기 쉽다.","cmp":[{"g":"～こそあれ","d":"명사 + こそあれ(差こそあれ). こそすれ는 동작을 나타내는 말(동사 ます형, する 동사 명사)에 붙는다."}],"ex":[{"jp":"感謝[かんしゃ]こそすれ、恨[うら]むことなどない。","ko":"감사하면 했지 원망할 일은 없다."},{"jp":"彼[かれ]の言葉[ことば]は私[わたし]を励[はげ]ましこそすれ、傷[きず]つけはしなかった。","ko":"그의 말은 나를 격려하면 했지 상처 주지는 않았다."},{"jp":"練習[れんしゅう]を休[やす]めば、下手[へた]になりこそすれ、上手[じょうず]になることはない。","ko":"연습을 쉬면 서툴러지면 서툴러졌지 능숙해질 일은 없다."}],"dr":[{"t":"make","q":"感謝する → ～こそすれ","a":"感謝こそすれ","hint":"する 동사는 명사 + こそすれ"},{"t":"make","q":"喜ぶ → ～こそすれ","a":"喜びこそすれ","hint":"ます형(ぶ를 び로) + こそすれ"},{"t":"fill","q":"親[おや]に心配[しんぱい]をかけたのだから、叱[しか]られ（　）、ほめられることはない。","a":"こそすれ","opts":["こそすれ","ばかりか","ものの","ようと"]}],"src":["https://bunpro.jp/grammar_points/991","https://jlptsensei.com/learn-japanese-grammar/こそすれ-koso-sure-meaning"],"vf":1,"u":38,"g":1,"gp":"gg_N1_14"},{"id":"g1_028","t":"～ずくめ","ko":"~일색, ~뿐","cat":"강조·한정","conn":[{"w":"명사","f":"黒 + ずくめ"},{"w":"명사 + の (명사 수식)","f":"いいことずくめ + の + 一年"},{"w":"명사 + だ","f":"規則ずくめ + だ"}],"rule":["1. 명사 뒤에 ずくめ를 붙인다(黒ずくめ).","2. 명사를 꾸밀 때는 の를 붙인다(黒ずくめの服).","3. 문장 끝은 だ, 이어 줄 때는 で를 붙인다(規則ずくめで)."],"why":"","nu":"붙을 수 있는 명사가 한정된 굳어진 표현이다. 黒・白 같은 색(옷차림 전체), いいこと, ごちそう, 規則 등. 좋은 일에도 나쁜 일에도 쓴다. 아무 명사에나 붙여 '많다'는 뜻으로 쓰는 것은 부자연스럽다.","cmp":[{"g":"～だらけ","d":"傷だらけ처럼 좋지 않은 것이 여기저기 많이 있음. 주로 부정적."},{"g":"～まみれ","d":"泥まみれ처럼 액체·가루 등이 표면 전체에 묻어 있음."}],"ex":[{"jp":"黒[くろ]ずくめの服[ふく]を着[き]た男[おとこ]が立[た]っていた。","ko":"온통 검은 옷을 입은 남자가 서 있었다."},{"jp":"今年[ことし]は結婚[けっこん]に就職[しゅうしょく]に、いいことずくめの一年[いちねん]だった。","ko":"올해는 결혼에 취직에, 좋은 일뿐인 한 해였다."},{"jp":"この学校[がっこう]は規則[きそく]ずくめで、自由[じゆう]がない。","ko":"이 학교는 규칙투성이라 자유가 없다."}],"dr":[{"t":"make","q":"黒 → ～ずくめ（服を修飾）","a":"黒ずくめの服","hint":"명사 + ずくめ + の + 명사"},{"t":"make","q":"いいこと → ～ずくめ（문장 끝）","a":"いいことずくめだ","hint":"명사 + ずくめ + だ"},{"t":"fill","q":"結婚[けっこん]、昇進[しょうしん]と、今年[ことし]はいいこと（　）だ。","a":"ずくめ","opts":["ずくめ","まみれ","ぐるみ","っぽい"]}],"src":["https://guidetojapanese.org/learn/grammar/covered"],"vf":1,"u":39,"g":1,"gp":"gg_N1_14"},{"id":"g1_029","t":"～だけではすまない","ko":"~만으로는 끝나지 않는다","cat":"강조·한정","conn":[{"w":"명사","f":"謝罪 + だけではすまない"},{"w":"동사 사전형","f":"謝る + だけではすまない"}],"rule":["1. すむ(済む)의 어미 む를 ま로 바꾸고 ない를 붙여 부정형 すまない를 만든다.","2. 명사나 동사 사전형 뒤에 한정의 だけ와 では를 붙인다(謝罪だけでは).","3. 이어서 すまない를 붙인다(謝罪だけではすまない)."],"why":"だけ(~만) + では + 済む(일이 해결되다, 끝나다)의 부정 済まない. '~만으로는 해결되지 않는다'는 구성.","nu":"문제가 그 정도로 끝나지 않고 더 큰 책임·처벌·대가가 따른다는 뜻. 심각한 상황에 쓴다. 문장 중간에서는 だけではすまず(に)도 쓴다.","cmp":[{"g":"～ではすまない","d":"冗談ではすまない처럼 'だけ' 없이 '~로는 끝나지 않는다'."},{"g":"～ないではすまない","d":"'~하지 않고는 끝나지 않는다', 즉 반드시 ~해야 한다는 의무."}],"ex":[{"jp":"これは謝[あやま]るだけではすまない問題[もんだい]だ。","ko":"이건 사과만으로는 끝나지 않는 문제다."},{"jp":"これだけの事故[じこ]になると、社長[しゃちょう]の謝罪[しゃざい]だけではすまないだろう。","ko":"이 정도의 사고라면 사장의 사과만으로는 끝나지 않을 것이다."},{"jp":"人[ひと]の物[もの]を壊[こわ]したら、「ごめん」だけではすまない。","ko":"남의 물건을 망가뜨렸으면 '미안'만으로는 끝나지 않는다."}],"dr":[{"t":"make","q":"すむ → 부정형","a":"すまない","hint":"어미 む를 ま로 + ない"},{"t":"make","q":"謝罪 → ～だけではすまない","a":"謝罪だけではすまない","hint":"명사 + だけでは + すまない"},{"t":"fill","q":"これほどの損害[そんがい]は、謝[あやま]る（　）。","a":"だけではすまない","opts":["だけではすまない","だけあって","ばかりに","せいで"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/では済まない-dewa-sumanai-meaning/"],"vf":1,"u":39,"g":1,"gp":"gg_N1_14"},{"id":"g1_030","t":"～たりとも～ない","ko":"단 ~도 (~않다)","cat":"강조·한정","conn":[{"w":"一 + 조수사","f":"一円 + たりとも"},{"w":"一 + 조수사","f":"一日 + たりとも"},{"w":"一 + 조수사","f":"一瞬 + たりとも"}],"rule":["1. 가장 작은 단위 '一 + 조수사'를 둔다(一円).","2. も 자리에 たりとも를 붙인다(一円も → 一円たりとも).","3. 뒤에 부정이나 금지 표현을 둔다(無駄にできない, ～てはいけない)."],"why":"","nu":"문어적이고 강한 표현. 최소 단위를 들어 '하나도 예외 없이 ~않는다'고 전면 부정한다. 뒤에는 ～ない, ～てはいけない, ～な(금지) 등 부정이 반드시 온다. 一 이외의 큰 수와는 쓰지 않는다.","cmp":[{"g":"一～も～ない","d":"一円も使わない처럼 같은 뜻의 일반 표현. たりとも가 훨씬 강하고 딱딱하다."}],"ex":[{"jp":"一円[いちえん]たりとも無駄[むだ]にはできない。","ko":"단 1엔도 헛되이 쓸 수 없다."},{"jp":"試験[しけん]まで一日[いちにち]たりとも休[やす]むわけにはいかない。","ko":"시험까지 단 하루도 쉴 수는 없다."},{"jp":"一瞬[いっしゅん]たりとも目[め]を離[はな]してはいけない。","ko":"한순간도 눈을 떼서는 안 된다."}],"dr":[{"t":"make","q":"一円も無駄にしない → たりとも","a":"一円たりとも無駄にしない","hint":"も 자리에 たりとも"},{"t":"make","q":"一日も休めない → たりとも","a":"一日たりとも休めない","hint":"も 자리에 たりとも"},{"t":"fill","q":"一秒[いちびょう]（　）気[き]を抜[ぬ]くな。","a":"たりとも","opts":["たりとも","ばかりか","だけに","にしては"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/たりとも～ない-tari-tomo-nai-meaning/"],"vf":1,"u":39,"g":1,"gp":"gg_N1_14"},{"id":"g1_032","t":"～ですら","ko":"~조차도","cat":"강조·한정","conn":[{"w":"명사","f":"専門家 + ですら"},{"w":"명사","f":"子供 + ですら"}],"rule":["1. 극단적인 예가 되는 명사를 둔다(専門家).","2. でさえ 자리에 ですら를 붙인다(専門家でさえ → 専門家ですら).","3. 뒤에 '그러니 다른 것은 말할 것도 없다'는 내용(주로 부정)이 온다(解けない)."],"why":"","nu":"문어적인 강조. 극단적인 예를 들어 다른 경우는 당연하다는 것을 암시한다. 뒤에는 부정적인 내용이 오는 경우가 많다. 회화에서는 でさえ나 さえ가 더 흔하다.","cmp":[{"g":"～でさえ","d":"뜻은 거의 같고 더 일반적으로 쓰인다."},{"g":"～すら","d":"で 없이 명사(+조사)에 붙는 형태(名前すら知らない)."}],"ex":[{"jp":"この問題[もんだい]は専門家[せんもんか]ですら解[と]けない。","ko":"이 문제는 전문가조차도 풀 수 없다."},{"jp":"それは小[ちい]さい子供[こども]ですら知[し]っていることだ。","ko":"그건 어린아이조차도 알고 있는 것이다."},{"jp":"彼[かれ]は忙[いそが]しくて、日曜日[にちようび]ですら休[やす]めない。","ko":"그는 바빠서 일요일조차도 쉬지 못한다."}],"dr":[{"t":"make","q":"専門家でさえ → ですら","a":"専門家ですら","hint":"でさえ 자리에 ですら"},{"t":"make","q":"子供 → ～ですら","a":"子供ですら","hint":"명사 + ですら"},{"t":"fill","q":"先生[せんせい]（　）読[よ]めない漢字[かんじ]がある。","a":"ですら","opts":["ですら","ばかりに","からには","ものの"]}],"src":["https://www.mlcjapanese.co.jp/n1_04_06.html"],"vf":1,"u":39,"g":1,"gp":"gg_N1_14"},{"id":"g1_033","t":"～でなくてなんだろう","ko":"~가 아니고 무엇이겠는가","cat":"강조·한정","conn":[{"w":"명사","f":"愛 + でなくてなんだろう"},{"w":"명사","f":"奇跡 + でなくてなんだろう"}],"rule":["1. 명사 뒤의 だ를 연용형 で로 바꾼다(愛だ → 愛で).","2. 부정 なくて를 붙인다(愛でなくて = 사랑이 아니고).","3. なんだろう를 붙여 반어 의문으로 끝낸다(愛でなくてなんだろう)."],"why":"で(だ의 연용형) + なくて(아니고) + 何だろう(무엇일까). '이것이 X가 아니면 무엇이겠는가', 즉 '바로 X다'라는 반어.","nu":"문어체. 수필·연설·소설에서 감동이나 확신을 강조할 때 쓴다. 'これが～でなくてなんだろう' 형태가 많다. 더 딱딱하게 でなくてなんであろう라고도 한다. 일상 회화에서는 거의 쓰지 않는다.","cmp":[{"g":"～にほかならない","d":"'바로 ~이다'라는 단정. でなくてなんだろう는 반어 의문으로 감정을 담는다."}],"ex":[{"jp":"これが奇跡[きせき]でなくてなんだろう。","ko":"이것이 기적이 아니고 무엇이겠는가."},{"jp":"命[いのち]をかけて子[こ]を守[まも]る、これが愛[あい]でなくてなんだろう。","ko":"목숨을 걸고 아이를 지킨다, 이것이 사랑이 아니고 무엇이겠는가."},{"jp":"十年間[じゅうねんかん]一日[いちにち]も休[やす]まなかった。これが努力[どりょく]でなくてなんだろう。","ko":"10년 동안 하루도 쉬지 않았다. 이것이 노력이 아니고 무엇이겠는가."}],"dr":[{"t":"make","q":"愛 → ～でなくてなんだろう","a":"愛でなくてなんだろう","hint":"だ를 で로 + なくて + なんだろう"},{"t":"make","q":"これは運命だ → 반어 강조","a":"これが運命でなくてなんだろう","hint":"これが + 명사 + でなくてなんだろう"},{"t":"fill","q":"これが幸[しあわ]せ（　）。","a":"でなくてなんだろう","opts":["でなくてなんだろう","ではあるまいし","でさえ","ずくめ"]}],"src":["https://bunpro.jp/grammar_points/847"],"vf":1,"u":40,"g":1,"gp":"gg_N1_14"},{"id":"g1_036","t":"～といい～といい","ko":"~도 ~도 (모두)","cat":"강조·한정","conn":[{"w":"명사 + 명사","f":"味 + といい + 値段 + といい"}],"rule":["1. 평가할 측면의 명사1 뒤에 といい를 붙인다(味といい).","2. 명사2 뒤에도 といい를 붙인다(値段といい).","3. 뒤에 전체에 대한 말하는 사람의 평가를 둔다(最高だ)."],"why":"","nu":"대상의 여러 측면을 예로 들어 '어느 면을 보아도'라고 전체를 평가한다. 칭찬에도 비판에도 쓴다. 뒤에는 말하는 사람의 평가·판단이 오며, 의지·명령·의뢰는 오지 않는다. 약간 딱딱한 표현.","cmp":[{"g":"～にしても～にしても","d":"'~든 ~든 어느 쪽이든'이라는 뜻으로, 평가보다 조건을 나열한다."},{"g":"～も～も","d":"단순한 나열. といい는 예를 들어 전체를 평가하는 뜻이 있다."}],"ex":[{"jp":"味[あじ]といい値段[ねだん]といい、この店[みせ]は文句[もんく]なしだ。","ko":"맛도 가격도, 이 가게는 나무랄 데가 없다."},{"jp":"色[いろ]といいデザインといい、このかばんは私[わたし]の好[この]みにぴったりだ。","ko":"색깔도 디자인도 이 가방은 내 취향에 딱 맞다."},{"jp":"兄[あに]といい弟[おとうと]といい、あの家[いえ]の息子[むすこ]はみんな背[せ]が高[たか]い。","ko":"형도 동생도, 그 집 아들들은 모두 키가 크다."}],"dr":[{"t":"make","q":"味 / 値段 → ～といい～といい","a":"味といい値段といい","hint":"명사1 + といい + 명사2 + といい"},{"t":"make","q":"色 / 形 → ～といい～といい","a":"色といい形といい","hint":"명사1 + といい + 명사2 + といい"},{"t":"fill","q":"景色[けしき]といい料理[りょうり]（　）、最高[さいこう]の旅館[りょかん]だった。","a":"といい","opts":["といい","にしろ","やら","だの"]}],"src":["https://liuxue.xdf.cn/blog/blog_7641969.shtml"],"vf":1,"u":40,"g":1,"gp":"gg_N1_14"},{"id":"g1_041","t":"～といわず～といわず","ko":"~이고 ~이고 할 것 없이 (전부)","cat":"강조·한정","conn":[{"w":"명사 + 명사","f":"手 + といわず + 足 + といわず"}],"rule":["1. 같은 범위에 속하는 명사 둘을 고른다(手, 足).","2. 각 명사 뒤에 といわず를 하나씩 붙인다(手といわず足といわず).","3. 뒤에는 그 둘을 포함한 전체에 해당하는 내용이 온다(泥だらけ)."],"why":"と(인용) + 言う의 부정 중지형 言わず로, 'A라고도 하지 않고 B라고도 하지 않고', 곧 구별하지 않고 전부라는 뜻이 된다.","nu":"대표적인 두 가지를 예로 들어 '어디든 언제든 전부 그렇다'를 강조한다. 문어적이고 딱딱하다. 뒤에는 평가보다 눈에 보이는 상태나 사실이 오는 경우가 많다.","cmp":[{"g":"～といい～といい","d":"두 가지를 예로 들어 화자의 평가(둘 다 좋다/나쁘다)를 말한다. といわず는 구별 없이 전체에 해당한다는 사실을 강조한다."}],"ex":[{"jp":"子供[こども]は手[て]といわず足[あし]といわず、泥[どろ]だらけになって帰[かえ]ってきた。","ko":"아이는 손이고 발이고 할 것 없이 진흙투성이가 되어 돌아왔다."},{"jp":"この道[みち]は昼[ひる]といわず夜[よる]といわず、車[くるま]が多[おお]い。","ko":"이 길은 낮이고 밤이고 할 것 없이 차가 많다."},{"jp":"彼[かれ]の部屋[へや]は机[つくえ]の上[うえ]といわず床[ゆか]といわず、本[ほん]でいっぱいだ。","ko":"그의 방은 책상 위고 바닥이고 할 것 없이 책으로 가득하다."}],"dr":[{"t":"make","q":"昼・夜 → ～といわず～といわず","a":"昼といわず夜といわず","hint":"각 명사 뒤에 といわず"},{"t":"make","q":"手・顔 → ～といわず～といわず","a":"手といわず顔といわず","hint":"각 명사 뒤에 といわず"},{"t":"fill","q":"部屋[へや]は机[つくえ]（　）床[ゆか]といわず、本[ほん]だらけだ。","a":"といわず","opts":["といわず","といい","にしろ","からして"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%A8%E3%81%84%E3%82%8F%E3%81%9A"],"vf":1,"u":40,"g":1,"gp":"gg_N1_14"},{"id":"g1_044","t":"～ともあろう～","ko":"~씩이나 되는 (사람이)","cat":"강조·한정","conn":[{"w":"명사(지위·직업·조직) + 명사","f":"教師 + ともあろう + 者"}],"rule":["1. 높은 지위나 책임 있는 직업을 나타내는 명사를 놓는다(教師).","2. 그 뒤에 ともあろう를 그대로 붙인다.","3. 이어서 者・人 같은 명사와 が를 붙인다(教師ともあろう者が).","4. 뒤에는 그 지위에 어울리지 않는 행동에 대한 비난·놀람이 온다."],"why":"","nu":"문어적이고 딱딱하다. 사회적으로 존경받거나 책임이 큰 지위(교사, 경찰관, 사장, 대기업 등)를 들어 '그런 사람이 이런 일을 하다니'라고 비난하거나 놀라움을 나타낸다. 문장 끝에 なんて・とは・べきではない 등이 자주 온다. 칭찬에는 쓰지 않는다.","cmp":[{"g":"～ともなると","d":"그 지위·시기에 이르면 자연히 따르는 상황을 말한다. ともあろう는 그 지위에 어울리지 않는 행동을 비난한다."}],"ex":[{"jp":"教師[きょうし]ともあろう者[もの]が、道[みち]にごみを捨[す]てるなんて。","ko":"교사씩이나 되는 사람이 길에 쓰레기를 버리다니."},{"jp":"警察官[けいさつかん]ともあろう人[ひと]が、交通[こうつう]ルールを守[まも]らないとは驚[おどろ]いた。","ko":"경찰관씩이나 되는 사람이 교통 규칙을 지키지 않다니 놀랐다."},{"jp":"社長[しゃちょう]ともあろう人[ひと]が、そんな簡単[かんたん]なミスをするとは思[おも]わなかった。","ko":"사장씩이나 되는 사람이 그런 간단한 실수를 할 줄은 몰랐다."}],"dr":[{"t":"make","q":"教師・者 → ～ともあろう～が","a":"教師ともあろう者が","hint":"지위 명사 + ともあろう + 者 + が"},{"t":"make","q":"医者・人 → ～ともあろう～が","a":"医者ともあろう人が","hint":"지위 명사 + ともあろう + 人 + が"},{"t":"fill","q":"大学[だいがく]の先生[せんせい]（　）人[ひと]が、こんな間違[まちが]いをするなんて。","a":"ともあろう","opts":["ともあろう","ともなると","といわず","ならでは"]}],"src":["https://bunpro.jp/grammar_points/990"],"vf":1,"u":40,"g":1,"gp":"gg_N1_15"},{"id":"g1_052","t":"～ならでは","ko":"~만의, ~가 아니면 할 수 없는","cat":"강조·한정","conn":[{"w":"명사 + の + 명사","f":"母 + ならではの + 味"},{"w":"명사(문말)","f":"職人 + ならではだ"}],"rule":["1. 그 사람·장소·물건을 나타내는 명사를 놓고 ならでは를 붙인다(母ならでは).","2. 뒤의 명사를 꾸밀 때는 の를 넣는다(母ならではの味).","3. 문장 끝에서는 だ를 붙인다(職人ならではだ)."],"why":"","nu":"그 대상만이 가진 독특한 장점을 칭찬할 때 쓰며, 주로 좋은 평가에 쓴다. 광고나 관광 안내에서 자주 보인다. 명사를 꾸밀 때 の를 빠뜨리는 실수가 많다.","cmp":[{"g":"～らしい","d":"그 대상의 전형적인 성질을 말한다. ならでは는 그 대상이 아니면 있을 수 없는 독특함을 강조한다."}],"ex":[{"jp":"これは京都[きょうと]ならではの景色[けしき]だ。","ko":"이것은 교토만의 경치다."},{"jp":"母[はは]ならではの優[やさ]しい味[あじ]がする。","ko":"엄마만이 낼 수 있는 부드러운 맛이 난다."},{"jp":"この細[こま]かい仕事[しごと]は、職人[しょくにん]ならではだ。","ko":"이 섬세한 작업은 장인이 아니면 할 수 없다."}],"dr":[{"t":"make","q":"母・味 → ～ならではの～","a":"母ならではの味","hint":"명사 + ならでは + の + 명사"},{"t":"make","q":"京都・景色 → ～ならではの～","a":"京都ならではの景色","hint":"명사 + ならでは + の + 명사"},{"t":"fill","q":"これは地元[じもと]の人[ひと]（　）の楽[たの]しみ方[かた]だ。","a":"ならでは","opts":["ならでは","なりとも","なくして","ともあろう"]}],"src":["https://nihongokyoshi-net.com/2019/06/20/jlptn1-grammar-naradewa/"],"vf":1,"u":40,"g":1,"gp":"gg_N1_15"},{"id":"g1_054","t":"～なりとも","ko":"~만이라도, 조금이라도","cat":"강조·한정","conn":[{"w":"명사(최소량)","f":"一口 + なりとも"},{"w":"부사","f":"少し + なりとも"}],"rule":["1. 아주 적은 양을 나타내는 말을 놓는다(一口).","2. 그 뒤에 なりとも를 그대로 붙인다(一口なりとも).","3. 뒤에는 희망·부탁 표현이 온다(食べてください, 会いたい)."],"why":"","nu":"문어적이고 예스러운 표현이다. 一目・一言・一口・少し 같은 최소량을 들어 '그만큼이라도 좋으니'라는 바람이나 부탁을 나타낸다. 뒤에는 희망·의뢰·의지 표현이 오며 단순한 사실 서술에는 쓰지 않는다.","cmp":[{"g":"～だけでも","d":"뜻은 비슷하지만 회화에서 쓰는 일반적인 표현이다."}],"ex":[{"jp":"一口[ひとくち]なりとも食[た]べてください。","ko":"한 입만이라도 드세요."},{"jp":"一目[ひとめ]なりとも会[あ]いたい。","ko":"한 번만이라도 보고 싶다."},{"jp":"少[すこ]しなりともお役[やく]に立[た]てれば幸[さいわ]いです。","ko":"조금이라도 도움이 된다면 다행입니다."}],"dr":[{"t":"make","q":"一口 → ～なりとも","a":"一口なりとも","hint":"최소량 명사 + なりとも"},{"t":"make","q":"一目 → ～なりとも","a":"一目なりとも","hint":"최소량 명사 + なりとも"},{"t":"fill","q":"一言[ひとこと]（　）お礼[れい]を言[い]いたい。","a":"なりとも","opts":["なりとも","ときたら","ならでは","なくして"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/なりとも-nari-tomo-meaning/"],"vf":1,"u":41,"g":1,"gp":"gg_N1_15"},{"id":"g1_055","t":"～に～を重ねて","ko":"~에 ~를 거듭하여, 거듭거듭 ~해서","cat":"강조·한정","conn":[{"w":"명사(같은 명사 반복)","f":"努力 + に + 努力 + を + 重ねて"},{"w":"명사 + 명사 수식","f":"改良に改良を + 重ねた + 結果"}],"rule":["1. 같은 명사를 두 번 쓴다(努力 … 努力).","2. 첫 번째 명사 뒤에 に, 두 번째 명사 뒤에 を를 붙인다(努力に努力を).","3. 그 뒤에 重ねる(거듭하다)의 て형 重ねて를 붙인다(努力に努力を重ねて).","4. 명사를 꾸밀 때는 た형 重ねた를 쓴다(改良に改良を重ねた製品)."],"why":"같은 명사를 に와 を 앞에 반복하고 重ねる(겹치다, 거듭하다)를 붙인 형태로, '~ 위에 ~를 또 쌓아서'라는 구성이 그대로 '몇 번이고 거듭해서'라는 강조가 된다.","nu":"문어적이며 딱딱한 표현이다. 努力・苦労・研究・改良・失敗처럼 반복될 수 있는 행위·경험 명사에 쓴다. 두 명사는 반드시 같은 말이어야 한다. 긴 과정 끝에 어떤 결과에 이르렀다는 문맥에서 자주 쓰인다.","cmp":[{"g":"～を重ねる","d":"経験を重ねる처럼 명사 하나로도 '쌓다, 거듭하다'는 뜻이 된다. ～に～を重ねて는 같은 명사를 반복해 그 횟수와 정도를 더 강하게 강조한다."}],"ex":[{"jp":"彼[かれ]は努力[どりょく]に努力[どりょく]を重[かさ]ねて、ついに医者[いしゃ]になった。","ko":"그는 노력에 노력을 거듭해서 마침내 의사가 되었다."},{"jp":"苦労[くろう]に苦労[くろう]を重[かさ]ねて、やっと自分[じぶん]の店[みせ]を開[ひら]いた。","ko":"고생에 고생을 거듭한 끝에 겨우 내 가게를 열었다."},{"jp":"これは改良[かいりょう]に改良[かいりょう]を重[かさ]ねた製品[せいひん]です。","ko":"이것은 개량에 개량을 거듭한 제품입니다."}],"dr":[{"t":"make","q":"努力 → ～に～を重ねて","a":"努力に努力を重ねて","hint":"같은 명사를 반복: 명사 + に + 명사 + を + 重ねて"},{"t":"make","q":"改良 → ～に～を重ねた（製品）","a":"改良に改良を重ねた","hint":"명사를 꾸밀 때는 重ねた"},{"t":"fill","q":"苦労[くろう]に苦労[くろう]を（　）、やっと夢[ゆめ]がかなった。","a":"重ねて","opts":["重ねて","限って","先駆けて","即して"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/に～を重ねて-ni-o-kasanete-meaning/"],"vf":1,"u":41,"g":1,"gp":"gg_N1_15"},{"id":"g1_060","t":"～にすら","ko":"~에게조차, ~에조차","cat":"강조·한정","conn":[{"w":"명사","f":"親友 + に + すら"},{"w":"명사(대상·상대)","f":"自分の名前 + に + すら"}],"rule":["1. 동사가 요구하는 조사 に가 붙은 명사를 쓴다(親友に).","2. に 뒤에 すら를 붙인다(親友にすら).","3. 뒤 문장은 보통 부정이나 의외의 내용이 온다(親友にすら言えない)."],"why":"조사 に 뒤에 '~조차'를 뜻하는 すら가 붙은 형태다. すら는 さえ와 같은 뜻의 문어적인 말이다.","nu":"にさえ와 뜻이 같지만 すら가 더 문어적이다. '가장 가능성이 높은 것조차 그렇다 → 다른 것은 말할 것도 없다'는 극단의 예를 든다. に는 동사에 따라 정해지므로(言う・反応する・分かる 등) 조사 없이 すら만 쓰는 경우(水すら飲めない)와 구별해야 한다.","cmp":[{"g":"～にさえ","d":"뜻은 거의 같다. さえ는 회화에서도 자주 쓰고, すら는 더 딱딱하고 문어적이다."}],"ex":[{"jp":"その秘密[ひみつ]は親友[しんゆう]にすら言[い]えなかった。","ko":"그 비밀은 절친에게조차 말할 수 없었다."},{"jp":"この犬[いぬ]は自分[じぶん]の名前[なまえ]にすら反応[はんのう]しない。","ko":"이 개는 자기 이름에조차 반응하지 않는다."},{"jp":"それは専門家[せんもんか]にすら分[わ]からない問題[もんだい]だ。","ko":"그것은 전문가조차 알 수 없는 문제다."}],"dr":[{"t":"make","q":"親友 → ～にすら（言えない）","a":"親友にすら","hint":"명사 + に + すら"},{"t":"make","q":"専門家にも分からない → すら로 강조","a":"専門家にすら分からない","hint":"も 자리에 すら를 넣는다"},{"t":"fill","q":"母[はは]（　）言[い]えない悩[なや]みがある。","a":"にすら","opts":["にすら","にして","にあっては","にもまして"]}],"src":["https://www.mlcjapanese.co.jp/n1_04_06.html"],"vf":1,"u":41,"g":1,"gp":"gg_N1_15"},{"id":"g1_061","t":"～にとどまらず","ko":"~에 그치지 않고 (~도)","cat":"강조·한정","conn":[{"w":"명사","f":"国内 + にとどまらず"},{"w":"동사 사전형","f":"話す + にとどまらず"}],"rule":["1. とどまる(머무르다)의 어미 る를 ら로 바꿔 ない형 어간 とどまら를 만든다.","2. 그 뒤에 문어 부정 ず를 붙여 とどまらず가 된다.","3. 명사 뒤에 に + とどまらず를 붙인다(国内にとどまらず).","4. 뒤 문장에는 보통 も・まで로 범위가 더 넓어진 내용이 온다(海外でも)."],"why":"조사 に + とどまる(머무르다, 그치다)의 부정형 とどまらず(とどまらない의 문어형)로 이루어져 '~에 머무르지 않고'라는 뜻이 된다.","nu":"문어적이며 뉴스·논설에서 자주 쓴다. 어떤 일의 범위·영향이 한정된 곳을 넘어 더 넓게 퍼짐을 말한다. 뒤 문장에 も・まで・にも 등이 자주 함께 온다. 범위가 넓어지는 방향이어야 하며, 단순 나열에는 쓰지 않는다.","cmp":[{"g":"～だけでなく","d":"회화에서도 두루 쓰는 '~뿐만 아니라'. にとどまらず는 문어적이고 범위가 넘어 퍼진다는 느낌이 강하다."}],"ex":[{"jp":"その歌[うた]は国内[こくない]にとどまらず、海外[かいがい]でも人気[にんき]がある。","ko":"그 노래는 국내에 그치지 않고 해외에서도 인기가 있다."},{"jp":"被害[ひがい]は一[ひと]つの町[まち]にとどまらず、周[まわ]りの地域[ちいき]にも広[ひろ]がった。","ko":"피해는 한 마을에 그치지 않고 주변 지역으로도 퍼졌다."},{"jp":"彼[かれ]の研究[けんきゅう]は医学[いがく]にとどまらず、教育[きょういく]の分野[ぶんや]にも影響[えいきょう]を与[あた]えた。","ko":"그의 연구는 의학에 그치지 않고 교육 분야에도 영향을 주었다."}],"dr":[{"t":"make","q":"とどまる → ～ず","a":"とどまらず","hint":"어미 る를 ら로 바꾸고 ず를 붙인다"},{"t":"make","q":"国内 → ～にとどまらず","a":"国内にとどまらず","hint":"명사 + に + とどまらず"},{"t":"fill","q":"彼[かれ]の人気[にんき]は日本[にほん]（　）、世界中[せかいじゅう]に広[ひろ]がっている。","a":"にとどまらず","opts":["にとどまらず","にひきかえ","にすら","にあるまじき"]}],"src":["https://nihongokyoshi-net.com/2019/06/27/jlptn1-grammar-nitodomarazu/"],"vf":1,"u":41,"g":1,"gp":"gg_N1_15"},{"id":"g1_069","t":"～に限ったことではない","ko":"~에 한한 일이 아니다, ~만의 일이 아니다","cat":"강조·한정","conn":[{"w":"명사","f":"若者 + に限ったことではない"},{"w":"명사(때)","f":"今日 + に限ったことではない"}],"rule":["1. 限る(한정하다)의 어미 る를 った로 바꿔 た형 限った를 만든다.","2. 限った 뒤에 こと(일)와 ではない(아니다)를 붙인다(限ったことではない).","3. 명사 뒤에 に + 限ったことではない를 붙인다(若者に限ったことではない)."],"why":"に + 限る(한정하다)의 た형 限った + こと(일) + ではない(아니다)로 이루어져 '~에 한정된 일이 아니다'라는 뜻이 된다.","nu":"어떤 현상·문제가 그 대상에만 해당하지 않고 더 넓게 있다는 뜻이다. 문제점·좋지 않은 일에 자주 쓴다. '今日に限ったことではない'는 '오늘만 그런 게 아니다(늘 그렇다)'라는 불만 섞인 표현으로 자주 쓴다. 문장 끝에 쓰며 회화·문어 모두 가능하다.","cmp":[{"g":"～だけではない","d":"일반적인 '~뿐만이 아니다'. に限ったことではない는 화제가 되는 현상이 그 범위에 한정되지 않음을 말하는 문말 표현이다."}],"ex":[{"jp":"物価[ぶっか]が上[あ]がっているのは日本[にほん]に限[かぎ]ったことではない。","ko":"물가가 오르고 있는 것은 일본만의 일이 아니다."},{"jp":"スマホを見[み]すぎるのは若者[わかもの]に限[かぎ]ったことではない。","ko":"스마트폰을 너무 많이 보는 것은 젊은이만의 일이 아니다."},{"jp":"彼[かれ]が遅刻[ちこく]するのは今日[きょう]に限[かぎ]ったことではない。","ko":"그가 지각하는 것은 오늘만의 일이 아니다."}],"dr":[{"t":"make","q":"限る → た형","a":"限った","hint":"る를 った로 바꾼다"},{"t":"make","q":"日本 → ～に限ったことではない","a":"日本に限ったことではない","hint":"명사 + に限ったことではない"},{"t":"fill","q":"彼[かれ]の遅刻[ちこく]は今日[きょう]（　）。","a":"に限ったことではない","opts":["に限ったことではない","に言わせれば","にもまして","に先駆けて"]}],"src":["https://nihongokyoshi-net.com/2020/01/13/jlptn1-grammar-nikagittakotodewanai/","https://bunpro.jp/grammar_points/998"],"vf":1,"u":41,"g":1,"gp":"gg_N1_15"},{"id":"g1_070","t":"～に限ったことでもない","ko":"~에 한한 일도 아니다, 꼭 ~만의 일도 아니다","cat":"강조·한정","conn":[{"w":"명사","f":"大人 + に限ったことでもない"}],"rule":["1. 명사 뒤에 に限ったこと를 붙인다(大人に限ったこと).","2. 그 뒤의 ではない에서 は를 も로 바꿔 でもない로 만든다(大人に限ったことでもない).","3. 限った는 限る의 る를 った로 바꾼 た형이다."],"why":"に限ったことではない의 は를 '~도'의 も로 바꾼 형태다.","nu":"に限ったことではない와 뜻은 같지만, も가 들어가 '꼭 ~만의 일인 것도 아니다'처럼 단정이 조금 부드러워지고, 다른 경우도 있다는 느낌이 더해진다. 뒤에 '~も同じだ' 같은 다른 예를 덧붙이는 경우가 많다.","cmp":[{"g":"～に限ったことではない","d":"ではない로 분명하게 부정한다. でもない는 も가 들어가 '~만의 일인 것도 아니다'라고 조금 부드럽게 말한다."}],"ex":[{"jp":"運動不足[うんどうぶそく]は大人[おとな]に限[かぎ]ったことでもない。子[こ]どもも同[おな]じだ。","ko":"운동 부족은 꼭 어른만의 일도 아니다. 아이도 마찬가지다."},{"jp":"雨[あめ]の日[ひ]に電車[でんしゃ]が遅[おく]れるのは、この路線[ろせん]に限[かぎ]ったことでもない。","ko":"비 오는 날 전철이 늦는 것은 이 노선만의 일도 아니다."},{"jp":"字[じ]が下手[へた]なのは彼[かれ]に限[かぎ]ったことでもない。","ko":"글씨를 못 쓰는 것은 그만의 일도 아니다."}],"dr":[{"t":"make","q":"大人に限ったことではない → も를 넣어서","a":"大人に限ったことでもない","hint":"ではない의 は를 も로 바꾼다"},{"t":"make","q":"子ども → ～に限ったことでもない","a":"子どもに限ったことでもない","hint":"명사 + に限ったことでもない"},{"t":"fill","q":"運動不足[うんどうぶそく]は子[こ]どもに（　）。大人[おとな]も同[おな]じだ。","a":"限ったことでもない","opts":["限ったことでもない","言わせれば","先駆けて","即して"]}],"src":[],"vf":0,"u":42,"g":1,"gp":"gg_N1_15"},{"id":"g1_087","t":"～はおろか～すら","ko":"~은커녕 ~조차","cat":"강조·한정","conn":[{"w":"명사","f":"漢字 + はおろか + ひらがな + すら"},{"w":"동사 + こと","f":"走ること + はおろか + 歩くこと + すら"}],"rule":["1. 정도가 큰(어려운) 명사A 뒤에 はおろか를 붙인다: 漢字はおろか.","2. 더 기본적인(쉬운) 명사B 뒤에 すら(또는 さえ)를 붙인다: ひらがなすら.","3. 동사는 こと를 붙여 명사로 만든다: 走ることはおろか.","4. 뒤에는 주로 부정 표현(～ない)이 온다."],"why":"","nu":"'A는 말할 것도 없고 가장 기본적인 B조차 ~않다'는 뜻으로, 말하는 사람의 놀람이나 불만이 담긴다. 문어적인 표현이다. 뒤에 의지·명령·권유 표현(～しよう, ～しなさい)은 쓰지 않는다. A에는 큰 것, B에는 작은 것을 놓는 순서를 반대로 쓰지 않도록 주의한다.","cmp":[{"g":"～どころか","d":"회화에서도 쓰며, '~은커녕 오히려 반대'라는 뜻으로도 쓸 수 있다."},{"g":"～はもちろん","d":"중립적인 '~은 물론'으로, 좋은 일에도 자연스럽게 쓴다. はおろか는 주로 부정적인 상황에 쓴다."}],"ex":[{"jp":"彼[かれ]は漢字[かんじ]はおろか、ひらがなすら読[よ]めない。","ko":"그는 한자는커녕 히라가나조차 못 읽는다."},{"jp":"忙[いそが]しくて、旅行[りょこう]はおろか、休[やす]みの日[ひ]すらない。","ko":"바빠서 여행은커녕 쉬는 날조차 없다."},{"jp":"足[あし]をけがして、走[はし]ることはおろか、歩[ある]くことすらできない。","ko":"다리를 다쳐서 달리기는커녕 걷는 것조차 못 한다."}],"dr":[{"t":"make","q":"漢字 / ひらがな / 書けない → ～はおろか～すら","a":"漢字はおろか、ひらがなすら書けない","hint":"A + はおろか、B + すら + 부정"},{"t":"make","q":"貯金 / 生活費 / ない → ～はおろか～すら","a":"貯金はおろか、生活費すらない","hint":"큰 것 A + はおろか、기본적인 B + すら"},{"t":"fill","q":"熱[ねつ]が高[たか]くて、食事[しょくじ]はおろか水[みず]（　）飲[の]めなかった。","a":"すら","opts":["すら","だけ","しか","ばかり"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AF%E3%81%8A%E3%82%8D%E3%81%8B","https://jlptsensei.com/learn-japanese-grammar/はおろか-wa-oroka-meaning/"],"vf":1,"u":42,"g":1,"gp":"gg_N1_15"},{"id":"g1_088","t":"～はおろか～まで","ko":"~은커녕(물론) ~까지","cat":"강조·한정","conn":[{"w":"명사","f":"財布 + はおろか + パスポート + まで"},{"w":"명사 + 조사","f":"友達 + はおろか + 家族に + まで"}],"rule":["1. 당연히 해당하는 명사A 뒤에 はおろか를 붙인다: 財布はおろか.","2. 범위가 더 넓어진 명사B 뒤에 まで를 붙인다: パスポートまで.","3. 뒤에는 예상을 넘어선 결과(주로 바람직하지 않은 일)를 쓴다."],"why":"","nu":"'A는 말할 것도 없고 B까지'라는 뜻으로 범위가 예상 이상으로 넓어졌다는 놀람을 나타낸다. まで를 쓰면 부정문이 아닌 긍정문(なくした, 飛ばされた)으로도 자연스럽게 쓴다. 문어적이며, 뒤에 의지·명령·권유 표현은 쓰지 않는다.","cmp":[{"g":"～はおろか～すら","d":"すら는 '가장 기본적인 B조차 ~않다'처럼 주로 부정문에 쓴다. まで는 '거기까지 미쳤다'는 확대를 나타낸다."},{"g":"～ばかりか～まで","d":"회화에서도 쓰며, 좋은 일에도 나쁜 일에도 쓴다."}],"ex":[{"jp":"旅行先[りょこうさき]で財布[さいふ]はおろか、パスポートまでなくしてしまった。","ko":"여행지에서 지갑은커녕 여권까지 잃어버리고 말았다."},{"jp":"台風[たいふう]で、窓[まど]はおろか屋根[やね]まで飛[と]ばされた。","ko":"태풍으로 창문은 물론 지붕까지 날아갔다."},{"jp":"彼[かれ]は友達[ともだち]はおろか、家族[かぞく]にまで嘘[うそ]をついていた。","ko":"그는 친구는 물론 가족에게까지 거짓말을 하고 있었다."}],"dr":[{"t":"make","q":"財布 / 携帯 / なくした → ～はおろか～まで","a":"財布はおろか、携帯までなくした","hint":"A + はおろか、B + まで"},{"t":"make","q":"手 / 顔 / 汚れた → ～はおろか～まで","a":"手はおろか、顔まで汚れた","hint":"A + はおろか、B + まで + 결과"},{"t":"fill","q":"雨[あめ]で、靴[くつ]はおろか下着[したぎ]（　）濡[ぬ]れてしまった。","a":"まで","opts":["まで","しか","だけ","ほど"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AF%E3%81%8A%E3%82%8D%E3%81%8B","https://jlptsensei.com/learn-japanese-grammar/はおろか-wa-oroka-meaning/"],"vf":1,"u":42,"g":1,"gp":"gg_N1_15"},{"id":"g1_089","t":"～はおろか～も","ko":"~은커녕 ~도","cat":"강조·한정","conn":[{"w":"명사","f":"コンビニ + はおろか + バス停 + も"},{"w":"동사 + こと","f":"走ること + はおろか + 立つこと + も"}],"rule":["1. 정도가 큰 명사A 뒤에 はおろか를 붙인다: コンビニはおろか.","2. 더 기본적인 명사B 뒤에 も를 붙인다: バス停も.","3. 뒤에는 주로 부정 표현(～ない)이 온다: バス停もない."],"why":"","nu":"'A는 말할 것도 없고 B도 ~않다'는 뜻으로, すら・さえ보다 강조가 약간 부드럽다. 문어적이며 놀람이나 불만이 담긴다. 뒤에 의지·명령·권유 표현은 쓰지 않는다. A에 큰 것, B에 작은(기본적인) 것을 놓는다.","cmp":[{"g":"～はおろか～すら / さえ","d":"すら・さえ는 '~조차'로 B가 가장 기본적인 것임을 더 강하게 강조한다."},{"g":"～どころか～も","d":"회화에서도 쓰는 비슷한 표현이다."}],"ex":[{"jp":"祖父[そふ]はパソコンはおろか、携帯電話[けいたいでんわ]も使[つか]えない。","ko":"할아버지는 컴퓨터는커녕 휴대전화도 못 쓰신다."},{"jp":"忙[いそが]しくて、昼[ひる]ご飯[はん]はおろか、朝[あさ]ご飯[はん]も食[た]べていない。","ko":"바빠서 점심은커녕 아침도 못 먹었다."},{"jp":"この村[むら]には、コンビニはおろか、バス停[てい]もない。","ko":"이 마을에는 편의점은커녕 버스 정류장도 없다."}],"dr":[{"t":"make","q":"海外旅行 / 国内旅行 / したことがない → ～はおろか～も","a":"海外旅行はおろか、国内旅行もしたことがない","hint":"A + はおろか、B + も + 부정"},{"t":"make","q":"車 / 自転車 / ない → ～はおろか～も","a":"車はおろか、自転車もない","hint":"A + はおろか、B + も + ない"},{"t":"fill","q":"疲[つか]れて、走[はし]ることはおろか、立[た]つこと（　）できない。","a":"も","opts":["も","しか","だけ","こそ"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/はおろか-wa-oroka-meaning/","https://bunpro.jp/grammar_points/%E3%81%AF%E3%81%8A%E3%82%8D%E3%81%8B"],"vf":1,"u":42,"g":1,"gp":"gg_N1_15"},{"id":"g1_093","t":"～もさることながら","ko":"~도 물론이거니와","cat":"강조·한정","conn":[{"w":"명사","f":"味 + もさることながら"}],"rule":["1. 명사A 뒤에 조사 も를 붙인다: 歌 → 歌も.","2. 그 뒤에 さることながら(물론이지만)를 붙인다: 歌もさることながら.","3. 뒤에 더 강조하고 싶은 명사B를 놓고 も 등을 붙인다: 歌もさることながら、ダンスも."],"why":"さる(然る, 그러한) + こと + ながら(~이지만)로 이루어져 '그것도 그렇지만'이라는 뜻이 된다.","nu":"문어적이고 격식 있는 표현으로, 주로 사람이나 물건을 높이 평가할 때 쓴다. A도 당연히 훌륭하지만 B 쪽에 더 무게를 둔다. 뒤에는 B + も 외에 B + が/は도 올 수 있다. 부정적인 내용을 늘어놓을 때는 잘 쓰지 않는다.","cmp":[{"g":"～はもちろん","d":"회화에서도 널리 쓰며 A는 당연하고 B까지라는 뜻이다. もさることながら는 더 딱딱하고 B 쪽을 더 강조한다."},{"g":"～はもとより","d":"はもちろん의 격식체로, もさることながら만큼 B를 강조하는 느낌은 약하다."}],"ex":[{"jp":"この店[みせ]は味[あじ]もさることながら、値段[ねだん]の安[やす]さも魅力[みりょく]だ。","ko":"이 가게는 맛도 물론이거니와 싼 가격도 매력이다."},{"jp":"彼女[かのじょ]は歌[うた]もさることながら、ダンスも上手[じょうず]だ。","ko":"그녀는 노래도 물론이지만 춤도 잘 춘다."},{"jp":"この試験[しけん]では、知識[ちしき]もさることながら、考[かんが]える力[ちから]が問[と]われる。","ko":"이 시험에서는 지식도 물론이거니와 생각하는 힘이 요구된다."}],"dr":[{"t":"make","q":"味 / サービス → ～もさることながら、～も","a":"味もさることながら、サービスも","hint":"명사A + も + さることながら、명사B + も"},{"t":"make","q":"デザイン / 使いやすさ → ～もさることながら、～も","a":"デザインもさることながら、使いやすさも","hint":"명사A + も + さることながら、명사B + も"},{"t":"fill","q":"この町[まち]は景色[けしき]（　）、食[た]べ物[もの]もおいしい。","a":"もさることながら","opts":["もさることながら","をものともせず","をよそに","をおいて"]}],"src":["https://bunpro.jp/grammar_points/845"],"vf":1,"u":43,"g":1,"gp":"gg_N1_15"},{"id":"g1_096","t":"～をおいて他に～ない","ko":"~을 빼고는 달리 (~없다)","cat":"강조·한정","conn":[{"w":"명사","f":"彼 + をおいて他にいない"}],"rule":["1. 1그룹 동사 おく의 어미 く를 い로 바꾼다(イ음편): おく → おい.","2. て를 붙여 おいて를 만들고, 명사 + を 뒤에 둔다: 彼をおいて.","3. 뒤에 他に(ほかに) + 부정형(いない / ない)을 써서 '그 외에는 없다'로 끝맺는다."],"why":"동사 おく(措く, 제쳐 두다)의 て형으로, '~을 제쳐 두고는 (달리) 없다'는 뜻이 된다.","nu":"문어적·격식 있는 표현이다. 주로 그 사람·장소·것이 유일하게 적합하다고 높이 평가할 때 쓴다. 사람이면 いない, 사물·장소면 ない를 쓴다. 他に는 생략하기도 한다(～をおいてない). 한국어 '~을 두고'로 직역해 일반적인 한정(~밖에 없다)에 쓰지 않도록 주의한다.","cmp":[{"g":"～しか～ない","d":"단순한 한정으로 평가의 뜻이 없다(百円しかない). をおいて他にない는 최고·유일이라는 높은 평가가 들어간다."},{"g":"～以外に～ない","d":"'~ 외에는 없다'는 중립적인 표현으로 회화에서도 쓴다."}],"ex":[{"jp":"このチームのキャプテンは、彼[かれ]をおいて他[ほか]にいない。","ko":"이 팀의 주장은 그 사람 말고는 달리 없다."},{"jp":"日本[にほん]の秋[あき]を楽[たの]しむなら、京都[きょうと]をおいて他[ほか]にない。","ko":"일본의 가을을 즐긴다면 교토만 한 곳이 없다."},{"jp":"この難[むずか]しい手術[しゅじゅつ]ができるのは、田中[たなか]先生[せんせい]をおいて他[ほか]にいない。","ko":"이 어려운 수술을 할 수 있는 사람은 다나카 선생님 말고는 없다."}],"dr":[{"t":"make","q":"彼 → ～をおいて他にいない","a":"彼をおいて他にいない","hint":"명사 + を + おく의 て형(く → いて) + 他に + いない"},{"t":"make","q":"この店 → ～をおいて他にない","a":"この店をおいて他にない","hint":"사물·장소는 ない로 끝낸다"},{"t":"fill","q":"社長[しゃちょう]の後継者[こうけいしゃ]は、山田[やまだ]さん（　）他[ほか]にいない。","a":"をおいて","opts":["をおいて","をもって","をよそに","を経て"]}],"src":["https://bunpro.jp/grammar_points/783","https://jlptsensei.com/learn-japanese-grammar/jlpt-n1-grammar-をおいて～ない-o-oitenai-meaning/"],"vf":1,"u":43,"g":1,"gp":"gg_N1_16"},{"id":"g1_115","t":"～こそすれ","ko":"~하면 했지 (반대로 ~하지는 않는다)","cat":"강조·한정","conn":[{"w":"동사 ます형","f":"褒め + こそすれ"},{"w":"する동사의 명사 부분","f":"感謝 + こそすれ"}],"rule":["1. 2그룹 동사 褒める의 어미 る를 떼어 ます형 褒め를 만든다.","2. 강조 조사 こそ를 붙인다: 褒めこそ.","3. する의 옛 활용형 すれ를 붙인다: 褒めこそすれ.","4. 뒤에 정반대의 일을 부정하는 문장을 둔다: 褒めこそすれ、叱ることはない."],"why":"강조 조사 こそ에 する의 고전 이연형(已然形) すれ가 이어진 형태다.","nu":"Xこそすれ、Y(は)ない의 형태로 'X라면 몰라도 그 반대인 Y는 절대 아니다'라고 강하게 부정한다. X와 Y는 感謝와 恨む, 増える와 減る처럼 서로 반대되는 일이어야 한다. 딱딱한 문어체로 회화에는 거의 쓰지 않는다. 단순히 'X는 하지만 Y는 안 한다'처럼 반대 관계가 아닌 두 일을 대비하는 데 쓰는 것은 틀린 사용이다.","cmp":[{"g":"～こそあれ","d":"명사·형용사 쪽에 붙어 '~는 있어도'라는 뜻이다(程度の差こそあれ, 違いこそあれ). こそすれ는 동사 ます형·する동사 명사에 붙는다."}],"ex":[{"jp":"助[たす]けてもらって感謝[かんしゃ]こそすれ、恨[うら]むことなどない。","ko":"도움을 받았으니 감사하면 했지 원망할 리는 없다."},{"jp":"このままでは赤字[あかじ]は増[ふ]えこそすれ、減[へ]ることはないだろう。","ko":"이대로라면 적자는 늘어나면 늘어났지 줄어들지는 않을 것이다."},{"jp":"彼[かれ]の行動[こうどう]は褒[ほ]められこそすれ、責[せ]められるものではない。","ko":"그의 행동은 칭찬받으면 받았지 비난받을 것은 아니다."}],"dr":[{"t":"make","q":"感謝する → ～こそすれ","a":"感謝こそすれ","hint":"する를 빼고 명사 + こそすれ"},{"t":"make","q":"増える → ～こそすれ","a":"増えこそすれ","hint":"る를 떼어 ます형 + こそすれ"},{"t":"fill","q":"親切[しんせつ]にしてもらって、感謝[かんしゃ]（　）、文句[もんく]を言[い]うことはない。","a":"こそすれ","opts":["こそすれ","ばかりか","がてら","なりに"]}],"src":["https://bunpro.jp/grammar_points/991"],"vf":1,"u":43,"g":1,"gp":"gg_N1_16"},{"id":"g1_128","t":"～たらきりがない","ko":"~하자면 끝이 없다","cat":"강조·한정","conn":[{"w":"동사 た형","f":"数えた + ら + きりがない"},{"w":"する동사","f":"心配した + ら + きりがない"}],"rule":["1. 동사를 た형으로 바꾼다. 2그룹 동사는 어미 る를 た로 바꾼다: 数える → 数えた.","2. た형 뒤에 조건의 ら를 붙인다: 数えたら.","3. 그 뒤에 きりがない를 붙인다: 数えたらきりがない.","4. 1그룹 동사는 음편을 거친다: 言う → 言ったら, する → したら."],"why":"きり(切り, 끝·한도) + が + ない(없다)로, 말 그대로 '한도가 없다'는 뜻이다.","nu":"그 일을 하기 시작하면 끝이 나지 않으니 적당히 해야 한다는 뜻으로 쓴다. 言う, 数える, 心配する, 挙げる, 気にする처럼 계속 이어질 수 있는 행위와 잘 어울린다. ～ばきりがない, ～ときりがない도 같은 뜻이다. たら형·と형은 회화적이고, ばきりがない가 더 표준적인 형태다.","cmp":[{"g":"～ばきりがない","d":"뜻은 같고 조건 형태만 ば형이다(言えばきりがない). 관용구로는 上を見ればきりがない가 흔하다."}],"ex":[{"jp":"細[こま]かいことを気[き]にしたらきりがない。","ko":"사소한 것을 신경 쓰자면 끝이 없다."},{"jp":"欲[ほ]しい物[もの]を数[かぞ]えたらきりがない。","ko":"갖고 싶은 것을 세자면 끝이 없다."},{"jp":"文句[もんく]を言[い]ったらきりがないから、もうやめよう。","ko":"불평을 하자면 끝이 없으니까 이제 그만하자."}],"dr":[{"t":"make","q":"心配する → ～たらきりがない","a":"心配したらきりがない","hint":"する → した, ら + きりがない"},{"t":"make","q":"挙げる → ～たらきりがない","a":"挙げたらきりがない","hint":"る → た, ら + きりがない"},{"t":"fill","q":"彼[かれ]の欠点[けってん]は、言[い]い出[だ]したら（　）。","a":"きりがない","opts":["きりがない","しかたがない","はずがない","わけがない"]}],"src":["https://www.vnjpclub.com/en/n1-grammar/bakiriga-nai.html"],"vf":1,"u":43,"g":1,"gp":"gg_N1_16"},{"id":"g1_132","t":"～てこそ","ko":"~해야 비로소","cat":"강조·한정","conn":[{"w":"동사 て형","f":"登って + こそ"},{"w":"する동사","f":"経験して + こそ"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 る동사는 어미 る가 っ로 바뀌고(촉음편) て가 붙는다: 登る → 登って.","2. て형 뒤에 강조 조사 こそ를 붙인다: 登ってこそ.","3. 2그룹은 る를 빼고 て, する는 して: 見る → 見てこそ, 経験する → 経験してこそ."],"why":"","nu":"그 행위를 해야만 뒤의 좋은 결과나 깨달음·가치가 생긴다는 뜻이다. 뒤에는 주로 긍정적인 평가(分かる, できる, 意味がある 등)가 오고, 부정적인 결과에는 잘 쓰지 않는다. 약간 딱딱하지만 회화에서도 쓴다.","cmp":[{"g":"～てはじめて","d":"~하고 나서야 처음으로 (깨닫다). 실제 경험의 순서를 말한다. てこそ는 그것이 꼭 필요한 조건이라는 평가를 강조한다."}],"ex":[{"jp":"この景色[けしき]は、自分[じぶん]の足[あし]で登[のぼ]ってこそ見[み]られる。","ko":"이 경치는 자기 발로 올라가야 비로소 볼 수 있다."},{"jp":"言葉[ことば]は実際[じっさい]に使[つか]ってこそ身[み]につく。","ko":"말은 실제로 써야 비로소 몸에 익는다."},{"jp":"失敗[しっぱい]してこそ分[わ]かることもある。","ko":"실패해야 비로소 알게 되는 것도 있다."}],"dr":[{"t":"make","q":"努力する → ～てこそ","a":"努力してこそ","hint":"する → して, + こそ"},{"t":"make","q":"読む → ～てこそ","a":"読んでこそ","hint":"む → んで(발음편), + こそ"},{"t":"fill","q":"親[おや]になって（　）、親[おや]の気持[きも]ちが分[わ]かる。","a":"こそ","opts":["こそ","さえ","まで","しか"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/てこそ-te-koso-meaning/"],"vf":1,"u":43,"g":1,"gp":"gg_N1_16"},{"id":"g1_135","t":"～てまでも","ko":"~하면서까지","cat":"강조·한정","conn":[{"w":"동사 て형","f":"削って + までも"},{"w":"する동사","f":"借金して + までも"}],"rule":["1. 동사를 て형으로 바꾼다. する는 불규칙으로 して가 된다: 借金する → 借金して.","2. て형 뒤에 まで를 붙인다: 借金してまで.","3. 강조의 も를 더한다: 借金してまでも.","4. 1그룹 동사는 음편을 거친다: 削る → 削って, 並ぶ → 並んで."],"why":"동사 て형 + 극단을 나타내는 まで(~까지) + 강조 も로 이루어져 '그런 일까지 해서'라는 뜻이 된다.","nu":"보통은 하지 않을 극단적인 수단을 써서라도 무언가를 한다는 뜻이다. 뒤에는 말하는 사람의 의지·희망(～たい), 또는 비판·부정(～たくない, ～必要はない)이 자주 온다. も가 없는 ～てまで와 뜻은 같고, までも는 강조가 조금 더 세다.","cmp":[{"g":"～てまで","d":"뜻은 같다. 회화에서는 も 없이 てまで를 더 자주 쓴다."}],"ex":[{"jp":"借金[しゃっきん]してまでも、その車[くるま]が欲[ほ]しいとは思[おも]わない。","ko":"빚을 지면서까지 그 차를 갖고 싶지는 않다."},{"jp":"彼[かれ]は寝[ね]る時間[じかん]を削[けず]ってまでも練習[れんしゅう]を続[つづ]けた。","ko":"그는 잘 시간을 줄이면서까지 연습을 계속했다."},{"jp":"何時間[なんじかん]も並[なら]んでまでも、あの店[みせ]のラーメンを食[た]べたい。","ko":"몇 시간이나 줄을 서서라도 그 가게 라멘을 먹고 싶다."}],"dr":[{"t":"make","q":"無理する → ～てまでも","a":"無理してまでも","hint":"する → して, + までも"},{"t":"make","q":"並ぶ → ～てまでも","a":"並んでまでも","hint":"ぶ → んで(발음편), + までも"},{"t":"fill","q":"友達[ともだち]を裏切[うらぎ]って（　）、お金[かね]を手[て]に入[い]れたくない。","a":"までも","opts":["までも","ばかりか","からには","ばこそ"]}],"src":[],"vf":0,"u":44,"g":1,"gp":"gg_N1_16"},{"id":"g1_137","t":"～てやまない","ko":"~해 마지않다, 진심으로 ~하다","cat":"강조·한정","conn":[{"w":"감정·바람의 동사 て형","f":"祈って + やまない"},{"w":"する동사","f":"期待して + やまない"}],"rule":["1. 동사를 て형으로 바꾼다. 1그룹 る동사는 어미 る가 っ로 바뀌고(촉음편) て가 붙는다: 祈る → 祈って.","2. て형 뒤에 やまない를 붙인다: 祈ってやまない.","3. やまない는 やむ(그치다)의 ない형으로, む가 ま로 바뀐 것이다: やむ → やまない."],"why":"止む(やむ, 그치다)의 부정형 やまない가 붙어 '~하는 마음이 그치지 않는다'는 뜻이 된다.","nu":"어떤 감정이 오래도록 강하게 이어진다는 딱딱한 문어체 표현이다. 願う, 祈る, 望む, 愛する, 期待する, 尊敬する 같은 감정·바람의 동사에만 쓴다. 인사말·연설·글에서 말하는 사람의 마음을 나타낼 때 많이 쓰며, 3인칭에는 彼が愛してやまない町처럼 명사 수식으로 쓰는 경우가 많다. 일상 동작(食べる 등)에는 쓸 수 없다.","cmp":[{"g":"～てたまらない","d":"참을 수 없을 만큼 ~하다. 회화체이며 감각·감정(暑い, 嬉しい)에 쓴다. てやまない는 격식 있는 글에서 바람·존경 등에 쓴다."}],"ex":[{"jp":"皆様[みなさま]のご健康[けんこう]を祈[いの]ってやみません。","ko":"여러분의 건강을 진심으로 기원합니다."},{"jp":"子[こ]どもたちの幸[しあわ]せを願[ねが]ってやまない。","ko":"아이들의 행복을 바라 마지않는다."},{"jp":"ここは彼[かれ]が愛[あい]してやまなかった町[まち]だ。","ko":"이곳은 그가 끔찍이도 사랑했던 마을이다."}],"dr":[{"t":"make","q":"願う → ～てやまない","a":"願ってやまない","hint":"う → って(촉음편), + やまない"},{"t":"make","q":"期待する → ～てやまない","a":"期待してやまない","hint":"する → して, + やまない"},{"t":"fill","q":"両国[りょうこく]の平和[へいわ]を望[のぞ]んで（　）。","a":"やまない","opts":["やまない","ならない","いられない","かなわない"]}],"src":["https://bunpro.jp/grammar_points/828"],"vf":1,"u":44,"g":1,"gp":"gg_N1_16"},{"id":"g1_138","t":"～ないではおかない","ko":"반드시 ~하게 만든다, 꼭 ~하고야 말겠다","cat":"강조·한정","conn":[{"w":"동사 ない형 (주로 사역형)","f":"泣かせない + ではおかない"},{"w":"동사 ない형 (의지)","f":"捕まえない + ではおかない"},{"w":"불규칙 する","f":"しない + ではおかない"}],"rule":["1. 동사의 어미 う단을 あ단으로 바꾸고 사역의 せる를 붙인다: 泣く → 泣かせる.","2. 사역형의 る를 ない로 바꾼다: 泣かせる → 泣かせない.","3. ない형 뒤에 ではおかない를 붙인다: 泣かせないではおかない.","4. 의지의 뜻에서는 사역 없이 ない형에 바로 붙인다: 捕まえる → 捕まえないではおかない."],"why":"ない형 + では + おく(그대로 두다)의 부정형으로, '~하지 않은 채로 두지 않는다'는 뜻이다.","nu":"① 무생물이나 사건이 주어가 되어 사람에게 어떤 감정·행동을 반드시 일으킨다는 뜻(この映画は見る人を泣かせないではおかない)으로, 感動させる, 考えさせる 같은 사역형과 자주 쓴다. ② 말하는 사람의 '반드시 ~하겠다'는 강한 의지. 딱딱한 문어체이며, 같은 뜻의 ～ずにはおかない가 더 자주 쓰인다. ～ないではいられない(나도 모르게 ~하게 된다)와 혼동하기 쉽다.","cmp":[{"g":"～ないではいられない","d":"말하는 사람이 저절로 그렇게 하게 된다는 뜻(泣かないではいられない). ないではおかない는 주로 대상이 사람에게 그런 결과를 일으킨다는 뜻이다."},{"g":"～ずにはおかない","d":"같은 뜻의 더 문어적인 형태. する는 せずにはおかない가 된다."}],"ex":[{"jp":"この映画[えいが]は見[み]る人[ひと]を泣[な]かせないではおかない。","ko":"이 영화는 보는 사람을 반드시 울리고 만다."},{"jp":"彼[かれ]の話[はなし]は聞[き]く人[ひと]を考[かんが]えさせないではおかない。","ko":"그의 이야기는 듣는 사람을 반드시 생각하게 만든다."},{"jp":"犯人[はんにん]を捕[つか]まえないではおかない。","ko":"범인을 꼭 잡고야 말겠다."}],"dr":[{"t":"make","q":"感動させる → ～ないではおかない","a":"感動させないではおかない","hint":"る → ない, + ではおかない"},{"t":"make","q":"笑う(사역) → ～ないではおかない","a":"笑わせないではおかない","hint":"う → わ + せる, る → ない, + ではおかない"},{"t":"fill","q":"彼[かれ]の演奏[えんそう]は聴[き]く人[ひと]を感動[かんどう]させないでは（　）。","a":"おかない","opts":["おかない","いられない","すまない","ならない"]}],"src":["https://bunpro.jp/grammar_points/945"],"vf":1,"u":44,"g":1,"gp":"gg_N1_16"},{"id":"g1_144","t":"～ばきりがない","ko":"~하자면 끝이 없다","cat":"강조·한정","conn":[{"w":"동사 ば형","f":"言え + ば + きりがない"},{"w":"2그룹 동사","f":"数えれ + ば + きりがない"}],"rule":["1. 1그룹 동사는 어미 う단을 え단으로 바꾼다: 言う → 言え.","2. 그 뒤에 조건의 ば를 붙인다: 言えば.","3. ば형 뒤에 きりがない를 붙인다: 言えばきりがない.","4. 2그룹 동사는 る를 れ로 바꾸고 ば: 数える → 数えれば, する는 すれば."],"why":"きり(切り, 끝·한도) + が + ない(없다)로, 말 그대로 '한도가 없다'는 뜻이다.","nu":"그 일을 하기 시작하면 끝없이 이어지니 적당한 데서 그만두자는 뜻이다. 言う, 数える, 挙げる, 心配する, 欲を言う 등과 잘 어울린다. 관용구 上を見ればきりがない(위를 보자면 끝이 없다)도 자주 쓴다. ～たらきりがない, ～ときりがない와 뜻이 같다.","cmp":[{"g":"～たらきりがない","d":"뜻은 같다. 회화에서는 たら형도 자주 쓴다."}],"ex":[{"jp":"文句[もんく]を言[い]えばきりがない。","ko":"불평을 하자면 끝이 없다."},{"jp":"欲[よく]を言[い]えばきりがないが、今[いま]の生活[せいかつ]で十分[じゅうぶん]だ。","ko":"욕심을 내자면 끝이 없지만 지금 생활로 충분하다."},{"jp":"この町[まち]のいいところは、挙[あ]げればきりがない。","ko":"이 동네의 좋은 점은 꼽자면 끝이 없다."}],"dr":[{"t":"make","q":"心配する → ～ばきりがない","a":"心配すればきりがない","hint":"する → すれ + ば, + きりがない"},{"t":"make","q":"挙げる → ～ばきりがない","a":"挙げればきりがない","hint":"る → れ + ば, + きりがない"},{"t":"fill","q":"上[うえ]を見[み]れば（　）。","a":"きりがない","opts":["きりがない","しかたがない","はずがない","違いない"]}],"src":["https://www.vnjpclub.com/en/n1-grammar/bakiriga-nai.html"],"vf":1,"u":44,"g":1,"gp":"gg_N1_16"},{"id":"g1_146","t":"～やしない","ko":"전혀 ~하지 않는다, ~할 리 없다","cat":"강조·한정","conn":[{"w":"1그룹 동사 ます형","f":"分かり + やしない"},{"w":"2그룹 동사 ます형","f":"信じ + やしない"},{"w":"来る / する","f":"来(き) + やしない / し + やしない"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다: 分かる → 分かり.","2. 2그룹 동사는 る를 뺀다: 信じる → 信じ. 来る는 来(き), する는 し가 된다.","3. ます형 뒤에 やしない를 붙인다: 分かりやしない."],"why":"ます형 + は + しない(~하지는 않는다)가 회화에서 소리가 줄어 やしない가 된 것이다.","nu":"'전혀 ~하지 않는다, ~할 리가 없다'는 강한 부정으로, 답답함이나 불만이 섞인다. 회화체이며 격식 있는 자리에는 맞지 않는다. 남의 행동에 대한 불평(いくら言っても聞きやしない)이나 강한 부인(誰も信じやしない)에 많이 쓴다.","cmp":[{"g":"～はしない","d":"원래 형태로, 조금 더 딱딱하고 담담한 부정(分かりはしない)."},{"g":"～ものか","d":"'~할까 보냐'처럼 말하는 사람의 결심·반발을 나타낸다(行くものか). やしない는 사실에 대한 강한 부정에도 쓴다."}],"ex":[{"jp":"いくら説明[せつめい]しても、彼[かれ]は分[わ]かりやしない。","ko":"아무리 설명해도 그는 전혀 알아듣지 못한다."},{"jp":"そんな話[はなし]、誰[だれ]も信[しん]じやしないよ。","ko":"그런 이야기, 아무도 믿지 않을 거야."},{"jp":"いくら待[ま]っても、バスは来[き]やしない。","ko":"아무리 기다려도 버스는 올 생각을 안 한다."}],"dr":[{"t":"make","q":"信じる → ～やしない","a":"信じやしない","hint":"2그룹: る를 빼고 + やしない"},{"t":"make","q":"聞く → ～やしない","a":"聞きやしない","hint":"1그룹: く → き + やしない"},{"t":"fill","q":"何度[なんど]言[い]っても、彼[かれ]は聞[き]き（　）。","a":"やしない","opts":["やしない","ましょう","たい","なさい"]}],"src":["https://maggiesensei.com/2017/06/26/verb-%e2%86%92noun-%e3%80%9c%e3%81%af%e3%81%97%e3%81%aa%e3%81%84-%e3%80%9c%e3%82%82%e3%81%97%e3%81%aa%e3%81%84-%e3%80%9c%e3%82%84%e3%81%97%e3%81%aa%e3%81%84-wa-shinai-mo-shinai-y/"],"vf":1,"u":45,"g":1,"gp":"gg_N1_16"},{"id":"g1_164","t":"～にとどまらず","ko":"~에 그치지 않고","cat":"강조·한정","conn":[{"w":"명사","f":"国内 + にとどまらず"},{"w":"동사 사전형","f":"話す + にとどまらず"}],"rule":["1. 범위를 나타내는 명사(또는 동사 사전형)에 にとどまらず를 붙인다: 国内にとどまらず.","2. 뒤에 더 넓은 범위를 나타내는 말을 쓰고 흔히 も를 붙인다: 海外にも.","3. 전체: 国内にとどまらず、海外にも."],"why":"동사 とどまる(留まる, 머무르다)의 부정 연용형 とどまらず에 조사 に가 앞선 형태로, '~에 머무르지 않고'라는 뜻이 그대로 살아 있다.","nu":"영향·활동·문제 등이 어떤 범위를 넘어 더 넓게 퍼진다는 뜻의 딱딱한 표현으로, 뉴스·논설문에 자주 나온다. 뒤에 も나 まで가 와서 범위가 넓어졌음을 보여 주는 경우가 많다. 개인의 사소한 일보다 사회적·공적인 범위 확대에 잘 어울린다.","cmp":[{"g":"～だけでなく","d":"일상적인 '~뿐만 아니라'로, 범위의 크고 작음과 상관없이 단순히 추가한다. にとどまらず는 범위가 넘어서 퍼진다는 느낌이 있다."},{"g":"～のみならず","d":"'~뿐만 아니라'의 문어체. 범위 확대보다는 단순 추가에 가깝다."}],"ex":[{"jp":"この歌手[かしゅ]の人気[にんき]は国内[こくない]にとどまらず、海外[かいがい]にも広[ひろ]がっている。","ko":"이 가수의 인기는 국내에 그치지 않고 해외로도 퍼지고 있다."},{"jp":"大雨[おおあめ]の被害[ひがい]は一[ひと]つの町[まち]にとどまらず、県[けん]全体[ぜんたい]に及[およ]んだ。","ko":"폭우 피해는 한 마을에 그치지 않고 현 전체에 미쳤다."},{"jp":"彼[かれ]は問題[もんだい]を指摘[してき]するにとどまらず、解決策[かいけつさく]まで示[しめ]した。","ko":"그는 문제를 지적하는 데 그치지 않고 해결책까지 제시했다."}],"dr":[{"t":"make","q":"日本 → ～にとどまらず","a":"日本にとどまらず","hint":"명사 + にとどまらず"},{"t":"make","q":"批判する → ～にとどまらず","a":"批判するにとどまらず","hint":"동사 사전형 + にとどまらず"},{"t":"fill","q":"その影響[えいきょう]は経済[けいざい]（　）、文化[ぶんか]にも及[およ]んだ。","a":"にとどまらず","opts":["にとどまらず","に限って","に沿って","に先立って"]}],"src":["https://nihongokyoshi-net.com/2019/06/27/jlptn1-grammar-nitodomarazu/"],"vf":1,"u":45,"g":1,"gp":"gg_N1_16"},{"id":"g1_182","t":"～から～に至るまで","ko":"~부터 ~에 이르기까지","cat":"강조·한정","conn":[{"w":"명사","f":"子ども + から + 大人 + に至るまで"},{"w":"명사","f":"食料品 + から + 家具 + に至るまで"}],"rule":["1. 범위의 시작이 되는 명사에 から를 붙인다: 子どもから.","2. 범위의 끝이 되는 명사에 に至るまで를 붙인다: 大人に至るまで.","3. 두 부분을 이어 '~부터 ~까지 모두'라는 넓은 범위를 나타낸다: 子どもから大人に至るまで."],"why":"동사 至る(이르다, 도달하다)에 まで(까지)가 붙은 형태이다.","nu":"격식 있는 문어체·뉴스체이다. 단순한 から～まで보다 범위가 넓고 '그런 것까지 전부'라는 놀라움·강조가 담긴다. 끝 쪽에는 의외이거나 극단적인 것을 두는 경우가 많다. 현재에 이르기까지(現在に至るまで)처럼 긴 시간의 범위를 나타낼 때도 쓴다.","cmp":[{"g":"～から～まで","d":"단순히 시작과 끝을 나타내는 일반 표현. に至るまで는 범위가 넓다는 것을 강조한다."},{"g":"～を問わず","d":"'~에 관계없이'로, 조건을 따지지 않음을 나타낸다. 범위의 양 끝을 나열하지 않는다."}],"ex":[{"jp":"この歌[うた]は子[こ]どもから大人[おとな]に至[いた]るまで、多[おお]くの人[ひと]に愛[あい]されている。","ko":"이 노래는 아이부터 어른에 이르기까지 많은 사람에게 사랑받고 있다."},{"jp":"その店[みせ]では食料品[しょくりょうひん]から家具[かぐ]に至[いた]るまで、何[なん]でも売[う]っている。","ko":"그 가게에서는 식료품부터 가구에 이르기까지 무엇이든 팔고 있다."},{"jp":"彼[かれ]は服装[ふくそう]から言葉[ことば]づかいに至[いた]るまで、母親[ははおや]に注意[ちゅうい]された。","ko":"그는 옷차림부터 말투에 이르기까지 어머니에게 주의를 받았다."}],"dr":[{"t":"make","q":"北海道 / 沖縄 → ～から～に至るまで","a":"北海道から沖縄に至るまで","hint":"시작 명사 + から + 끝 명사 + に至るまで"},{"t":"make","q":"社長 / 新入社員 → ～から～に至るまで","a":"社長から新入社員に至るまで","hint":"から 다음에 끝 명사 + に至るまで"},{"t":"fill","q":"この町[まち]では、子[こ]どもから老人[ろうじん]（　）、みんなが祭[まつ]りを楽[たの]しむ。","a":"に至るまで","opts":["に至るまで","に限って","に反して","に沿って"]}],"src":["https://bunpro.jp/grammar_points/%E3%81%AB%E8%87%B3%E3%82%8B%E3%81%BE%E3%81%A7","https://nihongokyoshi-net.com/2019/05/31/jlptn1-grammar-niitaru/"],"vf":1,"u":45,"g":1,"gp":"gg_N1_16"},{"id":"g1_189","t":"～ではすまない","ko":"~로는 끝나지 않는다, ~로는 해결되지 않는다","cat":"강조·한정","conn":[{"w":"명사","f":"冗談 + では済まない"},{"w":"명사 + だけ","f":"注意だけ + では済まない"},{"w":"동사 사전형 + だけ","f":"謝るだけ + では済まない"}],"rule":["1. 끝내려는 수단을 명사나 동사 사전형으로 둔다: 謝る.","2. 동사에는 だけ를 붙여 '~하는 것만'으로 만든다: 謝るだけ.","3. 그 뒤에 では済まない를 붙인다: 謝るだけでは済まない."],"why":"済む(일이 끝나다, 해결되다)의 부정형 済まない 앞에 조건·한정을 나타내는 では가 붙은 형태이다.","nu":"'그 정도로는 끝나지 않고 더 심각한 결과·책임이 따른다'는 경고나 비판에 쓴다. 동사에 붙일 때는 謝るだけでは済まない처럼 だけ를 끼우거나 の를 넣어(謝るのでは済まない) 잇는 경우가 많다. 더 강하게는 ～では済まされない를 쓴다. 済まない가 사과의 '미안하다'(すまない)와 같은 소리인 점에 주의한다.","cmp":[{"g":"～ずにはすまない","d":"'~하지 않고는 끝나지 않는다', 즉 반드시 ~해야 한다는 뜻. ではすまない는 '그 정도로는 부족하다'는 뜻."}],"ex":[{"jp":"これは冗談[じょうだん]では済[す]まない問題[もんだい]だ。","ko":"이것은 농담으로는 끝나지 않는 문제다."},{"jp":"人[ひと]の物[もの]を壊[こわ]したら、謝[あやま]るだけでは済[す]まない。","ko":"남의 물건을 망가뜨리면 사과만으로는 끝나지 않는다."},{"jp":"今度[こんど]遅刻[ちこく]したら、注意[ちゅうい]だけでは済[す]まないよ。","ko":"다음에 지각하면 주의만으로는 안 끝날 거야."}],"dr":[{"t":"make","q":"笑い話 → ～ではすまない","a":"笑い話では済まない","hint":"명사 + では済まない"},{"t":"make","q":"返す → ～ではすまない","a":"返すだけでは済まない","hint":"동사 사전형 + だけ + では済まない"},{"t":"fill","q":"これだけの損害[そんがい]を出[だ]したら、謝罪[しゃざい]だけ（　）。","a":"では済まない","opts":["では済まない","にすぎない","に限る","にほかならない"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/では済まない-dewa-sumanai-meaning/"],"vf":1,"u":45,"g":1,"gp":"gg_N1_16"},{"id":"g1_193","t":"～といったらありはしない","ko":"~하기 짝이 없다, 너무나 ~하다","cat":"강조·한정","conn":[{"w":"명사 (형용사의 명사형)","f":"うるささ + といったらありはしない"},{"w":"い형용사","f":"うるさい + といったらありはしない"},{"w":"명사","f":"不便さ + といったらありはしない"}],"rule":["1. い형용사의 어미 い를 さ로 바꿔 명사로 만든다: うるさい → うるささ.","2. 그 뒤에 といったら를 붙인다: うるささといったら.","3. 끝에 ありはしない를 붙여 '그보다 더한 것은 없다'는 뜻으로 맺는다: うるささといったらありはしない.","4. 명사형으로 바꾸지 않고 い형용사 보통형에 바로 붙이기도 한다: うるさいといったらありはしない."],"why":"といったら(~로 말할 것 같으면)에, ある의 연용형 あり + は + しない로 ない를 강조한 ありはしない(있지도 않다)가 붙은 형태이다.","nu":"말하는 사람의 짜증·불만·놀라움 같은 감정을 과장해서 말하는 표현으로, 주로 부정적인 일에 쓴다. 다소 딱딱하며, 회화에서는 축약형 ありゃしない를 많이 쓴다. 객관적인 사실 보고에는 쓰지 않는다.","cmp":[{"g":"～といったらない","d":"같은 뜻이지만 좋은 일(美しさといったらない)에도 쓸 수 있다. ありはしない는 주로 부정적인 감정에 쓴다."},{"g":"～といったらありゃしない","d":"ありはしない의 구어 축약형으로, 뜻은 같고 더 허물없는 말투이다."}],"ex":[{"jp":"夜中[よなか]の工事[こうじ]のうるささといったらありはしない。","ko":"한밤중 공사의 시끄러움이란 이루 말할 수 없다."},{"jp":"この家[いえ]は駅[えき]から遠[とお]く、その不便[ふべん]さといったらありはしない。","ko":"이 집은 역에서 멀어서 그 불편함이란 이루 말할 수 없다."},{"jp":"何度[なんど]説明[せつめい]しても分[わ]かってくれず、腹立[はらだ]たしいといったらありはしない。","ko":"몇 번을 설명해도 알아주지 않아서 화가 나기 짝이 없다."}],"dr":[{"t":"make","q":"汚い → 명사형 + ～といったらありはしない","a":"汚さといったらありはしない","hint":"い → さ로 명사화 + といったらありはしない"},{"t":"make","q":"面倒くさい → ～といったらありはしない","a":"面倒くさいといったらありはしない","hint":"い형용사 보통형 + といったらありはしない"},{"t":"fill","q":"満員電車[まんいんでんしゃ]の苦[くる]しさ（　）。","a":"といったらありはしない","opts":["といったらありはしない","にすぎない","に越したことはない","というものではない"]}],"src":["https://bunpro.jp/grammar_points/ったらない・といったらない"],"vf":1,"u":45,"g":1,"gp":"gg_N1_17"},{"id":"g1_194","t":"～といったらありゃしない","ko":"~하기 짝이 없다 (구어)","cat":"강조·한정","conn":[{"w":"명사 (형용사의 명사형)","f":"寒さ + といったらありゃしない"},{"w":"い형용사","f":"寒い + といったらありゃしない"}],"rule":["1. い형용사의 어미 い를 さ로 바꿔 명사로 만든다: 寒い → 寒さ.","2. 그 뒤에 といったら를 붙인다: 寒さといったら.","3. ありはしない의 あり + は가 줄어 ありゃ가 된다: ありはしない → ありゃしない.","4. 합쳐서 寒さといったらありゃしない가 된다."],"why":"ありはしない(있지도 않다)의 りは가 회화에서 りゃ로 줄어든 형태이다.","nu":"といったらありはしない의 구어 축약형으로, 친한 사이의 회화에서 불만·짜증을 과장해서 말할 때 쓴다. 격식 있는 자리나 글에서는 쓰지 않는다. 주로 부정적인 일에 쓴다.","cmp":[{"g":"～といったらありはしない","d":"축약 전 형태로, 조금 더 딱딱하다."},{"g":"～ったらない","d":"といったらない의 구어 축약형. 좋은 일에도 쓸 수 있다."}],"ex":[{"jp":"この部屋[へや]の寒[さむ]さといったらありゃしない。","ko":"이 방의 추위란 정말 말도 못 한다."},{"jp":"朝[あさ]から晩[ばん]まで電話[でんわ]が鳴[な]って、うるさいといったらありゃしない。","ko":"아침부터 밤까지 전화가 울려서 시끄럽기 짝이 없다."},{"jp":"あの人[ひと]の態度[たいど]の悪[わる]さといったらありゃしない。","ko":"저 사람의 태도 나쁜 것은 정말 말도 못 한다."}],"dr":[{"t":"make","q":"暑い → 명사형 + ～といったらありゃしない","a":"暑さといったらありゃしない","hint":"い → さ + といったらありゃしない"},{"t":"make","q":"恥ずかしい → ～といったらありゃしない","a":"恥ずかしいといったらありゃしない","hint":"い형용사 보통형 + といったらありゃしない"},{"t":"fill","q":"隣[となり]の犬[いぬ]がずっと吠[ほ]えていて、うるさい（　）。","a":"といったらありゃしない","opts":["といったらありゃしない","わけがない","ことはない","ものではない"]}],"src":["https://bunpro.jp/grammar_points/ったらない・といったらない"],"vf":1,"u":46,"g":1,"gp":"gg_N1_17"},{"id":"g1_195","t":"～といったらない","ko":"~하기 그지없다, 더할 나위 없이 ~하다","cat":"강조·한정","conn":[{"w":"명사 (형용사의 명사형)","f":"美しさ + といったらない"},{"w":"い형용사","f":"悔しい + といったらない"},{"w":"な형용사","f":"退屈 + といったらない"}],"rule":["1. い형용사의 어미 い를 さ로 바꿔 명사로 만든다: 美しい → 美しさ.","2. 그 뒤에 といったらない를 붙인다: 美しさといったらない.","3. い형용사 보통형에 바로 붙이기도 한다: 悔しいといったらない."],"why":"といったら(~로 말할 것 같으면) + ない로, '말로 표현할 만한 것(비교할 것)이 없을 정도'라는 뜻이 된다.","nu":"말로 다 할 수 없을 만큼 정도가 심하다는 감정적인 표현이다. 좋은 일(美しさ)과 나쁜 일(悔しさ, 退屈) 모두에 쓴다. 과거의 일은 といったらなかった로 쓴다. 회화에서는 ～ったらない로 줄이기도 한다. 말하는 사람 자신의 감정·감상을 나타내며 객관적인 설명에는 쓰지 않는다.","cmp":[{"g":"～といったらありはしない","d":"주로 부정적인 감정에 쓴다. といったらない는 긍정·부정 모두 쓴다."},{"g":"～きわまりない","d":"な형용사 + きわまりない(失礼きわまりない)로, 더 딱딱한 문어 표현이다."}],"ex":[{"jp":"山[やま]の上[うえ]から見[み]た夕日[ゆうひ]の美[うつく]しさといったらなかった。","ko":"산 위에서 본 석양의 아름다움은 이루 말할 수 없었다."},{"jp":"決勝[けっしょう]で負[ま]けたときの悔[くや]しさといったらない。","ko":"결승에서 졌을 때의 분함은 그지없다."},{"jp":"一人[ひとり]で待[ま]つ時間[じかん]の退屈[たいくつ]といったらない。","ko":"혼자 기다리는 시간은 지루하기 짝이 없다."}],"dr":[{"t":"make","q":"うれしい → 명사형 + ～といったらない","a":"うれしさといったらない","hint":"い → さ + といったらない"},{"t":"make","q":"恥ずかしい → ～といったらない","a":"恥ずかしいといったらない","hint":"い형용사 보통형 + といったらない"},{"t":"fill","q":"初[はじ]めて富士山[ふじさん]を見[み]たときの感動[かんどう]（　）。","a":"といったらなかった","opts":["といったらなかった","にすぎなかった","どころではなかった","までもなかった"]}],"src":["https://bunpro.jp/grammar_points/ったらない・といったらない"],"vf":1,"u":46,"g":1,"gp":"gg_N1_17"},{"id":"g1_196","t":"～ときている","ko":"(게다가) ~이기까지 하니","cat":"강조·한정","conn":[{"w":"い형용사","f":"安い + ときている"},{"w":"な형용사","f":"親切 + ときている"},{"w":"명사","f":"独身 + ときている"}],"rule":["1. 특징이 되는 말을 보통형(명사·な형용사는 어간)으로 둔다: 安い.","2. 그 뒤에 ときている를 붙인다: 安いときている.","3. 뒤에 から・ので 등을 이어 그 결과를 말한다: 安いときているから、いつも込んでいる."],"why":"","nu":"'~이기까지 하니 (당연히 그렇게 된다)'라고 어떤 특징을 강조해서 내세우는 회화체 표현이다. 앞에 다른 특징을 늘어놓고 しかも, おまけに와 함께 '거기에 ~까지'라고 덧붙이는 경우가 많다. 뒤에는 그러니 어쩔 수 없다·그러니 당연하다는 판단이 온다. 부러움이나 비꼼, 불만의 느낌이 담기기도 한다.","cmp":[{"g":"～うえに","d":"'~인 데다가'로 사실을 객관적으로 덧붙인다. ときている는 말하는 사람의 강조·감정이 강하다."}],"ex":[{"jp":"この店[みせ]は安[やす]くておいしいときているから、いつも行列[ぎょうれつ]ができている。","ko":"이 가게는 싸고 맛있기까지 하니 늘 줄이 서 있다."},{"jp":"彼[かれ]は医者[いしゃ]で、おまけに独身[どくしん]ときている。もてるはずだ。","ko":"그는 의사인 데다가 독신이기까지 하다. 인기가 많을 수밖에."},{"jp":"給料[きゅうりょう]は安[やす]いし、残業[ざんぎょう]も多[おお]いときている。辞[や]めたくもなるよ。","ko":"월급은 적고 야근도 많기까지 하니 그만두고 싶어질 만도 하지."}],"dr":[{"t":"make","q":"高い → ～ときている","a":"高いときている","hint":"い형용사 보통형 + ときている"},{"t":"make","q":"美人 → ～ときている","a":"美人ときている","hint":"명사 + ときている"},{"t":"fill","q":"彼女[かのじょ]は頭[あたま]がいいうえに、優[やさ]しい（　）。人気[にんき]があるわけだ。","a":"ときている","opts":["ときている","とされる","というものだ","とみえる"]}],"src":[],"vf":0,"u":46,"g":1,"gp":"gg_N1_17"},{"id":"g1_216","t":"～なくはない","ko":"~하지 않는 것은 아니다, ~할 수 없는 것도 아니다","cat":"강조·한정","conn":[{"w":"동사 ない형","f":"行く → 行かない → 行かなく + はない"},{"w":"동사 가능형","f":"食べられる → 食べられない → 食べられなく + はない"},{"w":"い형용사","f":"高い → 高くない → 高くなく + はない"},{"w":"な형용사·명사","f":"好きだ → 好きじゃない → 好きじゃなく + はない"}],"rule":["1. 동사를 ない형으로 바꾼다: 1그룹은 어미 う단을 あ단으로 바꾸고 ない를 붙인다(行く → 行かない).","2. ない의 い를 く로 바꿔 なく로 만든다: 行かなく.","3. 뒤에 は + ない를 붙인다: 行かなくはない.","4. い형용사는 くない → くなくはない, な형용사·명사는 じゃない(ではない) → じゃなく(ではなく)はない."],"why":"부정형 ～ない의 연용형 ～なく에 は + ない를 붙인 이중 부정이다.","nu":"이중 부정으로 '완전히 부정하지는 않는다, 어느 정도 가능성·여지가 있다'는 소극적인 긍정을 나타낸다. 적극적으로 하겠다는 뜻은 아니며, 뒤에 が・けど를 이어 조건이나 망설임을 덧붙이는 일이 많다. 가능형(行けなくはない), 気持ちはわからなくはない처럼 자주 쓰인다. 회화에서도 쓴다. 비슷한 ないこともない와 거의 같은 뜻이다.","cmp":[{"g":"～ないこともない","d":"뜻이 거의 같다(行かないこともない). なくはない가 조금 더 짧고 회화적이다."},{"g":"～ないわけではない","d":"'~하지 않는다는 것은 아니다'로 전면 부정을 부분적으로 정정할 때 쓴다."}],"ex":[{"jp":"少[すこ]し遠[とお]いけど、歩[ある]いて行[い]けなくはない。","ko":"조금 멀지만 걸어서 못 갈 것도 없다."},{"jp":"辛[から]いものは食[た]べられなくはないが、あまり好[す]きではない。","ko":"매운 것은 못 먹는 건 아니지만 별로 좋아하지 않는다."},{"jp":"君[きみ]の気持[きも]ちもわからなくはない。","ko":"네 마음도 모르는 건 아니다."}],"dr":[{"t":"make","q":"できる → ～なくはない","a":"できなくはない","hint":"ない형(できない) → なく + はない"},{"t":"make","q":"高い → ～なくはない","a":"高くなくはない","hint":"い형용사: 高くない → 高くなく + はない"},{"t":"fill","q":"日曜日[にちようび]なら時間[じかん]があるから、手伝[てつだ]え（　）よ。","a":"なくはない","opts":["なくはない","てはいけない","ようがない","るはずがない"]}],"src":[],"vf":0,"u":46,"g":1,"gp":"gg_N1_17"},{"id":"g1_218","t":"～なら～なりに","ko":"~면 ~인 대로, ~면 ~ 나름대로","cat":"강조·한정","conn":[{"w":"명사","f":"子どもなら子どもなりに"},{"w":"い형용사","f":"狭いなら狭いなりに"},{"w":"な형용사","f":"下手なら下手なりに"}],"rule":["1. 앞에 조건이 되는 말(명사·형용사)을 두고 なら를 붙인다: 子ども → 子どもなら.","2. 같은 말을 그대로 한 번 더 쓴다: 子どもなら子ども.","3. 그 뒤에 なりに를 붙인다: 子どもなら子どもなりに. 명사를 꾸밀 때는 なりの를 쓴다(子どもなら子どもなりの考え)."],"why":"なり는 それなりに, 自分なりに의 なり와 같이 '그에 걸맞은 정도·방식'을 뜻하고, 여기에 に가 붙어 부사처럼 쓰인다.","nu":"부족하거나 불리한 조건이라도 그 조건에 맞는 방식이 있다는 뜻이다. 子ども, 下手, 狭い, 安い처럼 약점으로 보이는 조건과 잘 어울린다. 앞뒤에 반드시 같은 말을 반복한다. 회화와 문장 모두에서 쓴다.","cmp":[{"g":"～なりに","d":"반복 없이 명사·형용사 + なりに(私なりに, 狭いなりに). なら～なりに는 같은 말을 반복해 '그 조건이라면 그 조건대로'를 더 강조한다."},{"g":"～ば～ほど","d":"같은 말을 반복하지만 '~할수록 더'라는 비례를 나타낸다."}],"ex":[{"jp":"子[こ]どもなら子[こ]どもなりに、ちゃんと考[かんが]えている。","ko":"아이는 아이 나름대로 제대로 생각하고 있다."},{"jp":"部屋[へや]が狭[せま]いなら狭[せま]いなりに、工夫[くふう]して使[つか]えばいい。","ko":"방이 좁으면 좁은 대로 궁리해서 쓰면 된다."},{"jp":"下手[へた]なら下手[へた]なりに、一生懸命[いっしょうけんめい]やればいい。","ko":"서툴면 서툰 대로 열심히 하면 된다."}],"dr":[{"t":"make","q":"安い → ～なら～なりに","a":"安いなら安いなりに","hint":"安い + なら + 같은 말 安い + なりに"},{"t":"make","q":"初心者 → ～なら～なりに","a":"初心者なら初心者なりに","hint":"명사 + なら + 같은 명사 + なりに"},{"t":"fill","q":"お金[かね]がないならない（　）、楽[たの]しみ方[かた]はある。","a":"なりに","opts":["なりに","ほど","ように","ばかりに"]}],"src":[],"vf":0,"u":47,"g":1,"gp":"gg_N1_17"},{"id":"g1_226","t":"～のは～ぐらいのものだ","ko":"~하는 것은 ~ 정도뿐이다","cat":"강조·한정","conn":[{"w":"동사 보통형","f":"頼める + のは + 君 + ぐらいのものだ"},{"w":"い형용사","f":"暇な日が多い + のは + 夏 + ぐらいのものだ"},{"w":"명사(뒤 슬롯)","f":"～のは + 母 + ぐらいのものだ"}],"rule":["1. 앞에 어떤 일을 보통형으로 두고 のは를 붙여 주제로 만든다: 頼める → 頼めるのは.","2. 그 일에 해당하는 유일한 대상을 명사로 둔다: 頼めるのは君.","3. 끝에 ぐらいのものだ(또는 くらいのものだ)를 붙인다: 頼めるのは君ぐらいのものだ."],"why":"","nu":"'그런 일을 하는(해당하는) 것은 그것 하나 정도밖에 없다'고 한정해서 말한다. 칭찬(君ぐらいのものだ)에도, 불만(笑っているのは彼ぐらいのものだ)에도 쓴다. 회화에서도 쓰지만 약간 딱딱하다. 뒤의 명사는 사람·때·물건 등 해당 대상이어야 하며, 정도를 나타내는 다른 말(時間の無駄 등)을 넣으면 어색하다.","cmp":[{"g":"～しか～ない","d":"'~밖에 ~않다'는 일반적 한정. ぐらいのものだ는 '그 정도뿐'이라고 조금 완곡하게 말한다."},{"g":"～だけだ","d":"단순 한정. ぐらいのものだ는 '굳이 꼽자면 그것 정도'라는 말투이다."}],"ex":[{"jp":"こんなことを頼[たの]めるのは君[きみ]ぐらいのものだ。","ko":"이런 걸 부탁할 수 있는 건 너 정도뿐이다."},{"jp":"毎朝[まいあさ]こんなに早[はや]く起[お]きるのは祖父[そふ]ぐらいのものだ。","ko":"매일 아침 이렇게 일찍 일어나는 건 할아버지 정도뿐이다."},{"jp":"この店[みせ]で安[やす]いのは飲[の]み物[もの]ぐらいのものだ。","ko":"이 가게에서 싼 건 음료 정도뿐이다."}],"dr":[{"t":"make","q":"文句を言わない / 彼 → ～のは～ぐらいのものだ","a":"文句を言わないのは彼ぐらいのものだ","hint":"보통형 + のは + 명사 + ぐらいのものだ"},{"t":"make","q":"暇だ / 日曜日 → ～のは～ぐらいのものだ","a":"暇なのは日曜日ぐらいのものだ","hint":"な형용사는 な + のは (暇だ → 暇なのは)"},{"t":"fill","q":"あんな難[むずか]しい問題[もんだい]が解[と]けるのは、田中[たなか]さん（　）。","a":"ぐらいのものだ","opts":["ぐらいのものだ","に越したことはない","に難くない","には及ばない"]}],"src":[],"vf":0,"u":47,"g":1,"gp":"gg_N1_17"},{"id":"g1_235","t":"～もなんでもない","ko":"~도 뭣도 아니다, 전혀 ~이 아니다","cat":"강조·한정","conn":[{"w":"명사","f":"友達 + でもなんでもない"},{"w":"な형용사","f":"好き + でもなんでもない"},{"w":"い형용사","f":"痛い → 痛く + もなんでもない"}],"rule":["1. 명사·な형용사는 단정 だ를 で로 바꾼다: 友達だ → 友達で.","2. で 뒤에 조사 も를 붙인다: 友達でも.","3. 마지막에 なんでもない를 붙인다: 友達でもなんでもない.","4. い형용사는 어미 い를 く로 바꾸고 바로 もなんでもない를 붙인다: 痛い → 痛くもなんでもない."],"why":"","nu":"상대의 말이나 세간의 생각을 '그런 것은 전혀 아니다'라고 강하게 부정하는 표현으로, 회화에서 감정을 담아 쓴다. 부정 대상 하나만이 아니라 그와 비슷한 어떤 것도 아니라는 느낌이다. 형태에 주의: 명사·な형용사는 で가 들어간 でもなんでもない, い형용사는 く형 + もなんでもない이다. 한국어 '아무것도 아니다'처럼 '중요하지 않다'는 뜻으로 오해하기 쉬운데, 핵심은 앞말의 강한 부정이다.","cmp":[{"g":"～ではない","d":"단순한 부정. でもなんでもない는 '전혀, 조금도 아니다'라는 반발이나 강조가 들어간다."},{"g":"～どころではない","d":"'~할 상황이 아니다'라는 뜻으로, 사정상 여유가 없음을 말한다. 사실 자체를 부정하는 でもなんでもない와 다르다."}],"ex":[{"jp":"あの人[ひと]は友達[ともだち]でもなんでもない。ただの知[し]り合[あ]いだ。","ko":"그 사람은 친구도 뭣도 아니다. 그냥 아는 사람이다."},{"jp":"こんな仕事[しごと]、好[す]きでもなんでもないけど、生活[せいかつ]のためにやっている。","ko":"이런 일, 좋아하는 것도 뭣도 아니지만 생활을 위해 하고 있다."},{"jp":"注射[ちゅうしゃ]なんて、痛[いた]くもなんでもないよ。","ko":"주사 따위, 전혀 안 아파."}],"dr":[{"t":"make","q":"恋人だ → ～でもなんでもない","a":"恋人でもなんでもない","hint":"だ를 で로 바꾸고 も + なんでもない"},{"t":"make","q":"怖い → ～もなんでもない","a":"怖くもなんでもない","hint":"い형용사 い → く, 그 뒤에 もなんでもない"},{"t":"fill","q":"彼[かれ]は天才[てんさい]（　）。ただ努力[どりょく]しているだけだ。","a":"でもなんでもない","opts":["でもなんでもない","にすぎない","にほかならない","であるべきだ"]}],"src":[],"vf":0,"u":47,"g":1,"gp":"gg_N1_17"},{"id":"g1_245","t":"～限りだ","ko":"정말 ~하다, ~하기 그지없다","cat":"강조·한정","conn":[{"w":"い형용사","f":"嬉しい + 限りだ"},{"w":"な형용사","f":"残念な + 限りだ"}],"rule":["1. い형용사는 사전형 그대로 둔다: 嬉しい.","2. 그 뒤에 限り를 붙인다: 嬉しい限り.","3. 마지막에 단정 だ를 붙인다: 嬉しい限りだ.","4. な형용사는 な를 붙인 형태 뒤에 限りだ를 잇는다: 残念な限りだ."],"why":"","nu":"말하는 이 자신이 지금 느끼는 감정이 아주 강하다는 것을 나타낸다. 嬉しい, 寂しい, 羨ましい, 心細い, 残念な 같은 감정 형용사에만 붙고, 高い·大きい 같은 성질 형용사에는 쓰지 않는다. 제3자의 감정에는 쓰지 않는다. 다소 격식 있는 말투로 인사말·스피치에 잘 어울린다. 정중하게는 限りです라고 한다.","cmp":[{"g":"～てたまらない","d":"참을 수 없을 만큼 ~하다는 감정·감각 표현으로 회화적이다. 限りだ는 더 차분하고 격식 있는 말투다."},{"g":"～の極み","d":"명사 + の極み(感激の極み)로 최고조를 말하며, 형용사에 붙는 限りだ와 접속이 다르다."}],"ex":[{"jp":"皆[みな]さんにお祝[いわ]いしていただき、嬉[うれ]しい限[かぎ]りです。","ko":"여러분께 축하를 받아서 정말 기쁩니다."},{"jp":"仲[なか]のいい友達[ともだち]が引[ひ]っ越[こ]してしまい、寂[さび]しい限[かぎ]りだ。","ko":"친한 친구가 이사를 가 버려서 쓸쓸하기 그지없다."},{"jp":"せっかくの旅行[りょこう]が中止[ちゅうし]になり、残念[ざんねん]な限[かぎ]りだ。","ko":"모처럼의 여행이 취소되어 정말 아쉽다."}],"dr":[{"t":"make","q":"羨ましい → ～限りだ","a":"羨ましい限りだ","hint":"い형용사 사전형 + 限りだ"},{"t":"make","q":"心細い → ～限りだ","a":"心細い限りだ","hint":"い형용사 사전형 + 限りだ"},{"t":"fill","q":"長年[ながねん]の夢[ゆめ]がかなって、嬉[うれ]しい（　）。","a":"限りだ","opts":["限りだ","ものか","わけがない","はずがない"]}],"src":[],"vf":0,"u":47,"g":1,"gp":"gg_N1_17"},{"id":"g1_004","t":"～かれ～かれ","ko":"~든 ~든 (관용구)","cat":"기타","conn":[{"w":"い형용사(정해진 관용구)","f":"遅かれ早かれ / 多かれ少なかれ / 善かれ悪しかれ"}],"rule":["1. い형용사의 어미 い를 かれ로 바꾼다. 遅い → 遅かれ.","2. 반대 뜻의 형용사도 같은 방법으로 바꿔 바로 이어 쓴다. 早い → 早かれ, 遅かれ早かれ.","3. 실제로는 遅かれ早かれ・多かれ少なかれ・善かれ悪しかれ 같은 정해진 짝으로만 쓴다."],"why":"","nu":"새로 만들어 쓰는 문형이 아니라 고정된 관용구다. 遅かれ早かれ(조만간, 언젠가는), 多かれ少なかれ(정도의 차이는 있어도), 善かれ悪しかれ(좋든 나쁘든)를 통째로 외우는 것이 좋다. 명사(冬かれ夏かれ)나 동사(来るかれ)에는 붙지 않는다.","cmp":[{"g":"～であれ～であれ","d":"명사를 자유롭게 넣어 만들 수 있다. かれ는 정해진 형용사 짝뿐이다."}],"ex":[{"jp":"遅[おそ]かれ早[はや]かれ、本当[ほんとう]のことは分[わ]かるだろう。","ko":"조만간 진실은 밝혀질 것이다."},{"jp":"人[ひと]は多[おお]かれ少[すく]なかれ、悩[なや]みを持[も]っている。","ko":"사람은 정도의 차이는 있어도 고민을 가지고 있다."},{"jp":"善[よ]かれ悪[あ]しかれ、これが今[いま]の現実[げんじつ]だ。","ko":"좋든 나쁘든 이것이 지금의 현실이다."}],"dr":[{"t":"make","q":"多い・少ない → ～かれ～かれ","a":"多かれ少なかれ","hint":"い를 かれ로 바꿔 두 말을 이어 쓴다"},{"t":"make","q":"遅い・早い → ～かれ～かれ","a":"遅かれ早かれ","hint":"い를 かれ로 바꿔 두 말을 이어 쓴다"},{"t":"fill","q":"遅[おそ]（　）早[はや]かれ、彼[かれ]も気[き]がつくはずだ。","a":"かれ","opts":["かれ","かろう","ければ","くても"]}],"src":["https://bunpro.jp/grammar_points/823"],"vf":1,"u":47,"g":1,"gp":"gg_N1_17"},{"id":"g1_005","t":"～だの～だの","ko":"~라는 둥 ~라는 둥, ~니 ~니","cat":"기타","conn":[{"w":"동사 보통형","f":"行く + だの / 行かない + だの"},{"w":"い형용사","f":"暑い + だの"},{"w":"な형용사","f":"不便 + だの"},{"w":"명사","f":"服 + だの"}],"rule":["1. 첫 번째 말(보통형) 뒤에 だの를 붙인다. 暑い → 暑いだの.","2. 두 번째 말 뒤에도 だの를 붙여 나란히 쓴다. 暑いだの寒いだの.","3. 명사·な형용사 어간은 그대로 だの를 붙인다(服だの, 不便だの). 뒤에는 と言う 등이 자주 온다."],"why":"","nu":"여러 예를 늘어놓을 때 쓰며, 불평·비난·짜증의 느낌이 강하다. 회화체. 좋은 일을 담담하게 나열할 때는 ～や～など, ～とか～とか가 자연스럽다. ～だの～だのと文句を言う 같은 꼴이 많다.","cmp":[{"g":"～やら～やら","d":"역시 나열이지만 '이것저것 여러 가지로 정신없음'의 느낌. だの는 불만을 늘어놓는 느낌이 더 강하다."},{"g":"～とか～とか","d":"중립적인 회화체 나열."}],"ex":[{"jp":"彼[かれ]は暑[あつ]いだの寒[さむ]いだのと、文句[もんく]ばかり言[い]っている。","ko":"그는 덥다느니 춥다느니 불평만 하고 있다."},{"jp":"妹[いもうと]は服[ふく]だの靴[くつ]だのに、お金[かね]を使[つか]いすぎる。","ko":"여동생은 옷이니 신발이니 하는 데 돈을 너무 많이 쓴다."},{"jp":"行[い]くだの行[い]かないだの、彼[かれ]の話[はなし]はいつも変[か]わる。","ko":"간다느니 안 간다느니 그의 말은 늘 바뀐다."}],"dr":[{"t":"make","q":"高い・まずい → ～だの～だの","a":"高いだのまずいだの","hint":"보통형 + だの를 두 번"},{"t":"make","q":"不便だ・狭い → ～だの～だの","a":"不便だの狭いだの","hint":"な형용사는 어간 + だの"},{"t":"fill","q":"夫[おっと]は疲[つか]れた（　）眠[ねむ]い（　）と言[い]って、何[なに]も手伝[てつだ]わない。","a":"だの","opts":["だの","ので","のに","なら"]}],"src":["https://nihongokyoshi-net.com/2019/10/25/jlptn1-grammar-dano/"],"vf":1,"u":48,"g":1,"gp":"gg_N1_17"},{"id":"g1_007","t":"～というか～というか","ko":"~라고 할까 ~라고 할까","cat":"기타","conn":[{"w":"명사","f":"天才 + というか"},{"w":"な형용사","f":"素直 + というか"},{"w":"い형용사","f":"甘い + というか"},{"w":"동사 보통형","f":"驚いた + というか"}],"rule":["1. 첫 번째 표현 뒤에 というか를 붙인다. 素直 → 素直というか.","2. 두 번째 표현 뒤에도 というか를 붙여 나란히 쓴다. 素直というか単純というか.","3. 명사·な형용사는 어간에 바로, 동사·い형용사는 보통형에 붙인다."],"why":"인용의 と + 言う(말하다) + 의문의 か로, '~라고 말할까'라는 뜻이 그대로 드러난다.","nu":"딱 맞는 말을 찾지 못해 떠오르는 두 표현을 늘어놓으며 인상을 말할 때 쓴다. 뒤에 とにかく(어쨌든)나 전체를 정리하는 말이 자주 온다. 회화에서 많이 쓰며, 좋은 평가와 나쁜 평가가 섞이기도 한다. 객관적 사실 나열이 아니라 말하는 사람의 느낌이다.","cmp":[{"g":"～やら～やら","d":"여러 일이나 감정이 섞여 정신없음을 나열. というか는 어떤 말로 표현할지 고르는 중임을 나타낸다."}],"ex":[{"jp":"彼女[かのじょ]は素直[すなお]というか単純[たんじゅん]というか、人[ひと]の話[はなし]をすぐ信[しん]じる。","ko":"그녀는 솔직하다고 할까 단순하다고 할까, 남의 말을 금방 믿는다."},{"jp":"このスープは甘[あま]いというか辛[から]いというか、不思議[ふしぎ]な味[あじ]だ。","ko":"이 수프는 달다고 할까 맵다고 할까, 묘한 맛이다."},{"jp":"驚[おどろ]いたというかあきれたというか、言葉[ことば]が出[で]なかった。","ko":"놀랐다고 할까 어이가 없었다고 할까, 말이 나오지 않았다."}],"dr":[{"t":"make","q":"親切だ・おせっかいだ → ～というか～というか","a":"親切というかおせっかいというか","hint":"な형용사 어간 + というか를 두 번"},{"t":"make","q":"うれしい・恥ずかしい → ～というか～というか","a":"うれしいというか恥ずかしいというか","hint":"い형용사 + というか를 두 번"},{"t":"fill","q":"彼[かれ]は大胆[だいたん]（　）無謀[むぼう]（　）、とにかく怖[こわ]いもの知[し]らずだ。","a":"というか","opts":["というか","にとって","によって","について"]}],"src":["https://aiueo.cc/pages_v2/ja/grammar/web/546.php"],"vf":1,"u":48,"g":1,"gp":"gg_N1_17"},{"id":"g1_008","t":"～とも～とも（言えない）","ko":"~라고도 ~라고도 (할 수 없다)","cat":"기타","conn":[{"w":"명사","f":"賛成 + とも"},{"w":"い형용사","f":"うれしい + とも"},{"w":"동사 보통형","f":"笑っている + とも"}],"rule":["1. 첫 번째 말 뒤에 とも를 붙인다. 賛成 → 賛成とも.","2. 대립하는 두 번째 말에도 とも를 붙인다. 賛成とも反対とも.","3. 뒤에 言えない・つかない・分からない 같은 부정 표현을 붙인다. 賛成とも反対とも言えない."],"why":"","nu":"A라고도 B라고도 분명히 말할 수 없는, 어느 한쪽으로 정하기 어려운 상태를 나타낸다. ～ともつかない(어느 쪽인지 분간이 안 되는)는 문어적인 고정 표현이다. 父とも兄とも話す(아버지와도 형과도)의 と+も(~와도)와는 다른 것이니 혼동하지 말 것.","cmp":[{"g":"～でも～でもない","d":"A도 B도 아니라고 단정한다. ～とも～とも言えない는 어느 쪽이라고 판단할 수 없다는 뜻."}],"ex":[{"jp":"彼[かれ]の返事[へんじ]は賛成[さんせい]とも反対[はんたい]ともつかないものだった。","ko":"그의 대답은 찬성인지 반대인지 알 수 없는 것이었다."},{"jp":"その時[とき]の気持[きも]ちは、うれしいとも悲[かな]しいとも言[い]えなかった。","ko":"그때의 기분은 기쁘다고도 슬프다고도 할 수 없었다."},{"jp":"男[おとこ]とも女[おんな]ともつかない声[こえ]が聞[き]こえた。","ko":"남자인지 여자인지 분간할 수 없는 목소리가 들렸다."}],"dr":[{"t":"make","q":"成功・失敗 → ～とも～とも言えない","a":"成功とも失敗とも言えない","hint":"각 명사 + とも, 마지막에 言えない"},{"t":"make","q":"本気・冗談 → ～とも～ともつかない","a":"本気とも冗談ともつかない","hint":"각 명사 + とも, 마지막에 つかない"},{"t":"fill","q":"この料理[りょうり]は和食[わしょく]（　）洋食[ようしょく]（　）言[い]えない。","a":"とも","opts":["とも","ほど","さえ","こそ"]}],"src":[],"vf":0,"u":48,"g":1,"gp":"gg_N1_18"},{"id":"g1_011","t":"～につけ～につけ","ko":"~든 ~든 (어느 때나), ~할 때나 ~할 때나","cat":"기타","conn":[{"w":"い형용사","f":"良い + につけ / 悪い + につけ"},{"w":"동사 사전형","f":"見る + につけ"},{"w":"명사","f":"雨 + につけ"}],"rule":["1. 첫 번째 말 뒤에 につけ를 붙인다. 良い → 良いにつけ.","2. 반대 뜻의 말에도 につけ를 붙여 이어 쓴다. 悪い → 悪いにつけ.","3. 동사는 사전형, 명사는 그대로 につけ를 붙인다."],"why":"","nu":"서로 반대되는 두 경우를 들어 '어느 경우든 늘 그렇다'는 뜻을 나타낸다. 良いにつけ悪いにつけ, うれしいにつけ悲しいにつけ, 雨につけ風につけ처럼 정해진 짝이 많다. 문어적이다. 동사 하나에 쓰면 '~할 때마다'(見るにつけ, 聞くにつけ)라는 뜻이 된다.","cmp":[{"g":"～にしろ～にしろ","d":"'어느 쪽이든 판단은 같다'에 중점. につけ는 '그런 일이 있을 때마다 늘'이라는 반복에 중점이 있다."}],"ex":[{"jp":"良[よ]いにつけ悪[わる]いにつけ、彼[かれ]はいつも話題[わだい]になる。","ko":"좋은 일로든 나쁜 일로든 그는 늘 화제가 된다."},{"jp":"うれしいにつけ悲[かな]しいにつけ、母[はは]に電話[でんわ]をする。","ko":"기쁠 때나 슬플 때나 어머니께 전화를 한다."},{"jp":"雨[あめ]につけ風[かぜ]につけ、祖父[そふ]は畑[はたけ]のことを心配[しんぱい]している。","ko":"비가 오나 바람이 부나 할아버지는 밭 걱정을 하신다."}],"dr":[{"t":"make","q":"うれしい・悲しい → ～につけ～につけ","a":"うれしいにつけ悲しいにつけ","hint":"い형용사 + につけ를 두 번"},{"t":"make","q":"雨・風 → ～につけ～につけ","a":"雨につけ風につけ","hint":"명사 + につけ를 두 번"},{"t":"fill","q":"良[よ]い（　）悪[わる]い（　）、親[おや]は子供[こども]のことを考[かんが]えている。","a":"につけ","opts":["につけ","につれ","にしたがって","にかわって"]}],"src":["https://bunpro.jp/grammar_points/につけ"],"vf":1,"u":48,"g":1,"gp":"gg_N1_18"},{"id":"g1_013","t":"～が～なら、～も～だ","ko":"~가 ~이니 ~도 ~이다 (둘 다 마찬가지)","cat":"기타","conn":[{"w":"명사(같은 명사 반복)","f":"親が親なら + 子も子だ"}],"rule":["1. 명사1에 が를 붙이고 같은 명사1을 한 번 더 쓴 뒤 なら를 붙인다. 親 → 親が親なら.","2. 이어서 명사2에 も를 붙이고 같은 명사2를 반복한 뒤 だ로 끝낸다. 子 → 子も子だ.","3. 두 명사에는 부모와 자식, 학교와 학생처럼 서로 관계있는 사람이나 대상이 온다."],"why":"","nu":"한쪽도 문제지만 다른 쪽도 똑같이 문제라고 양쪽을 함께 비판하는 표현. 칭찬에는 쓰지 않는다. 고정된 말투라 명사를 반복하는 형태 그대로 쓴다. 親が親なら子も子だ가 대표적이며, 같은 뜻으로 ～も～なら、～も～だ의 꼴이 더 자주 쓰인다.","cmp":[{"g":"～も～なら、～も～だ","d":"뜻은 거의 같다. 둘 다 양쪽을 비판하며, 일상에서는 も를 쓰는 꼴이 더 흔하다."}],"ex":[{"jp":"子供[こども]にうそを教[おし]えるなんて、親[おや]が親[おや]なら子[こ]も子[こ]だ。","ko":"아이에게 거짓말을 가르치다니, 부모가 그러니 자식도 그 모양이다."},{"jp":"社長[しゃちょう]が社長[しゃちょう]なら、社員[しゃいん]も社員[しゃいん]だ。","ko":"사장이 그 모양이니 직원도 그 모양이다."},{"jp":"夫[おっと]が夫[おっと]なら、妻[つま]も妻[つま]だ。二人[ふたり]とも約束[やくそく]を守[まも]らない。","ko":"남편이 그러니 아내도 마찬가지다. 둘 다 약속을 안 지킨다."}],"dr":[{"t":"make","q":"先生・生徒 → ～が～なら、～も～だ","a":"先生が先生なら、生徒も生徒だ","hint":"명사1が명사1なら、명사2も명사2だ"},{"t":"make","q":"店長・店員 → ～が～なら、～も～だ","a":"店長が店長なら、店員も店員だ","hint":"같은 명사를 두 번씩 반복"},{"t":"fill","q":"親[おや]が親[おや]（　）、子[こ]も子[こ]だ。","a":"なら","opts":["なら","ので","から","のに"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/が-も～なら～も～だ-ga-mo-nara-mo-da-meaning/","https://aiueo.cc/pages_v2/en/grammar/web/419.php"],"vf":1,"u":49,"g":1,"gp":"gg_N1_18"},{"id":"g1_014","t":"～も～なら、～も～だ","ko":"~도 ~지만 ~도 ~다 (둘 다 똑같다)","cat":"기타","conn":[{"w":"명사(같은 명사 반복)","f":"兄も兄なら + 弟も弟だ"}],"rule":["1. 명사1에 も를 붙이고 같은 명사1을 반복한 뒤 なら를 붙인다. 兄 → 兄も兄なら.","2. 이어서 명사2에 も를 붙이고 같은 명사2를 반복한 뒤 だ로 끝낸다. 弟 → 弟も弟だ.","3. 두 명사에는 서로 관계있는 사람이나 대상(형과 동생, 상품과 점원, 학교와 학생 등)이 온다."],"why":"","nu":"양쪽 모두 똑같이 잘못이 있다고 비판할 때 쓴다. 놀람·어이없음이 섞이며 칭찬에는 쓰지 않는다. 회화에서도 쓰는 관용적 표현이다. 君も君なら私も私だ처럼 말하는 사람 자신을 포함해 반성하는 말로도 쓴다.","cmp":[{"g":"～が～なら、～も～だ","d":"뜻은 거의 같다. 일상에서는 이쪽(も…なら)이 더 흔하다."}],"ex":[{"jp":"兄[あに]も兄[あに]なら弟[おとうと]も弟[おとうと]だ。二人[ふたり]ともすぐけんかする。","ko":"형도 형이지만 동생도 동생이다. 둘 다 금방 싸운다."},{"jp":"親[おや]も親[おや]なら子[こ]も子[こ]だ。","ko":"부모도 부모지만 자식도 자식이다."},{"jp":"店員[てんいん]も店員[てんいん]なら、客[きゃく]も客[きゃく]だ。どちらも失礼[しつれい]だった。","ko":"점원도 점원이지만 손님도 손님이다. 양쪽 다 무례했다."}],"dr":[{"t":"make","q":"夫・妻 → ～も～なら、～も～だ","a":"夫も夫なら、妻も妻だ","hint":"명사1も명사1なら、명사2も명사2だ"},{"t":"make","q":"上司・部下 → ～も～なら、～も～だ","a":"上司も上司なら、部下も部下だ","hint":"같은 명사를 두 번씩 반복"},{"t":"fill","q":"兄[あに]も兄[あに]なら、弟[おとうと]（　）弟[おとうと]だ。","a":"も","opts":["も","を","へ","で"]}],"src":["https://aiueo.cc/pages_v2/en/grammar/web/419.php","https://aiueo.cc/pages/en/grammar/web/419.php"],"vf":1,"u":49,"g":1,"gp":"gg_N1_18"},{"id":"g1_021","t":"～から言わせれば","ko":"~의 입장에서 말하자면","cat":"기타","conn":[{"w":"명사(사람)","f":"私 + から言わせれば"},{"w":"명사(사람·집단)","f":"専門家 + から言わせれば"}],"rule":["1. 言う의 어미 う를 わ로 바꾸고 せる를 붙여 사역형 言わせる를 만든다.","2. 言わせる의 る를 れ로 바꾸고 ば를 붙여 가정형 言わせれば를 만든다.","3. 의견을 말하는 사람 명사 + から 뒤에 붙인다(私から言わせれば)."],"why":"言う의 사역형 言わせる(말하게 하다) + 가정의 ば. '(그 사람에게) 말하게 한다면'이 '그 사람 입장에서 말하자면'이 되었다.","nu":"주로 사람이나 집단 뒤에 쓴다. 일반적인 생각과 다르거나 비판적인 의견을 강하게 내세울 때 많이 쓴다. 같은 뜻으로 に言わせれば가 더 흔하다. 회화와 글 모두에서 쓴다.","cmp":[{"g":"～に言わせれば","d":"뜻은 거의 같고 더 많이 쓰인다."},{"g":"～から見れば","d":"그 입장에서 바라본 판단을 나타내며, 의견을 강하게 주장하는 느낌은 약하다."}],"ex":[{"jp":"私[わたし]から言[い]わせれば、その計画[けいかく]は無理[むり]だ。","ko":"내 입장에서 말하자면 그 계획은 무리다."},{"jp":"母[はは]から言[い]わせれば、私[わたし]はまだ子供[こども]らしい。","ko":"엄마 말로는 나는 아직 어린애라고 한다."},{"jp":"プロの料理人[りょうりにん]から言[い]わせれば、この店[みせ]の味[あじ]は普通[ふつう]だそうだ。","ko":"프로 요리사의 입장에서 말하자면 이 가게의 맛은 평범하다고 한다."}],"dr":[{"t":"make","q":"言う → 사역형","a":"言わせる","hint":"어미 う를 わ로 + せる"},{"t":"make","q":"言わせる → ば 가정형","a":"言わせれば","hint":"る를 れ로 + ば"},{"t":"fill","q":"医者[いしゃ]（　）、毎日[まいにち]の睡眠[すいみん]が一番[いちばん]大事[だいじ]だそうだ。","a":"から言わせれば","opts":["から言わせれば","からといって","からには","からこそ"]}],"src":["https://bunpro.jp/grammar_points/890"],"vf":1,"u":49,"g":1,"gp":"gg_N1_18"},{"id":"g1_042","t":"～ときたら","ko":"~로 말할 것 같으면 (불만)","cat":"기타","conn":[{"w":"명사","f":"息子 + ときたら"}],"rule":["1. 불만스러운 대상(사람·물건)을 명사로 놓는다(うちの息子).","2. 그 뒤에 ときたら를 그대로 붙여 화제로 삼는다(息子ときたら).","3. 뒤에는 그 대상에 대한 불만·어이없음이 온다."],"why":"","nu":"회화체. 화자와 가까운 대상(가족, 자기 물건 등)이나 주변의 일을 화제로 꺼내며 비난·불만·어이없음을 드러낸다. 뒤에 칭찬이나 중립적인 설명을 이어 쓰면 어색하다. 화자 자신을 화제로 삼지는 않는다.","cmp":[{"g":"～といったら","d":"정도가 대단함에 대한 감탄을 나타내며 좋은 쪽, 나쁜 쪽 모두에 쓴다. ときたら는 주로 불만·비난이다."}],"ex":[{"jp":"うちの息子[むすこ]ときたら、休[やす]みの日[ひ]は昼[ひる]まで寝[ね]ている。","ko":"우리 아들로 말할 것 같으면, 쉬는 날에는 점심때까지 잔다."},{"jp":"この携帯[けいたい]ときたら、すぐに電池[でんち]がなくなる。","ko":"이 휴대폰은 정말이지 금방 배터리가 닳는다."},{"jp":"最近[さいきん]の天気[てんき]ときたら、暑[あつ]かったり寒[さむ]かったりで困[こま]る。","ko":"요즘 날씨로 말하자면, 더웠다 추웠다 해서 곤란하다."}],"dr":[{"t":"make","q":"うちの夫 → ～ときたら","a":"うちの夫ときたら","hint":"명사 + ときたら"},{"t":"make","q":"この携帯 → ～ときたら","a":"この携帯ときたら","hint":"명사 + ときたら"},{"t":"fill","q":"うちの兄[あに]（　）、毎日[まいにち]ゲームばかりしている。","a":"ときたら","opts":["ときたら","にかけては","をめぐって","にこたえて"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/ときたら-tokitara-meaning/"],"vf":1,"u":49,"g":1,"gp":"gg_N1_18"},{"id":"g1_047","t":"～と相まって","ko":"~와 어우러져, ~와 맞물려","cat":"기타","conn":[{"w":"명사","f":"音楽 + と相まって"},{"w":"A와 B를 함께 주어로","f":"照明と音楽が + 相まって"}],"rule":["1. 함께 작용하는 요소를 명사로 놓고 と를 붙인다(音楽と).","2. 동사 相まつ의 어미 つ를 っ로 바꾼다(촉음편).","3. 그 뒤에 て를 붙여 相まって가 된다(音楽と相まって).","4. 뒤에는 두 요소가 겹쳐서 생긴 더 큰 결과가 온다."],"why":"5단 동사 相まつ(相俟つ, 서로 어울려 작용하다)의 て형이다.","nu":"문어적이다. 두 가지 이상의 요인이 겹쳐 효과가 더 커졌음을 나타내며 좋은 결과, 나쁜 결과 모두에 쓴다. 'AとBが相まって'처럼 두 요소를 함께 주어로 세우기도 한다.","cmp":[{"g":"～も相まって","d":"다른 요인에 A까지 더해져 결과가 커졌다는 뜻이다. と相まって는 A와 다른 요소가 함께 작용함을 말한다."}],"ex":[{"jp":"美[うつく]しい景色[けしき]と相[あい]まって、料理[りょうり]がいっそうおいしく感[かん]じられた。","ko":"아름다운 경치와 어우러져 요리가 한층 맛있게 느껴졌다."},{"jp":"照明[しょうめい]と音楽[おんがく]が相[あい]まって、すばらしい舞台[ぶたい]になった。","ko":"조명과 음악이 어우러져 훌륭한 무대가 되었다."},{"jp":"円安[えんやす]も相[あい]まって、外国人観光客[がいこくじんかんこうきゃく]が増[ふ]えている。","ko":"엔저까지 맞물려 외국인 관광객이 늘고 있다."}],"dr":[{"t":"make","q":"相まつ → て형","a":"相まって","hint":"어미 つ를 っ로 바꾸고 て"},{"t":"make","q":"音楽 → ～と相まって","a":"音楽と相まって","hint":"명사 + と + 相まって"},{"t":"fill","q":"彼[かれ]の才能[さいのう]が努力[どりょく]（　）、大[おお]きな成果[せいか]を生[う]んだ。","a":"と相まって","opts":["と相まって","ときたら","なりとも","といわず"]}],"src":["https://bunpro.jp/grammar_points/853"],"vf":1,"u":49,"g":1,"gp":"gg_N1_18"},{"id":"g1_056","t":"～にあっては","ko":"~에 있어서는, ~(의 상황·입장)에서는","cat":"기타","conn":[{"w":"명사(상황·시대·입장)","f":"非常時 + にあっては"},{"w":"명사 + の + 명사","f":"親の立場 + にあっては"}],"rule":["1. 상황·시대·입장을 나타내는 명사를 쓴다(非常時).","2. 명사 뒤에 にあっては를 그대로 붙인다(非常時にあっては).","3. 명사는 형태가 바뀌지 않는다."],"why":"조사 に + ある(있다)의 て형 あって + 주제 조사 は로 이루어져 '~에 있어서는'이라는 뜻이 된다.","nu":"매우 딱딱한 문어체로 연설·논설·공식 문서에서 쓴다. 보통과 다른 특별한 상황이나 입장을 내세우고 '그런 상황에서는 ~하다/~해야 한다'고 말할 때 쓴다. 비슷하게 にあっても는 '~에 있어서도'라는 뜻이다.","cmp":[{"g":"～において","d":"장소·시간·분야를 중립적으로 나타낸다(会議室において). にあっては는 특별한 상황이나 입장을 강조하며 더 딱딱하다."}],"ex":[{"jp":"非常時[ひじょうじ]にあっては、冷静[れいせい]な判断[はんだん]が求[もと]められる。","ko":"비상시에는 냉정한 판단이 요구된다."},{"jp":"親[おや]の立場[たちば]にあっては、子[こ]どもの安全[あんぜん]が何[なに]より大切[たいせつ]だ。","ko":"부모의 입장에서는 아이의 안전이 무엇보다 중요하다."},{"jp":"現代[げんだい]にあっては、インターネットなしの生活[せいかつ]は考[かんが]えにくい。","ko":"현대에 있어서는 인터넷 없는 생활은 생각하기 어렵다."}],"dr":[{"t":"make","q":"非常時 → ～にあっては","a":"非常時にあっては","hint":"명사 + にあっては"},{"t":"make","q":"教師の立場 → ～にあっては","a":"教師の立場にあっては","hint":"명사구 그대로 + にあっては"},{"t":"fill","q":"緊急時[きんきゅうじ]（　）、係員[かかりいん]の指示[しじ]に従[したが]ってください。","a":"にあっては","opts":["にあっては","にひきかえ","にすら","にもまして"]}],"src":["https://nihongokyoshi-net.com/2019/07/08/jlptn1-grammar-niatte/"],"vf":1,"u":50,"g":1,"gp":"gg_N1_18"},{"id":"g1_058","t":"～にして","ko":"~에 (이르러), ~이자 ~이면서","cat":"기타","conn":[{"w":"명사(나이·시간)","f":"70歳 + にして"},{"w":"명사(순간)","f":"一瞬 + にして"},{"w":"명사 + 명사(병렬)","f":"医者 + にして + 作家"}],"rule":["1. 명사 뒤에 にして를 그대로 붙인다(70歳にして).","2. 나이·시간 명사에 붙으면 '그 단계에 와서'라는 뜻이 된다(70歳にして入学した).","3. 一瞬にして는 '순식간에'라는 굳은 표현이다.","4. A にして B 형태로 두 명사를 이으면 'A이자 B'라는 뜻이 된다(医者にして作家)."],"why":"","nu":"문어적인 표현이다. 나이·시간에 붙는 용법은 '그 나이·단계에 이르러서야(또는 벌써) ~했다'는 놀라움이 담긴다. 병렬 용법 'AにしてB'는 한 사람이나 사물이 두 성질을 함께 가짐을 말하며 회화의 'Aであり、Bでもある'보다 딱딱하다. 비슷한 형태의 ～にしては(~치고는)와 헷갈리지 않도록 주의.","cmp":[{"g":"～にしては","d":"子どもにしては上手だ처럼 '~치고는(기대와 다르게)'라는 뜻. にして는 단계·시점이나 병렬을 나타낸다."}],"ex":[{"jp":"祖父[そふ]は70歳[ななじゅっさい]にして大学[だいがく]に入学[にゅうがく]した。","ko":"할아버지는 70세에 대학에 입학했다."},{"jp":"古[ふる]い家[いえ]は火事[かじ]で一瞬[いっしゅん]にして燃[も]えてしまった。","ko":"오래된 집은 화재로 순식간에 타 버렸다."},{"jp":"彼女[かのじょ]は歌手[かしゅ]にして女優[じょゆう]でもある。","ko":"그녀는 가수이자 배우이기도 하다."}],"dr":[{"t":"make","q":"70歳 → ～にして（入学した）","a":"70歳にして","hint":"나이 명사 + にして"},{"t":"make","q":"医者・作家 → AにしてB","a":"医者にして作家","hint":"명사A + にして + 명사B"},{"t":"fill","q":"部屋[へや]は一瞬[いっしゅん]（　）煙[けむり]でいっぱいになった。","a":"にして","opts":["にして","にすら","にひきかえ","にあっては"]}],"src":["https://bunpro.jp/ja/grammar_points/%E3%81%AB%E3%81%97%E3%81%A61"],"vf":1,"u":50,"g":1,"gp":"gg_N1_18"},{"id":"g1_064","t":"～によらず","ko":"~에 관계없이, ~을 불문하고","cat":"기타","conn":[{"w":"명사","f":"年齢 + によらず"},{"w":"관용 표현","f":"見かけ + によらず"},{"w":"何事","f":"何事 + によらず"}],"rule":["1. よる(의하다, 좌우되다)의 어미 る를 ら로 바꿔 ない형 어간 よら를 만든다.","2. 그 뒤에 문어 부정 ず를 붙여 よらず가 된다(よらない의 문어형).","3. 명사 뒤에 に + よらず를 붙인다(年齢によらず)."],"why":"조사 に + よる(의하다, ~에 좌우되다)의 부정형 よらず로 이루어져 '~에 좌우되지 않고'라는 뜻이 된다.","nu":"문어적이다. 年齢・性別・経験・国籍 같은 조건을 묻지 않는다는 뜻으로 공지·안내문에 자주 나온다. 見かけによらず(겉보기와 달리)와 何事によらず(무슨 일이든)는 굳어진 표현이다.","cmp":[{"g":"～を問わず","d":"뜻이 거의 같으며 男女を問わず처럼 대립되는 쌍과 잘 쓴다. 見かけによらず 같은 관용 표현은 によらず로만 쓴다."}],"ex":[{"jp":"この仕事[しごと]は年齢[ねんれい]によらず、だれでも応募[おうぼ]できる。","ko":"이 일은 나이에 관계없이 누구나 응모할 수 있다."},{"jp":"彼[かれ]は見[み]かけによらず、力[ちから]が強[つよ]い。","ko":"그는 겉보기와 달리 힘이 세다."},{"jp":"何事[なにごと]によらず、最後[さいご]まであきらめないことが大切[たいせつ]だ。","ko":"무슨 일이든 끝까지 포기하지 않는 것이 중요하다."}],"dr":[{"t":"make","q":"よる → ～ず","a":"よらず","hint":"어미 る를 ら로 바꾸고 ず를 붙인다"},{"t":"make","q":"経験 → ～によらず","a":"経験によらず","hint":"명사 + に + よらず"},{"t":"fill","q":"彼[かれ]は見[み]かけ（　）、とても優[やさ]しい人[ひと]だ。","a":"によらず","opts":["によらず","にとどまらず","にして","にすら"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/によらず-ni-yorazu-meaning/"],"vf":1,"u":50,"g":1,"gp":"gg_N1_18"},{"id":"g1_067","t":"～に即して","ko":"~에 입각하여, ~에 맞추어","cat":"기타","conn":[{"w":"명사 + 동사","f":"法律 + に即して + 判断する"}],"rule":["1. 即する(꼭 맞다, 따르다)의 어미 する를 して로 바꿔 て형 即して를 만든다.","2. 기준이 되는 명사 뒤에 に + 即して를 붙인다(法律に即して).","3. 그 뒤에 동사를 쓴다(法律に即して判断する).","4. 문어에서는 て를 빼고 に即し、로 잇기도 한다."],"why":"即する(딱 맞다, 따르다)의 て형으로, '~에 딱 맞추어서'라는 뜻이 된다.","nu":"문어적이며 보고서·법률·공적인 문장에서 쓴다. 명사에는 事実・現実・実態・法律・状況 등 실제 기준이 되는 말이 온다. 뒤에 명사가 올 때는 に即した를 쓴다.","cmp":[{"g":"～に基づいて","d":"자료·근거를 토대로 한다는 뜻(データに基づいて). に即して는 실제 상황이나 기준에 어긋나지 않게 맞춘다는 느낌이 강하다."},{"g":"～に即した","d":"같은 뜻으로 뒤에 명사가 온다(現実に即した計画)."}],"ex":[{"jp":"事実[じじつ]に即[そく]して話[はな]してください。","ko":"사실에 입각해서 이야기해 주세요."},{"jp":"裁判官[さいばんかん]は法律[ほうりつ]に即[そく]して判断[はんだん]しなければならない。","ko":"재판관은 법률에 입각하여 판단해야 한다."},{"jp":"自分[じぶん]の経験[けいけん]に即[そく]して説明[せつめい]すると、分[わ]かりやすい。","ko":"자신의 경험에 맞추어 설명하면 이해하기 쉽다."}],"dr":[{"t":"make","q":"即する → て형","a":"即して","hint":"する를 して로 바꾼다"},{"t":"make","q":"事実・話す → ～に即して～","a":"事実に即して話す","hint":"명사 + に即して + 동사"},{"t":"fill","q":"現場[げんば]の状況[じょうきょう]（　）、計画[けいかく]を見直[みなお]した。","a":"に即して","opts":["に即して","にひきかえ","にすら","にあるまじき"]}],"src":["https://bunpro.jp/grammar_points/882"],"vf":1,"u":50,"g":1,"gp":"gg_N1_18"},{"id":"g1_068","t":"～に言わせれば","ko":"~의 말로는, ~에게 말하라고 하면","cat":"기타","conn":[{"w":"명사(사람)","f":"母 + に言わせれば"},{"w":"인칭대명사","f":"私 + に言わせれば"}],"rule":["1. 言う의 어미 う를 わ로 바꾸고 せる를 붙여 사역형 言わせる를 만든다.","2. 言わせる의 る를 れ로 바꾸고 ば를 붙여 가정형 言わせれば를 만든다.","3. 의견을 말하는 사람 명사 뒤에 に + 言わせれば를 붙인다(母に言わせれば)."],"why":"言う의 사역형 言わせる(말하게 하다)에 가정형 ば가 붙은 형태로, '~에게 말하게 하면' → '~의 의견으로는'이라는 뜻이 된다.","nu":"사람 명사에만 붙는다. 그 사람 특유의 주관적 의견·평가를 소개할 때 쓰며, 다른 사람과 의견이 다르다는 느낌이 있다. 뒤에는 ~だ, ~そうだ, ~という 같은 의견 내용이 온다. 私に言わせれば는 '내가 보기에는'이라고 자기 의견을 강하게 내세울 때 쓴다.","cmp":[{"g":"～によると","d":"정보의 출처를 나타낸다(天気予報によると). に言わせれば는 객관적 정보가 아니라 그 사람의 개인적 견해다."}],"ex":[{"jp":"母[はは]に言[い]わせれば、私[わたし]はまだ子[こ]どもだそうだ。","ko":"엄마 말로는 나는 아직 어린애라고 한다."},{"jp":"専門家[せんもんか]に言[い]わせれば、この計画[けいかく]には無理[むり]がある。","ko":"전문가의 말로는 이 계획에는 무리가 있다."},{"jp":"私[わたし]に言[い]わせれば、彼[かれ]のやり方[かた]は間違[まちが]っている。","ko":"내가 보기에는 그의 방식은 틀렸다."}],"dr":[{"t":"make","q":"言う → 사역 가정형","a":"言わせれば","hint":"う를 わ로 + せる → る를 れ로 + ば"},{"t":"make","q":"父 → ～に言わせれば","a":"父に言わせれば","hint":"사람 명사 + に言わせれば"},{"t":"fill","q":"祖父[そふ]（　）、今[いま]の若者[わかもの]は苦労[くろう]が足[た]りないそうだ。","a":"に言わせれば","opts":["に言わせれば","にひきかえ","に先駆けて","にすら"]}],"src":["https://bunpro.jp/grammar_points/890"],"vf":1,"u":51,"g":1,"gp":"gg_N1_18"},{"id":"g1_073","t":"～を抜いて","ko":"~을 빼고, ~을 거르고","cat":"기타","conn":[{"w":"명사","f":"朝ご飯 + を抜いて"}],"rule":["1. 동사 抜く(빼다)의 어미 く를 い로 바꾼다(イ음편): 抜く → 抜い.","2. 그 뒤에 て를 붙여 て형 抜いて를 만든다.","3. 빼는 대상인 명사에 を를 붙여 앞에 둔다: 朝ご飯を抜いて."],"why":"타동사 抜く(뽑다, 빼다)의 て형이다. 원래 있어야 할 것을 빼낸다는 동사 뜻이 그대로 살아 있다.","nu":"원래 들어가야 할 것(식사, 재료, 순서 등)을 빼고 무언가를 한다는 뜻이다. 끼니를 거른다는 食事を抜く・朝ご飯を抜く가 특히 자주 쓰인다. 경쟁·순위 문맥에서는 '제치고, 앞지르고'라는 뜻이 되므로(前の車を抜いて) 문맥에 주의한다. 단순히 범위에서 제외한다는 '~을 제외하고'는 を除いて가 더 일반적이다.","cmp":[{"g":"～を除いて","d":"어떤 범위에서 일부를 제외한다는 일반적·격식 있는 표현(日曜日を除いて毎日開いている). を抜いて는 들어갈 것을 실제로 빼낸다는 느낌이 강하다."},{"g":"～抜きで / ～を抜きにして","d":"명사 + 抜きで(わさび抜きで), 冗談は抜きにして처럼 명사형 抜き를 쓰는 관용적 표현이다."}],"ex":[{"jp":"寝坊[ねぼう]して、朝[あさ]ご飯[はん]を抜[ぬ]いて学校[がっこう]へ行[い]った。","ko":"늦잠을 자서 아침을 거르고 학교에 갔다."},{"jp":"ダイエット中[ちゅう]なので、ご飯[はん]を抜[ぬ]いておかずだけ食[た]べた。","ko":"다이어트 중이라서 밥을 빼고 반찬만 먹었다."},{"jp":"子[こ]どもの分[ぶん]は、わさびを抜[ぬ]いて握[にぎ]ってもらった。","ko":"아이 몫은 와사비를 빼고 쥐어 달라고 했다."}],"dr":[{"t":"make","q":"昼ご飯 → ～を抜いて","a":"昼ご飯を抜いて","hint":"명사 + を + 抜く의 て형(く → いて)"},{"t":"make","q":"砂糖 → ～を抜いて","a":"砂糖を抜いて","hint":"명사 + を + 抜いて"},{"t":"fill","q":"忙[いそが]しくて、昼[ひる]ご飯[はん]を（　）働[はたら]いた。","a":"抜いて","opts":["抜いて","抜けて","抜かれて","抜き出して"]}],"src":["https://jisho.org/search/%E3%81%AC%E3%81%8F%20%E6%8A%9C%20%23sentences"],"vf":1,"u":51,"g":1,"gp":"gg_N1_19"},{"id":"g1_074","t":"～抜く","ko":"끝까지 ~해내다, 철저히 ~하다","cat":"기타","conn":[{"w":"1그룹 동사 ます형","f":"走る → 走り + 抜く"},{"w":"2그룹 동사 ます형","f":"考える → 考え + 抜く"},{"w":"1그룹 동사 ます형","f":"やる → やり + 抜く"}],"rule":["1. 1그룹 동사는 어미 う단을 い단으로 바꿔 ます형을 만든다: 走る → 走り.","2. 2그룹 동사는 어미 る를 뗀다: 考える → 考え.","3. 그 뒤에 抜く를 붙인다: 走り抜く, 考え抜く.","4. 抜く는 1그룹 동사처럼 활용한다: 走り抜いた, 考え抜いて."],"why":"동사 ます형에 抜く를 붙여 만든 복합동사다.","nu":"힘들고 오래 걸리는 일을 중간에 포기하지 않고 마지막까지 해낸다는 의지와 노력을 강조한다. 走る・やる・頑張る・戦う・生きる・耐える・守る・考える・悩む처럼 노력이나 시간이 드는 동사와 주로 쓰고, 노력이 필요 없는 동작이나 순간 동작에는 잘 붙이지 않는다. 終わる처럼 '끝나다' 자체를 뜻하는 동사에는 쓰지 않는다.","cmp":[{"g":"～きる","d":"食べきる・使いきる처럼 '남김없이 다 ~하다'라는 양적 완료에도 쓴다. 抜く는 고난을 견디며 끝까지 해내는 의지가 중심이다."},{"g":"～通す","d":"言い通す・隠し通す처럼 같은 행위나 태도를 끝까지 바꾸지 않고 계속한다는 뜻이다."}],"ex":[{"jp":"彼[かれ]は足[あし]を痛[いた]めながらも、最後[さいご]まで走[はし]り抜[ぬ]いた。","ko":"그는 다리를 다치면서도 마지막까지 달려냈다."},{"jp":"一度[いちど]始[はじ]めたことは、最後[さいご]までやり抜[ぬ]くつもりだ。","ko":"한번 시작한 일은 끝까지 해낼 생각이다."},{"jp":"考[かんが]え抜[ぬ]いて出[だ]した結論[けつろん]だから、後悔[こうかい]はない。","ko":"깊이 고민한 끝에 내린 결론이라 후회는 없다."}],"dr":[{"t":"make","q":"戦う → ～抜く","a":"戦い抜く","hint":"1그룹: 어미 う를 い로 바꾼 ます형 + 抜く"},{"t":"make","q":"耐える → ～抜く","a":"耐え抜く","hint":"2그룹: る를 뗀 ます형 + 抜く"},{"t":"fill","q":"彼女[かのじょ]はつらい練習[れんしゅう]に最後[さいご]まで耐[た]え（　）。","a":"抜いた","opts":["抜いた","かけた","がちだった","そびれた"]}],"src":["https://bunpro.jp/grammar_points/抜く"],"vf":1,"u":51,"g":1,"gp":"gg_N1_19"},{"id":"g1_090","t":"～はさておき","ko":"~은 제쳐 두고, ~은 어쨌든","cat":"기타","conn":[{"w":"명사","f":"冗談 + はさておき"},{"w":"지시어","f":"それ + はさておき"}],"rule":["1. 일단 미뤄 둘 명사 뒤에 は를 붙인다: 冗談は.","2. 동사 さておく(제쳐 두다)의 어미 く를 き로 바꾼 ます형 さておき를 붙인다: 冗談はさておき.","3. 뒤에는 더 중요한 본래 화제를 쓴다."],"why":"さておき는 화제를 바꾸는 말 さて(그런데)와 置く(두다)의 ます형(연용형) 置き가 합쳐진 말로, '그런데 (그건) 놓아 두고'라는 느낌이다.","nu":"어떤 화제를 일단 미뤄 두고 더 중요한 이야기로 옮겨 갈 때 쓴다. 冗談はさておき・それはさておき는 화제를 바꿀 때 쓰는 관용적인 표현이다. 회화와 글 모두에서 쓰지만 약간 딱딱한 느낌이 있다.","cmp":[{"g":"～はともかく(として)","d":"거의 같은 뜻으로 바꿔 쓸 수 있으며, 'A는 몰라도 B는'이라는 평가의 대비에도 쓴다."}],"ex":[{"jp":"冗談[じょうだん]はさておき、そろそろ本題[ほんだい]に入[はい]りましょう。","ko":"농담은 제쳐 두고 슬슬 본론으로 들어갑시다."},{"jp":"値段[ねだん]はさておき、このデザインはとても気[き]に入[い]った。","ko":"가격은 어쨌든 이 디자인은 정말 마음에 들었다."},{"jp":"結果[けっか]はさておき、最後[さいご]まで頑張[がんば]ったことが大切[たいせつ]だ。","ko":"결과는 제쳐 두고 끝까지 노력한 것이 중요하다."}],"dr":[{"t":"make","q":"冗談 → ～はさておき","a":"冗談はさておき","hint":"명사 + は + さておき(さておく → さておき)"},{"t":"make","q":"費用 → ～はさておき","a":"費用はさておき","hint":"명사 + は + さておき"},{"t":"fill","q":"見[み]た目[め]（　）、この料理[りょうり]は味[あじ]がいい。","a":"はさておき","opts":["はさておき","はおろか","のごとき","の至り"]}],"src":["https://bunpro.jp/grammar_points/848","https://jlptsensei.com/learn-japanese-grammar/はさておき-wa-sateoki-meaning/"],"vf":1,"u":51,"g":1,"gp":"gg_N1_19"},{"id":"g1_092","t":"～まみれ","ko":"~투성이, ~범벅","cat":"기타","conn":[{"w":"명사","f":"泥 + まみれ"}],"rule":["1. 명사 뒤에 조사 없이 まみれ를 바로 붙인다: 泥 → 泥まみれ.","2. 泥まみれ는 명사처럼 써서 ～になる / ～だ / ～の + 명사로 잇는다: 泥まみれになる, 泥まみれの靴."],"why":"","nu":"진흙·땀·피·기름·먼지처럼 표면에 끈적하게 온통 묻어 있는 상태를 말하며, 대개 불쾌한 것에 쓴다. 借金まみれ처럼 비유적으로도 쓴다. 상처·실수처럼 표면에 '묻는' 것이 아닌 경우에는 まみれ가 아니라 だらけ를 쓴다(傷だらけ, 間違いだらけ).","cmp":[{"g":"～だらけ","d":"무언가가 많이 있거나 흩어져 있음을 말하며 쓰임이 넓다(間違いだらけ, 傷だらけ). まみれ는 표면 전체에 묻어 덮인 경우에 한정된다."}],"ex":[{"jp":"子[こ]どもたちは泥[どろ]まみれになって遊[あそ]んでいた。","ko":"아이들은 진흙투성이가 되어 놀고 있었다."},{"jp":"一日中[いちにちじゅう]働[はたら]いて、汗[あせ]まみれのシャツを洗[あら]った。","ko":"하루 종일 일해서 땀범벅이 된 셔츠를 빨았다."},{"jp":"彼[かれ]は借金[しゃっきん]まみれの生活[せいかつ]からやっと抜[ぬ]け出[だ]した。","ko":"그는 빚투성이 생활에서 겨우 빠져나왔다."}],"dr":[{"t":"make","q":"汗 → ～まみれになる","a":"汗まみれになる","hint":"명사 + まみれ + になる"},{"t":"make","q":"油 → ～まみれの手","a":"油まみれの手","hint":"명사 + まみれ + の + 명사"},{"t":"fill","q":"雨[あめ]の中[なか]でサッカーをして、全身[ぜんしん]泥（　）になった。","a":"まみれ","opts":["まみれ","っぽい","がち","ぎみ"]}],"src":["https://nihongokyoshi-net.com/2019/07/23/jlptn1-grammar-mamire/","https://guidetojapanese.org/learn/grammar/covered"],"vf":1,"u":51,"g":1,"gp":"gg_N1_19"},{"id":"g1_097","t":"～をもって","ko":"~으로(써), ~을 끝으로 / ~부로","cat":"기타","conn":[{"w":"명사 (시점)","f":"本日 + をもって"},{"w":"명사 (수단)","f":"書面 + をもって"}],"rule":["1. 1그룹 동사 もつ(持つ)의 어미 つ를 っ로 바꾼다(촉음편): もつ → もっ.","2. て를 붙여 もって를 만든다.","3. 시점이나 수단을 나타내는 명사 + を 뒤에 둔다: 本日をもって."],"why":"","nu":"딱딱한 격식 표현으로 공지·인사·공문서에 많이 쓴다. ① 시점: 本日をもって閉店する처럼 어떤 일이 끝나거나 시작되는 기한을 나타낸다. ② 수단·방법: 書面をもって通知する처럼 '~으로써'의 뜻이다. 더 정중하게는 をもちまして를 쓴다. 일상 회화에서는 で를 쓰는 것이 자연스럽다.","cmp":[{"g":"～で","d":"수단·시점을 나타내는 일반적인 조사로 회화에서 쓴다. をもって는 공식적인 자리에 쓰는 딱딱한 표현이다."},{"g":"～をもちまして","d":"をもって의 더 정중한 형태로, 식사·폐회 인사 등에서 쓴다."}],"ex":[{"jp":"本日[ほんじつ]をもって、この店[みせ]は閉店[へいてん]いたします。","ko":"오늘부로 이 가게는 문을 닫습니다."},{"jp":"結果[けっか]は書面[しょめん]をもってお知[し]らせします。","ko":"결과는 서면으로 알려 드리겠습니다."},{"jp":"以上[いじょう]をもちまして、本日[ほんじつ]の会[かい]を終[お]わります。","ko":"이것으로 오늘 모임을 마치겠습니다."}],"dr":[{"t":"make","q":"本日 → ～をもって","a":"本日をもって","hint":"명사 + を + もつ의 て형(つ → って)"},{"t":"make","q":"書面 → ～をもって","a":"書面をもって","hint":"수단 명사 + をもって"},{"t":"fill","q":"三月[さんがつ]末日[まつじつ]（　）、退職[たいしょく]することになりました。","a":"をもって","opts":["をもって","をよそに","を経て","をめぐって"]}],"src":["https://bunpro.jp/grammar_points/739","https://www.mlcjapanese.co.jp/n1_04_29.html"],"vf":1,"u":52,"g":1,"gp":"gg_N1_19"},{"id":"g1_101","t":"～を前提として","ko":"~을 전제로 (하여)","cat":"기타","conn":[{"w":"명사","f":"結婚 + を前提として"},{"w":"동사 사전형 + こと","f":"返すこと + を前提として"}],"rule":["1. する의 어미 る를 떼고 し로 바꾼다: とする → とし.","2. て를 붙여 として를 만든다.","3. 명사 + を + 前提 뒤에 둔다: 結婚を前提として."],"why":"前提(전제) + として(とする의 て형, '~로 하여')로 이루어져 '~을 전제로 하여'라는 뜻이 된다.","nu":"다소 격식 있는 표현으로 계획·계약·제도 설명, 그리고 結婚を前提として付き合う 같은 관용적 표현에 쓴다. 뒤 명사를 꾸밀 때는 ～を前提とした + 명사, 짧게는 ～を前提に로 쓴다. 한국어 '전제로'와 거의 같지만 조사 を를 빠뜨리지 않도록 주의한다.","cmp":[{"g":"～を前提にして","d":"뜻은 거의 같다. として 쪽이 조금 더 딱딱하다."},{"g":"～をもとに(して)","d":"재료·근거를 바탕으로 무언가를 만든다는 뜻(事実をもとにした映画). 前提는 아직 확정되지 않은 조건을 미리 성립한다고 보는 것이다."}],"ex":[{"jp":"結婚[けっこん]を前提[ぜんてい]として、お付[つ]き合[あ]いしています。","ko":"결혼을 전제로 사귀고 있습니다."},{"jp":"この計画[けいかく]は、国[くに]の補助[ほじょ]を前提[ぜんてい]として作[つく]られている。","ko":"이 계획은 국가 보조를 전제로 만들어져 있다."},{"jp":"返[かえ]すことを前提[ぜんてい]として、友人[ゆうじん]にお金[かね]を貸[か]した。","ko":"돌려받는 것을 전제로 친구에게 돈을 빌려주었다."}],"dr":[{"t":"make","q":"結婚 → ～を前提として","a":"結婚を前提として","hint":"명사 + を + 前提 + として"},{"t":"make","q":"合格 → ～を前提として","a":"合格を前提として","hint":"명사 + を + 前提 + として"},{"t":"fill","q":"全員[ぜんいん]が参加[さんか]すること（　）、会場[かいじょう]を予約[よやく]した。","a":"を前提として","opts":["を前提として","をよそに","をものともせずに","を禁じ得ず"]}],"src":["https://jlptsensei.com/learn-japanese-grammar/を前提として-o-zentei-toshite-meaning/","https://bunpro.jp/grammar_points/997"],"vf":1,"u":52,"g":1,"gp":"gg_N1_19"},{"id":"g1_102","t":"～を前提にして","ko":"~을 전제로 해서","cat":"기타","conn":[{"w":"명사","f":"晴れ + を前提にして"},{"w":"동사 사전형 + こと","f":"使うこと + を前提にして"}],"rule":["1. 前提 뒤에 결과를 나타내는 조사 に를 붙인다: 前提に.","2. する의 る를 떼고 し로 바꾼 뒤 て를 붙인다: する → して.","3. 명사 + を 뒤에 둔다: 晴れを前提にして."],"why":"前提(전제) + に + して(する의 て형)로 이루어진 '~을 전제로 해서'라는 뜻이다.","nu":"を前提として와 뜻이 거의 같고, 조금 더 부드러워 회화에서도 쓴다. して를 생략한 ～を前提に, 명사를 꾸미는 ～を前提にした + 명사도 자주 쓴다. 앞에는 명사 또는 'こと'로 명사화한 동사가 온다.","cmp":[{"g":"～を前提として","d":"뜻은 같고 조금 더 딱딱한 문장체다."}],"ex":[{"jp":"晴[は]れを前提[ぜんてい]にして、明日[あした]の予定[よてい]を立[た]てた。","ko":"맑은 날씨를 전제로 해서 내일 일정을 세웠다."},{"jp":"この机[つくえ]は、子[こ]どもが使[つか]うことを前提[ぜんてい]にして作[つく]られている。","ko":"이 책상은 아이가 쓰는 것을 전제로 해서 만들어져 있다."},{"jp":"これは留学[りゅうがく]を前提[ぜんてい]にした授業[じゅぎょう]なので、英語[えいご]で行[おこな]われる。","ko":"이것은 유학을 전제로 한 수업이라서 영어로 진행된다."}],"dr":[{"t":"make","q":"晴れ → ～を前提にして","a":"晴れを前提にして","hint":"명사 + を + 前提 + に + して"},{"t":"make","q":"経済成長 / 計画 → ～を前提にした～","a":"経済成長を前提にした計画","hint":"명사 수식: 前提にした + 명사"},{"t":"fill","q":"雨[あめ]が降[ふ]らないこと（　）、外[そと]で準備[じゅんび]を進[すす]めた。","a":"を前提にして","opts":["を前提にして","をおいて","をよそに","を余儀なくされて"]}],"src":["https://bunpro.jp/grammar_points/997","https://jlptsensei.com/learn-japanese-grammar/を前提として-o-zentei-toshite-meaning/"],"vf":1,"u":52,"g":1,"gp":"gg_N1_19"},{"id":"g1_109","t":"～を踏まえて","ko":"~을 토대로, ~을 바탕으로 하여","cat":"기타","conn":[{"w":"명사","f":"結果 + を踏まえて"},{"w":"명사(명사 수식)","f":"結果 + を踏まえた + 計画"}],"rule":["1. 2그룹 동사 踏まえる(근거로 삼다)의 어미 る를 뗀다: 踏まえる → 踏まえ.","2. 그 뒤에 て를 붙여 て형 踏まえて를 만든다.","3. 근거가 되는 명사에 を를 붙여 앞에 둔다: 結果を踏まえて.","4. 뒤의 명사를 꾸밀 때는 て 대신 た를 붙여 踏まえた + 명사로 쓴다."],"why":"","nu":"앞의 사실·결과·의견 등을 판단의 근거나 전제로 삼고 뒤의 행동(계획을 세우다, 검토하다, 결정하다 등)을 한다는 뜻이다. 회의, 보고서, 뉴스 등 격식 있는 문어체에서 주로 쓰고 가벼운 일상 회화에는 잘 쓰지 않는다. 뒤에는 생각하고 판단하는 행동이 오며, 단순히 '~에 따라서'라는 기준·규칙을 나타낼 때는 に基づいて가 더 자연스럽다.","cmp":[{"g":"～に基づいて","d":"자료·규칙·사실을 직접적인 기준이나 근거로 삼는다(法律に基づいて判断する). を踏まえて는 앞의 내용을 충분히 고려하여 그 위에서 다음 단계를 생각한다는 느낌이 강하다."},{"g":"～をもとに(して)","d":"재료·소재로 삼아 무언가를 만들어 낸다(実話をもとにした映画). 판단의 전제보다 '재료'라는 느낌이다."}],"ex":[{"jp":"前回[ぜんかい]の反省[はんせい]を踏[ふ]まえて、今年[ことし]は準備[じゅんび]を早[はや]めに始[はじ]めた。","ko":"지난번의 반성을 토대로 올해는 준비를 일찍 시작했다."},{"jp":"アンケートの結果[けっか]を踏[ふ]まえて、メニューを見直[みなお]すことにした。","ko":"설문 결과를 바탕으로 메뉴를 재검토하기로 했다."},{"jp":"皆[みな]さんの意見[いけん]を踏[ふ]まえた上[うえ]で、最終的[さいしゅうてき]に決[き]めます。","ko":"여러분의 의견을 토대로 한 뒤에 최종적으로 정하겠습니다."}],"dr":[{"t":"make","q":"調査の結果 → ～を踏まえて","a":"調査の結果を踏まえて","hint":"명사 + を + 踏まえる의 て형(る를 떼고 て)"},{"t":"make","q":"現状 → ～を踏まえた（＋対策）","a":"現状を踏まえた対策","hint":"명사를 꾸밀 때는 踏まえ + た + 명사"},{"t":"fill","q":"去年[きょねん]の失敗[しっぱい]を（　）、新[あたら]しい計画[けいかく]を立[た]てた。","a":"踏まえて","opts":["踏まえて","めぐって","問わず","限りに"]}],"src":["https://bunpro.jp/grammar_points/814","https://nihongokyoshi-net.com/2019/06/12/jlptn1-grammar-wofumaete/"],"vf":1,"u":52,"g":1,"gp":"gg_N1_19"},{"id":"g1_130","t":"～つ～つ","ko":"~하거니 ~하거니, ~했다 ~했다","cat":"기타","conn":[{"w":"동사 ます형 (반대 뜻의 두 동사)","f":"行き + つ + 戻り + つ"},{"w":"동사 ます형 (능동·수동 짝)","f":"抜き + つ + 抜かれ + つ"}],"rule":["1. 두 동사를 ます형으로 바꾼다. 1그룹 동사는 어미 う단을 い단으로 바꾼다: 行く → 行き, 戻る → 戻り.","2. 각 ます형 뒤에 つ를 붙인다: 行きつ, 戻りつ.","3. 두 개를 나란히 이어 쓴다: 行きつ戻りつ.","4. 같은 동사의 능동·수동을 짝짓기도 한다: 抜く → 抜き / 抜かれる → 抜かれ → 抜きつ抜かれつ."],"why":"","nu":"두 동작이 번갈아 되풀이되는 모습을 나타내는 문어적 표현으로, 실제로는 거의 관용구로만 쓴다: 行きつ戻りつ(왔다 갔다), 抜きつ抜かれつ(앞서거니 뒤서거니), 持ちつ持たれつ(서로 돕고 도움받는), 浮きつ沈みつ(떴다 가라앉았다). 아무 동사에나 붙여 새로 만들지 않는 것이 좋다. 뒤에는 する나 の + 명사가 온다.","cmp":[{"g":"～たり～たりする","d":"여러 동작을 예로 드는 일반적인 표현으로, 어떤 동사에도 쓸 수 있다. ～つ～つ는 서로 반대되는 두 동작의 반복에 한정된 관용적 표현이다."}],"ex":[{"jp":"彼[かれ]は駅[えき]の前[まえ]を行[い]きつ戻[もど]りつしていた。","ko":"그는 역 앞을 왔다 갔다 하고 있었다."},{"jp":"二台[にだい]の車[くるま]は抜[ぬ]きつ抜[ぬ]かれつのレースを続[つづ]けた。","ko":"두 대의 차는 앞서거니 뒤서거니 하는 레이스를 계속했다."},{"jp":"隣[となり]の家[いえ]とは持[も]ちつ持[も]たれつの関係[かんけい]だ。","ko":"옆집과는 서로 돕고 사는 관계다."}],"dr":[{"t":"make","q":"浮く・沈む → ～つ～つ","a":"浮きつ沈みつ","hint":"두 동사를 ます형(く → き, む → み)으로 바꾸고 각각 つ"},{"t":"make","q":"持つ・持たれる → ～つ～つ","a":"持ちつ持たれつ","hint":"つ → ち, 持たれる → 持たれ, 각각 + つ"},{"t":"fill","q":"彼[かれ]は家[いえ]の前[まえ]を行[い]き（　）戻[もど]りつしていた。","a":"つ","opts":["つ","て","たり","ながら"]}],"src":["https://bunpro.jp/grammar_points/つ-つ"],"vf":1,"u":53,"g":1,"gp":"gg_N1_19"},{"id":"g1_155","t":"～がままに","ko":"~하는 대로, ~에 맡긴 채","cat":"기타","conn":[{"w":"동사 사전형","f":"思う + がままに"},{"w":"동사 수동형","f":"言われる + がままに"}],"rule":["1. 1그룹 동사의 수동형은 어미 う단을 あ단으로 바꾸고 れる를 붙인다. 어미가 う이면 わ가 된다: 言う → 言われる.","2. 사전형 또는 수동형 뒤에 が를 붙인다: 言われるが.","3. 그 뒤에 ままに를 붙인다: 言われるがままに."],"why":"","nu":"자기 판단 없이 남이 시키는 대로, 또는 흐름·감정에 몸을 맡긴 채 행동한다는 뜻이다. 言われる・勧められる・流される 같은 수동형과 자주 쓰이고, 思う・感じる・ある와 함께 思うがままに・あるがままに 같은 관용 표현이 된다. 문어적인 표현이다.","cmp":[{"g":"～まま(に)","d":"'~한 채로, ~대로'. がままに는 더 문어적이고 '맡겨 버린다'는 느낌이 강하다."},{"g":"～とおりに","d":"지시·설명과 똑같이 한다는 뜻(説明のとおりに). 수동적 체념의 느낌은 없다."}],"ex":[{"jp":"店員[てんいん]に勧[すす]められるがままに、高[たか]い服[ふく]を買[か]ってしまった。","ko":"점원이 권하는 대로 비싼 옷을 사 버렸다."},{"jp":"言[い]われるがままに、書類[しょるい]にサインした。","ko":"시키는 대로 서류에 사인했다."},{"jp":"自分[じぶん]が感[かん]じるがままに、絵[え]を描[か]いた。","ko":"내가 느끼는 대로 그림을 그렸다."}],"dr":[{"t":"make","q":"勧める → (수동) ～がままに","a":"勧められるがままに","hint":"2그룹 수동: る → られる, 그 뒤에 がままに"},{"t":"make","q":"思う → ～がままに","a":"思うがままに","hint":"사전형 + がままに"},{"t":"fill","q":"彼[かれ]は友達[ともだち]に誘[さそ]われる（　）、毎晩[まいばん]遊[あそ]び歩[ある]いた。","a":"がままに","opts":["がままに","が早いか","ばかりか","からには"]}],"src":["https://bunpro.jp/grammar_points/807","https://bunpro.jp/grammar_points/822"],"vf":1,"u":53,"g":1,"gp":"gg_N1_19"},{"id":"g1_161","t":"～ともなく","ko":"특별히 ~하려는 생각도 없이","cat":"기타","conn":[{"w":"동사 사전형 (같은 동사 반복)","f":"見る + ともなく + 見る"},{"w":"의문사","f":"どこ + から + ともなく"}],"rule":["1. 동사는 사전형을 그대로 쓴다: 見る.","2. 사전형 뒤에 ともなく를 붙인다: 見るともなく.","3. 그 뒤에 같은 동사를 다시 쓴다: 見るともなく見ていた."],"why":"","nu":"특별히 의도하지 않고 무심코 그 행동을 하고 있었다는 뜻이다. 見る・聞く・眺める・考える처럼 감각이나 생각을 나타내는 동사를 같은 동사로 반복하는 형태가 기본이고, 뒤에 우연히 무언가를 알게 되는 내용이 이어지기 쉽다. どこからともなく(어디선가), 誰からともなく(누구랄 것 없이)처럼 의문사와 쓰는 관용 표현도 있다.","cmp":[{"g":"～ともなしに","d":"뜻이 같다."},{"g":"なんとなく","d":"'왠지, 그냥'이라는 부사로 회화적이다."}],"ex":[{"jp":"テレビを見[み]るともなく見[み]ていた。","ko":"텔레비전을 그냥 멍하니 보고 있었다."},{"jp":"隣[となり]の人[ひと]の話[はなし]を聞[き]くともなく聞[き]いていた。","ko":"옆 사람의 이야기를 듣는 둥 마는 둥 듣고 있었다."},{"jp":"どこからともなく、いい匂[にお]いがしてきた。","ko":"어디선가 좋은 냄새가 풍겨 왔다."}],"dr":[{"t":"make","q":"聞く → ～ともなく～ていた","a":"聞くともなく聞いていた","hint":"사전형 + ともなく + 같은 동사(聞いていた)"},{"t":"make","q":"眺める → ～ともなく～ていた","a":"眺めるともなく眺めていた","hint":"사전형 + ともなく + 眺めていた"},{"t":"fill","q":"窓[まど]の外[そと]を見[み]る（　）見[み]ていたら、虹[にじ]が出[で]た。","a":"ともなく","opts":["ともなく","ばかりか","からには","くせに"]}],"src":["https://bunpro.jp/grammar_points/745","https://jlptsensei.com/learn-japanese-grammar/ともなく-ともなしに-tomo-naku-meaning/"],"vf":1,"u":53,"g":1,"gp":"gg_N1_19"},{"id":"g1_162","t":"～ともなしに","ko":"특별히 ~하려는 생각도 없이","cat":"기타","conn":[{"w":"동사 사전형 (같은 동사 반복)","f":"眺める + ともなしに + 眺める"}],"rule":["1. 동사는 사전형을 그대로 쓴다: 眺める.","2. 사전형 뒤에 ともなしに를 붙인다: 眺めるともなしに.","3. 그 뒤에 같은 동사를 다시 쓴다: 眺めるともなしに眺めていた."],"why":"","nu":"ともなく와 같은 뜻으로, 의도 없이 무심코 하고 있었다는 것을 나타낸다. 見る・聞く・眺める 같은 감각 동사를 반복하는 형태가 기본이다.","cmp":[{"g":"～ともなく","d":"뜻이 같다. どこからともなく처럼 의문사와 함께 쓰는 관용 표현은 ともなく 형태로 흔히 쓴다."},{"g":"なんとなく","d":"'그냥, 왠지'라는 회화적 부사."}],"ex":[{"jp":"窓[まど]の外[そと]を眺[なが]めるともなしに眺[なが]めていた。","ko":"창밖을 그저 멍하니 바라보고 있었다."},{"jp":"ラジオを聞[き]くともなしに聞[き]いていたら、懐[なつ]かしい曲[きょく]が流[なが]れてきた。","ko":"라디오를 무심코 듣고 있었더니 그리운 곡이 흘러나왔다."},{"jp":"雑誌[ざっし]を読[よ]むともなしに読[よ]んでいた。","ko":"잡지를 읽는 둥 마는 둥 읽고 있었다."}],"dr":[{"t":"make","q":"見る → ～ともなしに～ていた","a":"見るともなしに見ていた","hint":"사전형 + ともなしに + 見ていた"},{"t":"make","q":"聞く → ～ともなしに～ていた","a":"聞くともなしに聞いていた","hint":"사전형 + ともなしに + 聞いていた"},{"t":"fill","q":"電車[でんしゃ]の中[なか]で、隣[となり]の会話[かいわ]を聞[き]く（　）聞[き]いていた。","a":"ともなしに","opts":["ともなしに","ことなしに","ばかりに","ように"]}],"src":["https://bunpro.jp/grammar_points/745","https://jlptsensei.com/learn-japanese-grammar/ともなく-ともなしに-tomo-naku-meaning/"],"vf":1,"u":53,"g":1,"gp":"gg_N1_19"},{"id":"g1_211","t":"～と言わんばかりに","ko":"마치 ~라고 말하려는 듯이","cat":"기타","conn":[{"w":"동사 (보통형·의지형·명령형 등 인용)","f":"行こう + と言わんばかりに / 帰れ + と言わんばかりに"},{"w":"い형용사","f":"うるさい + と言わんばかりに"},{"w":"な형용사","f":"迷惑だ + と言わんばかりに"},{"w":"명사","f":"邪魔だ + と言わんばかりに"}],"rule":["1. 상대가 말하고 싶어 보이는 내용을 인용 형태로 둔다: 行こう.","2. 인용의 と + 言う를 붙인다: 行こうと言う.","3. 言う의 어미 う를 わ로 바꾼 ない형 言わ에 ん을 붙인다: 行こうと言わん.","4. 끝에 ばかりに를 붙인다: 行こうと言わんばかりに."],"why":"言う의 ない형 言わ에 문어 조동사 ん(현대어의 う・よう에 해당)이 붙은 言わん(말하려 하다)에, '거의 ~할 정도'를 뜻하는 ばかり + に가 이어진 형태다.","nu":"실제로 말은 하지 않았지만 태도·표정·행동이 그런 말을 하는 것처럼 보인다는 뜻이다. 남(사람·동물)의 모습을 묘사할 때 쓰며 화자 자신의 행동에는 잘 쓰지 않는다. 문장체이며 소설·묘사문에 많다. 뒤에는 동작이 온다. 명사를 꾸밀 때는 と言わんばかりの + 명사.","cmp":[{"g":"～んばかりに","d":"동사 ない형 + んばかりに(泣かんばかりに)로 '금방이라도 ~할 듯이'라는 정도를 나타낸다. と言わんばかりに는 '~라고 말하는 듯이'로 태도가 전하는 메시지에 초점이 있다."},{"g":"～かのように","d":"사실과 다른 것을 비유하는 일반적인 표현. と言わんばかりに는 무언의 메시지를 표현할 때 쓴다."}],"ex":[{"jp":"犬[いぬ]は散歩[さんぽ]に行[い]こうと言[い]わんばかりに、リードをくわえてきた。","ko":"개는 산책 가자고 말하려는 듯이 목줄을 물고 왔다."},{"jp":"彼[かれ]は早[はや]く帰[かえ]れと言[い]わんばかりに、何度[なんど]も時計[とけい]を見[み]た。","ko":"그는 빨리 돌아가라고 말하려는 듯이 몇 번이나 시계를 보았다."},{"jp":"彼女[かのじょ]は邪魔[じゃま]だと言[い]わんばかりに、私[わたし]をにらんだ。","ko":"그녀는 방해된다고 말하려는 듯이 나를 노려보았다."}],"dr":[{"t":"make","q":"うるさい → ～と言わんばかりに","a":"うるさいと言わんばかりに","hint":"인용 + と + 言わ(ない형) + ん + ばかりに"},{"t":"make","q":"もう知らない → ～と言わんばかりに","a":"もう知らないと言わんばかりに","hint":"말하려는 내용 그대로 + と言わんばかりに"},{"t":"fill","q":"猫[ねこ]は早[はや]くご飯[はん]をくれ（　）、私[わたし]の足[あし]にすり寄[よ]ってきた。","a":"と言わんばかりに","opts":["と言わんばかりに","と言っても","というより","というのは"]}],"src":[],"vf":0,"u":53,"g":1,"gp":"gg_N1_20"},{"id":"g1_213","t":"～ながらに","ko":"~(한 상태) 그대로, ~하면서, ~부터","cat":"기타","conn":[{"w":"명사 (한정된 말)","f":"涙 + ながらに / 昔 + ながらに"},{"w":"동사 ます형 (한정된 말)","f":"生まれる → 生まれ + ながらに / 居る → 居 + ながらにして"}],"rule":["1. 정해진 명사는 그대로 쓴다: 涙.","2. 동사는 ます형으로 만든다: 生まれる → 生まれ(る 탈락).","3. 뒤에 ながらに(또는 ながらにして)를 붙인다: 涙ながらに / 生まれながらに."],"why":"","nu":"어떤 상태가 그대로 유지된 채라는 뜻으로, 자유롭게 아무 말에나 붙지 않고 거의 관용구로 쓴다: 涙ながらに(눈물을 흘리며), 生まれながらに(태어날 때부터), 居ながらにして(그 자리에 있는 채로), 昔ながらに(옛날 그대로). 문장체 표현이다. 명사를 꾸밀 때는 ながらの를 쓴다(昔ながらの町).","cmp":[{"g":"～ながら(동시 동작)","d":"동사 ます형 + ながら로 두 동작을 동시에 함(歩きながら). ながらに는 상태가 그대로 계속됨을 뜻하는 관용적 용법이다."},{"g":"～ながらの + 명사","d":"같은 의미를 명사 수식으로 쓴 형태(生まれながらの才能)."}],"ex":[{"jp":"彼女[かのじょ]は涙[なみだ]ながらに事故[じこ]の様子[ようす]を語[かた]った。","ko":"그녀는 눈물을 흘리며 사고 상황을 이야기했다."},{"jp":"この子[こ]は生[う]まれながらにして音楽[おんがく]の才能[さいのう]を持[も]っている。","ko":"이 아이는 태어날 때부터 음악적 재능을 가지고 있다."},{"jp":"インターネットのおかげで、家[いえ]に居[い]ながらにして世界中[せかいじゅう]の情報[じょうほう]が手[て]に入[はい]る。","ko":"인터넷 덕분에 집에 있으면서도 전 세계의 정보를 얻을 수 있다."}],"dr":[{"t":"make","q":"生まれる → ～ながらに","a":"生まれながらに","hint":"ます형(る 탈락) + ながらに"},{"t":"make","q":"涙 → ～ながらに","a":"涙ながらに","hint":"명사 + ながらに"},{"t":"fill","q":"彼[かれ]は涙[なみだ]（　）別[わか]れの言葉[ことば]を述[の]べた。","a":"ながらに","opts":["ながらに","ばかりか","とおりに","からして"]}],"src":[],"vf":0,"u":54,"g":1,"gp":"gg_N1_20"},{"id":"g1_222","t":"～に耐える","ko":"~을 견디다, ~에 버티다","cat":"기타","conn":[{"w":"명사","f":"寒さ + に耐える"},{"w":"い형용사의 명사형(～さ)","f":"寒い → 寒さ + に耐える"}],"rule":["1. 견디는 대상을 명사로 둔다. い형용사는 어미 い를 さ로 바꿔 명사로 만든다: 寒い → 寒さ.","2. 조사 に를 붙인다: 寒さに.","3. 2그룹 동사 耐える를 붙인다: 寒さに耐える. 가능형은 耐えられる, 과거형은 耐えた."],"why":"","nu":"사람이 고통·추위·외로움 등을 참고 견디거나, 물건이 무게·열·지진 등에 견디는 것을 나타낸다(地震に耐える建物). 대상에는 조사 に를 쓴다. 한국어 '~을 견디다'에 끌려 を를 쓰는 실수가 많으니 주의한다(痛みを耐える보다 痛みに耐える가 기본). 일상에서는 我慢する가 더 흔하다.","cmp":[{"g":"～に堪える","d":"같은 たえる이지만 '~할 가치가 있다'는 평가의 뜻으로 쓰일 때는 堪える로 쓴다."},{"g":"我慢する","d":"일상적인 '참다'. 대상에 を를 쓴다(痛みを我慢する)."}],"ex":[{"jp":"冬[ふゆ]の寒[さむ]さに耐[た]えて、花[はな]が咲[さ]いた。","ko":"겨울 추위를 견디고 꽃이 피었다."},{"jp":"この建物[たてもの]は大[おお]きな地震[じしん]にも耐[た]えられる。","ko":"이 건물은 큰 지진에도 견딜 수 있다."},{"jp":"彼[かれ]は厳[きび]しい練習[れんしゅう]に耐[た]えて、選手[せんしゅ]になった。","ko":"그는 혹독한 연습을 견디고 선수가 되었다."}],"dr":[{"t":"make","q":"暑い → ～に耐える","a":"暑さに耐える","hint":"い를 さ로 바꿔 명사로 + に + 耐える"},{"t":"make","q":"痛み → ～に耐えた","a":"痛みに耐えた","hint":"명사 + に + 耐える의 る를 떼고 た"},{"t":"fill","q":"この橋[はし]は強[つよ]い風[かぜ]（　）耐[た]えられるように作[つく]られている。","a":"に","opts":["に","を","で","から"]}],"src":[],"vf":0,"u":54,"g":1,"gp":"gg_N1_20"},{"id":"g1_236","t":"～ものとして","ko":"~한 것으로 간주하고, ~라고 치고","cat":"기타","conn":[{"w":"동사 보통형","f":"来ない + ものとして"},{"w":"い형용사","f":"正しい + ものとして"},{"w":"な형용사","f":"有効である + ものとして"},{"w":"명사","f":"事実である + ものとして"}],"rule":["1. 동사를 보통형으로 만든다. 예: 来る의 ない형은 る가 ない로 바뀌어 来ない가 된다.","2. 보통형 뒤에 ものとして를 그대로 붙인다: 来ないものとして.","3. な형용사·명사는 である를 붙인 뒤 ものとして를 잇는다: 事実であるものとして."],"why":"","nu":"실제로 확인되지 않았거나 사실이 아닐 수도 있는 일을 '그렇다고 보고' 다음 행동을 하거나 처리한다는 뜻이다. 공지·규칙·업무 문서 등 딱딱한 문장에서 많이 쓰며, 뒤에는 扱う, 考える, 進める, みなす 같은 처리·판단 동사가 온다(返事がない場合は欠席するものとして扱います). '~로서(자격)'를 뜻하는 として와 혼동하지 않는다.","cmp":[{"g":"～として","d":"명사 + として는 '~의 자격·입장으로'(教師として働く). ものとして는 어떤 상황을 사실로 가정·간주한다는 뜻이다."},{"g":"～とみなす","d":"'~로 간주하다'라는 판단 자체를 서술하는 동사. ものとして는 그 간주를 전제로 다음 행동을 이어 간다."}],"ex":[{"jp":"明日[あした]までに返事[へんじ]がなければ、参加[さんか]しないものとして準備[じゅんび]を進[すす]めます。","ko":"내일까지 답이 없으면 참가하지 않는 것으로 보고 준비를 진행하겠습니다."},{"jp":"この資料[しりょう]の数字[すうじ]は正[ただ]しいものとして計算[けいさん]した。","ko":"이 자료의 숫자는 맞는 것으로 간주하고 계산했다."},{"jp":"会議[かいぎ]に来[こ]なかった人[ひと]は、賛成[さんせい]したものとして扱[あつか]います。","ko":"회의에 오지 않은 사람은 찬성한 것으로 처리합니다."}],"dr":[{"t":"make","q":"出席する（ない형） → ～ものとして","a":"出席しないものとして","hint":"する → しない로 바꾸고 ものとして를 붙인다"},{"t":"make","q":"同意した → ～ものとして","a":"同意したものとして","hint":"보통형(た형) + ものとして"},{"t":"fill","q":"連絡[れんらく]がない場合[ばあい]は、欠席[けっせき]する（　）扱[あつか]います。","a":"ものとして","opts":["ものとして","ものなら","ものの","ものだから"]}],"src":[],"vf":0,"u":54,"g":1,"gp":"gg_N1_20"},{"id":"g1_243","t":"～足りない","ko":"~이 부족하다 / ~할 가치가 없다(に足りない)","cat":"기타","conn":[{"w":"명사","f":"時間 + が足りない"},{"w":"동사 사전형","f":"取る + に足りない"},{"w":"동사 사전형","f":"恐れる + に足りない"}],"rule":["1. 2그룹 동사 足りる(충분하다)의 る를 ない로 바꾼다: 足りる → 足りない.","2. 명사 + が足りない는 '~이 부족하다'는 뜻이다: 時間が足りない.","3. 동사 사전형 + に足りない는 '~할 만한 가치가 없다'는 뜻이다: 取るに足りない.","4. に足りない는 문어형 足る의 부정 足らない를 써서 に足らない라고도 한다."],"why":"足りる(충분하다)의 부정형이다. に足りない는 '~하기에 충분하지 않다' → '~할 가치가 없다'로 쓰인다.","nu":"명사 + が足りない는 일상적인 '부족하다'이다. N1에서 중요한 것은 동사 사전형 + に足りない(に足らない)로, 取るに足りない(하찮다), 恐れるに足りない(두려워할 것 없다), 信じるに足りない(믿을 가치가 없다)처럼 평가를 나타내며 문어적이다. 긍정형은 ～に足る이다.","cmp":[{"g":"～に足る","d":"긍정형으로 '~할 만한 가치가 있다'(信頼に足る人物)."},{"g":"～までもない","d":"'~할 필요도 없다'(言うまでもない). 필요성의 부정이며, に足りない는 가치의 부정이다."}],"ex":[{"jp":"時間[じかん]が足[た]りなくて、最後[さいご]の問題[もんだい]まで解[と]けなかった。","ko":"시간이 부족해서 마지막 문제까지 풀지 못했다."},{"jp":"そんな取[と]るに足[た]りないことで悩[なや]む必要[ひつよう]はない。","ko":"그런 하찮은 일로 고민할 필요는 없다."},{"jp":"今[いま]の彼[かれ]の実力[じつりょく]なら、相手[あいて]は恐[おそ]れるに足[た]りない。","ko":"지금 그의 실력이라면 상대는 두려워할 것 없다."}],"dr":[{"t":"make","q":"お金が足りる → 부정형","a":"お金が足りない","hint":"足りる의 る → ない"},{"t":"make","q":"恐れる → ～に足りない","a":"恐れるに足りない","hint":"동사 사전형 + に + 足りない"},{"t":"fill","q":"それは取[と]る（　）小[ちい]さなミスだから、気[き]にしなくていい。","a":"に足りない","opts":["に足りない","にかたくない","わけがない","べきではない"]}],"src":[],"vf":0,"u":54,"g":1,"gp":"gg_N1_20"}];
